def render_markdown_or_html_with_cache(text, final=False, workspace_dir=""):
    text = text or ""
    raw_html = extract_renderable_html_response(text) if final else ""
    cache_kind = "raw_html" if raw_html else "markdown"
    workspace_key = os.path.normcase(os.path.abspath(workspace_dir)) if workspace_dir else ""
    app = QApplication.instance()
    theme_key = (
        app.font().family() if app is not None else "",
        str(app.property("themeMonoFontFamily") or "") if app is not None else "",
        DesignTokens.chat_text,
        DesignTokens.chat_text_muted,
        DesignTokens.bg_code,
        DesignTokens.bg_secondary,
        DesignTokens.chat_border,
        DesignTokens.primary,
        DesignTokens.font_size_body,
    )
    cache_key = (cache_kind, text, workspace_key, theme_key)
    cached = _MARKDOWN_RENDER_CACHE.get(cache_key)
    if cached is not None:
        _MARKDOWN_RENDER_CACHE.move_to_end(cache_key)
        return cached
    if raw_html:
        html_output = markdown_render_style() + raw_html
        if final and workspace_dir:
            html_output = linkify_workspace_paths_in_html(html_output, workspace_dir)
        result = ("raw_html", html_output)
    else:
        html_content = markdown.markdown(text, extensions=['fenced_code', 'tables', 'nl2br', 'sane_lists'])
        html_output = markdown_render_style() + html_content
        if final and workspace_dir:
            html_output = linkify_workspace_paths_in_html(html_output, workspace_dir)
        result = ("html", html_output)
    _MARKDOWN_RENDER_CACHE[cache_key] = result
    while len(_MARKDOWN_RENDER_CACHE) > MARKDOWN_RENDER_CACHE_SIZE:
        _MARKDOWN_RENDER_CACHE.popitem(last=False)
    return result


def looks_like_markdown_text(text):
    value = str(text or "")
    if not value.strip():
        return False
    markdown_patterns = (
        r"(?m)^\s{0,3}#{1,6}\s+\S",
        r"(?m)^\s*[-*+]\s+\S",
        r"(?m)^\s*\d+\.\s+\S",
        r"(?m)^\s{0,3}>\s+\S",
        r"(?m)^\s*\|.+\|\s*$",
        r"```",
        r"\*\*[^*\n][\s\S]*?\*\*",
        r"`[^`\n]+`",
    )
    return any(re.search(pattern, value) for pattern in markdown_patterns)

def set_stylesheet_if_changed(widget, stylesheet):
    if widget.property("_cached_stylesheet") == stylesheet:
        return
    widget.setStyleSheet(stylesheet)
    widget.setProperty("_cached_stylesheet", stylesheet)


def set_text_if_changed(widget, text):
    if widget.text() == text:
        return
    widget.setText(text)


def add_soft_shadow(widget, blur=28, y_offset=10, alpha=28):
    shadow = QGraphicsDropShadowEffect(widget)
    shadow.setBlurRadius(blur)
    shadow.setOffset(0, y_offset)
    shadow.setColor(QColor(0, 0, 0, alpha))
    widget.setGraphicsEffect(shadow)


