def log_sub_agent_runtime(event, **fields):
    if not runtime_debug_logging_enabled():
        return
    try:
        payload = {"event": event}
        payload.update(fields or {})
        log_dir = get_app_data_dir()
        os.makedirs(log_dir, exist_ok=True)
        log_path = os.path.join(log_dir, "sub_agent_runtime.log")
        ts = time.strftime("%Y-%m-%d %H:%M:%S")
        with open(log_path, "a", encoding="utf-8") as handle:
            handle.write(f"[{ts}] {json.dumps(payload, ensure_ascii=False, default=str)}\n")
    except Exception:
        try:
            print(f"[sub-agent-runtime] {event} {fields}")
        except Exception:
            return


def sub_agent_log_path():
    return os.path.join(get_app_data_dir(), "sub_agent_runtime.log")


def _qt_object_alive(obj):
    if obj is None:
        return False
    try:
        return bool(is_qt_object_valid(obj))
    except RuntimeError:
        return False
    except TypeError:
        # Some tests use lightweight Python doubles in place of QObjects.
        return True
    except Exception:
        return True


def _sub_agent_payload_content_len(payload):
    if not isinstance(payload, dict):
        return 0
    total = 0
    for key in (
        "content",
        "input_text",
        "reasoning_delta",
        "content_delta",
        "log_content",
        "provider_message",
        "tool_result",
        "output_text",
        "error",
    ):
        value = payload.get(key)
        if value is not None:
            total += len(str(value))
    return total


def _safe_text_preview(text, limit=6000):
    value = "" if text is None else str(text)
    if len(value) <= limit:
        return value
    omitted = len(value) - limit
    return f"{value[:limit]}\n\n...[truncated {omitted} chars for UI safety]"


def _safe_text_tail_preview(text, limit=6000):
    value = "" if text is None else str(text)
    if len(value) <= limit:
        return value
    omitted = len(value) - limit
    prefix = f"...[hidden {omitted} earlier chars for UI safety]\n\n"
    tail_limit = max(limit - len(prefix), 0)
    return prefix + value[-tail_limit:]


