def status_color(status):
    status = (status or "").strip().lower()
    if status in {"active", "running", "pending", "waiting_input", "log", "content", "input"}:
        return DesignTokens.status_running
    if status == "thinking":
        return DesignTokens.status_thinking
    if status in {"tool", "tool_use", "tool_result"}:
        return DesignTokens.status_tool
    if status in {"completed", "done"}:
        return DesignTokens.status_success
    if status in {"error", "failed", "failed_recovered", "killed", "provider_error"}:
        return DesignTokens.status_error
    return DesignTokens.status_idle


def status_label_text(status):
    mapping = {
        "input": "收到输入",
        "pending": "等待",
        "active": "运行中",
        "running": "运行中",
        "thinking": "思考中",
        "content": "输出中",
        "tool_use": "调用工具",
        "tool_result": "工具结果",
        "log": "日志",
        "provider_log": "Provider",
        "provider_error": "Provider 异常",
        "waiting_input": "等待输入",
        "completed": "已完成",
        "done": "已完成",
        "failed": "失败",
        "failed_recovered": "失败已恢复",
        "closed": "已关闭",
        "killed": "已终止",
    }
    return mapping.get(status or "", status or "空闲")


def rgba_from_hex(hex_color, alpha):
    text = str(hex_color or "").strip().lstrip("#")
    if len(text) != 6:
        raise ValueError(f"无法转换非 #RRGGBB 颜色：{hex_color}")
    try:
        r = int(text[0:2], 16)
        g = int(text[2:4], 16)
        b = int(text[4:6], 16)
    except ValueError:
        raise ValueError(f"无法转换非 #RRGGBB 颜色：{hex_color}") from None
    return f"rgba({r}, {g}, {b}, {alpha})"


def apple_status_chip_style(status, subtle=False):
    color = status_color(status)
    bg = DesignTokens.bg_secondary if subtle else rgba_from_hex(color, 0.10)
    return (
        f"background: {bg}; color: {color}; border: 1px solid {rgba_from_hex(color, 0.22)}; "
        "border-radius: 6px; padding: 3px 7px; font-size: 11px; font-weight: 600;"
    )


def normalize_token_usage_summary(summary):
    normalized = {
        "input_tokens": 0,
        "output_tokens": 0,
        "total_tokens": 0,
        "cached_input_tokens": 0,
        "uncached_input_tokens": 0,
        "request_count": 0,
        "missing_usage_count": 0,
    }
    if not isinstance(summary, dict):
        return normalized
    for key in normalized:
        try:
            normalized[key] = max(0, int(summary.get(key, 0) or 0))
        except Exception:
            normalized[key] = 0
    return normalized


TOKEN_USAGE_METADATA_KEYS = (
    "provider",
    "base_url",
    "model",
    "protocol",
    "profile_id",
    "request_id",
    "cache_namespace",
    "cache_metrics_status",
    "cache_bucket",
)


def normalize_last_token_usage(usage):
    normalized = normalize_token_usage_summary(usage)
    if not isinstance(usage, dict):
        return normalized
    for key in TOKEN_USAGE_METADATA_KEYS:
        value = usage.get(key)
        if value not in (None, ""):
            normalized[key] = str(value)
    return normalized


def token_usage_bucket_key(usage):
    """Build a stable, non-secret bucket for protocol/provider comparisons."""
    if not isinstance(usage, dict):
        usage = {}
    values = [
        str(usage.get("provider") or "").strip(),
        str(usage.get("base_url") or "").strip(),
        str(usage.get("model") or "").strip(),
        str(usage.get("protocol") or "").strip(),
        str(usage.get("profile_id") or "").strip(),
    ]
    if not any(values):
        return "default"
    return json.dumps(values, ensure_ascii=False, separators=(",", ":"))


def normalize_token_usage_buckets(buckets):
    if not isinstance(buckets, dict):
        return {}
    normalized = {}
    for key, value in buckets.items():
        bucket_key = str(key or "").strip()
        if not bucket_key:
            continue
        normalized[bucket_key] = normalize_token_usage_summary(value)
    return normalized


def compact_token_count(value):
    try:
        count = max(0, int(value or 0))
    except Exception:
        count = 0
    if count >= 1_000_000:
        text = f"{count / 1_000_000:.1f}M"
    elif count >= 1_000:
        text = f"{count / 1_000:.1f}K"
    else:
        text = str(count)
    return text.replace(".0", "")


def token_usage_cache_rate(summary):
    usage = normalize_token_usage_summary(summary)
    input_tokens = usage.get("input_tokens", 0)
    cached_tokens = usage.get("cached_input_tokens", 0)
    if input_tokens <= 0:
        return 0.0
    return max(0.0, min(1.0, cached_tokens / input_tokens))


def format_token_speed_rate(rate):
    try:
        value = max(0.0, float(rate))
    except (TypeError, ValueError):
        return "--"
    return f"{value:.1f} tok/s"


def _deepseek_billing_currency(snapshot):
    billing = normalize_deepseek_billing_snapshot(snapshot)
    balance = billing.get("balance") if isinstance(billing.get("balance"), dict) else {}
    infos = balance.get("balance_infos") if isinstance(balance.get("balance_infos"), list) else []
    available = {
        str(item.get("currency") or "").strip().upper()
        for item in infos
        if isinstance(item, dict)
    }
    if "CNY" in available:
        return "CNY"
    if "USD" in available:
        return "USD"
    costs = billing.get("costs") if isinstance(billing.get("costs"), dict) else {}
    return "CNY" if "CNY" in costs else "USD" if "USD" in costs else ""


def _format_billing_money(value, currency, balance=False):
    try:
        amount = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError):
        return ""
    symbol = "¥" if currency == "CNY" else "$" if currency == "USD" else currency
    if balance:
        return f"{symbol}{amount:.2f}"
    if Decimal("0") < amount < Decimal("0.0001"):
        return f"＜{symbol}0.0001"
    text = f"{amount:.4f}".rstrip("0").rstrip(".")
    return f"{symbol}{text or '0'}"


def _deepseek_balance_info(snapshot, currency):
    billing = normalize_deepseek_billing_snapshot(snapshot)
    balance = billing.get("balance") if isinstance(billing.get("balance"), dict) else {}
    for info in balance.get("balance_infos", []) if isinstance(balance.get("balance_infos"), list) else []:
        if isinstance(info, dict) and str(info.get("currency") or "").upper() == currency:
            return info
    return {}


def format_token_usage_chip_text(summary, speed_snapshot=None, billing_snapshot=None):
    usage = normalize_token_usage_summary(summary)
    total_tokens = usage.get("total_tokens", 0)
    cached_tokens = usage.get("cached_input_tokens", 0)
    if cached_tokens > 0:
        rate = token_usage_cache_rate(usage) * 100
        text = f"{compact_token_count(total_tokens)} tokens · 缓存 {compact_token_count(cached_tokens)} / {rate:.0f}%"
    else:
        text = f"{compact_token_count(total_tokens)} tokens · 缓存 0"
    if isinstance(speed_snapshot, dict):
        if str(speed_snapshot.get("unavailable_reason") or "").strip():
            text += " · 速度不可用"
        elif speed_snapshot.get("active"):
            text += " · 速度 " + format_token_speed_rate(speed_snapshot.get("current_rate"))
        elif speed_snapshot.get("last_rate") is not None:
            text += " · 最近 " + format_token_speed_rate(speed_snapshot.get("last_rate"))
    billing = normalize_deepseek_billing_snapshot(billing_snapshot)
    currency = _deepseek_billing_currency(billing)
    costs = billing.get("costs") if isinstance(billing.get("costs"), dict) else {}
    if billing.get("cost_status") == "available" and currency in costs:
        cost_text = _format_billing_money(costs.get(currency), currency)
        if cost_text:
            text += " · 本轮 " + cost_text
    if billing.get("balance_status") == "succeeded" and currency:
        info = _deepseek_balance_info(billing, currency)
        balance_text = _format_billing_money(info.get("total_balance"), currency, balance=True)
        if balance_text:
            text += " · 余 " + balance_text
    return text


def format_token_usage_tooltip(summary, last_usage=None, speed_snapshot=None, billing_snapshot=None):
    usage = normalize_token_usage_summary(summary)
    lines = [
        "当前统计桶累计 token 用量（按 Provider / 模型 / 协议隔离）",
        f"总量：{usage.get('total_tokens', 0):,}",
        f"输入：{usage.get('input_tokens', 0):,}",
        f"输出：{usage.get('output_tokens', 0):,}",
        f"缓存输入：{usage.get('cached_input_tokens', 0):,} ({token_usage_cache_rate(usage) * 100:.1f}%)",
        f"未缓存输入：{usage.get('uncached_input_tokens', 0):,}",
        f"已统计请求：{usage.get('request_count', 0):,}",
    ]
    if usage.get("missing_usage_count", 0):
        lines.append(f"未返回用量的请求：{usage.get('missing_usage_count', 0):,}")
    if isinstance(speed_snapshot, dict):
        unavailable_reason = str(speed_snapshot.get("unavailable_reason") or "").strip()
        active = bool(speed_snapshot.get("active"))
        last_rate = speed_snapshot.get("last_rate")
        if unavailable_reason or active or last_rate is not None:
            lines.extend(["", "Token 生成速度（估算）"])
            if unavailable_reason:
                lines.append("状态：不可用")
                lines.append("原因：" + unavailable_reason)
                lines.append("恢复：下一次模型请求将重新初始化速度监控。")
            elif active:
                current_rate = speed_snapshot.get("current_rate")
                lines.append(
                    "当前速度："
                    + (
                        format_token_speed_rate(current_rate)
                        if current_rate is not None
                        else "等待首个生成片段"
                    )
                )
                lines.append(
                    f"当前请求已估算：{int(speed_snapshot.get('current_tokens') or 0):,} tokens"
                )
            if last_rate is not None:
                lines.extend(
                    [
                        f"最近完成请求均速：{format_token_speed_rate(last_rate)}",
                        f"最近估算输出：{int(speed_snapshot.get('last_tokens') or 0):,} tokens",
                        f"有效计时：{float(speed_snapshot.get('last_duration') or 0.0):.2f} 秒",
                    ]
                )
            lines.append("口径：近 3 秒滑动窗口；统计思考与正文，不含 Tool 参数和首 token 等待时间。")
    if isinstance(last_usage, dict) and last_usage:
        last = normalize_last_token_usage(last_usage)
        lines.extend(
            [
                "",
                "最近一轮请求（本轮，不是累计）",
                f"总量：{last.get('total_tokens', 0):,}",
                f"输入：{last.get('input_tokens', 0):,}",
                f"输出：{last.get('output_tokens', 0):,}",
                f"缓存输入：{last.get('cached_input_tokens', 0):,}",
            ]
        )
        request_context = [
            str(last.get(key) or "").strip()
            for key in ("provider", "model", "protocol")
            if str(last.get(key) or "").strip()
        ]
        if request_context:
            lines.append("协议/模型：" + " / ".join(request_context))
        cache_status = str(last.get("cache_metrics_status") or "").strip()
        if cache_status:
            lines.append("缓存口径：" + cache_status)
        if str(last.get("request_id") or "").strip():
            lines.append("request_id：" + str(last.get("request_id")))
    billing = normalize_deepseek_billing_snapshot(billing_snapshot)
    if billing:
        lines.extend(["", "本次运行费用（DeepSeek 官方目录价计算）"])
        run_usage = billing.get("usage") if isinstance(billing.get("usage"), dict) else {}
        lines.extend(
            [
                f"输入：{int(run_usage.get('input_tokens') or 0):,}",
                f"输出：{int(run_usage.get('output_tokens') or 0):,}",
                f"缓存输入：{int(run_usage.get('cached_input_tokens') or 0):,}",
                f"未缓存输入：{int(run_usage.get('uncached_input_tokens') or 0):,}",
                f"模型请求：{int(run_usage.get('request_count') or 0):,}",
            ]
        )
        periods = list(dict.fromkeys(billing.get("pricing_periods") or []))
        if periods:
            labels = {"peak": "高峰", "off_peak": "空闲"}
            lines.append("计价时段：" + " / ".join(labels.get(item, item) for item in periods))
        if billing.get("pricing_version"):
            lines.append("价格版本：" + str(billing.get("pricing_version")))
        currency = _deepseek_billing_currency(billing)
        costs = billing.get("costs") if isinstance(billing.get("costs"), dict) else {}
        if billing.get("cost_status") == "available" and currency in costs:
            lines.append("本轮预估：" + _format_billing_money(costs.get(currency), currency))
        else:
            reason_labels = {
                "unknown_model": "当前模型没有已核验价格",
                "missing_usage": "模型未返回完整 token 用量",
                "missing_cache_usage": "模型未返回可计价的缓存明细",
                "inconsistent_usage": "token 用量与缓存明细不一致",
                "missing_request_start": "缺少请求开始时间",
            }
            reason = reason_labels.get(
                str(billing.get("cost_reason_code") or ""),
                "费用不可计算",
            )
            lines.append("本轮预估：不可用（" + reason + "）")
        balance_status = str(billing.get("balance_status") or "")
        if balance_status == "succeeded" and currency:
            balance = billing.get("balance") if isinstance(billing.get("balance"), dict) else {}
            info = _deepseek_balance_info(billing, currency)
            lines.append(
                "运行结束时余额："
                + _format_billing_money(info.get("total_balance"), currency, balance=True)
            )
            lines.append(
                "其中赠金："
                + _format_billing_money(info.get("granted_balance"), currency, balance=True)
                + "；充值余额："
                + _format_billing_money(info.get("topped_up_balance"), currency, balance=True)
            )
            fetched_at = float(balance.get("fetched_at") or 0.0)
            if fetched_at > 0:
                lines.append("余额查询时间：" + datetime.fromtimestamp(fetched_at).strftime("%Y-%m-%d %H:%M:%S"))
            if not bool(balance.get("is_available", True)):
                lines.append("账户状态：余额不足，当前不可调用 API")
        elif balance_status == "querying":
            lines.append("余额：正在后台查询")
        elif balance_status == "failed":
            error_labels = {
                "missing_key": "未配置 API Key",
                "authentication": "API Key 无权查询余额",
                "timeout": "查询超时",
                "network": "网络连接失败",
                "http_status": "官方接口返回错误",
                "invalid_response": "官方响应格式异常",
            }
            category = str(billing.get("balance_error_category") or "")
            lines.append("余额：查询失败（" + error_labels.get(category, "未知错误") + "）")
            lines.append("说明：不影响本轮结果；下次运行结束后会重新查询。")
    return "\n".join(lines)


