def apply_settings_combo_style(combo):
    """Keep settings combo popup items legible across active and inactive states."""
    view = combo.view()
    view.setStyleSheet(
        f"""
        QAbstractItemView {{
            background: {DesignTokens.bg_panel_strong};
            color: {DesignTokens.text_primary};
            border: 1px solid {DesignTokens.border_subtle};
            outline: none;
            padding: 4px;
            selection-background-color: {DesignTokens.selection_bg};
            selection-color: {DesignTokens.selection_text};
        }}
        QAbstractItemView::item {{
            color: {DesignTokens.text_primary};
            min-height: 28px;
            padding: 4px 8px;
            border: none;
            border-radius: 8px;
        }}
        QAbstractItemView::item:hover {{
            background: {DesignTokens.bg_hover};
            color: {DesignTokens.text_primary};
        }}
        QAbstractItemView::item:selected,
        QAbstractItemView::item:selected:active,
        QAbstractItemView::item:selected:!active,
        QAbstractItemView::item:selected:!focus {{
            background: {DesignTokens.primary_soft};
            color: {DesignTokens.text_primary};
        }}
        """
    )
    palette = view.palette()
    palette.setColor(QPalette.Base, QColor(DesignTokens.bg_panel_strong))
    palette.setColor(QPalette.Text, QColor(DesignTokens.text_primary))
    palette.setColor(QPalette.Highlight, QColor(DesignTokens.primary_soft))
    palette.setColor(QPalette.HighlightedText, QColor(DesignTokens.text_primary))
    view.setPalette(palette)
    return combo


def settings_status_chip(text, tone="neutral"):
    colors = {
        "neutral": (DesignTokens.muted_chip_bg, DesignTokens.muted_chip_text, DesignTokens.border_subtle),
        "primary": (rgba_from_hex(DesignTokens.primary, 0.10), DesignTokens.primary, rgba_from_hex(DesignTokens.primary, 0.18)),
        "success": (DesignTokens.success_bg, DesignTokens.success_text, DesignTokens.success_border),
        "warning": (DesignTokens.warning_bg, DesignTokens.warning_text, DesignTokens.warning_border),
        "danger": (DesignTokens.error_bg, DesignTokens.error_text, DesignTokens.error_border),
    }
    bg, fg, border = colors.get(tone, colors["neutral"])
    return (
        f"<span style=\"background:{bg};color:{fg};border:1px solid {border};"
        "border-radius:10px;padding:3px 8px;font-size:11px;font-weight:700;\">"
        f"{text}</span>"
    )


def build_settings_surface(title="", subtitle="", radius=8, show_subtitle=True):
    frame = QFrame()
    frame.setProperty("settingsSurface", True)
    frame.setStyleSheet(apple_settings_surface_style(radius=radius))
    layout = QVBoxLayout(frame)
    layout.setContentsMargins(4, 14, 4, 18)
    layout.setSpacing(12)
    if title:
        title_label = QLabel(title)
        title_label.setStyleSheet(apple_settings_section_title_style())
        layout.addWidget(title_label)
    if subtitle and show_subtitle:
        subtitle_label = QLabel(subtitle)
        subtitle_label.setWordWrap(True)
        subtitle_label.setStyleSheet(apple_settings_inline_note_style() + " background: transparent; border: none;")
        layout.addWidget(subtitle_label)
    return frame, layout


def build_settings_page_header(title, intro=None):
    header_widget = QWidget()
    header_layout = QVBoxLayout(header_widget)
    header_layout.setContentsMargins(0, 0, 0, 0)
    header_layout.setSpacing(4)
    header = QLabel(str(title or ""))
    header.setProperty("roleTitle", True)
    header_layout.addWidget(header)
    if intro:
        intro_label = QLabel(str(intro))
        intro_label.setObjectName("SettingsPageIntro")
        intro_label.setWordWrap(True)
        intro_label.setStyleSheet(apple_settings_inline_note_style())
        header_layout.addWidget(intro_label)
    return header_widget


def format_file_size(size):
    try:
        size = float(size)
    except Exception:
        return ""
    units = ["B", "KB", "MB", "GB", "TB"]
    index = 0
    while size >= 1024 and index < len(units) - 1:
        size /= 1024.0
        index += 1
    if index == 0:
        return f"{int(size)} {units[index]}"
    return f"{size:.1f} {units[index]}"


