    def _set_browser_setup_actions(
        self,
        primary_text="",
        primary_action="",
        secondary_text="",
        secondary_action="",
    ):
        self._browser_primary_action = str(primary_action or "")
        self._browser_secondary_action = str(secondary_action or "")
        self.browser_setup_primary_btn.setText(str(primary_text or ""))
        self.browser_setup_primary_btn.setVisible(bool(primary_text and primary_action))
        self.browser_setup_primary_btn.setEnabled(bool(primary_text and primary_action))
        self.browser_setup_secondary_btn.setText(str(secondary_text or ""))
        self.browser_setup_secondary_btn.setVisible(bool(secondary_text and secondary_action))
        self.browser_setup_secondary_btn.setEnabled(bool(secondary_text and secondary_action))

    def _set_browser_setup_status(self, text="", tone="neutral"):
        color = {
            "success": DesignTokens.success_text,
            "warning": DesignTokens.warning_text,
            "error": DesignTokens.error_text,
        }.get(str(tone or "neutral"), DesignTokens.text_tertiary)
        self.browser_setup_status.setText(str(text or ""))
        self.browser_setup_status.setVisible(bool(text))
        self.browser_setup_status.setStyleSheet(
            f"font-size: {DesignTokens.font_size_meta}px; color: {color};"
        )

    def _selected_browser_id(self):
        if not hasattr(self, "browser_choice_combo"):
            return ""
        return str(self.browser_choice_combo.currentData() or "").strip()

    def _refresh_browser_extension_controls(self):
        if not hasattr(self, "browser_extension_controls"):
            return
        status = dict(self.browser_component_status or {})
        browsers = [
            dict(item)
            for item in (status.get("available_browsers") or [])
            if isinstance(item, dict) and item.get("id")
        ]
        signature = tuple(
            (str(item.get("id")), str(item.get("name")), str(item.get("path")))
            for item in browsers
        )
        if signature != getattr(self, "_browser_choice_signature", None):
            previous = self._selected_browser_id()
            self.browser_choice_combo.blockSignals(True)
            self.browser_choice_combo.clear()
            self.browser_choice_combo.addItem("请选择浏览器…", "")
            for browser in browsers:
                self.browser_choice_combo.addItem(
                    str(browser.get("name") or browser.get("id")),
                    str(browser.get("id")),
                )
            if previous:
                index = self.browser_choice_combo.findData(previous)
                if index >= 0:
                    self.browser_choice_combo.setCurrentIndex(index)
            self.browser_choice_combo.blockSignals(False)
            self._browser_choice_signature = signature
        has_browser = bool(browsers)
        selected_browser = self._selected_browser_id()
        busy = bool(self.browser_component_task)
        extension_available = bool(status.get("bundled_extension_available"))
        prepared = bool(status.get("extension_prepared"))
        path = str(status.get("extension_path") or "")
        self.browser_choice_combo.setEnabled(has_browser and not busy)
        self.browser_choice_combo.setToolTip(
            ""
            if has_browser
            else "未检测到 Google Chrome 或 Microsoft Edge，请先安装受支持浏览器。"
        )
        self.browser_offline_btn.setEnabled(
            bool(selected_browser and extension_available and not busy)
        )
        if not extension_available:
            self.browser_offline_btn.setToolTip(
                str(status.get("bundle_error") or "随包离线扩展不可用。")
            )
        elif not has_browser:
            self.browser_offline_btn.setToolTip(
                "请先安装 Google Chrome 或 Microsoft Edge。"
            )
        elif not selected_browser:
            self.browser_offline_btn.setToolTip("请先明确选择目标浏览器。")
        else:
            self.browser_offline_btn.setToolTip("")
        self.browser_store_btn.setEnabled(not busy)
        show_guidance = bool(prepared or self.browser_offline_guidance_visible)
        self.browser_extension_guidance.setVisible(show_guidance)
        self.browser_extension_path_label.setText(
            f"扩展目录：{path}" if path else "扩展目录尚未准备。"
        )
        self.browser_open_manager_btn.setEnabled(bool(selected_browser and not busy))
        self.browser_open_folder_btn.setEnabled(bool(prepared and path and not busy))
        self.browser_copy_path_btn.setEnabled(bool(prepared and path and not busy))
        self.browser_offline_btn.setStyleSheet(
            product_button_style(
                "secondary" if self.browser_extension_page_opened else "primary"
            )
        )

    def _render_browser_automation_setup(self):
        if not hasattr(self, "browser_setup_title"):
            return
        manager = self.browser_component_manager
        status = dict(self.browser_component_status or {})
        task = dict(self.browser_component_task or {})
        self.browser_setup_progress.hide()
        self.browser_extension_controls.hide()
        self._set_browser_setup_actions()

        if manager is None:
            self.browser_setup_title.setText("暂时无法完成设置")
            self.browser_setup_description.setText(
                "浏览器设置服务没有启动。请重启 Cowork 后再试。"
            )
            self._set_browser_setup_status("设置服务不可用", "error")
            return

        if task:
            action = str(task.get("action") or "")
            progress = int(task.get("progress") or 0)
            if status.get("installed") and not status.get("needs_repair"):
                self.browser_extension_controls.show()
                self._refresh_browser_extension_controls()
            self.browser_setup_title.setText(
                "正在检查浏览器连接"
                if action == "check"
                else "正在确认浏览器状态"
                if action == "probe"
                else "正在准备离线扩展"
                if action == "prepare_extension"
                else "正在准备浏览器自动化"
            )
            task_message = {
                "check": "正在检查 Chrome 或 Edge 的连接，请稍候…",
                "probe": "正在确认当前状态，请稍候…",
                "repair": "正在修复浏览器自动化，请稍候…",
                "prepare_extension": "正在校验并解压随 Cowork 提供的浏览器扩展…",
                "install": (
                    "正在完成离线安装，请稍候…"
                    if progress >= 80
                    else "正在校验并安装随 Cowork 提供的 CLI…"
                ),
            }.get(action, "正在处理，请稍候…")
            self.browser_setup_description.setText(task_message)
            self.browser_setup_progress.setRange(
                (0 if progress else 0),
                (100 if progress else 0),
            )
            if progress:
                self.browser_setup_progress.setValue(progress)
            self.browser_setup_progress.show()
            self._set_browser_setup_status()
            return

        if self.browser_setup_error:
            self._set_browser_setup_status(self.browser_setup_error, "error")
        elif status.get("ready"):
            self._set_browser_setup_status("✓ 浏览器已连接", "success")
        elif status.get("known") and status.get("installed"):
            self._set_browser_setup_status("还差最后一步", "warning")
        else:
            self._set_browser_setup_status()

        if not status.get("known"):
            self.browser_setup_title.setText("确认浏览器状态")
            self.browser_setup_description.setText(
                "先确认当前环境，再继续完成开启。"
            )
            self._set_browser_setup_actions("检测状态", "probe")
            return

        if not status.get("installed"):
            if not status.get("bundled_cli_available", status.get("bundle_ready", True)):
                self.browser_setup_title.setText("随包安装文件不可用")
                self.browser_setup_description.setText(
                    str(status.get("bundle_error") or "BrowserSkill CLI 未随 Cowork 正确提供。")
                )
                self._set_browser_setup_status("请重新安装完整的 Cowork 发布包。", "error")
            else:
                self.browser_setup_title.setText("准备浏览器自动化")
                self.browser_setup_description.setText(
                    "CLI 已随 Cowork 提供，将从本机校验并安装，不会在运行时访问 GitHub。"
                )
                self._set_browser_setup_actions("开始设置", "install")
            return

        if status.get("needs_update") or status.get("needs_repair"):
            self.browser_setup_title.setText("需要修复后继续")
            self.browser_setup_description.setText(
                str(status.get("health_error") or "浏览器自动化的本地文件需要修复。")
            )
            if status.get("bundled_cli_available", status.get("bundle_ready", True)):
                self._set_browser_setup_actions("修复", "repair")
            return

        if status.get("ready"):
            if self.skill.get("enabled"):
                self.browser_setup_title.setText("浏览器自动化已开启")
                self.browser_setup_description.setText(
                    "Cowork 现在可以在独立窗口中读取和操作 Chrome 或 Edge 网页。"
                )
                self._set_browser_setup_actions(
                    secondary_text="关闭能力",
                    secondary_action="disable",
                )
            else:
                self.browser_setup_title.setText("准备完成")
                self.browser_setup_description.setText(
                    "浏览器已经连接，现在可以开启这项能力。"
                )
                self._set_browser_setup_actions("开启能力", "enable")
            return

        self.browser_extension_controls.show()
        self._refresh_browser_extension_controls()
        if status.get("protocol_incompatible"):
            self.browser_setup_title.setText("更新浏览器扩展")
            self.browser_setup_description.setText(
                "当前扩展协议与 CLI 不兼容。请选择离线更新或前往 Chrome Web Store 更新。"
            )
        else:
            self.browser_setup_title.setText("连接 Chrome 或 Edge")
            self.browser_setup_description.setText(
                "离线安装为主路径，也可保留使用 Chrome Web Store；完成后共用连接检查。"
            )
        if not status.get("available_browsers"):
            self._set_browser_setup_status(
                "未检测到 Chrome 或 Edge，请先安装受支持浏览器。",
                "warning",
            )
        if self.browser_extension_page_opened:
            self._set_browser_setup_actions("检查并开启", "check")
        else:
            self._set_browser_setup_actions(
                secondary_text="检查并开启",
                secondary_action="check",
            )

    def _probe_browser_component(self):
        manager = self.browser_component_manager
        if manager is None or manager.has_task(BROWSER_SKILL_COMPONENT_ID):
            return False
        self.browser_setup_error = ""
        log_ui_navigation("browser_capability_setup_action", action="probe")
        accepted = manager.probe_component(BROWSER_SKILL_COMPONENT_ID)
        if not accepted:
            self.browser_setup_error = "状态检测未能开始，请稍后重试。"
            self._render_browser_automation_setup()
        return bool(accepted)

    def _enqueue_browser_component_action(self, action):
        manager = self.browser_component_manager
        if manager is None:
            self.browser_setup_error = "浏览器设置服务不可用，请重启 Cowork 后重试。"
            self._render_browser_automation_setup()
            return False
        if manager.has_task(BROWSER_SKILL_COMPONENT_ID):
            return False
        self.browser_setup_error = ""
        self.browser_enable_after_check = action == "check"
        log_ui_navigation("browser_capability_setup_action", action=action)
        accepted = manager.enqueue(action, BROWSER_SKILL_COMPONENT_ID, {})
        if not accepted:
            self.browser_enable_after_check = False
            self.browser_setup_error = "操作未能开始，请稍后重试。"
            self._render_browser_automation_setup()
        return bool(accepted)

    def _open_browser_extension_page(self):
        log_ui_navigation("browser_capability_setup_action", action="open_chrome_web_store")
        if QDesktopServices.openUrl(QUrl(BROWSER_SKILL_EXTENSION_URL)):
            self.browser_extension_page_opened = True
            self.browser_setup_error = ""
            self._render_browser_automation_setup()
            return True
        self.browser_setup_error = "系统未能打开浏览器扩展页面，请检查默认浏览器设置后重试。"
        self._render_browser_automation_setup()
        return False

    def _prepare_offline_browser_extension(self):
        browser_id = self._selected_browser_id()
        if not browser_id:
            browsers = self.browser_component_status.get("available_browsers") or []
            self.browser_setup_error = (
                "请先明确选择 Chrome 或 Edge。"
                if browsers
                else "未检测到 Chrome 或 Edge，请先安装受支持浏览器。"
            )
            self._render_browser_automation_setup()
            return False
        if not self.browser_component_status.get("bundled_extension_available"):
            self.browser_setup_error = str(
                self.browser_component_status.get("bundle_error")
                or "随包 BrowserSkill 扩展不可用，请重新安装完整的 Cowork 发布包。"
            )
            self._render_browser_automation_setup()
            return False
        self.browser_pending_browser_id = browser_id
        self.browser_offline_guidance_visible = True
        return self._enqueue_browser_component_action("prepare_extension")

    def _open_selected_extension_manager(self):
        browser_id = self._selected_browser_id()
        if not browser_id:
            self.browser_setup_error = "请先明确选择 Chrome 或 Edge。"
            self._render_browser_automation_setup()
            return False
        try:
            launch_browser_skill_extension_manager(browser_id)
        except Exception as exc:
            self.browser_setup_error = str(exc)
            self._render_browser_automation_setup()
            return False
        self.browser_extension_page_opened = True
        self.browser_setup_error = ""
        self._render_browser_automation_setup()
        return True

    def _open_browser_extension_folder(self):
        path = str(self.browser_component_status.get("extension_path") or "")
        result = reveal_path_in_file_manager(path)
        if not result.ok:
            self.browser_setup_error = result.error or "系统未能打开扩展目录。"
            self._render_browser_automation_setup()
            return False
        self.browser_setup_error = ""
        self.browser_offline_guidance_visible = True
        self._render_browser_automation_setup()
        return True

    def _copy_browser_extension_path(self):
        path = str(self.browser_component_status.get("extension_path") or "")
        if not path:
            self.browser_setup_error = "扩展目录尚未准备。"
            self._render_browser_automation_setup()
            return False
        QApplication.clipboard().setText(path)
        log_ui_navigation("browser_capability_setup_action", action="copy_extension_path")
        self.browser_setup_error = ""
        self._render_browser_automation_setup()
        self._set_browser_setup_status("✓ 扩展目录路径已复制", "success")
        return True

    def _finish_offline_browser_extension_setup(self):
        browser_id = self.browser_pending_browser_id or self._selected_browser_id()
        self.browser_pending_browser_id = ""
        if browser_id:
            index = self.browser_choice_combo.findData(browser_id)
            if index >= 0:
                self.browser_choice_combo.setCurrentIndex(index)
        errors = []
        try:
            launch_browser_skill_extension_manager(browser_id)
            self.browser_extension_page_opened = True
        except Exception as exc:
            errors.append(str(exc))
        path = str(self.browser_component_status.get("extension_path") or "")
        folder_result = reveal_path_in_file_manager(path)
        if not folder_result.ok:
            errors.append(folder_result.error or "系统未能打开扩展目录。")
        self.browser_offline_guidance_visible = True
        self.browser_setup_error = "；".join(errors)
        self._render_browser_automation_setup()
        return not errors

    def _run_browser_setup_action(self, action):
        action = str(action or "")
        if action == "probe":
            return self._probe_browser_component()
        if action in {"install", "repair", "check"}:
            return self._enqueue_browser_component_action(action)
        if action in {"extension", "store_extension"}:
            return self._open_browser_extension_page()
        if action == "offline_extension":
            return self._prepare_offline_browser_extension()
        if action == "open_extension_manager":
            return self._open_selected_extension_manager()
        if action == "open_extension_folder":
            return self._open_browser_extension_folder()
        if action == "copy_extension_path":
            return self._copy_browser_extension_path()
        if action == "enable":
            if not self.browser_component_status.get("ready"):
                self.browser_setup_error = "浏览器尚未连接，请先完成检查。"
                self._render_browser_automation_setup()
                return False
            return self._set_simple_enabled(True)
        if action == "disable":
            return self._set_simple_enabled(False)
        return False

    def _handle_browser_component_status(self, component_id, status):
        if str(component_id or "") != BROWSER_SKILL_COMPONENT_ID:
            return
        self.browser_component_status = dict(status or {})
        self._render_browser_automation_setup()

    def _handle_browser_component_tasks(self, snapshot):
        self.browser_component_task = dict(
            ((snapshot or {}).get("tasks") or {}).get(BROWSER_SKILL_COMPONENT_ID)
            or {}
        )
        self._render_browser_automation_setup()

    def _handle_browser_component_finished(self, component_id, action, result):
        if str(component_id or "") != BROWSER_SKILL_COMPONENT_ID:
            return
        result = dict(result or {})
        component_status = result.get("result")
        if isinstance(component_status, dict):
            self.browser_component_status = dict(component_status)
            self.browser_component_status["known"] = True
        ok = bool(result.get("ok"))
        error = str(result.get("error") or "")
        log_ui_navigation(
            "browser_capability_setup_result",
            action=str(action or ""),
            ok=ok,
            error=error,
        )
        if not ok:
            self.browser_enable_after_check = False
            if str(action or "") == "prepare_extension":
                self.browser_pending_browser_id = ""
            self.browser_setup_error = error or "操作失败，请重试。"
            self._render_browser_automation_setup()
            return
        self.browser_setup_error = ""
        if str(action or "") == "prepare_extension":
            self._finish_offline_browser_extension_setup()
            return
        should_enable = (
            str(action or "") == "check"
            and self.browser_enable_after_check
            and bool(self.browser_component_status.get("ready"))
        )
        self.browser_enable_after_check = False
        self._render_browser_automation_setup()
        if should_enable:
            QTimer.singleShot(0, lambda: self._set_simple_enabled(True))

    def _build_simple_intro(self, root_layout):
        presentation = capability_presentation(self.skill)
        user_owned = False
        try:
            user_owned = bool(self.skill_manager.is_skill_editable(self.skill_name))
        except Exception:
            user_owned = False
        summary = QLabel(capability_summary(self.skill, user_owned=user_owned))
        summary.setWordWrap(True)
        summary.setStyleSheet(
            f"font-size: {DesignTokens.font_size_body}px; color: {DesignTokens.text_secondary};"
        )
        root_layout.addWidget(summary)
        examples = [
            str(item).strip()
            for item in (presentation.get("examples") or [])
            if str(item).strip()
        ]
        if examples:
            examples_section = ProductSection("适合完成", "", kind="subtle")
            examples_label = QLabel(" · ".join(examples))
            examples_label.setWordWrap(True)
            examples_label.setStyleSheet(
                f"font-size: {DesignTokens.font_size_meta}px; color: {DesignTokens.text_secondary};"
            )
            examples_section.layout.addWidget(examples_label)
            root_layout.addWidget(examples_section)
        access_note = str(presentation.get("access_note") or "").strip()
        if access_note:
            root_layout.addWidget(ProductInlineNotice(access_note, "neutral"))

    def _build_simple_actions(self, root_layout):
        actions = ProductActionBar()
        user_owned = False
        try:
            user_owned = bool(self.skill_manager.is_skill_editable(self.skill_name))
        except Exception as exc:
            log_ui_navigation(
                "capability_ownership_error",
                skill_name=self.skill_name,
                error=str(exc),
            )
        if user_owned:
            advanced_btn = QPushButton("编辑与管理")
            advanced_btn.setStyleSheet(product_button_style("secondary"))
            advanced_btn.clicked.connect(self._open_advanced_workbench)
            actions.layout.insertWidget(actions.layout.count() - 1, advanced_btn)
        if self.skill.get("enabled"):
            disable_btn = QPushButton("关闭能力")
            disable_btn.setStyleSheet(product_button_style("secondary"))
            disable_btn.clicked.connect(lambda checked=False: self._set_simple_enabled(False))
            actions.layout.addWidget(disable_btn)
        elif not self._skill_config_fields():
            enable_btn = QPushButton("开启能力")
            enable_btn.setObjectName("PrimaryBtn")
            enable_btn.setStyleSheet(product_button_style("primary"))
            enable_btn.clicked.connect(lambda checked=False: self._set_simple_enabled(True))
            actions.layout.addWidget(enable_btn)
        root_layout.addWidget(actions)

    def _open_advanced_workbench(self):
        window = self.window()
        if hasattr(window, "show_advanced_capabilities"):
            window.show_advanced_capabilities()
        if hasattr(window, "show_capability_workbench"):
            window.show_capability_workbench(self.skill)

    def _set_simple_enabled(self, enabled):
        name = self.skill_name
        if (
            enabled
            and self._has_authorization()
            and str(self.authorization_status.get("state") or "") != "connected"
        ):
            if hasattr(self, "authorization_notice"):
                self.authorization_notice.set_text(
                    "请先扫码连接并通过企业微信联网验证。",
                    "warning",
                )
            return False
        if (
            enabled
            and self._is_browser_automation()
            and not self.browser_component_status.get("ready")
        ):
            self.browser_setup_error = "浏览器尚未连接，请先完成检查。"
            self._render_browser_automation_setup()
            return False
        log_ui_navigation("capability_enable_begin", skill_name=name, enabled=bool(enabled))
        try:
            self.config_manager.set_skill_enabled(name, bool(enabled))
            window = self.window()
            if hasattr(window, "publish_ui_skill_change"):
                if not window.publish_ui_skill_change(name, "enabled" if enabled else "disabled"):
                    raise RuntimeError("能力目录刷新失败")
                self.skill_manager = window.skill_manager
            self.skill["enabled"] = bool(enabled)
            if hasattr(window, "add_system_toast"):
                window.add_system_toast("能力已开启" if enabled else "能力已关闭", "success", auto_close_ms=3200)
            log_ui_navigation("capability_enable_done", skill_name=name, enabled=bool(enabled))
            if hasattr(window, "handle_product_back"):
                window.handle_product_back()
            return True
        except Exception as exc:
            log_ui_navigation(
                "capability_enable_error",
                skill_name=name,
                enabled=bool(enabled),
                error=str(exc),
            )
            QMessageBox.warning(self, "能力", f"无法更新能力状态：{exc}")
            return False

    def done(self, result):
        worker = self.authorization_status_worker
        if worker is not None and worker.isRunning():
            worker.cancel()
            if not worker.wait(5000):
                QMessageBox.warning(self, "能力", "企业微信连接检测仍在停止，请稍候再关闭。")
                return
        super().done(result)

    def _subtitle_text(self):
        if self._is_mcp_skill():
            return "调试 MCP 连接、查看 tools，并用 JSON 参数直接调用 tool。"
        if self.skill_manager.is_skill_editable(self.skill_name):
            return "编辑用户能力文件、验证结构，并直接调试该能力暴露的工具或脚本。"
        return "内置能力为只读模式，可查看文件并调试已暴露工具。"

    def _is_mcp_skill(self):
        return str(self.skill.get("source_format") or "") == SkillManager.MCP_SOURCE_FORMAT

    def _format_payload(self, value):
        if isinstance(value, str):
            try:
                parsed = json.loads(value)
                return json.dumps(parsed, ensure_ascii=False, indent=2)
            except Exception:
                return value
        try:
            return json.dumps(value, ensure_ascii=False, indent=2)
        except Exception:
            return str(value)

    def _parse_json_editor(self, editor, fallback):
        raw = editor.toPlainText().strip()
        if not raw:
            return fallback
        try:
            return json.loads(raw)
        except Exception as exc:
            QMessageBox.warning(self, "JSON 参数", f"JSON 格式无效：{exc}")
            return None

    def _build_skill_tabs(self):
        self._build_config_tab()
        self._build_files_tab()
        self._build_tool_debug_tab()
        self._build_script_debug_tab()

    def _skill_config_fields(self):
        fields = self.skill.get("config_fields") or []
        if fields:
            return fields
        if hasattr(self.skill_manager, "get_skill_config_fields"):
            return self.skill_manager.get_skill_config_fields(self.skill_name)
        return []

    def _skill_mcp_server_presets(self):
        presets = self.skill.get("mcp_server_presets") or []
        if presets:
            return presets
        if hasattr(self.skill_manager, "get_skill_mcp_server_presets"):
            return self.skill_manager.get_skill_mcp_server_presets(self.skill_name)
        return []

    def _build_config_tab(self):
        fields = [field for field in self._skill_config_fields() if isinstance(field, dict)]
        if not fields:
            return
        page = QWidget()
        page.setObjectName("CapabilityConfigPage")
        page.setMinimumWidth(0)
        page.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 8, 0, 0)
        layout.setSpacing(12)

        if self.skill_name == "web-search":
            hint_text = (
                "选择默认搜索服务并配置可选 API Key。未配置 Key 时将使用供应商官方的匿名/Keyless 模式，"
                "速率与额度较低；服务失败时不会自动切换供应商。"
            )
        elif self.simple_mode:
            hint_text = "填写这项能力需要的设置。必填项缺失时会明确提示，不会静默忽略。"
        else:
            hint_text = "这些配置会在运行该能力的脚本或工具时提供给它。必填项缺失时会直接报错。"
        hint = QLabel(hint_text)
        hint.setWordWrap(True)
        hint.setStyleSheet(apple_settings_inline_note_style())
        layout.addWidget(hint)

        card, card_layout = build_settings_surface(
            "能力设置" if self.simple_mode else "运行配置",
            "保存后，Cowork 下次使用这项能力时生效。"
            if self.simple_mode
            else "保存后下次调试或调用该能力时生效。",
            radius=18,
        )
        form = QFormLayout()
        form.setSpacing(12)
        configure_responsive_form_layout(form)
        values = self.config_manager.get_skill_config(self.skill_name) if hasattr(self.config_manager, "get_skill_config") else {}
        self.config_editors = {}
        for field in fields:
            name = str(field.get("name") or "").strip()
            if not name:
                continue
            current_value = str(values.get(name, "") or field.get("default") or "")
            kind = str(field.get("kind") or "text").lower()
            if kind == "select":
                editor = QComboBox()
                for option in field.get("options") or []:
                    if not isinstance(option, dict):
                        continue
                    option_value = str(option.get("value") or "").strip()
                    if option_value:
                        editor.addItem(str(option.get("label") or option_value), option_value)
                selected_index = editor.findData(current_value)
                if selected_index >= 0:
                    editor.setCurrentIndex(selected_index)
            else:
                editor = QLineEdit()
                editor.setText(current_value)
                editor.setPlaceholderText(str(field.get("placeholder") or ""))
                if kind == "secret":
                    editor.setEchoMode(QLineEdit.Password)
            editor.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            label = str(field.get("label") or name)
            if field.get("required"):
                label += " *"
            help_text = str(field.get("help") or "").strip()
            if help_text:
                editor.setToolTip(help_text)
            action_label = str(field.get("action_label") or "").strip()
            action_url = str(field.get("action_url") or "").strip()
            if action_label or action_url:
                field_row = QWidget()
                field_row.setObjectName("SkillConfigFieldRow")
                field_layout = QHBoxLayout(field_row)
                field_layout.setContentsMargins(0, 0, 0, 0)
                field_layout.setSpacing(8)
                field_layout.addWidget(editor, 1)
                action_btn = QPushButton(action_label or "打开")
                action_btn.setObjectName("SkillConfigActionButton")
                action_btn.setStyleSheet(apple_button_style("secondary", radius=10))
                action_btn.setEnabled(bool(action_label and action_url))
                action_btn.clicked.connect(
                    lambda _checked=False, url=action_url: self._open_skill_config_action_url(url)
                )
                field_layout.addWidget(action_btn)
                form.addRow(build_form_row_label(label), field_row)
            else:
                form.addRow(build_form_row_label(label), editor)
            self.config_editors[name] = editor
            if self.skill_name == SPEECH_TO_TEXT_SKILL_ID:
                if isinstance(editor, QComboBox):
                    editor.currentIndexChanged.connect(self._refresh_config_status)
                else:
                    editor.textChanged.connect(self._refresh_config_status)
        card_layout.addLayout(form)
        layout.addWidget(card)

        self.config_status = QLabel("")
        self.config_status.setWordWrap(True)
        self.config_status.setStyleSheet(apple_settings_inline_note_style())
        layout.addWidget(self.config_status)
        if self.skill_name == SPEECH_TO_TEXT_SKILL_ID:
            self.config_security_notice = ProductInlineNotice("", "warning")
            self.config_security_notice.hide()
            layout.addWidget(self.config_security_notice)

        row = QHBoxLayout()
        row.addStretch()
        save_btn = QPushButton(
            "保存并开启"
            if self.simple_mode and not self.skill.get("enabled")
            else "保存设置"
            if self.simple_mode
            else "保存配置"
        )
        save_btn.setStyleSheet(apple_button_style("primary", radius=14))
        save_btn.clicked.connect(self.save_skill_config)
        row.addWidget(save_btn)
        layout.addLayout(row)

        if self._skill_mcp_server_presets():
            mcp_card, mcp_layout = build_settings_surface(
                "MCP 连接",
                "保存配置后会自动启用对应 MCP。需要确认远端或本地运行状态时，再单独测试连接。",
                radius=18,
            )
            preset_names = [
                str(item.get("name") or item.get("id") or "").strip()
                for item in self._skill_mcp_server_presets()
                if isinstance(item, dict)
            ]
            preset_label = QLabel("托管服务：" + "、".join([name for name in preset_names if name]))
            preset_label.setWordWrap(True)
            preset_label.setStyleSheet(apple_settings_inline_note_style())
            mcp_layout.addWidget(preset_label)
            existing_server = self._configured_managed_mcp_server()
            if existing_server and existing_server.get("enabled", True):
                managed_status_text = "MCP 已启用，连接待测试。"
            elif existing_server:
                managed_status_text = "MCP 已随 Skill 停用。"
            else:
                managed_status_text = "保存配置后可测试连接。"
            self.managed_mcp_status = QLabel(managed_status_text)
            self.managed_mcp_status.setWordWrap(True)
            self.managed_mcp_status.setStyleSheet(apple_settings_inline_note_style())
            mcp_layout.addWidget(self.managed_mcp_status)
            preset_row = QHBoxLayout()
            preset_row.addStretch()
            preset_btn = QPushButton("测试连接")
            preset_btn.setStyleSheet(apple_button_style("secondary", radius=14))
            preset_btn.clicked.connect(self.test_managed_mcp_connection)
            preset_row.addWidget(preset_btn)
            mcp_layout.addLayout(preset_row)
            layout.addWidget(mcp_card)
        layout.addStretch()
        self.config_page_scroll = QScrollArea()
        self.config_page_scroll.setObjectName("CapabilityConfigScroll")
        self.config_page_scroll.setWidgetResizable(True)
        self.config_page_scroll.setFrameShape(QFrame.NoFrame)
        self.config_page_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.config_page_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        self.config_page_scroll.setStyleSheet("QScrollArea#CapabilityConfigScroll { border: none; background: transparent; }")
        self.config_page_scroll.setWidget(page)
        self.tabs.addTab(self.config_page_scroll, "配置")
        self._refresh_config_status()

    def _open_skill_config_action_url(self, value):
        url = QUrl(str(value or "").strip())
        if (
            not url.isValid()
            or url.scheme().lower() != "https"
            or not url.host()
            or url.userName()
            or url.password()
        ):
            QMessageBox.warning(self, "打开链接", "配置链接无效，仅支持不包含凭据的 HTTPS 地址。")
            return False
        if not QDesktopServices.openUrl(url):
            QMessageBox.warning(self, "打开链接", "无法打开浏览器，请检查系统默认浏览器设置。")
            return False
        return True

    def _refresh_config_status(self):
        label = getattr(self, "config_status", None)
        if label is None:
            return
        if not hasattr(self.skill_manager, "get_skill_config_status"):
            label.setText("")
            return
        draft_values = self._current_skill_config_values() if self.config_editors else None
        try:
            status = self.skill_manager.get_skill_config_status(
                self.skill_name,
                values=draft_values,
            )
        except TypeError:
            status = self.skill_manager.get_skill_config_status(self.skill_name)
        missing = status.get("missing_required") or []
        if missing:
            label.setText("还缺少必填配置：" + "、".join(missing))
        elif status.get("config_errors"):
            label.setText("配置还不完整：" + "；".join(status.get("config_errors") or []))
        else:
            label.setText("配置完整。")
        security_notice = getattr(self, "config_security_notice", None)
        if security_notice is not None:
            warning = speech_to_text_http_warning(draft_values)
            security_notice.set_text(warning, "warning")
            security_notice.setVisible(bool(warning))

    def _current_skill_config_values(self):
        values = {}
        for name, editor in self.config_editors.items():
            if isinstance(editor, QComboBox):
                value = str(editor.currentData() or editor.currentText() or "").strip()
            else:
                value = editor.text().strip()
            if value:
                values[name] = value
        return values

    def _save_skill_config_values(self, show_message=True):
        if not hasattr(self.config_manager, "set_skill_config"):
            QMessageBox.warning(self, "能力配置", "当前配置管理器不支持能力配置。")
            return False
        values = self._current_skill_config_values()
        missing_labels = []
        for field in self._skill_config_fields():
            if not isinstance(field, dict) or not field.get("required"):
                continue
            name = str(field.get("name") or "").strip()
            if name and not str(values.get(name) or "").strip():
                missing_labels.append(str(field.get("label") or name))
        if missing_labels:
            message = "还缺少必填配置：" + "、".join(missing_labels)
            if getattr(self, "config_status", None) is not None:
                self.config_status.setText(message)
            QMessageBox.warning(self, "能力设置", message)
            return False
        if self.skill_name == SPEECH_TO_TEXT_SKILL_ID:
            try:
                validate_speech_to_text_config(values)
            except ValueError as exc:
                message = str(exc)
                if getattr(self, "config_status", None) is not None:
                    self.config_status.setText(message)
                QMessageBox.warning(self, "能力设置", message)
                return False
        if hasattr(self.skill_manager, "get_skill_config_status"):
            try:
                draft_status = self.skill_manager.get_skill_config_status(
                    self.skill_name,
                    values=values,
                ) or {}
            except TypeError:
                draft_status = {}
            draft_errors = draft_status.get("config_errors") or []
            if draft_errors:
                message = "配置还不完整：" + "；".join(str(item) for item in draft_errors)
                if getattr(self, "config_status", None) is not None:
                    self.config_status.setText(message)
                QMessageBox.warning(self, "能力设置", message)
                return False
        batch_save = getattr(self.config_manager, "batch_save", None)
        if callable(batch_save):
            with batch_save():
                self.config_manager.set_skill_config(self.skill_name, values)
                managed_result = self._materialize_managed_mcp_servers(publish_refresh=False)
        else:
            self.config_manager.set_skill_config(self.skill_name, values)
            managed_result = self._materialize_managed_mcp_servers(publish_refresh=False)
        if not managed_result.get("ok"):
            QMessageBox.warning(self, "MCP 配置", managed_result.get("error") or "无法启用 MCP。")
            self._refresh_config_status()
            return False
        if managed_result.get("servers") and not self._publish_managed_mcp_refresh():
            QMessageBox.warning(self, "MCP 配置", "MCP 配置已保存，但能力目录刷新失败。")
            self._refresh_config_status()
            return False
        self._refresh_config_status()
        if hasattr(self.skill_manager, "get_skill_config_status"):
            status = self.skill_manager.get_skill_config_status(self.skill_name) or {}
            missing = status.get("missing_required") or []
            config_errors = status.get("config_errors") or []
            if missing or config_errors:
                message = (
                    "还缺少必填配置：" + "、".join(str(item) for item in missing)
                    if missing
                    else "配置还不完整：" + "；".join(str(item) for item in config_errors)
                )
                if getattr(self, "config_status", None) is not None:
                    self.config_status.setText(message)
                QMessageBox.warning(self, "能力设置", message)
                return False
        if show_message:
            message = "配置已保存。"
            if managed_result.get("servers"):
                message = "配置已保存，MCP 已启用；可点击“测试连接”确认可用工具。"
            QMessageBox.information(self, "能力配置", message)
        return True

    def save_skill_config(self):
        log_ui_navigation("capability_config_save_begin", skill_name=self.skill_name)
        try:
            saved = self._save_skill_config_values(show_message=not self.simple_mode)
            if not saved:
                log_ui_navigation("capability_config_save_error", skill_name=self.skill_name, error="save_failed")
                return False
            log_ui_navigation("capability_config_save_done", skill_name=self.skill_name)
            if self.simple_mode:
                window = self.window()
                if not self.skill.get("enabled"):
                    return self._set_simple_enabled(True)
                if hasattr(window, "add_system_toast"):
                    window.add_system_toast("能力设置已保存", "success", auto_close_ms=3200)
            return True
        except Exception as exc:
            log_ui_navigation(
                "capability_config_save_error",
                skill_name=self.skill_name,
                error=str(exc),
            )
            QMessageBox.warning(self, "能力设置", f"保存失败：{exc}")
            return False

    def _publish_managed_mcp_refresh(self):
        window = self.window()
        if hasattr(window, "publish_ui_skill_change"):
            published = bool(window.publish_ui_skill_change(self.skill_name, "updated", source="skill_config"))
            if published and hasattr(window, "skill_manager"):
                self.skill_manager = window.skill_manager
            return published
        self.skill_manager.load_skills(load_mcp_tools=False)
        return True

    def _materialize_managed_mcp_servers(self, publish_refresh=True):
        if not self._skill_mcp_server_presets():
            return {"ok": True, "error": "", "servers": []}
        if not hasattr(self.skill_manager, "build_skill_mcp_server_configs"):
            return {"ok": False, "error": "当前能力管理器不支持生成 MCP 配置。", "servers": []}
        result = self.skill_manager.build_skill_mcp_server_configs(self.skill_name)
        if not result.get("ok"):
            return result
        generated = result.get("servers") or []
        if not generated:
            return {"ok": False, "error": "没有可生成的 MCP 配置。", "servers": []}
        if hasattr(self.config_manager, "upsert_mcp_servers"):
            self.config_manager.upsert_mcp_servers(generated)
        else:
            servers = self.config_manager.get_mcp_servers() if hasattr(self.config_manager, "get_mcp_servers") else []
            by_id = {str(server.get("id") or "").strip(): index for index, server in enumerate(servers)}
            for server in generated:
                server_id = str(server.get("id") or "").strip()
                if server_id in by_id:
                    servers[by_id[server_id]] = server
                else:
                    servers.append(server)
            self.config_manager.set_mcp_servers(servers)
        self.managed_mcp_server = json.loads(json.dumps(generated[0], ensure_ascii=False))
        status = getattr(self, "managed_mcp_status", None)
        if status is not None:
            status.setText("MCP 已启用，连接待测试。")
        if publish_refresh and not self._publish_managed_mcp_refresh():
            return {"ok": False, "error": "MCP 配置已保存，但能力目录刷新失败。", "servers": generated}
        return {"ok": True, "error": "", "servers": generated}

    def _configured_managed_mcp_server(self):
        servers = self.config_manager.get_mcp_servers() if hasattr(self.config_manager, "get_mcp_servers") else []
        for server in servers:
            if str(server.get("source_skill") or "").strip() == self.skill_name:
                return server
        preset_ids = {
            str(item.get("id") or "").strip()
            for item in self._skill_mcp_server_presets()
            if isinstance(item, dict)
        }
        return next((server for server in servers if str(server.get("id") or "").strip() in preset_ids), None)

    def test_managed_mcp_connection(self):
        saved_values = self.config_manager.get_skill_config(self.skill_name) if hasattr(self.config_manager, "get_skill_config") else {}
        if self._current_skill_config_values() != saved_values:
            QMessageBox.warning(self, "测试连接", "当前配置尚未保存，请先保存配置再测试连接。")
            return
        server = self._configured_managed_mcp_server()
        if not server:
            QMessageBox.warning(self, "测试连接", "尚未生成托管 MCP，请先保存配置。")
            return
        if self.mcp_worker and self.mcp_worker.isRunning():
            return
        status = getattr(self, "managed_mcp_status", None)
        if status is not None:
            status.setText(f"正在测试 {server.get('name') or 'MCP'} ...")
        self.mcp_worker = McpConnectionWorker(
            server,
            config_manager=self.config_manager,
            parent=self,
            skill_manager=self.skill_manager,
        )
        self.mcp_worker.finished_signal.connect(self._handle_managed_mcp_test_result)
        self.mcp_worker.finished.connect(self.mcp_worker.deleteLater)
        self.mcp_worker.start()

    def _handle_managed_mcp_test_result(self, result):
        self.mcp_worker = None
        status = getattr(self, "managed_mcp_status", None)
        if status is None:
            return
        if result.get("ok"):
            tools = result.get("tools") or []
            preview = "、".join(tools[:6]) if tools else "未暴露 tools"
            status.setText(f"连接可用，共发现 {result.get('tool_count', 0)} 个工具：{preview}")
            self._publish_managed_mcp_refresh()
            return
        status.setText("连接不可用：" + str(result.get("error") or "未知错误"))

    def _build_files_tab(self):
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 8, 0, 0)
        layout.setSpacing(10)

        splitter = QSplitter(Qt.Horizontal)
        self.file_list = QListWidget()
        self.file_list.setStyleSheet(apple_list_style(border=False, bg=DesignTokens.bg_panel_strong, radius=14, padding=6))
        self.file_list.currentTextChanged.connect(self._load_selected_skill_file)
        splitter.addWidget(self.file_list)

        editor_wrap = QWidget()
        editor_layout = QVBoxLayout(editor_wrap)
        editor_layout.setContentsMargins(0, 0, 0, 0)
        editor_layout.setSpacing(8)
        self.file_status = QLabel("")
        self.file_status.setStyleSheet(apple_settings_inline_note_style())
        editor_layout.addWidget(self.file_status)
        self.file_editor = QTextEdit()
        self.file_editor.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        editor_layout.addWidget(self.file_editor, 1)
        button_row = QHBoxLayout()
        self.validate_btn = QPushButton("验证")
        self.validate_btn.setStyleSheet(apple_button_style("secondary", radius=14))
        self.validate_btn.clicked.connect(self.validate_current_skill)
        self.save_file_btn = QPushButton("保存并重载")
        self.save_file_btn.setStyleSheet(apple_button_style("primary", radius=14))
        self.save_file_btn.clicked.connect(self.save_current_skill_file)
        self.save_file_btn.setVisible(self.skill_manager.is_skill_editable(self.skill_name))
        button_row.addStretch()
        button_row.addWidget(self.validate_btn)
        button_row.addWidget(self.save_file_btn)
        editor_layout.addLayout(button_row)
        splitter.addWidget(editor_wrap)
        splitter.setSizes([260, 720])
        layout.addWidget(splitter, 1)
        self.tabs.addTab(page, "文件")
        self.reload_skill_files()

    def reload_skill_files(self):
        payload = self.skill_manager.list_skill_files(self.skill_name)
        self.file_list.clear()
        if not payload.get("ok"):
            self.file_status.setText(payload.get("error") or "无法读取能力文件。")
            self.file_editor.setReadOnly(True)
            return
        for rel_path in payload.get("files") or []:
            self.file_list.addItem(rel_path)
        editable = bool(payload.get("editable"))
        self.file_editor.setReadOnly(not editable)
        self.file_status.setText("可编辑用户能力。" if editable else "只读：内置能力不能在这里修改。")
        if self.file_list.count():
            self.file_list.setCurrentRow(0)

    def _load_selected_skill_file(self, rel_path):
        self.current_file_path = str(rel_path or "").strip()
        if not self.current_file_path:
            return
        payload = self.skill_manager.read_skill_file(self.skill_name, self.current_file_path)
        if payload.get("ok"):
            self.file_editor.setPlainText(payload.get("content") or "")
            self.file_status.setText(self.current_file_path)
        else:
            self.file_editor.setPlainText("")
            self.file_status.setText(payload.get("error") or "读取失败。")

    def save_current_skill_file(self):
        if not self.current_file_path:
            return
        result = self.skill_manager.write_skill_file(
            self.skill_name,
            self.current_file_path,
            self.file_editor.toPlainText(),
        )
        if not result.get("ok"):
            QMessageBox.warning(self, "保存能力", result.get("error") or "保存失败。")
            return
        owner = self.parent()
        while owner is not None and not hasattr(owner, "publish_ui_skill_change"):
            owner = owner.parent() if hasattr(owner, "parent") else None
        if owner is None or not owner.publish_ui_skill_change(self.skill_name, "updated"):
            QMessageBox.warning(self, "保存能力", "文件已保存，但能力目录刷新失败。")
            return
        self.skill_manager = owner.skill_manager
        validation = result.get("validation") or {}
        if validation.get("ok", True):
            QMessageBox.information(self, "保存能力", "已保存并重新加载能力。")
        else:
            QMessageBox.warning(self, "保存能力", "已保存，但验证发现问题：\n" + "\n".join(validation.get("issues") or []))

    def validate_current_skill(self):
        result = self.skill_manager.validate_skill(self.skill_name)
        if result.get("ok"):
            QMessageBox.information(self, "验证能力", "验证通过。")
        else:
            QMessageBox.warning(self, "验证能力", "\n".join(result.get("issues") or ["验证失败。"]))

    def _build_tool_debug_tab(self):
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 8, 0, 0)
        layout.setSpacing(10)
        self.tool_combo = QComboBox()
        for tool_name in self.skill.get("tools") or []:
            self.tool_combo.addItem(str(tool_name), str(tool_name))
        self.tool_combo.currentIndexChanged.connect(self._refresh_tool_schema)
        layout.addWidget(self.tool_combo)
        self.tool_schema = QTextEdit()
        self.tool_schema.setReadOnly(True)
        self.tool_schema.setFixedHeight(130)
        self.tool_schema.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.tool_schema)
        self.tool_args = QTextEdit()
        self.tool_args.setPlaceholderText('{\n  "arg": "value"\n}')
        self.tool_args.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.tool_args, 1)
        run_row = QHBoxLayout()
        run_row.addStretch()
        run_btn = QPushButton("运行 Tool")
        run_btn.setStyleSheet(apple_button_style("primary", radius=14))
        run_btn.clicked.connect(self.run_selected_tool)
        run_row.addWidget(run_btn)
        layout.addLayout(run_row)
        self.tool_result = QTextEdit()
        self.tool_result.setReadOnly(True)
        self.tool_result.setStyleSheet(apple_code_edit_style(bg=DesignTokens.bg_panel_strong, radius=14, subtle=True, padding=10))
        layout.addWidget(self.tool_result, 1)
        self.tabs.addTab(page, "Tool 调试")
        self._refresh_tool_schema()

    def _refresh_tool_schema(self):
        tool_name = str(self.tool_combo.currentData() or "")
        record = self.skill_manager.get_tool_record(tool_name) if tool_name else None
        if isinstance(record, dict):
            schema = record.get("parameters_schema") or {}
        else:
            schema = getattr(record, "parameters_schema", {}) if record else {}
        self.tool_schema.setPlainText(self._format_payload(schema))

    def _confirm_high_risk_debug(self):
        risk = str(self.skill.get("risk_level") or self.skill.get("security_level") or "").lower()
        if risk != "high":
            return True
        reply = QMessageBox.question(
            self,
            "调试高风险能力",
            "这个能力可能会访问或修改重要内容。确认要继续调试吗？",
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.No,
        )
        return reply == QMessageBox.Yes

    def run_selected_tool(self):
        tool_name = str(self.tool_combo.currentData() or "")
        if not tool_name:
            QMessageBox.warning(self, "Tool 调试", "没有可调试的 tool。")
            return
        if not self._confirm_high_risk_debug():
            return
        args = self._parse_json_editor(self.tool_args, {})
        if args is None:
            return
        self.tool_result.setPlainText("Running...")
        self.tool_worker = SkillToolDebugWorker(self.skill_manager, tool_name, args, self)
        self.tool_worker.finished_signal.connect(self._handle_tool_result)
        self.tool_worker.finished.connect(self.tool_worker.deleteLater)
        self.tool_worker.start()

    def _handle_tool_result(self, result):
        self.tool_worker = None
        self.tool_result.setPlainText(self._format_payload(result.get("result") if result.get("ok") else result))

    def _build_script_debug_tab(self):
        page = QWidget()
        layout = QVBoxLayout(page)
        layout.setContentsMargins(0, 8, 0, 0)
        layout.setSpacing(10)
        self.script_combo = QComboBox()
        for entry in self.skill.get("script_entries") or []:
            if isinstance(entry, dict):
                self.script_combo.addItem(str(entry.get("name") or entry.get("path") or "script"), dict(entry))
        layout.addWidget(self.script_combo)
