    def _start_memory_generation(self, scope):
        if not self._main or not hasattr(self._main, "start_memory_update"):
            QMessageBox.warning(self, "无法更新记忆", "当前窗口没有可用的记忆更新服务。")
            return
        workspace_dir = self.memory_workspace_dir if scope == "workspace" else ""
        self._main.start_memory_update(scope, workspace_dir)
        if hasattr(self._main, "add_system_toast"):
            self._main.add_system_toast(
                "长期记忆正在后台更新，完成后需要确认草稿",
                "info",
                auto_close_ms=5000,
            )

    def _connect_settings_dirty_tracking(self):
        callback = lambda *_args: self._refresh_settings_dirty_state()
        roots = [self] + list(getattr(self, "_settings_pages", []) or [])

        def descendants(widget_type):
            seen = set()
            for root in roots:
                for widget in root.findChildren(widget_type):
                    if id(widget) in seen:
                        continue
                    seen.add(id(widget))
                    yield widget

        for editor in descendants(QLineEdit):
            editor.textChanged.connect(callback)
        for editor in descendants(QTextEdit):
            editor.textChanged.connect(callback)
        for editor in descendants(QPlainTextEdit):
            editor.textChanged.connect(callback)
        for combo in descendants(QComboBox):
            combo.currentIndexChanged.connect(callback)
        for check in descendants(QCheckBox):
            check.toggled.connect(callback)
        for spin in descendants(QSpinBox):
            spin.valueChanged.connect(callback)
        for date_edit in descendants(QDateTimeEdit):
            date_edit.dateTimeChanged.connect(callback)
        for manager in (self.model_channel_manager, self.agent_profile_manager, self.mcp_server_manager):
            manager.changed.connect(callback)
        self.theme_settings_panel.changed.connect(callback)

    @staticmethod
    def _strip_settings_state_metadata(value):
        if isinstance(value, dict):
            return {
                key: SettingsDialog._strip_settings_state_metadata(item)
                for key, item in value.items()
                if key not in {"created_at", "updated_at"}
            }
        if isinstance(value, list):
            return [SettingsDialog._strip_settings_state_metadata(item) for item in value]
        return value

    def _settings_state(self):
        source_state = {}
        for kind in ("python", "node"):
            combo = getattr(self, f"{kind}_source_combo")
            editor = getattr(self, f"{kind}_source_url")
            source_state[kind] = {
                "selected": str(combo.currentData() or ""),
                "url": editor.text().strip(),
            }
        state = {
            "config": {
                "model_channels": self.model_channel_manager.get_channels(),
                "selected_model_id": self.model_channel_manager.get_default_model_id(),
                "agent_profiles": self.agent_profile_manager.get_profiles(),
                "mcp_servers": normalize_mcp_servers(self.mcp_server_manager.get_servers()),
                "default_workspace": self.default_ws_input.text().strip(),
                "history_dir": self.history_dir_input.text().strip(),
                "chat_workspace_root": self.chat_workspace_root_input.text().strip(),
                "god_mode": self.god_mode_check.isChecked(),
                "download_sources": source_state,
            },
            "appearance": self.theme_settings_panel.state_signature(),
            "memory": {
                "soul": self.memory_soul_edit.toPlainText(),
                "global": self.memory_global_edit.toPlainText(),
                "workspace": self.memory_workspace_edit.toPlainText() if self.memory_workspace_dir else "",
                "workspace_dir": self.memory_workspace_dir,
            },
        }
        return self._strip_settings_state_metadata(state)

    @staticmethod
    def _serialize_settings_state(state):
        return json.dumps(state, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

    def _settings_state_signature(self):
        return self._serialize_settings_state(self._settings_state())

    def _refresh_settings_dirty_state(self):
        dirty = self._settings_state_signature() != self._settings_baseline
        self._settings_dirty = dirty
        if hasattr(self, "save_settings_btn"):
            self.save_settings_btn.setEnabled(dirty)
        if hasattr(self, "settings_dirty_label"):
            self.settings_dirty_label.setText("有未保存的修改" if dirty else "没有未保存的修改")

    def _mark_settings_dirty(self):
        self._refresh_settings_dirty_state()

    def _clear_settings_dirty(self):
        self._settings_dirty = False
        self._settings_baseline_state = self._settings_state()
        self._settings_baseline = self._serialize_settings_state(self._settings_baseline_state)
        if hasattr(self, "save_settings_btn"):
            self.save_settings_btn.setEnabled(False)
        if hasattr(self, "settings_dirty_label"):
            self.settings_dirty_label.setText("没有未保存的修改")

    def _confirm_discard_settings(self):
        if self._settings_dirty:
            reply = QMessageBox.question(
                self,
                "还有未保存的设置",
                "关闭后将丢弃尚未保存的修改，确定继续吗？",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if reply != QMessageBox.Yes:
                return False
            self.theme_settings_panel.restore_saved_theme()
        return True

    def request_reject(self):
        if not self._confirm_discard_settings():
            return
        self._allow_close_without_prompt = True
        self._settings_dirty = False
        if self.property("embeddedProductPage") and self._main:
            self._main.show_conversation_page()
            return
        self._clear_settings_dirty()
        self.reject()

    def closeEvent(self, event):
        if not self._allow_close_without_prompt and not self._confirm_discard_settings():
            event.ignore()
            return
        if hasattr(self, "_im_gateway_status_timer"):
            self._im_gateway_status_timer.stop()
        if self._settings_dirty:
            self._clear_settings_dirty()
        event.accept()

    def select_initial_page(self, initial_page_label):
        if not initial_page_label:
            self.nav_list.setCurrentRow(0)
            return
        matches = self.nav_list.findItems(str(initial_page_label), Qt.MatchExactly)
        if not matches:
            raise ValueError(f"未找到设置页：{initial_page_label}")
        self.nav_list.setCurrentItem(matches[0])

    def refresh_archive_lists(self):
        def format_time(timestamp):
            if not timestamp:
                return ""
            try:
                return datetime.fromtimestamp(int(timestamp)).strftime("%Y-%m-%d %H:%M")
            except Exception:
                return ""

        self.archived_project_list.clear()
        for project in self.config_manager.get_projects(include_hidden=True):
            if not project.get("archived") and not project.get("hidden"):
                continue
            path = str(project.get("path") or "")
            name = str(project.get("name") or "").strip() or os.path.basename(path.rstrip(os.sep)) or path
            archived_at = format_time(project.get("archived_at") or project.get("updated_at"))
            suffix = f" · {archived_at}" if archived_at else ""
            item = QListWidgetItem(f"{name}{suffix}\n{path}")
            item.setData(Qt.UserRole, path)
            self.archived_project_list.addItem(item)
        if self.archived_project_list.count() == 0:
            item = QListWidgetItem("暂无已归档项目")
            item.setFlags(Qt.NoItemFlags)
            self.archived_project_list.addItem(item)

        self.archived_conversation_list.clear()
        conversations = []
        if self._main and hasattr(self._main, "chat_storage"):
            conversations = self._main.chat_storage.list_archived_conversations()
        for conversation in conversations:
            title = str(conversation.get("title") or "新任务")
            updated_at = format_time(conversation.get("updated_at"))
            meta = conversation.get("meta") or {}
            workspace_dir = str(meta.get("workspace_dir") or "")
            detail = workspace_dir or "独立对话"
            suffix = f" · {updated_at}" if updated_at else ""
            item = QListWidgetItem(f"{title}{suffix}\n{detail}")
            item.setData(Qt.UserRole, conversation.get("id"))
            self.archived_conversation_list.addItem(item)
        if self.archived_conversation_list.count() == 0:
            item = QListWidgetItem("暂无已归档对话")
            item.setFlags(Qt.NoItemFlags)
            self.archived_conversation_list.addItem(item)
        self.update_archive_action_state()

    def update_archive_action_state(self):
        project_item = self.archived_project_list.currentItem()
        project_path = str(project_item.data(Qt.UserRole) or "") if project_item else ""
        self.restore_project_btn.setEnabled(bool(project_path))
        self.open_archived_project_btn.setEnabled(bool(project_path and os.path.isdir(project_path)))
        conversation_item = self.archived_conversation_list.currentItem()
        conversation_id = str(conversation_item.data(Qt.UserRole) or "") if conversation_item else ""
        self.restore_conversation_btn.setEnabled(bool(conversation_id))

    def restore_selected_archived_project(self):
        item = self.archived_project_list.currentItem()
        path = str(item.data(Qt.UserRole) or "") if item else ""
        if not path:
            return
        self.config_manager.restore_project(path)
        if self._main and hasattr(self._main, "refresh_history_list"):
            self._main.refresh_history_list()
            if hasattr(self._main, "refresh_project_selector"):
                self._main.refresh_project_selector()
        self.refresh_archive_lists()

    def open_selected_archived_project(self):
        item = self.archived_project_list.currentItem()
        path = str(item.data(Qt.UserRole) or "") if item else ""
        if not path:
            return
        if self._main and hasattr(self._main, "reveal_in_explorer"):
            self._main.reveal_in_explorer(path)

    def restore_selected_archived_conversation(self):
        item = self.archived_conversation_list.currentItem()
        conversation_id = str(item.data(Qt.UserRole) or "") if item else ""
        if not conversation_id or not self._main or not hasattr(self._main, "chat_storage"):
            return
        self._main.chat_storage.restore_conversation(conversation_id)
        if hasattr(self._main, "sessions") and conversation_id in self._main.sessions:
            record = self._main.chat_storage.get_conversation_record(conversation_id) or {}
            self._main.sessions[conversation_id].persisted_conversation_meta = copy.deepcopy(record.get("meta") or {})
        if hasattr(self._main, "refresh_history_list"):
            self._main.refresh_history_list()
        self.refresh_archive_lists()

    def _source_config_from_editors(self):
        config = normalize_download_sources(self.download_sources)
        for kind, combo, url_input in (
            ("python", self.python_source_combo, self.python_source_url),
            ("node", self.node_source_combo, self.node_source_url),
        ):
            selected = combo.currentData()
            if selected == "custom" or str(selected).startswith("custom-"):
                url = url_input.text().strip()
                if not url.lower().startswith("https://"):
                    raise ValueError("自定义下载源必须使用 HTTPS。")
                custom_id = "custom-" + uuid.uuid5(uuid.NAMESPACE_URL, url).hex[:12]
                custom_name = url.split("/", 3)[2] if "/" in url else "自定义源"
                custom_item = {"id": custom_id, "name": custom_name, "url": url}
                retained = [item for item in config[kind]["custom"] if item.get("id") not in {selected, custom_id}]
                config[kind]["custom"] = retained + [custom_item]
                config[kind]["selected"] = custom_id
            else:
                config[kind]["selected"] = str(selected)
        return normalize_download_sources(config)

    def _current_component_source(self, kind):
        config = self._source_config_from_editors()
        return selected_source(kind, config)

    def test_component_source(self, kind):
        if self.source_test_worker and self.source_test_worker.isRunning():
            return
        try:
            source = self._current_component_source(kind)
        except Exception as exc:
            QMessageBox.warning(self, "下载源", str(exc))
            return
        button = self.python_source_test_btn if kind == "python" else self.node_source_test_btn
        button.setEnabled(False)
        button.setText("测试中…")
        self.source_test_worker = SourceTestWorker(kind, source, self)
        self.source_test_worker.finished_signal.connect(self.handle_source_test_finished)
        self.source_test_worker.start()

    def handle_source_test_finished(self, result):
        kind = result.get("kind")
        button = self.python_source_test_btn if kind == "python" else self.node_source_test_btn
        button.setEnabled(True)
        button.setText("测试")
        if result.get("ok"):
            QMessageBox.information(self, "下载源", "连接测试成功。")
        else:
            QMessageBox.warning(self, "下载源测试失败", result.get("error") or "无法连接下载源。")
        self.source_test_worker = None

    def _cached_component_status(self, component_id):
        return dict((getattr(self, "component_status_cache", {}) or {}).get(component_id) or {})

    def update_component_row(self, component_id, status):
        row = self.component_rows.get(component_id)
        if not row:
            return
        status = dict(status or {})
        if not status.get("known"):
            row["status"].setText("尚未检测")
            row["action"].setText("检测状态")
            row["repair"].setVisible(False)
            row["progress"].setVisible(False)
            return
        installed = bool(status.get("installed"))
        bundled = bool(status.get("bundled") or (TOOLKITS.get(component_id) or {}).get("bundled"))
        needs_update = bool(status.get("needs_update"))
        needs_repair = bool(status.get("needs_repair"))
        size = int(status.get("size") or 0)
        suffix = f" · {format_file_size(size)}" if size else ""
        source = status.get("source") or ""
        source_suffix = f" · {source}" if source and not bundled else ""
        state_text = (
            "随应用安装"
            if bundled and bool(status.get("healthy"))
            else (
                "随应用安装异常"
                if bundled
                else ("需要更新" if needs_update else ("需要修复" if needs_repair else ("已安装" if installed else "未安装")))
            )
        )
        if (bundled or needs_repair) and status.get("health_error"):
            state_text += f"：{status['health_error']}"
        updated_at = int(status.get("updated_at") or 0)
        recorded_suffix = ""
        if updated_at:
            recorded_suffix = f" · 上次记录 {datetime.fromtimestamp(updated_at).strftime('%m-%d %H:%M')}"
        cache_error = str(status.get("cache_write_error") or "")
        error_suffix = f" · 状态缓存未保存：{cache_error}" if cache_error else ""
        row["status"].setText(state_text + suffix + source_suffix + recorded_suffix + error_suffix)
        if component_id == SPEECH_TO_TEXT_COMPONENT_ID:
            row["action"].setText("卸载" if installed and not needs_update and not needs_repair else "选择安装包")
            row["repair"].setText("重新安装")
        else:
            row["action"].setText("检测状态" if bundled else ("更新" if needs_update else ("卸载" if installed else "安装")))
            row["repair"].setText("修复")
        row["repair"].setVisible(installed and not bundled)
        row["progress"].setVisible(False)

    def toggle_component(self, component_id):
        if not self.component_task_manager:
            QMessageBox.warning(self, "组件管理", "后台组件任务管理器不可用。")
            return
        status = self._cached_component_status(component_id)
        if (TOOLKITS.get(component_id) or {}).get("bundled"):
            self.component_task_manager.probe_component(component_id)
            return
        if not status.get("known"):
            self.component_task_manager.probe_component(component_id)
            return
        action = "repair" if status.get("needs_update") or status.get("needs_repair") else ("uninstall" if status.get("installed") else "install")
        if component_id == SPEECH_TO_TEXT_COMPONENT_ID and action in {"install", "repair"}:
            self.choose_speech_component_package(action)
            return
        if action == "uninstall":
            reply = QMessageBox.question(
                self,
                "卸载组件",
                "确定卸载该组件？相关能力下次使用时可能重新安装依赖。",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if reply != QMessageBox.Yes:
                return
        self.start_component_action(action, component_id)

    def choose_speech_component_package(self, action="install"):
        path, _selected_filter = QFileDialog.getOpenFileName(
            self,
            "选择语音转文字组件安装包",
            "",
            "Cowork 语音组件 (deepseek-cowork-speech-to-text-v*-win-x64.zip);;ZIP 文件 (*.zip)",
        )
        if not path:
            return False
        if not self.component_task_manager or self.component_task_manager.has_task(SPEECH_TO_TEXT_COMPONENT_ID):
            QMessageBox.warning(self, "语音组件", "当前已有语音组件任务正在运行。")
            return False
        log_sub_agent_runtime(
            "speech_component_package_selected",
            action=str(action or "install"),
            package=os.path.basename(path),
        )
        return bool(
            self.component_task_manager.enqueue(
                str(action or "install"),
                SPEECH_TO_TEXT_COMPONENT_ID,
                {"package_path": os.path.abspath(path)},
            )
        )

    def start_component_action(self, action, component_id):
        if not self.component_task_manager:
            QMessageBox.warning(self, "组件管理", "后台组件任务管理器不可用。")
            return
        if self.component_task_manager.has_task(component_id):
            return
        try:
            source = (
                self._current_component_source("node" if component_id == "node" else "python")
                if action in {"install", "repair"}
                and component_id not in {BROWSER_SKILL_COMPONENT_ID, SPEECH_TO_TEXT_COMPONENT_ID}
                else {}
            )
        except Exception as exc:
            QMessageBox.warning(self, "组件管理", str(exc))
            return
        self.component_task_manager.enqueue(action, component_id, source)

    def refresh_all_component_statuses(self):
        if not self.component_task_manager:
            QMessageBox.warning(self, "组件管理", "后台组件任务管理器不可用。")
            return
        snapshot = self.component_task_manager.snapshot()
        has_probes = any(
            task.get("action") == "probe"
            for task in (snapshot.get("tasks") or {}).values()
        )
        if has_probes:
            self.component_task_manager.cancel_component_probes()
            return
        self.component_task_manager.refresh_all_component_statuses()

    def handle_component_status_changed(self, component_id, status):
        self.component_status_cache[str(component_id)] = dict(status or {})
        self.update_component_row(str(component_id), status)

    def handle_component_task_state(self, snapshot):
        tasks = (snapshot or {}).get("tasks") or {}
        queue_lines = []
        for component_id, row in self.component_rows.items():
            task = tasks.get(component_id)
            if not task:
                status = self._cached_component_status(component_id)
                self.update_component_row(component_id, status)
                row["action"].setEnabled(True)
                row["repair"].setEnabled(True)
                continue
            row["action"].setEnabled(False)
            row["repair"].setEnabled(False)
            state = task.get("state")
            if state == "queued":
                position = int(task.get("queue_position") or 0)
                text = f"排队中 · 第 {position} 项"
                queue_lines.append(f"{position}. {component_id}")
                row["progress"].setRange(0, 0)
            else:
                text = task.get("message") or "正在处理…"
                progress = int(task.get("progress") or 0)
                row["progress"].setRange(0, 100)
                row["progress"].setValue(progress)
                queue_lines.insert(0, f"正在处理：{component_id}")
            row["status"].setText(text)
            row["progress"].setVisible(True)
        has_probes = any(task.get("action") == "probe" for task in tasks.values())
        if hasattr(self, "refresh_component_status_btn"):
            self.refresh_component_status_btn.setText("取消刷新" if has_probes else "手动刷新状态")
        self.component_queue_label.setText("\n".join(queue_lines) if queue_lines else "当前没有组件任务。")
        logs = (snapshot or {}).get("logs") or []
        self.component_log_edit.setPlainText("\n".join(logs))
        scrollbar = self.component_log_edit.verticalScrollBar()
        scrollbar.setValue(scrollbar.maximum())

    def refresh_current_version_label(self):
        self.update_current_label.setText(f"当前版本：{APP_VERSION}")

    def showEvent(self, event):
        self.refresh_current_version_label()
        super().showEvent(event)
        if not self._automatic_update_check_started:
            self._automatic_update_check_started = True
            self.start_app_update(check_only=True)

    def start_app_update(self, checked=False, check_only=False):
        if self.app_update_worker and self.app_update_worker.isRunning():
            return
        self.refresh_current_version_label()
        install_enabled = bool(getattr(sys, "frozen", False) and platform.system() == "Windows")
        self.update_btn.setEnabled(False)
        self.local_update_btn.setEnabled(install_enabled and bool(check_only))
        if not check_only:
            self.update_btn.setText("正在检查...")
        self.update_status_label.setText("正在连接 GitHub Releases...")
        if not check_only:
            self.update_log_edit.clear()
            self.append_app_update_log("开始检查更新。")
        self.update_progress.setValue(0)
        self.update_progress.setVisible(install_enabled and not check_only)
        self.app_update_worker = AppUpdateWorker(
            install_enabled=install_enabled,
            check_only=check_only,
            parent=self,
        )
        self.app_update_worker.progress_signal.connect(self.handle_app_update_progress)
        self.app_update_worker.finished_signal.connect(self.handle_app_update_finished)
        self.app_update_worker.finished.connect(self.app_update_worker.deleteLater)
        self.app_update_worker.start()

    def start_local_app_update(self, checked=False):
        install_enabled = bool(getattr(sys, "frozen", False) and platform.system() == "Windows")
        if not install_enabled:
            QMessageBox.warning(self, "本地更新不可用", "本地安装仅适用于 Windows 打包版。")
            return
        path, _selected_filter = QFileDialog.getOpenFileName(
            self,
            "选择本地更新安装包",
            "",
            "DeepSeek Cowork 安装包 (deepseek-cowork-v*.zip);;ZIP 文件 (*.zip)",
        )
        if not path:
            return
        path = os.path.abspath(path)
        package_name = os.path.basename(path)
        try:
            version = local_update_package_version(path)
            package_size = os.path.getsize(path)
        except Exception as exc:
            message = str(exc)
            self.update_status_label.setText(f"本地安装包不可用：{message}")
            self.append_app_update_log(f"本地安装包不可用：{message}")
            log_app_update(
                "local_selected_error",
                package=package_name,
                error_type=type(exc).__name__,
            )
            QMessageBox.warning(self, "本地安装包不可用", message)
            return

        self._pending_local_update_path = path
        self.update_latest_label.setText(f"本地版本：{version}")
        self.update_notes_label.setText("更新日志：本地安装包未携带更新日志。")
        self.update_available_banner.setText(
            f"已选择本地版本 {version}，验证通过后可以安装。"
        )
        self.update_available_banner.setVisible(True)
        self.append_app_update_log(
            f"已选择本地安装包：{package_name}（{format_file_size(package_size)}）。"
        )
        log_app_update(
            "local_selected",
            package=package_name,
            version=version,
            size=package_size,
        )
        worker = self.app_update_worker
        if worker and worker.isRunning():
            if worker.check_only:
                self.local_update_btn.setEnabled(False)
                self.update_status_label.setText("本地安装包已选择，将在当前在线检查结束后立即验证。")
                self.append_app_update_log("等待当前在线检查结束后验证本地安装包。")
                log_app_update("local_queued", package=package_name, version=version)
                return
            self._pending_local_update_path = ""
            QMessageBox.warning(self, "应用更新", "当前更新任务正在运行，请等待任务结束后再选择本地安装包。")
            return
        self._begin_local_app_update(path)

    def _begin_local_app_update(self, path):
        install_enabled = bool(getattr(sys, "frozen", False) and platform.system() == "Windows")
        if not install_enabled:
            self._pending_local_update_path = ""
            self.local_update_btn.setEnabled(False)
            self.update_status_label.setText("本地安装仅适用于 Windows 打包版。")
            return
        if self.app_update_worker and self.app_update_worker.isRunning():
            raise RuntimeError("无法启动本地更新：已有更新任务正在运行。")
        self._pending_local_update_path = ""
        self.refresh_current_version_label()
        self.update_btn.setEnabled(False)
        self.local_update_btn.setEnabled(False)
        self.update_btn.setText("正在验证...")
        self.update_status_label.setText("正在验证本地安装包...")
        self.update_log_edit.clear()
        self.append_app_update_log(f"开始验证本地安装包：{os.path.basename(path)}。")
        self.update_progress.setRange(0, 100)
        self.update_progress.setValue(0)
        self.update_progress.setVisible(True)
        self.app_update_worker = AppUpdateWorker(
            install_enabled=True,
            check_only=False,
            local_zip_path=path,
            parent=self,
        )
        self.app_update_worker.progress_signal.connect(self.handle_app_update_progress)
        self.app_update_worker.finished_signal.connect(self.handle_app_update_finished)
        self.app_update_worker.finished.connect(self.app_update_worker.deleteLater)
        self.app_update_worker.start()

    def handle_app_update_progress(self, message, percent):
        if message:
            self.update_status_label.setText(message)
            self.append_app_update_log(message)
        if percent >= 0:
            self.update_progress.setVisible(True)
            self.update_progress.setValue(max(0, min(100, percent)))

    def append_app_update_log(self, message):
        if not message:
            return
        timestamp = datetime.now().strftime("%H:%M:%S")
        self.update_log_edit.append(f"[{timestamp}] {message}")

    def choose_app_update_install_mode(self, latest_version, zip_path):
        package_line = f"\n安装包位置：{zip_path}" if zip_path else ""
        result = ProductMessageDialog(
            "安装更新",
            f"新版本 {latest_version} 已准备好。{package_line}\n"
            "主程序将关闭，独立更新器会安装更新并自动重启。",
            "confirm",
            [
                ("前台安装并重启", "foreground", "primary", True),
                ("后台安装并重启", "background", "secondary", False),
                ("取消", "cancel", "secondary", False),
            ],
            parent=self,
        ).exec_result("cancel")
        if result == "foreground":
            return "foreground"
        if result == "background":
            return "background"
        return "cancel"

    def handle_app_update_finished(self, result):
        worker = self.app_update_worker
        worker_check_only = bool(getattr(worker, "check_only", False))
        self.refresh_current_version_label()
        self.update_btn.setEnabled(True)
        self.update_btn.setText("检查并更新")
        self.app_update_worker = None
        install_enabled = bool(getattr(sys, "frozen", False) and platform.system() == "Windows")
        self.local_update_btn.setEnabled(install_enabled)
        check_only = bool(
            worker_check_only
            or (isinstance(result, dict) and result.get("check_only"))
        )
        if check_only and self._pending_local_update_path:
            pending_path = self._pending_local_update_path
            self.update_status_label.setText("在线检查已结束，正在开始验证本地安装包...")
            self.append_app_update_log("在线检查已结束，开始处理排队的本地安装包。")
            log_app_update(
                "local_dequeued",
                package=os.path.basename(pending_path),
            )
            self._begin_local_app_update(pending_path)
            return
        if not isinstance(result, dict):
            self.update_status_label.setText("检查更新失败：返回结果无效。")
            self.append_app_update_log("检查更新失败：返回结果无效。")
            return
        update_source = str(result.get("update_source") or "online")
        is_local_update = update_source == "local"
        if result.get("error"):
            message = result.get("error") or "未知错误"
            action_label = "本地安装包验证" if is_local_update else "检查更新"
            self.update_status_label.setText(f"{action_label}失败：{message}")
            if not check_only:
                self.append_app_update_log(f"{action_label}失败：{message}")
                QMessageBox.warning(self, f"{action_label}失败", message)
            return

        release = result.get("release") or {}
        latest_version = release.get("tag_name") or release.get("name") or "未知"
        self.update_latest_label.setText(
            f"本地版本：{latest_version}" if is_local_update else f"最新版本：{latest_version}"
        )
        notes = (release.get("body") or "").strip()
        if notes:
            notes = re.sub(r"\s+", " ", notes)
            if len(notes) > 240:
                notes = notes[:240].rstrip() + "..."
            self.update_notes_label.setText(f"更新日志：{notes}")
        elif is_local_update:
            self.update_notes_label.setText("更新日志：本地安装包未携带更新日志。")
        else:
            self.update_notes_label.setText("更新日志：该 Release 未填写说明。")

        if not result.get("update_available"):
            self.update_available_banner.setVisible(False)
            self.update_nav_item.setText("更新")
            self.update_progress.setVisible(False)
            self.update_status_label.setText("当前已是最新版本。")
            if not check_only:
                self.append_app_update_log("当前已是最新版本。")
                QMessageBox.information(self, "应用更新", "当前已是最新版本。")
            return

        html_url = release.get("html_url") or GITHUB_RELEASES_URL
        if is_local_update:
            self.update_available_banner.setText(f"本地版本 {latest_version} 已通过验证，可以安装。")
        else:
            self.update_available_banner.setText(
                f"发现新版本 {latest_version}，可以更新。点击下方“立即更新”开始下载。"
            )
        self.update_available_banner.setVisible(True)
        self.update_nav_item.setText("更新  •")
        self.update_btn.setText("检查并更新" if is_local_update else "立即更新")
        if check_only:
            self.update_progress.setVisible(False)
            self.update_status_label.setText(
                f"新版本 {latest_version} 已发布，当前版本为 {APP_VERSION}。"
            )
            return

        if not result.get("install_enabled"):
            self.update_progress.setVisible(False)
            self.update_status_label.setText("发现新版本。源码运行模式不会自动替换目录，可打开 Releases 页面手动下载。")
            self.append_app_update_log("源码运行模式只检查版本，不执行自动安装。")
            reply = QMessageBox.question(
                self,
                "发现新版本",
                f"发现新版本 {latest_version}。\n当前处于源码运行模式，不能自动安装。是否打开 GitHub Releases 页面？",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.Yes,
            )
            if reply == QMessageBox.Yes:
                QDesktopServices.openUrl(QUrl(html_url))
            return

        staged_app_dir = result.get("staged_app_dir")
        if not staged_app_dir:
            self.update_status_label.setText("更新包已检查，但没有准备好安装目录。")
            self.append_app_update_log("更新包已检查，但没有准备好安装目录。")
            QMessageBox.warning(self, "应用更新", "更新包已检查，但没有准备好安装目录。")
            return

        self.update_progress.setValue(100)
        zip_path = result.get("zip_path") or ""
        change_summary = result.get("change_summary") or {}
        change_count = (
            int(change_summary.get("added") or 0)
            + int(change_summary.get("modified") or 0)
            + int(change_summary.get("deleted") or 0)
        )
        write_mb = int(change_summary.get("write_bytes") or 0) / (1024 * 1024)
        self.update_status_label.setText(
            f"新版本 {latest_version} 已准备完成，将差异更新 {change_count} 个文件。"
        )
        self.append_app_update_log(
            "本地安装包解压和结构校验完成。"
            if is_local_update
            else "完整安装包下载、解压和结构校验完成。"
        )
        self.append_app_update_log(
            "本地文件比较："
            f"新增 {int(change_summary.get('added') or 0)}，"
            f"修改 {int(change_summary.get('modified') or 0)}，"
            f"删除 {int(change_summary.get('deleted') or 0)}，"
            f"未变化 {int(change_summary.get('unchanged') or 0)}；"
            f"实际写入约 {write_mb:.1f} MB。"
        )
        if zip_path:
            self.append_app_update_log(f"安装包位置：{zip_path}")
        install_mode = self.choose_app_update_install_mode(latest_version, zip_path)
        package_name = str((result.get("asset") or {}).get("name") or os.path.basename(zip_path))
        log_app_update(
            "install_choice",
            source=update_source,
            package=package_name,
            version=latest_version,
            mode=install_mode,
        )
        if install_mode == "cancel":
            self.update_status_label.setText(
                "本地安装包已验证，尚未安装；可以重新选择安装包。"
                if is_local_update
                else "更新已下载，尚未安装。再次点击可重新检查。"
            )
            self.append_app_update_log("用户取消安装；本次安装包已保留，历史更新痕迹已清理。")
            return
        background_install = install_mode == "background"
        try:
            if background_install:
                self.append_app_update_log("正在启动独立更新器，安装将在后台进行。")
            else:
                self.append_app_update_log("正在启动独立更新进度窗口，可在窗口中最小化。")
            log_app_update(
                "installer_launch_start",
                source=update_source,
                package=package_name,
                version=latest_version,
                mode=install_mode,
            )
            launch_log_path = os.path.join(result.get("updates_dir") or get_app_data_dir(), "update-launch.log")
            self.append_app_update_log(f"更新器启动日志：{launch_log_path}")
            extra_wait_pids = []
            if getattr(self._main, "daemon_process", None) and self._main.daemon_process.poll() is None:
                extra_wait_pids.append(self._main.daemon_process.pid)
                self.append_app_update_log(f"更新器将等待守护进程退出：PID {self._main.daemon_process.pid}")
            if getattr(self._main, "gateway_process", None) and self._main.gateway_process.poll() is None:
                extra_wait_pids.append(self._main.gateway_process.pid)
                self.append_app_update_log(f"更新器将等待企业消息网关退出：PID {self._main.gateway_process.pid}")
            script_path = create_windows_update_script(
                install_dir=get_base_dir(),
                staged_app_dir=staged_app_dir,
                change_plan_path=result.get("change_plan_path"),
                current_pid=os.getpid(),
                exe_name=os.path.basename(sys.executable) or "deepseek-cowork.exe",
                target_dir=result.get("updates_dir"),
                extra_wait_pids=extra_wait_pids,
                background_install=background_install,
            )
            launch_windows_update_script(script_path)
            log_app_update(
                "installer_launch_finish",
                source=update_source,
                package=package_name,
                version=latest_version,
                mode=install_mode,
            )
            if hasattr(self._main, "quit_app"):
                self._main.quit_app()
            else:
                QApplication.quit()
        except Exception as exc:
            log_app_update(
                "installer_launch_error",
                source=update_source,
                package=package_name,
                version=latest_version,
                mode=install_mode,
                error_type=type(exc).__name__,
            )
            self.update_status_label.setText(f"启动更新安装失败：{exc}")
            self.append_app_update_log(f"启动更新安装失败：{exc}")
            QMessageBox.warning(self, "应用更新", f"启动更新安装失败：{exc}")

    def _build_im_gateway_experience(self, im_layout, im_cfg):
        providers = (im_cfg or {}).get("providers") or {}
        enabled = (im_cfg or {}).get("enabled_providers") or []
        self.im_selected_provider = enabled[0] if enabled else IM_PROVIDER_ORDER[0]
        self.im_provider_buttons = {}
        self.im_provider_rows = {}
        self.im_provider_icon_labels = {}
        self.im_provider_row_badges = {}
        self.im_provider_statuses = {}
        self.im_provider_detail_badges = {}
        self.im_provider_panels = {}
        self.im_provider_fields = {}
        self.im_provider_checks = {}
        self.im_provider_connect_buttons = {}
        self.im_provider_restart_buttons = {}
        self.im_provider_stop_buttons = {}
        self.im_provider_log_buttons = {}
        self.im_provider_advanced_widgets = {}
        self.im_provider_advanced_toggles = {}
        self.im_runtime_errors = {}

        browse = QWidget()
        browse.setMinimumWidth(270)
        browse_layout = QVBoxLayout(browse)
        browse_layout.setContentsMargins(0, 0, 8, 0)
        browse_layout.setSpacing(10)
        self.im_overview_notice = ProductInlineNotice("", "neutral")
        browse_layout.addWidget(self.im_overview_notice)

        self.im_search_input = QLineEdit()
        self.im_search_input.setPlaceholderText("搜索聊天软件")
        self.im_search_input.setClearButtonEnabled(True)
        self.im_search_input.setVisible(len(IM_PROVIDER_SPECS) > 6)
        self.im_search_input.textChanged.connect(self._filter_im_channels)
        browse_layout.addWidget(self.im_search_input)

        channel_section = ProductSection(
            "聊天软件",
            "同一时间只使用一个，切换后会保留其他软件的连接信息。",
            kind="plain",
        )
        self.im_channel_rows_layout = QVBoxLayout()
        self.im_channel_rows_layout.setContentsMargins(0, 0, 0, 0)
        self.im_channel_rows_layout.setSpacing(0)
        for spec in IM_PROVIDER_SPECS:
            row = ProductDataRow(spec.title, spec.subtitle)
            row.setProperty("imChannelRow", True)
            row.setProperty("providerId", spec.provider_id)
            icon_label = QLabel()
            icon_label.setFixedSize(28, 28)
            icon_label.setAlignment(Qt.AlignCenter)
            icon_label.setProperty("imProviderIcon", spec.icon)
            row.row_layout.insertWidget(0, icon_label)
            badge = ProductStatusBadge("未连接", "neutral")
            action = QPushButton("查看")
            action.setObjectName("SecondaryBtn")
            action.setCursor(Qt.PointingHandCursor)
            action.clicked.connect(
                lambda checked=False, name=spec.provider_id: self._select_im_provider(name)
            )
            row.row_layout.addWidget(badge, 0, Qt.AlignVCenter)
            row.row_layout.addWidget(action, 0, Qt.AlignVCenter)
            self.im_channel_rows_layout.addWidget(row)
            self.im_provider_rows[spec.provider_id] = row
            self.im_provider_icon_labels[spec.provider_id] = icon_label
            self.im_provider_row_badges[spec.provider_id] = badge
            self.im_provider_buttons[spec.provider_id] = action
        channel_section.layout.addLayout(self.im_channel_rows_layout)
        browse_layout.addWidget(channel_section)
        browse_layout.addStretch()

        detail = QWidget()
        detail.setMinimumWidth(400)
        detail_layout = QVBoxLayout(detail)
        detail_layout.setContentsMargins(8, 0, 0, 0)
        detail_layout.setSpacing(10)
        back_btn = QPushButton("返回聊天软件")
        back_btn.setObjectName("SecondaryBtn")
        back_btn.setIcon(qta.icon("fa5s.arrow-left", color=DesignTokens.icon_secondary))
        back_btn.clicked.connect(
            lambda: self.im_master_detail.show_browse()
            if hasattr(self, "im_master_detail")
            else None
        )
        self.im_back_to_channels_btn = back_btn
        detail_layout.addWidget(back_btn, 0, Qt.AlignLeft)

        self.im_provider_stack = QStackedWidget()
        self.im_provider_stack.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        for spec in IM_PROVIDER_SPECS:
            panel = self._build_im_provider_detail(
                spec,
                providers.get(spec.provider_id) or {},
            )
            self.im_provider_panels[spec.provider_id] = panel
            self.im_provider_stack.addWidget(panel)
        detail_layout.addWidget(self.im_provider_stack, 1)

        self.im_master_detail = ProductMasterDetail(browse, detail)
        self.im_master_detail.setMinimumHeight(420)
        im_layout.addWidget(self.im_master_detail)
        self._layout_sync_timer.start(0)
        self._refresh_im_channel_theme()
        bind_theme(
            self.im_master_detail,
            self._refresh_im_channel_theme,
            surface="management",
        )
        self._refresh_im_action_theme()
        self._select_im_provider(self.im_selected_provider, show_detail=False)

    def _ensure_im_master_detail_layout(self):
        master = getattr(self, "im_master_detail", None)
        if master is None:
            return
        if hasattr(self, "im_back_to_channels_btn"):
            self.im_back_to_channels_btn.setVisible(bool(master._compact))
        if master._compact:
            return
        master.browse.show()
        master.detail.show()
        total = max(700, master.width())
        browse_width = min(340, max(280, total // 3))
        master.splitter.setSizes([browse_width, max(400, total - browse_width)])

    def _build_im_provider_detail(self, spec, config):
        panel = QWidget()
        layout = QVBoxLayout(panel)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(10)

        header = ProductSection(spec.title, spec.description, kind="plain")
        badge = ProductStatusBadge("未连接", "neutral")
        header.layout.addWidget(badge, 0, Qt.AlignLeft)
        self.im_provider_detail_badges[spec.provider_id] = badge
        layout.addWidget(header)

        status = ProductInlineNotice("", "neutral")
        status.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self.im_provider_statuses[spec.provider_id] = status
        layout.addWidget(status)

        if spec.auth_kind == "qr":
            steps = ProductSection(
                "三步完成",
                f"1. 点击下方按钮生成二维码\n"
                f"2. 使用手机{spec.title}扫码并确认\n"
                "3. 返回聊天软件发送一条文字消息测试",
                kind="subtle",
            )
            layout.addWidget(steps)
            self.im_provider_fields[spec.provider_id] = {}
        else:
            form_section = ProductSection(
                "连接信息",
                "这些信息只保存在当前设备。保存失败时不会清空你的输入。",
                kind="subtle",
            )
            basic_form = QFormLayout()
            basic_form.setSpacing(10)
            configure_responsive_form_layout(basic_form)
            advanced_form = QFormLayout()
            advanced_form.setSpacing(10)
            configure_responsive_form_layout(advanced_form)
            fields = {}
            for field in spec.fields:
                editor = QLineEdit(str(config.get(field.key) or ""))
                editor.setPlaceholderText(field.placeholder)
                editor.setEchoMode(
                    QLineEdit.Password if field.secret else QLineEdit.Normal
                )
                editor.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                target_form = advanced_form if field.advanced else basic_form
                target_form.addRow(build_form_row_label(field.label), editor)
                fields[field.key] = editor
            form_section.layout.addLayout(basic_form)
            advanced_widget = QWidget()
            advanced_widget.setLayout(advanced_form)
            advanced_widget.hide()
            if any(field.advanced for field in spec.fields):
                toggle = QToolButton()
                toggle.setText("高级设置")
                toggle.setCheckable(True)
                toggle.setToolButtonStyle(Qt.ToolButtonTextBesideIcon)
                toggle.setArrowType(Qt.RightArrow)
                toggle.toggled.connect(
                    lambda checked, name=spec.provider_id: self._set_im_advanced_visible(
                        name,
                        checked,
                    )
                )
                form_section.layout.addWidget(toggle, 0, Qt.AlignLeft)
                form_section.layout.addWidget(advanced_widget)
                self.im_provider_advanced_toggles[spec.provider_id] = toggle
                self.im_provider_advanced_widgets[spec.provider_id] = advanced_widget
            self.im_provider_fields[spec.provider_id] = fields
            layout.addWidget(form_section)

        actions = ProductActionBar()
        connect_btn = QPushButton(spec.connect_label)
        connect_btn.setObjectName("PrimaryBtn")
        if spec.auth_kind == "qr":
            connect_btn.clicked.connect(
                lambda checked=False, name=spec.provider_id: self._connect_qr_im_provider(name)
            )
        else:
            connect_btn.clicked.connect(
                lambda checked=False, name=spec.provider_id: self._connect_form_im_provider(name)
            )
        restart_btn = QPushButton("使用现有连接重新启动")
        restart_btn.setObjectName("SecondaryBtn")
        restart_btn.clicked.connect(
            lambda checked=False, name=spec.provider_id: self._restart_existing_im_provider(name)
        )
        stop_btn = QPushButton("停止使用")
        stop_btn.setObjectName("SecondaryBtn")
        stop_btn.clicked.connect(self._stop_im_gateway)
        log_btn = QPushButton("查看诊断日志")
        log_btn.setObjectName("SecondaryBtn")
        log_btn.clicked.connect(self._open_im_gateway_log)
        actions.layout.addWidget(log_btn)
        actions.layout.addWidget(stop_btn)
        actions.layout.addWidget(restart_btn)
        actions.layout.addWidget(connect_btn)
        layout.addWidget(actions)
        layout.addStretch()

        self.im_provider_connect_buttons[spec.provider_id] = connect_btn
        self.im_provider_restart_buttons[spec.provider_id] = restart_btn
        self.im_provider_stop_buttons[spec.provider_id] = stop_btn
        self.im_provider_log_buttons[spec.provider_id] = log_btn

        if spec.provider_id == "feishu":
            self.feishu_connect_btn = connect_btn
            self.feishu_restart_btn = restart_btn
            self.feishu_fields = {}
        elif spec.provider_id == "dingtalk":
            self.dingtalk_fields = self.im_provider_fields[spec.provider_id]
        elif spec.provider_id == "wecom":
            self.wecom_fields = self.im_provider_fields[spec.provider_id]
            legacy_wecom = any(
                str(config.get(key) or "").strip()
                for key in ("bot_key", "webhook_url", "ws_url")
            ) and not spec.is_configured(config)
            if legacy_wecom:
                layout.insertWidget(
                    2,
                    ProductInlineNotice(
                        "检测到旧版企业微信连接，请重新填写 Bot ID 和 Secret。",
                        "warning",
                    ),
                )
        return panel

    def _set_im_advanced_visible(self, provider_name, visible):
        widget = self.im_provider_advanced_widgets.get(provider_name)
        toggle = self.im_provider_advanced_toggles.get(provider_name)
        if widget is not None:
            widget.setVisible(bool(visible))
        if toggle is not None:
            toggle.setArrowType(Qt.DownArrow if visible else Qt.RightArrow)

    def _filter_im_channels(self, query):
        needle = str(query or "").strip().lower()
        for spec in IM_PROVIDER_SPECS:
            haystack = " ".join(
                (spec.title, spec.subtitle, spec.description, spec.provider_id)
            ).lower()
            row = self.im_provider_rows.get(spec.provider_id)
            if row is not None:
                row.setVisible(not needle or needle in haystack)

    def _select_im_provider(self, provider_name, show_detail=True):
        name = str(provider_name or "").strip().lower()
        if name not in IM_PROVIDER_ORDER:
            return
        self.im_selected_provider = name
        panel = self.im_provider_panels.get(name)
        if panel:
            self.im_provider_stack.setCurrentWidget(panel)
        for provider_id, row in getattr(self, "im_provider_rows", {}).items():
            row.setProperty("selected", provider_id == name)
            row.style().unpolish(row)
            row.style().polish(row)
        if show_detail and hasattr(self, "im_master_detail"):
            self.im_master_detail.show_detail()
        self._refresh_im_provider_states()

    def _refresh_im_channel_theme(self, _resolved=None):
        row_style = (
            f'QFrame[imChannelRow="true"] {{ background:transparent; border:none; '
            f'border-bottom:1px solid {DesignTokens.separator}; }}'
            f'QFrame[imChannelRow="true"][selected="true"] {{ '
            f'background:{DesignTokens.primary_soft}; '
            f'border-radius:{DesignTokens.radius_sm}px; }}'
        )
        for name, row in getattr(self, "im_provider_rows", {}).items():
            row.setStyleSheet(row_style)
            spec = get_provider_spec(name)
            icon_label = getattr(self, "im_provider_icon_labels", {}).get(name)
            if spec and icon_label is not None:
                try:
                    icon = qta.icon(spec.icon, color=DesignTokens.icon_secondary)
                except Exception:
                    icon = qta.icon(
                        "fa5s.comment-dots",
                        color=DesignTokens.icon_secondary,
                    )
                icon_label.setPixmap(icon.pixmap(18, 18))
                icon_label.setStyleSheet(
                    f"background:{DesignTokens.bg_secondary}; border:none; "
                    f"border-radius:{DesignTokens.radius_sm}px;"
                )
        for button in getattr(self, "im_provider_buttons", {}).values():
            button.setStyleSheet(product_button_style("secondary"))

    def _refresh_im_action_theme(self, _resolved=None):
        for button in getattr(self, "im_provider_stop_buttons", {}).values():
            button.setIcon(
                qta.icon("fa5s.stop", color=DesignTokens.icon_secondary)
            )
        for button in getattr(self, "im_provider_log_buttons", {}).values():
            button.setIcon(
                qta.icon("fa5s.file-alt", color=DesignTokens.icon_secondary)
            )

    def _resize_im_provider_stack(self):
        return

    @staticmethod
    def _im_provider_is_configured(provider_name, config):
        spec = get_provider_spec(provider_name)
        return bool(spec and spec.is_configured(config))

    def _refresh_im_provider_states(self):
        if not hasattr(self, "im_provider_rows"):
            return
        cfg = normalize_im_gateway_config(self.config_manager.get("im_gateway", {}))
        providers = cfg["providers"]
        active = (cfg.get("enabled_providers") or [""])[0]
        running = bool(
            self._main
            and getattr(self._main, "gateway_process", None)
            and self._main.gateway_process.poll() is None
        )
        runtime_status = read_im_gateway_status()
        runtime_state = (
            runtime_status.get("state")
            if runtime_status.get("provider") == active
            else ""
        )
        runtime_error = str(runtime_status.get("error") or "")
        if runtime_state == "error" and runtime_error:
            self.im_runtime_errors[active] = runtime_error
        for spec in IM_PROVIDER_SPECS:
            name = spec.provider_id
            configured = spec.is_configured(providers.get(name))
            provider_error = self.im_runtime_errors.get(name, "")
            if name == active and provider_error:
                status_text = "连接失败"
                tone = "error"
            elif name == active and running and runtime_state == "connected":
                status_text = "使用中"
                tone = "success"
            elif name == active and running and runtime_state == "reconnecting":
                status_text = "重连中"
                tone = "warning"
            elif name == active and running and runtime_state == "connecting":
                status_text = "连接中"
                tone = "primary"
            elif name == active and running:
                status_text = "连接中"
                tone = "primary"
            elif name == active:
                status_text = "已配置，未运行"
                tone = "warning"
            elif configured:
                status_text = "已停用"
                tone = "neutral"
            else:
                status_text = "未连接"
                tone = "neutral"
            badge = self.im_provider_row_badges.get(name)
            if badge is not None:
                badge.setText(status_text)
                badge.set_tone(tone)
            detail_badge = self.im_provider_detail_badges.get(name)
            if detail_badge is not None:
                detail_badge.setText(status_text)
                detail_badge.set_tone(tone)
            action = self.im_provider_buttons.get(name)
            if action is not None:
                action.setText("管理" if name == active else ("查看" if configured else "接入"))
            notice = self.im_provider_statuses[name]
            if name == active and running and runtime_state == "connected":
                notice.set_text(
                    f"{spec.title}正在使用中，收到的文字和链接会交给默认主助手处理。",
                    "success",
                )
            elif name == active and running and runtime_state == "reconnecting":
                notice.set_text(
                    f"{spec.title}连接暂时中断，正在自动重连。",
                    "warning",
                )
            elif name == active and running and runtime_state == "error":
                notice.set_text(
                    f"连接失败：{runtime_error or '平台认证或连接失败。'}",
                    "error",
                )
            elif name == active and running:
                notice.set_text(f"正在连接{spec.title}…", "info")
            elif name == active and provider_error:
                notice.set_text(
                    f"连接失败：{provider_error}",
                    "error",
                )
            elif name == active and configured:
                notice.set_text(
                    f"{spec.title}的连接信息已保存，但目前没有运行。",
                    "warning",
                )
            elif configured:
                notice.set_text(
                    f"{spec.title}的连接信息已保留，切换回来即可继续使用。",
                    "neutral",
                )
            else:
                notice.set_text(
                    f"尚未连接{spec.title}。连接后即可直接发消息安排任务。",
                    "neutral",
                )
            connect_btn = self.im_provider_connect_buttons.get(name)
            if connect_btn is not None:
                connect_btn.setText(
                    spec.reconnect_label if configured else spec.connect_label
                )
            restart_btn = self.im_provider_restart_buttons.get(name)
            if restart_btn is not None:
                restart_btn.setVisible(configured)
            stop_btn = self.im_provider_stop_buttons.get(name)
            if stop_btn is not None:
                stop_btn.setVisible(name == active)

        self._order_im_channel_rows(active)
        active_error = self.im_runtime_errors.get(active, "")
        if active and active_error:
            self.im_overview_notice.set_text(
                f"{provider_title(active)}连接失败：{active_error}",
                "error",
            )
        elif active and running and runtime_state == "connected":
            self.im_overview_notice.set_text(
                f"当前通过{provider_title(active)}接收消息。",
                "success",
            )
        elif active:
            self.im_overview_notice.set_text(
                f"已选择{provider_title(active)}，当前未运行。",
                "warning",
            )
        else:
            self.im_overview_notice.set_text(
                "选择一个常用聊天软件开始连接。",
                "neutral",
            )

    def _order_im_channel_rows(self, active):
        order = [active] if active in IM_PROVIDER_ORDER else []
        order.extend(name for name in IM_PROVIDER_ORDER if name not in order)
        for index, name in enumerate(order):
            row = self.im_provider_rows.get(name)
            if row is not None:
                self.im_channel_rows_layout.removeWidget(row)
                self.im_channel_rows_layout.insertWidget(index, row)

    def _connect_feishu(self):
        self._connect_qr_im_provider("feishu")

    def _connect_qr_im_provider(self, provider_name):
        name = str(provider_name or "").strip().lower()
        spec = get_provider_spec(name)
        if spec is None or spec.auth_kind != "qr":
            return
        cfg = normalize_im_gateway_config(self.config_manager.get("im_gateway", {}))
        current = dict(cfg["providers"].get(name) or {})
        dialog = ChannelQrDialog(name, current, parent=self)
        if dialog.exec() != QDialog.Accepted:
            return
        credentials = dict(dialog.credentials or {})
        if name == "feishu":
            credentials["long_connection"] = True
        self._commit_im_provider(name, credentials)

    def _restart_existing_feishu(self):
        self._restart_existing_im_provider("feishu")

    def _restart_existing_im_provider(self, provider_name):
        name = str(provider_name or "").strip().lower()
        spec = get_provider_spec(name)
        if spec is None:
            return
        cfg = normalize_im_gateway_config(self.config_manager.get("im_gateway", {}))
        values = dict(cfg["providers"].get(name) or {})
        if not spec.is_configured(values):
            self.im_provider_statuses[name].set_text(
                f"{spec.title}还没有可用的连接信息，请先完成接入。",
                "error",
            )
            return
        if name == "feishu":
            values["long_connection"] = True
        self._commit_im_provider(name, values)

    def _connect_form_im_provider(self, provider_name):
        name = str(provider_name or "").strip().lower()
        spec = get_provider_spec(name)
        if spec is None or spec.auth_kind != "form":
            return
        fields = self.im_provider_fields.get(name) or {}
        values = {key: editor.text().strip() for key, editor in fields.items()}
        field_by_key = {field.key: field for field in spec.fields}
        missing_keys = [key for key in spec.required_keys if not values.get(key)]
        missing = [
            field_by_key[key].label if key in field_by_key else key
            for key in missing_keys
        ]
        if missing:
            message = "请填写：" + "、".join(missing)
            self.im_provider_statuses[name].set_text(message, "error")
            if any(
                field_by_key.get(key) and field_by_key[key].advanced
                for key in missing_keys
            ):
                toggle = self.im_provider_advanced_toggles.get(name)
                if toggle is not None:
                    toggle.setChecked(True)
            first_editor = fields.get(missing_keys[0]) if missing_keys else None
            if first_editor is not None:
                first_editor.setFocus(Qt.OtherFocusReason)
            return
        self._commit_im_provider(name, values)

    def _commit_im_provider(self, provider_name, provider_values):
        name = str(provider_name or "").strip().lower()
        try:
            current = normalize_im_gateway_config(self.config_manager.get("im_gateway", {}))
            target = update_selected_provider(current, name, provider_values)
            self.config_manager.set("im_gateway", target)
        except Exception as exc:
            self.im_provider_statuses[name].set_text(f"保存失败：{exc}", "error")
            return
        append_background_process_log("im_gateway.log", f"{name} connect requested")
        self.im_runtime_errors.pop(name, None)
        write_im_gateway_status(name, "connecting")
        self._select_im_provider(name, show_detail=False)
        self.im_provider_statuses[name].set_text(
            f"连接信息已保存，正在启动{provider_title(name)}…",
            "info",
        )
        if not self._main:
            self.im_provider_statuses[name].set_text("配置已保存，但当前窗口无法启动网关。", "error")
            return
        try:
            if hasattr(self._main, "stop_gateway_process"):
                self._main.stop_gateway_process()
            if hasattr(self._main, "queue_daemon_connection"):
                self._main.queue_daemon_connection(allow_start=True, retries=6)
            elif hasattr(self._main, "try_connect_daemon"):
                self._main.try_connect_daemon(allow_start=True, retries=6)
            if not hasattr(self._main, "start_gateway_process"):
                raise RuntimeError("当前窗口没有企业消息网关启动能力。")
            started = self._main.start_gateway_process()
            if started is False:
                raise RuntimeError(
                    str(getattr(self._main, "gateway_last_error", "") or "无法启动企业消息网关进程。")
                )
            QTimer.singleShot(
                GATEWAY_START_SETTLE_DELAY_MS + 500,
                lambda selected=name: self._verify_im_gateway_start(selected),
            )
        except Exception as exc:
            append_background_process_log(
                "im_gateway.log",
                f"{name} connect launch failed error={exc}",
            )
            self.im_provider_statuses[name].set_text(
                f"配置已保存，接入失败：{exc}",
                "error",
            )

    def _latest_im_gateway_error(self):
        log_path = os.path.join(get_app_data_dir(), "im_gateway.log")
        try:
            with open(log_path, "r", encoding="utf-8", errors="replace") as handle:
                lines = handle.readlines()[-60:]
        except Exception:
            return ""
        markers = (" failed", " error=", " missing", " unavailable", "不可用", "未配置")
        for line in reversed(lines):
            text = line.strip()
            lowered = text.lower()
            if any(marker in lowered for marker in markers):
                return text.split("] ", 1)[-1]
        return ""

    def _verify_im_gateway_start(self, provider_name):
        running = bool(
            self._main
            and getattr(self._main, "gateway_process", None)
            and self._main.gateway_process.poll() is None
        )
        if running:
            runtime_status = read_im_gateway_status()
            if (
                runtime_status.get("provider") == provider_name
                and runtime_status.get("state") == "error"
            ):
                reason = runtime_status.get("error") or "平台认证或连接失败。"
                self.im_runtime_errors[provider_name] = reason
            else:
                self.im_runtime_errors.pop(provider_name, None)
        else:
            reason = self._latest_im_gateway_error() or "网关进程未能保持运行，请打开日志查看详情。"
            self.im_runtime_errors[provider_name] = reason
            self.im_provider_statuses[provider_name].set_text(
                f"配置已保存，接入失败：{reason}",
                "error",
            )
        self._refresh_im_provider_states()

    def _stop_im_gateway(self):
        try:
            target = disable_im_gateway(self.config_manager.get("im_gateway", {}))
            self.config_manager.set("im_gateway", target)
            if self._main and hasattr(self._main, "stop_gateway_process"):
                self._main.stop_gateway_process()
            append_background_process_log("im_gateway.log", "enterprise message gateway stopped by user")
            write_im_gateway_status("", "stopped")
            self.im_runtime_errors.clear()
        except Exception as exc:
            selected = getattr(self, "im_selected_provider", "")
            notice = self.im_provider_statuses.get(selected)
            if notice is not None:
                notice.set_text(f"停止失败：{exc}", "error")
            return
        self._refresh_im_provider_states()

    def _open_im_gateway_log(self):
        log_path = os.path.join(get_app_data_dir(), "im_gateway.log")
        try:
            if not os.path.exists(log_path):
                with open(log_path, "a", encoding="utf-8"):
                    pass
            os.startfile(log_path)
        except Exception:
            QMessageBox.information(self, "企业消息网关日志", log_path)

    def _save_im_gateway_config(self):
        """Enterprise-message settings are committed by their local action."""
        return normalize_im_gateway_config(self.config_manager.get("im_gateway", {}))

    def save_settings(self):
        self.requires_skill_reload = False
        selected_model_id = self.model_channel_manager.get_default_model_id()
        model_channels = self.model_channel_manager.get_channels()
        mcp_servers = normalize_mcp_servers(self.mcp_server_manager.get_servers())
        current_mcp_servers = self.config_manager.get_mcp_servers()
        all_model_ids = [
            model.get("id")
            for channel in model_channels
            for model in (channel.get("models") or [])
            if model.get("id")
        ]
        if all_model_ids and selected_model_id not in all_model_ids:
            log_model_service_event("default_model_save_rejected", reason="selection_required")
            QMessageBox.warning(self, "请选择默认模型", "默认模型未选择或已删除，请在“模型与服务”重新选择后保存。")
            return
        if self.god_mode_check.isChecked() and not self.config_manager.get_god_mode():
            reply = QMessageBox.question(
                self,
                "确认开启扩展权限",
                "扩展权限模式会突破工作区限制，并允许更高风险的执行操作。确定要开启吗？",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if reply != QMessageBox.Yes:
                self.god_mode_check.setChecked(False)
        try:
            pending_download_sources = self._source_config_from_editors()
        except ValueError as exc:
            QMessageBox.warning(self, "下载源", str(exc))
            return
        current_state = self._settings_state()
        baseline_state = self._settings_baseline_state
        current_config_state = current_state["config"]
        baseline_config_state = baseline_state["config"]
        config_changed = current_config_state != baseline_config_state
        appearance_changed = (
            current_state["appearance"] != baseline_state["appearance"]
            or self.theme_settings_panel.has_active_preview()
        )
        target_history_dir = self.history_dir_input.text().strip()
        history_dir_changed = (
            current_config_state["history_dir"] != baseline_config_state["history_dir"]
        )
        current_memory_state = current_state["memory"]
        baseline_memory_state = baseline_state["memory"]
        memory_write_scopes = set()
        if history_dir_changed or current_memory_state["soul"] != baseline_memory_state["soul"]:
            memory_write_scopes.add("soul")
        if history_dir_changed or current_memory_state["global"] != baseline_memory_state["global"]:
            memory_write_scopes.add("global")
        if self.memory_workspace_dir and (
            history_dir_changed
            or current_memory_state["workspace"] != baseline_memory_state["workspace"]
        ):
            memory_write_scopes.add("workspace")
        target_memory_store = self.memory_store
        previous_memory = {}
        if memory_write_scopes:
            if history_dir_changed:
                target_memory_store = MemoryStore(target_history_dir)
            if "soul" in memory_write_scopes:
                previous_memory["soul"] = target_memory_store.read_soul()
            if "global" in memory_write_scopes:
                previous_memory["global"] = target_memory_store.read_summary("global", "")
            if "workspace" in memory_write_scopes:
                previous_memory["workspace"] = target_memory_store.read_summary(
                    "workspace",
                    self.memory_workspace_dir,
                )
        previous_config = {}
        if config_changed:
            previous_config = {
                "model_channels": self.config_manager.get_model_channels(),
                "selected_model_id": self.config_manager.get_selected_model_id(),
                "agent_profiles": self.config_manager.get_agent_profiles(),
                "mcp_servers": self.config_manager.get_mcp_servers(),
                "default_workspace": self.config_manager.get("default_workspace", ""),
                "history_dir": self.config_manager.get_chat_history_dir(),
                "chat_workspace_root": self.config_manager.get_chat_workspace_root(),
                "god_mode": self.config_manager.get_god_mode(),
                "download_sources": self.config_manager.get("download_sources", {}),
            }
        if config_changed:
            log_model_service_event("default_model_save_started", model_id=selected_model_id)
        try:
            if "soul" in memory_write_scopes:
                target_memory_store.save_soul(current_memory_state["soul"])
            if "global" in memory_write_scopes:
                target_memory_store.save_summary(current_memory_state["global"], "global", "")
            if "workspace" in memory_write_scopes:
                target_memory_store.save_summary(
                    current_memory_state["workspace"],
                    "workspace",
                    self.memory_workspace_dir,
                )
            if config_changed:
                with self.config_manager.batch_save():
                    self.config_manager.set_model_channels(model_channels, selected_model_id)
                    self.config_manager.set_agent_profiles(self.agent_profile_manager.get_profiles())
                    self.config_manager.set_mcp_servers(mcp_servers)
                    self.config_manager.set(
                        "default_workspace",
                        current_config_state["default_workspace"],
                    )
                    self.config_manager.set_chat_history_dir(target_history_dir)
                    self.config_manager.set_chat_workspace_root(
                        current_config_state["chat_workspace_root"]
                    )
                    self.config_manager.set_god_mode(current_config_state["god_mode"])
                    self.download_sources = pending_download_sources
                    self.config_manager.set("download_sources", self.download_sources)
            if appearance_changed:
                self.theme_settings_panel.commit()
        except Exception as exc:
            if config_changed:
                log_model_service_event("default_model_save_failed", error_type=type(exc).__name__)
            try:
                if appearance_changed:
                    self.theme_settings_panel.restore_saved_theme()
                if "soul" in memory_write_scopes:
                    target_memory_store.save_soul(previous_memory["soul"])
                if "global" in memory_write_scopes:
                    target_memory_store.save_summary(previous_memory["global"], "global", "")
                if "workspace" in memory_write_scopes:
                    target_memory_store.save_summary(
                        previous_memory["workspace"],
                        "workspace",
                        self.memory_workspace_dir,
                    )
                if config_changed:
                    with self.config_manager.batch_save():
                        self.config_manager.set_model_channels(
                            previous_config["model_channels"],
                            previous_config["selected_model_id"],
                        )
                        self.config_manager.set_agent_profiles(previous_config["agent_profiles"])
                        self.config_manager.set_mcp_servers(previous_config["mcp_servers"])
                        self.config_manager.set(
                            "default_workspace",
                            previous_config["default_workspace"],
                        )
                        self.config_manager.set_chat_history_dir(previous_config["history_dir"])
                        self.config_manager.set_chat_workspace_root(
                            previous_config["chat_workspace_root"]
                        )
                        self.config_manager.set_god_mode(previous_config["god_mode"])
                        self.config_manager.set(
                            "download_sources",
                            previous_config["download_sources"],
                        )
            except Exception as rollback_exc:
                QMessageBox.critical(
                    self,
                    "保存设置失败",
                    f"保存失败：{exc}\n回滚也未完成：{rollback_exc}",
                )
                return
            QMessageBox.critical(self, "保存设置失败", f"所有修改已回滚：{exc}")
            return
        if config_changed:
            log_model_service_event("default_model_save_completed", model_id=selected_model_id)
        if memory_write_scopes:
            self.memory_store = target_memory_store
        self.requires_skill_reload = mcp_servers != current_mcp_servers
        theme_commit_warning = (
            self.theme_settings_panel.last_commit_warning
            if appearance_changed
            else ""
        )
        self._clear_settings_dirty()
        self._allow_close_without_prompt = True
        if self.property("embeddedProductPage"):
            if self._main and hasattr(self._main, "add_system_toast"):
                if theme_commit_warning:
                    self._main.add_system_toast(
                        theme_commit_warning,
                        "warning",
                        auto_close_ms=10000,
                    )
                else:
                    self._main.add_system_toast(
                        "设置已保存",
                        "success",
                        auto_close_ms=3200,
                    )
            if self.requires_skill_reload and self._main:
                self._main.skill_manager_ready = False
                self._main.start_background_skill_load(force=True)
            return
        if theme_commit_warning:
            QMessageBox.warning(
                self,
                "设置已保存",
                theme_commit_warning,
            )
        self.accept()


