        layout = QVBoxLayout(self)
        layout.setContentsMargins(24, 20, 24, 20)
        layout.setSpacing(14)

        title = QLabel("沉淀为 Skill")
        title.setProperty("roleTitle", True)
        subtitle = QLabel("把当前会话中可复用的经验保存为长期能力。")
