        subtitle = QLabel(subtitle_text)
        subtitle.setProperty("roleSubtitle", True)
        subtitle.setWordWrap(True)
        layout.addWidget(title)
        layout.addWidget(subtitle)

        self.tabs = QTabWidget()
        self.tabs.setStyleSheet(apple_tab_style())
