def _forward_wheel_to_chat_scroll(widget, event):
    """Route message-body wheel input to the single owning chat scroll area."""
    parent = widget.parentWidget()
    chat_scroll = None
    while parent is not None:
        if isinstance(parent, QScrollArea) and parent.objectName() == "ChatScrollArea":
            chat_scroll = parent
            break
        parent = parent.parentWidget()
    if chat_scroll is None:
        event.ignore()
        return

    target = chat_scroll.viewport()
    global_position = event.globalPosition()
    local_position = QPointF(target.mapFromGlobal(global_position.toPoint()))
    forwarded = QWheelEvent(
        local_position,
        global_position,
        event.pixelDelta(),
        event.angleDelta(),
        event.buttons(),
        event.modifiers(),
        event.phase(),
        event.inverted(),
        event.source(),
    )
    QApplication.sendEvent(target, forwarded)
    event.setAccepted(forwarded.isAccepted())


class AutoResizingTextEdit(ReadOnlyTextEdit):
    linkActivated = Signal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        # self.setReadOnly(True) # Inherited
        self.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.setFrameStyle(QFrame.NoFrame)
        self.setLineWrapMode(QTextEdit.WidgetWidth)
        self.setFixedHeight(24)
        self._height_adjust_pending = False
        self.textChanged.connect(self.scheduleAdjustHeight)
        self.setStyleSheet("background: transparent;")
        
        # Set word wrap mode to break anywhere if needed (for long strings)
        self.setWordWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
        text_option = self.document().defaultTextOption()
        text_option.setWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
        self.document().setDefaultTextOption(text_option)

    def mouseReleaseEvent(self, event):
        anchor = self.anchorAt(event.position().toPoint()) if event.button() == Qt.LeftButton else ""
        super().mouseReleaseEvent(event)
        if anchor and not self.textCursor().hasSelection():
            self.linkActivated.emit(anchor)

    def wheelEvent(self, event):
        _forward_wheel_to_chat_scroll(self, event)

    def scheduleAdjustHeight(self):
        if not _qt_object_alive(self):
            return
        if self._height_adjust_pending:
            return
        self._height_adjust_pending = True
        QTimer.singleShot(0, self.adjustHeight)

    def adjustHeight(self):
        """
        根据文档内容调整文本框高度
        添加最大高度限制防止初始渲染时高度异常
        """
        if not _qt_object_alive(self):
            return
        self._height_adjust_pending = False
        viewport_width = self.viewport().width()
        if viewport_width <= 0:
            viewport_width = self.width() - (self.frameWidth() * 2)
        self.document().setTextWidth(max(0.0, float(viewport_width)))
        doc_height = self.document().size().height()
        margins = self.contentsMargins()
        frame = self.frameWidth() * 2
        height = int(doc_height + margins.top() + margins.bottom() + frame + 4)
        # 确保最小高度避免不可见，同时限制最大高度防止初始异常
        height = max(height, 24)
        if self.height() != height:
            self.setFixedHeight(height)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.adjustHeight()


