            empty = QLabel("暂无可用自定义智能体。可在设置里创建，也可以先使用内置 PPT 助手。")
            empty.setWordWrap(True)
            empty.setStyleSheet(f"font-size: 12px; color: {DesignTokens.text_secondary};")
            layout.addWidget(empty)
