class InlineVisualizationCard(QFrame):
    def __init__(self, artifact, conversation_id, chat_storage, read_only=False, parent=None):
        super().__init__(parent)
        self.artifact = dict(artifact or {})
        self.conversation_id = str(conversation_id or "")
        self.chat_storage = chat_storage
        self.read_only = bool(read_only)
        self.web_view = None
        self.bridge = None
        self._pending_state = None
        self._active = True
        self._expanded = False
        self._visualization_error = ""
        self.setObjectName("InlineVisualizationCard")
        self.setStyleSheet(
            f"QFrame#InlineVisualizationCard {{ background: {DesignTokens.bg_main}; "
            f"border: 1px solid {DesignTokens.border_subtle}; border-radius: 8px; }}"
        )
        layout = QVBoxLayout(self)
        layout.setContentsMargins(12, 10, 12, 10)
        layout.setSpacing(8)

        header = QHBoxLayout()
        header.setContentsMargins(0, 0, 0, 0)
        self.title_label = QLabel(self.artifact.get("title") or self.artifact.get("file") or "交互可视化")
        self.title_label.setStyleSheet(f"color: {DesignTokens.text_primary}; font-size: 13px; font-weight: 700;")
        header.addWidget(self.title_label, 1)
        if self.read_only:
            readonly = QLabel("只读")
            readonly.setStyleSheet(apple_status_chip_style("disabled", subtle=True))
            header.addWidget(readonly)
        self.expand_btn = QPushButton("展开")
        self.expand_btn.setCursor(Qt.PointingHandCursor)
        self.expand_btn.setFixedHeight(26)
        self.expand_btn.setStyleSheet(apple_button_style("secondary", radius=7))
        self.expand_btn.clicked.connect(self._toggle_expanded)
        header.addWidget(self.expand_btn)
        layout.addLayout(header)

        self.body_layout = QVBoxLayout()
        self.body_layout.setContentsMargins(0, 0, 0, 0)
        self.status_label = QLabel("正在准备交互视图…")
        self.status_label.setWordWrap(True)
        self.status_label.setStyleSheet(f"color: {DesignTokens.text_secondary}; font-size: 12px; padding: 12px;")
        self.body_layout.addWidget(self.status_label)
        layout.addLayout(self.body_layout)
        self.state_timer = QTimer(self)
        self.state_timer.setSingleShot(True)
        self.state_timer.setInterval(500)
        self.state_timer.timeout.connect(self._flush_state)
        QTimer.singleShot(0, self.ensure_loaded)

    def _toggle_expanded(self):
        self._expanded = not self._expanded
        self.expand_btn.setText("收起" if self._expanded else "展开")
        if self.web_view is not None:
            self.web_view.setFixedHeight(900 if self._expanded else max(180, min(620, self.web_view.height())))

    def _show_error(self, message):
        self._visualization_error = str(message or "交互可视化加载失败。")
        self.status_label.setText(self._visualization_error)
        self.status_label.setStyleSheet(f"color: {DesignTokens.error_text}; font-size: 12px; padding: 12px;")
        self.status_label.setVisible(True)

    def _configure_view(self, view, allow_remote=False):
        try:
            module = importlib.import_module("PySide6.QtWebEngineCore")
            settings = view.settings()
            attributes = module.QWebEngineSettings.WebAttribute
            for name, enabled in (
                ("JavascriptEnabled", True),
                ("JavascriptCanOpenWindows", False),
                ("JavascriptCanAccessClipboard", False),
                ("LocalContentCanAccessFileUrls", False),
                ("LocalContentCanAccessRemoteUrls", bool(allow_remote)),
                ("FullScreenSupportEnabled", False),
            ):
                attribute = getattr(attributes, name, None)
                if attribute is not None:
                    settings.setAttribute(attribute, enabled)
        except Exception as exc:
            raise RuntimeError(f"无法配置交互可视化沙箱：{exc}") from exc

    def ensure_loaded(self):
        if not self._active or self.web_view is not None:
            return
        path = os.path.abspath(str(self.artifact.get("path") or ""))
        expected_hash = str(self.artifact.get("sha256") or "")
        try:
            if not os.path.isfile(path):
                raise FileNotFoundError(f"历史可视化文件不存在：{path}")
            if sha256_file(path) != expected_hash:
                raise RuntimeError("可视化文件校验失败，内容与历史记录不一致。")
            with open(path, "r", encoding="utf-8") as handle:
                fragment = handle.read()
            initial_state = self.chat_storage.get_inline_visualization_state(
                self.conversation_id,
                self.artifact.get("file"),
                expected_hash,
            ) if self.chat_storage is not None else {}
            origins = self.artifact.get("origins") or []
            document = build_visualization_document(
                fragment,
                initial_state=initial_state,
                read_only=self.read_only,
                theme_css=inline_visualization_theme_css(),
                origins=origins,
            )
            view_cls = load_qwebengine_view()
            if view_cls is None:
                raise RuntimeError(webengine_unavailable_message())
            view = view_cls(self)
            self._configure_view(view, allow_remote=bool(origins))
            view.setStyleSheet("background: transparent; border: none;")
            view.setFixedHeight(420)
            channel_module = importlib.import_module("PySide6.QtWebChannel")
            channel = channel_module.QWebChannel(view.page())
            bridge = InlineVisualizationBridge(channel)
            channel.registerObject("bridge", bridge)
            view.page().setWebChannel(channel)
            bridge.heightReported.connect(self._apply_height)
            bridge.stateReceived.connect(self._queue_state)
            bridge.errorReported.connect(self._handle_runtime_error)
            view.loadFinished.connect(self._handle_load_finished)
            self.bridge = bridge
            self._web_channel = channel
            self.web_view = view
            self.body_layout.addWidget(view)
            view.setHtml(document, QUrl("qrc:///"))
            log_sub_agent_runtime(
                "inline_visualization_load_start",
                conversation_id=self.conversation_id,
                file=self.artifact.get("file"),
                read_only=self.read_only,
            )
        except Exception as exc:
            self._show_error(str(exc))
            log_sub_agent_runtime(
                "inline_visualization_load_error",
                conversation_id=self.conversation_id,
                file=self.artifact.get("file"),
                error=str(exc),
            )

    def _handle_load_finished(self, ok):
        if ok and not self._visualization_error:
            self.status_label.setVisible(False)
        elif not ok:
            self._show_error("交互可视化页面加载失败，请检查 Fragment 的 HTML、CSS 和 JavaScript。")
        log_sub_agent_runtime(
            "inline_visualization_load_finish",
            conversation_id=self.conversation_id,
            file=self.artifact.get("file"),
            ok=bool(ok),
        )

    def _apply_height(self, height):
        if self.web_view is None or self._expanded:
            return
        self.web_view.setFixedHeight(max(180, min(620, int(height or 420))))

    def _handle_runtime_error(self, message):
        detail = str(message or "未知 JavaScript 错误")
        resource_error = detail.startswith(("外部资源加载失败：", "内容安全策略已阻止资源："))
        if resource_error:
            self._show_error(f"交互可视化资源加载失败：{detail}")
        else:
            self._show_error(f"交互可视化脚本运行失败：{detail}")
        log_sub_agent_runtime(
            "inline_visualization_resource_error" if resource_error else "inline_visualization_runtime_error",
            conversation_id=self.conversation_id,
            file=self.artifact.get("file"),
            error=detail,
        )

    def _queue_state(self, payload):
        if self.read_only:
            return
        try:
            state = json.loads(str(payload or "{}"))
            if not isinstance(state, dict):
                raise ValueError("状态必须是 JSON object。")
            self._pending_state = state
            self.state_timer.start()
        except Exception as exc:
            log_sub_agent_runtime("inline_visualization_state_invalid", error=str(exc))

    def _flush_state(self):
        if self.read_only or self._pending_state is None or self.chat_storage is None:
            return
        state = self._pending_state
        self._pending_state = None
        try:
            self.chat_storage.save_inline_visualization_state(
                self.conversation_id,
                self.artifact.get("file"),
                self.artifact.get("sha256"),
                state,
            )
            log_sub_agent_runtime(
                "inline_visualization_state_saved",
                conversation_id=self.conversation_id,
                file=self.artifact.get("file"),
            )
        except Exception as exc:
            self._show_error(f"交互状态保存失败：{exc}")

    def set_active(self, active):
        self._active = bool(active)
        if self._active:
            self.ensure_loaded()
            return
        if self.state_timer.isActive():
            self.state_timer.stop()
            self._flush_state()
        if self.web_view is not None:
            self.body_layout.removeWidget(self.web_view)
            self.web_view.deleteLater()
            self.web_view = None
            self.bridge = None
            self.status_label.setText("滚动回此消息时重新加载交互视图。")
            self.status_label.setVisible(True)


class AssistantTurnGroup(QFrame):
    """One visible assistant turn containing one or more conversational stages."""

    def __init__(self, group_id, parent=None):
        super().__init__(parent)
        self.group_id = str(group_id or uuid.uuid4().hex)
        self.stage_bubbles = []
        self.stage_separators = []
        self.process_finalized = False
        self.process_expanded = True
        self.process_finalization_pending = False
        self.process_result_bubble = None
        self.setObjectName("AssistantTurnGroup")
        self.setFrameShape(QFrame.NoFrame)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Maximum)
        self.setStyleSheet("QFrame#AssistantTurnGroup { background: transparent; border: none; }")
        self.group_layout = QVBoxLayout(self)
        self.group_layout.setContentsMargins(0, 0, 0, 0)
        self.group_layout.setSpacing(0)
        self.group_layout.setAlignment(Qt.AlignTop)
        self.process_disclosure = QPushButton(self)
        self.process_disclosure.setObjectName("HistoricalProcessDisclosure")
        self.process_disclosure.setCheckable(True)
        self.process_disclosure.setCursor(Qt.PointingHandCursor)
        self.process_disclosure.setVisible(False)
        self.process_disclosure.toggled.connect(self.set_process_expanded)
        self.group_layout.addWidget(self.process_disclosure)
        bind_theme(self, self.refresh_theme, surface="conversation")

    def refresh_theme(self, _resolved=None):
        self.setStyleSheet(
            "QFrame#AssistantTurnGroup { background: transparent; border: none; }"
        )
        self.process_disclosure.setStyleSheet(apple_disclosure_button_style())
        for separator in self.stage_separators:
            separator_layout = separator.layout()
            if separator_layout is not None:
                separator_layout.setContentsMargins(
                    DesignTokens.assistant_stage_separator_indent,
                    DesignTokens.assistant_stage_separator_vertical_margin,
                    DesignTokens.assistant_stage_separator_right_margin,
                    DesignTokens.assistant_stage_separator_vertical_margin,
                )
            line = separator.findChild(QFrame, "AssistantStageSeparator")
            if line is not None:
                line.setStyleSheet(
                    f"QFrame#AssistantStageSeparator {{ background: {DesignTokens.chat_border}; border: none; }}"
                )

    def add_stage(self, bubble, stage_id=None):
        if bubble is None:
            raise ValueError("AI 轮次阶段不能为空。")
        if self.stage_bubbles:
            self._finish_stage_thinking(self.stage_bubbles[-1])
            separator = QWidget(self)
            separator.setObjectName("AssistantStageSeparatorArea")
            separator_layout = QHBoxLayout(separator)
            separator_layout.setContentsMargins(
                DesignTokens.assistant_stage_separator_indent,
                DesignTokens.assistant_stage_separator_vertical_margin,
                DesignTokens.assistant_stage_separator_right_margin,
                DesignTokens.assistant_stage_separator_vertical_margin,
            )
            separator_layout.setSpacing(0)
            line = QFrame(separator)
            line.setObjectName("AssistantStageSeparator")
            line.setFixedHeight(1)
            line.setStyleSheet(
                f"QFrame#AssistantStageSeparator {{ background: {DesignTokens.border_subtle}; border: none; }}"
            )
            separator_layout.addWidget(line)
            self.stage_separators.append(separator)
            self.group_layout.addWidget(separator)
        bubble.ui_turn_group_id = self.group_id
        bubble.ui_stage_id = str(stage_id or f"{self.group_id}:stage-{len(self.stage_bubbles) + 1}")
        self.stage_bubbles.append(bubble)
        self.group_layout.addWidget(bubble)
        self.sync_stage_visibility()
        return bubble

    def sync_stage_visibility(self):
        """Hide semantically empty stages and separators without changing stage order."""
        if self.process_finalized and not self.process_expanded:
            for bubble in self.stage_bubbles:
                bubble.setVisible(
                    self.process_result_bubble is not None
                    and bubble is self.process_result_bubble
                )
                if bubble.thinking_widget is not None:
                    bubble.thinking_widget.setVisible(False)
            for separator in self.stage_separators:
                separator.setVisible(False)
            self.setVisible(bool(self.process_disclosure.isVisible() or self.process_result_bubble is not None))
            self.group_layout.invalidate()
            self.updateGeometry()
            return
        visible_before = False
        for index, bubble in enumerate(self.stage_bubbles):
            visible = bubble.has_visible_stage_content()
            bubble.setVisible(visible)
            if index > 0:
                self.stage_separators[index - 1].setVisible(bool(visible_before and visible))
            if visible:
                visible_before = True
        self.setVisible(visible_before)
        self.group_layout.invalidate()
        self.updateGeometry()

    def _process_counts(self, result_bubble):
        process_stage_count = 0
        tool_count = 0
        for bubble in self.stage_bubbles:
            bubble_tool_count = sum(
                1 for event in bubble.timeline_events if isinstance(event, ToolCallCard)
            )
            tool_count += bubble_tool_count
            has_reasoning = bubble._has_thinking_details()
            if bubble is not result_bubble or has_reasoning or bubble_tool_count:
                process_stage_count += 1
        return process_stage_count, tool_count

    def _refresh_process_disclosure_text(self, stage_count, tool_count):
        parts = []
        if stage_count:
            parts.append(f"{stage_count} 个阶段")
        if tool_count:
            parts.append(f"{tool_count} 次 Tool 调用")
        summary = " · ".join(parts) or "执行详情"
        arrow = "▴" if self.process_disclosure.isChecked() else "▾"
        self.process_disclosure.setText(f" 执行过程 · {summary}  {arrow}")
        self.process_disclosure.setAccessibleName(
            f"执行过程，{summary}，{'已展开' if self.process_disclosure.isChecked() else '已折叠'}"
        )

    def request_process_finalization(self, result_bubble=None):
        result_bubble = result_bubble or self.active_stage()
        if result_bubble is None:
            return False
        if not bool(getattr(result_bubble, "_rendered_main_content_final", False)):
            self.process_finalization_pending = True
            self.process_result_bubble = result_bubble
            return False
        self.finalize_process(result_bubble)
        return True

    def complete_pending_process_finalization(self, result_bubble):
        if not self.process_finalization_pending or result_bubble is not self.process_result_bubble:
            return False
        self.finalize_process(result_bubble)
        return True

    def _finish_stage_thinking(self, bubble):
        if bubble is None or not _qt_object_alive(bubble):
            return
        replay_timer = getattr(bubble, "_thinking_replay_timer", None)
        if replay_timer is not None and replay_timer.isActive():
            replay_timer.stop()
        bubble.update_thinking(duration=None, is_final=True)

    def finalize_non_result_stages(self, result_bubble):
        for bubble in self.stage_bubbles:
            if bubble is result_bubble:
                continue
            self._finish_stage_thinking(bubble)
            bubble.set_message_actions_enabled(False)

    def finalize_process_only(self):
        """Fold a completed process group that does not own the turn's final answer."""
        active_timer_count = sum(
            1
            for bubble in self.stage_bubbles
            if (
                bubble.think_timer.isActive()
                or bool(
                    getattr(bubble, "_thinking_replay_timer", None)
                    and bubble._thinking_replay_timer.isActive()
                )
            )
        )
        for bubble in self.stage_bubbles:
            self._finish_stage_thinking(bubble)
            bubble.set_message_actions_enabled(False)

        self.process_finalization_pending = False
        self.process_finalized = True
        self.process_result_bubble = None
        stage_count, tool_count = self._process_counts(None)
        has_process = bool(stage_count or tool_count)
        self.process_disclosure.setVisible(has_process)
        self.process_disclosure.blockSignals(True)
        self.process_disclosure.setChecked(False)
        self.process_disclosure.blockSignals(False)
        self.process_expanded = False
        self._refresh_process_disclosure_text(stage_count, tool_count)
        self.sync_stage_visibility()
        log_sub_agent_runtime(
            "ui_assistant_process_only_folded",
            session_id=str(
                getattr(self.stage_bubbles[-1], "session_id", "")
                if self.stage_bubbles
                else ""
            ),
            group_id=self.group_id,
            stage_count=stage_count,
            tool_count=tool_count,
            active_timer_count=active_timer_count,
            has_process=has_process,
        )

    def finalize_process(self, result_bubble=None):
        result_bubble = result_bubble or self.active_stage()
        if result_bubble is None:
            raise RuntimeError("折叠执行过程时缺少最终结果阶段。")
        self.process_finalization_pending = False
        self.process_finalized = True
        self.process_result_bubble = result_bubble
        stage_count, tool_count = self._process_counts(result_bubble)
        has_process = bool(stage_count or tool_count)
        self.process_disclosure.setVisible(has_process)
        self.process_disclosure.blockSignals(True)
        self.process_disclosure.setChecked(False)
        self.process_disclosure.blockSignals(False)
        self.process_expanded = False
        self._refresh_process_disclosure_text(stage_count, tool_count)
        self.sync_stage_visibility()
        log_sub_agent_runtime(
            "ui_assistant_process_folded",
            session_id=str(getattr(result_bubble, "session_id", "") or ""),
            group_id=self.group_id,
            stage_count=stage_count,
            tool_count=tool_count,
            has_process=has_process,
        )

    def set_process_expanded(self, expanded):
        if not self.process_finalized:
            return
        self.process_expanded = bool(expanded)
        if self.process_expanded:
            for bubble in self.stage_bubbles:
                if bubble._has_thinking_details():
                    bubble.thinking_widget.setVisible(True)
                    bubble.think_toggle_btn.setChecked(True)
        self._refresh_process_disclosure_text(*self._process_counts(self.process_result_bubble))
        self.sync_stage_visibility()
        log_sub_agent_runtime(
            "ui_assistant_process_toggled",
            session_id=str(getattr(self.process_result_bubble, "session_id", "") or ""),
            group_id=self.group_id,
            expanded=self.process_expanded,
        )

    def active_stage(self):
        return self.stage_bubbles[-1] if self.stage_bubbles else None

    def apply_dynamic_widths(self, message_width, user_bubble_width):
        for bubble in self.stage_bubbles:
            bubble.apply_dynamic_widths(message_width, user_bubble_width)


class SummonedAgentProcessBlock(QFrame):
    """Named, independently updating assistant process embedded in the chat."""

    STATUS_COPY = {
        "input": "已接收",
        "pending": "等待中",
        "running": "运行中",
        "active": "运行中",
        "thinking": "思考中",
        "content": "输出中",
        "tool_use": "调用工具",
        "tool_result": "运行中",
        "waiting_input": "等待输入",
        "completed": "已完成",
        "failed": "失败",
        "failed_recovered": "恢复失败",
        "provider_error": "异常",
        "closed": "已关闭",
        "killed": "已终止",
    }

    def __init__(self, agent_id, agent_name, group_id="", parent=None):
        super().__init__(parent)
        self.agent_id = str(agent_id or "")
        self.agent_name = str(agent_name or "智能体").strip() or "智能体"
        self.status = "pending"
        self.setObjectName("SummonedAgentProcessBlock")
        self.setFrameShape(QFrame.NoFrame)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Maximum)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(
            DesignTokens.assistant_stage_separator_indent,
            DesignTokens.spacing_sm,
            DesignTokens.assistant_stage_separator_right_margin,
            DesignTokens.spacing_sm,
        )
        layout.setSpacing(DesignTokens.spacing_sm)
        layout.setAlignment(Qt.AlignTop)

        header = QHBoxLayout()
        header.setContentsMargins(0, 0, 0, 0)
        header.setSpacing(DesignTokens.spacing_sm)
        self.icon_label = QLabel(self)
        self.icon_label.setFixedSize(DesignTokens.icon_size_lg, DesignTokens.icon_size_lg)
        self.icon_label.setAlignment(Qt.AlignCenter)
        self.name_label = QLabel(self.agent_name, self)
        self.name_label.setTextInteractionFlags(Qt.TextSelectableByMouse)
        self.status_label = QLabel(self)
        self.status_label.setAlignment(Qt.AlignCenter)
        header.addWidget(self.icon_label)
        header.addWidget(self.name_label)
        header.addStretch()
        header.addWidget(self.status_label)
        layout.addLayout(header)

        self.turn_group = AssistantTurnGroup(group_id or f"summoned-agent-{self.agent_id}", self)
        layout.addWidget(self.turn_group)
        bind_theme(self, self.refresh_theme, surface="conversation")
        self.refresh_theme()
        self.set_status("pending")

    def refresh_theme(self, _resolved=None):
        self.setStyleSheet(
            f"QFrame#SummonedAgentProcessBlock {{ background: transparent; border: none; "
            f"border-left: 2px solid {DesignTokens.chat_border}; }}"
        )
        self.icon_label.setPixmap(
            qta.icon("fa5s.user-astronaut", color=DesignTokens.primary).pixmap(
                DesignTokens.icon_size_sm,
                DesignTokens.icon_size_sm,
            )
        )
        self.name_label.setStyleSheet(
            f"color: {DesignTokens.chat_text}; font-size: {DesignTokens.font_size_meta}px; "
            f"font-weight: {DesignTokens.font_weight_semibold}; background: transparent; border: none;"
        )
        self.set_status(self.status)

    def set_status(self, status):
        self.status = str(status or "pending").strip().lower()
        label = self.STATUS_COPY.get(self.status, status_label_text(self.status))
        self.status_label.setText(label)
        self.status_label.setStyleSheet(apple_status_chip_style(self.status, subtle=True))
        self.status_label.setAccessibleName(f"{self.agent_name} {label}")

    def add_stage(self, bubble, stage_id=None):
        return self.turn_group.add_stage(bubble, stage_id=stage_id)

    def apply_dynamic_widths(self, message_width, user_bubble_width):
        self.turn_group.apply_dynamic_widths(message_width, user_bubble_width)


class HistoricalAssistantSummary(QFrame):
    detailRequested = Signal(bool)

    def __init__(self, stage_count=0, tool_count=0, parent=None):
        super().__init__(parent)
        self.setObjectName("HistoricalAssistantSummary")
        self.setFrameShape(QFrame.NoFrame)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Maximum)
        self.setStyleSheet(
            "QFrame#HistoricalAssistantSummary { background: transparent; border: none; }"
        )
        self.stage_count = max(0, int(stage_count or 0))
        self.tool_count = max(0, int(tool_count or 0))
        self.detail_groups = []
        self.detail_batches = []
        self.detail_batch_index = 0
        self.detail_loading = False
        self.detail_error = ""
        self.message_ids = []
        self.span_start = 0
        self.span_end = 0

        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(4)
        self.detail_button = QPushButton()
        self.detail_button.setObjectName("HistoricalProcessDisclosure")
        self.detail_button.setCheckable(True)
        self.detail_button.setCursor(Qt.PointingHandCursor)
        self.detail_button.setStyleSheet(apple_disclosure_button_style())
        self.detail_button.toggled.connect(self._on_toggled)
        layout.addWidget(self.detail_button)
        self.retry_button = QPushButton("重试恢复")
        self.retry_button.setObjectName("HistoricalProcessRetryButton")
        self.retry_button.setCursor(Qt.PointingHandCursor)
        self.retry_button.setStyleSheet(apple_button_style("secondary"))
        self.retry_button.clicked.connect(self._retry_details)
        self.retry_button.hide()
        layout.addWidget(self.retry_button, 0, Qt.AlignLeft)
        self.body = QWidget(self)
        self.body.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Maximum)
        self.body_layout = QVBoxLayout(self.body)
        self.body_layout.setContentsMargins(0, 0, 0, 0)
        self.body_layout.setSpacing(0)
        layout.addWidget(self.body)
        self._refresh_button_text()

    def _refresh_button_text(self, progress_text=""):
        parts = []
        if self.stage_count:
            parts.append(f"{self.stage_count} 个阶段")
        if self.tool_count:
            parts.append(f"{self.tool_count} 次 Tool 调用")
        summary = " · ".join(parts) or "执行详情"
        arrow = "▴" if self.detail_button.isChecked() else "▾"
        suffix = f" · {progress_text}" if progress_text else ""
        self.detail_button.setText(f" 执行过程 · {summary}{suffix}  {arrow}")
        self.detail_button.setVisible(bool(self.stage_count or self.tool_count))

    def _on_toggled(self, checked):
        self._refresh_button_text()
        self.detailRequested.emit(bool(checked))

    def set_progress(self, completed, total):
        self.retry_button.hide()
        self._refresh_button_text(f"正在加载 {int(completed)}/{int(total)}")

    def set_error(self, message):
        self.detail_error = str(message or "")
        self._refresh_button_text(f"加载失败：{self.detail_error}")
        self.retry_button.show()

    def _retry_details(self):
        self.detail_error = ""
        self.detail_loading = False
        self.retry_button.hide()
        self.detailRequested.emit(True)

    def set_complete(self):
        self.detail_loading = False
        self.retry_button.hide()
        self._refresh_button_text("已加载")


class ChatBubble(QFrame):
    editSubmitRequested = Signal(str, str)
    deleteRequested = Signal(str)
    deliverablePathActivated = Signal(str)
    deliverablePathsChanged = Signal(object)
    officeDraftRequested = Signal(str, str, str)
    skillCaptureRequested = Signal(str)
    geometryChanged = Signal()

    """Refined Chat Bubble component with Avatar and Better Thinking UI"""

    def event(self, event):
        result = super().event(event)
        if event.type() == QEvent.ParentChange and self.parentWidget() is not None:
            # Reparenting into an already visible scroll layout is not a safe
            # point to call setVisible(): Qt can leave WA_WState_Hidden set
            # while reporting the widget as visible, and QLayout then treats
            # the message item as empty. Apply the desired state after the
            # ParentChange transaction has completed.
            QTimer.singleShot(0, self._apply_deferred_theme_visibility)
        return result

    def _apply_deferred_theme_visibility(self):
        if not _qt_object_alive(self) or self.parentWidget() is None:
            return
        self.setVisible(
            bool(getattr(self, "_theme_component_desired_visible", True))
        )
        self.updateGeometry()
        parent = self.parentWidget()
        if parent is not None and parent.layout() is not None:
            parent.layout().invalidate()

    def __init__(
        self,
        role,
        text,
        thinking=None,
        duration=None,
        attachments=None,
        attachment_hint="用户添加的文件",
        source_message_id="",
        created_at=None,
        workspace_dir="",
        edited=False,
        session_id="",
        chat_storage=None,
        visualize_enabled=False,
        parent=None,
    ):
        super().__init__(parent)
        self.role = role
        self.content_wrapper = None
        self.user_bubble_frame = None
        self.user_content_edit = None
        self.user_wrapper_layout = None
        self.edited_label = None
        self.content_edit = None
        self.content_col = None
        self.avatar_container = None
        self._virtualized = False
        self._virtualized_height = 0
        self._virtualized_visible_state = {}
        self.source_message_id = str(source_message_id or "").strip()
        self.created_at = created_at if created_at is not None else time.time()
        self.workspace_dir = str(workspace_dir or "").strip()
        self.session_id = str(session_id or "").strip()
        self.chat_storage = chat_storage
        self.visualize_enabled = bool(visualize_enabled)
        self._inline_visualization_files = []
        self.inline_visualization_cards = []
        self.inline_visualization_container = None
        self.inline_visualization_layout = None
        self.edit_btn = None
        self.copy_btn = None
        self.delete_btn = None
        self.user_action_bar = None
        self.user_action_effect = None
        self.message_time_label = None
        self._message_actions_theme_enabled = True
        self.message_action_buttons = []
        self.message_actions_enabled = True
        self.edit_controls = None
        self.edit_original_text = ""
        self.code_output_label = None
        self.code_output_edit = None
        self.setFrameShape(QFrame.NoFrame)
        self.setLineWidth(0)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Maximum)
        attachments = list(attachments or [])
        self.user_attachments = attachments
        
        # Main Horizontal Layout (Avatar | Content)
        main_layout = QHBoxLayout(self)
        main_layout.setContentsMargins(0, DesignTokens.chat_message_vertical_margin, 0, DesignTokens.chat_message_vertical_margin)
        main_layout.setSpacing(10)
        
        if role == "User":
            main_layout.setAlignment(Qt.AlignRight | Qt.AlignTop)
            
            # 1. Content Wrapper (to push content to right)
            content_wrapper = QWidget()
            self.content_wrapper = content_wrapper
            content_wrapper.setMaximumWidth(DesignTokens.message_max_width)
            cw_layout = QVBoxLayout(content_wrapper)
            self.user_wrapper_layout = cw_layout
            cw_layout.setContentsMargins(0, 0, 0, 0)
            cw_layout.setSpacing(8 if attachments and text else 5)

            if attachments:
                attachment_group = QWidget()
                attachment_group_layout = QVBoxLayout(attachment_group)
                attachment_group_layout.setContentsMargins(0, 0, 0, 0)
                attachment_group_layout.setSpacing(4)

                attachment_hint_label = QLabel(attachment_hint)
                attachment_hint_label.setAlignment(Qt.AlignRight)
                attachment_hint_label.setStyleSheet(
                    f"color: {DesignTokens.info_text}; font-size: 11px; font-weight: 600; padding-right: 2px;"
                )
                attachment_group_layout.addWidget(attachment_hint_label)

                chip_row = QWidget()
                chip_row_layout = QHBoxLayout(chip_row)
                chip_row_layout.setContentsMargins(0, 0, 0, 0)
                chip_row_layout.setSpacing(8)
                chip_row_layout.addStretch()
                for attachment in attachments:
                    chip_row_layout.addWidget(FileChip(attachment.get("path") or "", removable=False))
                attachment_group_layout.addWidget(chip_row)
                cw_layout.addWidget(attachment_group, 0, Qt.AlignRight)

            # Bubble Frame
            if text or attachments:
                bubble_frame = QFrame()
                self.user_bubble_frame = bubble_frame
                bubble_frame.setObjectName("UserBubbleFrame")
                bubble_frame.setMaximumWidth(DesignTokens.user_bubble_max_width)
                bubble_frame.setStyleSheet(f"""
                    QFrame#UserBubbleFrame {{
                        background: {DesignTokens.bg_user_bubble};
                        border: 1px solid {DesignTokens.border_settings_summary};
                        border-radius: 8px;
                    }}
                """)
                bubble_layout = QVBoxLayout(bubble_frame)
                bubble_layout.setContentsMargins(
                    DesignTokens.user_message_padding_horizontal,
                    DesignTokens.user_message_padding_vertical,
                    DesignTokens.user_message_padding_horizontal,
                    DesignTokens.user_message_padding_vertical,
                )
                self.user_bubble_layout = bubble_layout

                content_edit = AutoResizingTextEdit()
                self.user_content_edit = content_edit
                content_edit.installEventFilter(self)
                content_edit.setPlainText(text)
                content_edit.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
                content_edit.setStyleSheet(
                    f"color: {DesignTokens.text_primary}; font-size: 14px; line-height: 1.6; border: none; background: transparent; "
                    f"selection-background-color: {DesignTokens.selection_bg}; selection-color: {DesignTokens.selection_text};"
                )
