    def refresh_theme(self, _resolved=None):
        layout = self.layout()
        if layout is not None:
            layout.setContentsMargins(
                0,
                DesignTokens.chat_message_vertical_margin,
                0,
                DesignTokens.chat_message_vertical_margin,
            )
            layout.setSpacing(DesignTokens.spacing_sm + 2)
        if self.content_wrapper is not None:
            self.content_wrapper.setMaximumWidth(DesignTokens.message_max_width)
        if self.content_col is not None:
            self.content_col.setMaximumWidth(DesignTokens.message_max_width)
        if self.user_bubble_frame is not None:
            self.user_bubble_frame.setMaximumWidth(DesignTokens.user_bubble_max_width)
            self.user_bubble_frame.setStyleSheet(
                f"QFrame#UserBubbleFrame {{ background: {DesignTokens.bg_user_bubble}; "
                f"border: 1px solid {DesignTokens.chat_border}; "
                f"border-radius: {DesignTokens.radius_md}px; }}"
            )
        if self.user_content_edit is not None:
            self.user_content_edit.setStyleSheet(
                f"color: {DesignTokens.chat_text}; font-size: {DesignTokens.font_size_body}px; "
                "line-height: 1.6; border: none; background: transparent; "
                f"selection-background-color: {DesignTokens.selection_bg}; "
                f"selection-color: {DesignTokens.selection_text};"
            )
            apply_selection_palette(
                self.user_content_edit,
                DesignTokens.selection_bg,
                DesignTokens.selection_text,
            )
        if getattr(self, "think_toggle_btn", None) is not None:
            self.think_toggle_btn.setIcon(
                qta.icon("fa5s.lightbulb", color=DesignTokens.accent_tool)
            )
            self.think_toggle_btn.setStyleSheet(
                f"QPushButton {{ text-align: left; min-height: {DesignTokens.assistant_stage_header_height}px; "
                f"max-height: {DesignTokens.assistant_stage_header_height}px; background: transparent; "
                f"color: {DesignTokens.chat_text_muted}; border: none; "
                f"border-radius: {DesignTokens.radius_sm}px; padding: 0 {DesignTokens.spacing_xs}px; "
                f"font-size: {DesignTokens.font_size_meta}px; font-weight: {DesignTokens.font_weight_semibold}; }}"
                f"QPushButton:hover {{ background: {DesignTokens.bg_hover}; color: {DesignTokens.chat_text}; }}"
                f"QPushButton:checked {{ background: transparent; color: {DesignTokens.chat_text}; }}"
            )
        if getattr(self, "think_container", None) is not None:
            self.think_container.setStyleSheet(
                f"QWidget#ThinkingContainer {{ background: transparent; border: none; "
                f"border-left: 2px solid {DesignTokens.chat_border}; "
                f"margin-left: {DesignTokens.assistant_thinking_timeline_indent}px; }}"
            )
        for editor in (
            getattr(self, "content_rich_edit", None),
            getattr(self, "content_plain_edit", None),
        ):
            if editor is not None:
                editor.setStyleSheet(
                    f"background: transparent; border: none; padding: 0; "
                    f"color: {DesignTokens.chat_text}; "
                    f"font-size: {DesignTokens.font_size_body}px; "
                    f"selection-background-color: {DesignTokens.selection_bg}; "
                    f"selection-color: {DesignTokens.selection_text};"
                )
                apply_selection_palette(
                    editor,
                    DesignTokens.selection_bg,
                    DesignTokens.selection_text,
                )
        action_style = (
            f"QPushButton {{ border: none; border-radius: {DesignTokens.radius_sm}px; "
            f"padding: 2px {DesignTokens.spacing_sm + 1}px; background: transparent; "
            f"color: {DesignTokens.chat_text_muted}; font-size: {DesignTokens.font_size_meta}px; }}"
            f"QPushButton:hover {{ color: {DesignTokens.primary}; background: {DesignTokens.primary_soft}; }}"
        )
        action_icons = (
            ("copy_result_btn", "fa5s.copy"),
            ("office_draft_btn", "fa5s.file-code"),
            ("skill_capture_btn", "fa5s.magic"),
        )
        for attribute, icon_name in action_icons:
            button = getattr(self, attribute, None)
            if button is not None:
                button.setStyleSheet(action_style)
                button.setIcon(qta.icon(icon_name, color=DesignTokens.icon_secondary))
        if self.code_output_label is not None:
            self.code_output_label.setStyleSheet(
                f"font-weight: {DesignTokens.font_weight_semibold}; "
                f"color: {DesignTokens.chat_text}; "
                f"font-size: {DesignTokens.font_size_meta}px; "
                f"margin-top: {DesignTokens.spacing_sm}px; margin-left: {DesignTokens.spacing_xs}px;"
            )
        if self.code_output_edit is not None:
            mono_family = str(
                QApplication.instance().property("themeMonoFontFamily") or "Consolas"
            )
            self.code_output_edit.setStyleSheet(
                f"color: {DesignTokens.chat_text}; font-family: '{mono_family}'; "
                f"font-size: {DesignTokens.font_size_code}px; "
                f"background: {DesignTokens.bg_code}; border: 1px solid {DesignTokens.chat_border}; "
                f"padding: {DesignTokens.spacing_sm}px; border-radius: {DesignTokens.radius_sm}px; "
                f"margin-left: {DesignTokens.spacing_xs}px;"
            )
        if self.message_time_label is not None:
            self.message_time_label.setStyleSheet(
                f"color: {DesignTokens.chat_text_muted}; font-size: {DesignTokens.font_size_meta}px; "
                "padding-right: 2px; border: none; background: transparent;"
            )
        if self.content_edit is not None and self.main_content_text:
            was_final = bool(getattr(self, "_rendered_main_content_final", False))
            self._rendered_main_content_text = None
            self._render_main_content(
                self.main_content_text,
                content_parts=self._pending_main_content_parts,
                final=was_final,
            )
        resolved = _resolved or getattr(getattr(QApplication.instance(), "theme_manager", None), "current", None) or {}
        component_id = "conversation.user_message" if self.role == "User" else "conversation.assistant_message"
        spec = (resolved.get("components") or {}).get(component_id) or {}
        apply_theme_component_visibility(self, spec.get("visible", True))
        style = spec.get("style") or {}
        target = self.user_bubble_frame if self.role == "User" else self.content_col
        if target is not None and style:
            rules = []
            for field, css_name in (
                ("foreground", "color"),
                ("background", "background-color"),
                ("border_color", "border-color"),
            ):
                if field in style:
                    rules.append(f"{css_name}: {style[field]}")
            for field, css_name in (
                ("border_width", "border-width"),
                ("radius", "border-radius"),
                ("padding", "padding"),
            ):
                if field in style:
                    rules.append(f"{css_name}: {int(style[field])}px")
            if "border_color" in style:
                rules.append("border-style: solid")
            selector = target.metaObject().className()
            target.setStyleSheet(target.styleSheet() + f"\n{selector} {{ " + "; ".join(rules) + "; }")
            if "max_width" in style:
                target.setMaximumWidth(int(style["max_width"]))
            if "min_width" in style:
                target.setMinimumWidth(int(style["min_width"]))
        alignment = (spec.get("layout") or {}).get("alignment")
        if layout is not None and alignment in {"start", "center", "end"}:
            qt_alignment = {
                "start": Qt.AlignLeft | Qt.AlignTop,
                "center": Qt.AlignHCenter | Qt.AlignTop,
                "end": Qt.AlignRight | Qt.AlignTop,
            }[alignment]
            layout.setAlignment(qt_alignment)
        action_spec = (resolved.get("components") or {}).get("conversation.message_actions") or {}
        self._message_actions_theme_enabled = action_spec.get("visible") is not False
        for button in self.message_action_buttons + [
            item for item in (
                getattr(self, "copy_result_btn", None),
                getattr(self, "office_draft_btn", None),
                getattr(self, "skill_capture_btn", None),
            ) if item is not None
        ]:
            if action_spec.get("visible") is False:
                button.hide()
        if self.user_action_bar is not None and not self._message_actions_theme_enabled:
            self.user_action_bar.hide()
        thinking_spec = (resolved.get("components") or {}).get("conversation.thinking_stage") or {}
        if thinking_spec.get("visible") is False and getattr(self, "thinking_widget", None) is not None:
            self.thinking_widget.hide()
        self.updateGeometry()

    def set_virtualized(self, virtualized):
        virtualized = bool(virtualized)
        if self._virtualized == virtualized:
            return
        if virtualized:
            for card in self.inline_visualization_cards:
                card.set_active(False)
            height = self.height() if self.height() > 0 else self.sizeHint().height()
            self._virtualized_height = max(32, int(height or 32))
            self.setUpdatesEnabled(False)
            self._virtualized_visible_state = {}
            for widget in (self.content_wrapper, self.content_col, self.avatar_container):
                if widget is not None:
                    self._virtualized_visible_state[id(widget)] = widget.isVisible()
                    widget.setVisible(False)
            self.setFixedHeight(self._virtualized_height)
            self._virtualized = True
            return
        self.setMinimumHeight(0)
        self.setMaximumHeight(16777215)
        for widget in (self.content_wrapper, self.content_col, self.avatar_container):
            if widget is not None:
                widget.setVisible(self._virtualized_visible_state.get(id(widget), True))
        self._virtualized_visible_state = {}
        self._virtualized = False
        self.setUpdatesEnabled(True)
        for card in self.inline_visualization_cards:
            card.set_active(True)
        if self.user_content_edit is not None:
            self.user_content_edit.scheduleAdjustHeight()
        if self.content_edit is not None:
            self.content_edit.scheduleAdjustHeight()

    def is_virtualized(self):
        return bool(self._virtualized)

    def _create_edit_button(self):
        if self.edit_btn is not None:
            return self.edit_btn
        btn = self._create_message_action_button("fa5s.pen", "编辑并重新生成", self.begin_inline_edit)
        self.edit_btn = btn
        return btn

    @staticmethod
    def _format_message_time(value):
        try:
            timestamp = float(value)
            moment = datetime.fromtimestamp(timestamp)
        except (TypeError, ValueError, OSError, OverflowError):
            return "时间无效"
        now = datetime.now()
        if moment.year == now.year:
            return f"{moment.month}月{moment.day}日 {moment:%H:%M}"
        return f"{moment.year}年{moment.month}月{moment.day}日 {moment:%H:%M}"

    def _create_copy_button(self):
        if self.copy_btn is not None:
            return self.copy_btn
        btn = self._create_message_action_button("fa5s.copy", "复制消息", self.copy_user_content)
        self.copy_btn = btn
        return btn

    def copy_user_content(self):
        if self.role != "User" or self.user_content_edit is None:
            return
        QApplication.clipboard().setText(self.user_content_edit.toPlainText())
        if self.copy_btn is not None:
            self.copy_btn.setToolTip("已复制")
            QTimer.singleShot(
                1200,
                lambda: self.copy_btn.setToolTip("复制消息")
                if self.copy_btn is not None and _qt_object_alive(self.copy_btn)
                else None,
            )

    def _set_user_action_bar_visible(self, visible):
        if self.user_action_bar is None:
            return
        editing = bool(self.edit_controls is not None and self.edit_controls.isVisible())
        contents_visible = bool(visible and not editing and self._message_actions_theme_enabled)
        self.user_action_bar.setVisible(self._message_actions_theme_enabled)
        self.user_action_bar.setEnabled(contents_visible)
        if self.user_action_effect is not None:
            self.user_action_effect.setOpacity(1.0 if contents_visible else 0.0)

    def enterEvent(self, event):
        self._set_user_action_bar_visible(True)
        super().enterEvent(event)

    def leaveEvent(self, event):
        QTimer.singleShot(
            0,
            lambda: self._set_user_action_bar_visible(False)
            if _qt_object_alive(self) and not self.underMouse()
            else None,
        )
        super().leaveEvent(event)

    def mark_edited(self):
        if self.role != "User" or self.user_wrapper_layout is None or self.edited_label is not None:
            return
        label = QLabel("已编辑")
        label.setAlignment(Qt.AlignRight)
        label.setStyleSheet(f"color: {DesignTokens.text_tertiary}; font-size: 10px; padding-right: 2px;")
        self.user_wrapper_layout.addWidget(label)
        self.edited_label = label

    def _create_delete_button(self):
        if self.delete_btn is not None:
            return self.delete_btn
        btn = self._create_message_action_button("fa5s.trash-alt", "删除这条消息", self._emit_delete_request)
        self.delete_btn = btn
        return btn

    def _create_message_action_button(self, icon_name, tooltip, slot):
        btn = QToolButton()
        btn.setCursor(Qt.PointingHandCursor)
        btn.setAutoRaise(True)
        btn.setIcon(qta.icon(icon_name, color=DesignTokens.text_tertiary))
        btn.setIconSize(QSize(13, 13))
        btn.setToolTip(tooltip)
        btn.setFixedSize(26, 26)
        btn.setStyleSheet(apple_ghost_icon_button_style(radius=13))
        btn.clicked.connect(slot)
        self.message_action_buttons.append(btn)
        return btn

    def begin_inline_edit(self):
        if not self.source_message_id or self.role != "User" or self.user_content_edit is None:
            return
        self.edit_original_text = self.user_content_edit.toPlainText()
        self.user_content_edit.setReadOnly(False)
        self.user_content_edit.setFocus()
        self.user_content_edit.selectAll()
        if self.user_bubble_frame is not None:
            self.user_bubble_frame.setStyleSheet(f"""
                QFrame#UserBubbleFrame {{
                    background: {DesignTokens.bg_secondary};
                    border: 1px solid {DesignTokens.primary_focus};
                    border-radius: 8px;
                }}
            """)
        self.user_content_edit.setStyleSheet(
            f"color: {DesignTokens.text_primary}; font-size: 14px; line-height: 1.6; "
            "border: none; background: transparent;"
        )
        if self.edit_controls is not None:
            self.edit_controls.setVisible(True)
        self._set_user_action_bar_visible(False)
        for button in self.message_action_buttons:
            button.setVisible(False)

    def eventFilter(self, obj, event):
        if obj is self.user_content_edit and self.edit_controls is not None and self.edit_controls.isVisible():
            if event.type() == QEvent.KeyPress and event.key() == Qt.Key_Escape:
                self.cancel_inline_edit()
                return True
            if (
                event.type() == QEvent.KeyPress
                and event.key() in {Qt.Key_Return, Qt.Key_Enter}
                and event.modifiers() & Qt.ControlModifier
            ):
                self.submit_inline_edit()
                return True
        return super().eventFilter(obj, event)

    def cancel_inline_edit(self):
        if self.user_content_edit is None:
            return
        self.user_content_edit.setPlainText(self.edit_original_text)
        self._finish_inline_edit()

    def submit_inline_edit(self):
        if not self.source_message_id or self.user_content_edit is None:
            return
        text = self.user_content_edit.toPlainText().strip()
        if not text and not self.user_attachments:
            return
        self.editSubmitRequested.emit(self.source_message_id, text)

    def _finish_inline_edit(self):
        if self.user_content_edit is not None:
            self.user_content_edit.setReadOnly(True)
            self.user_content_edit.setStyleSheet(
                f"color: {DesignTokens.text_primary}; font-size: 14px; line-height: 1.6; border: none; background: transparent; "
                f"selection-background-color: {DesignTokens.selection_bg}; selection-color: {DesignTokens.selection_text};"
            )
        if self.user_bubble_frame is not None:
            self.user_bubble_frame.setStyleSheet(f"""
                QFrame#UserBubbleFrame {{
                    background: {DesignTokens.bg_user_bubble};
                    border: 1px solid {DesignTokens.border_settings_summary};
                    border-radius: 8px;
                }}
            """)
        if self.edit_controls is not None:
            self.edit_controls.setVisible(False)
        for button in self.message_action_buttons:
            button.setVisible(True)
        self._set_user_action_bar_visible(self.underMouse())

    def _emit_delete_request(self):
        if self.source_message_id:
            self.deleteRequested.emit(self.source_message_id)

    def show_office_draft_menu(self):
        if not getattr(self, "office_draft_menu", None) or not getattr(self, "office_draft_btn", None):
            return
        self.office_draft_menu.exec(self.office_draft_btn.mapToGlobal(self.office_draft_btn.rect().bottomLeft()))

    def _emit_office_draft_request(self, profile):
        text = (getattr(self, "main_content_text", "") or "").strip()
        if not text and self.content_edit is not None:
            text = self.content_edit.toPlainText().strip()
        if not text:
            return
        self.officeDraftRequested.emit(str(profile or OFFICE_OUTPUT_PROFILE_FREE), self.source_message_id, text)

    def set_source_message_id(self, source_message_id):
        self.source_message_id = str(source_message_id or "").strip()
        if not self.source_message_id:
            if self.edit_btn is not None:
                self.edit_btn.setVisible(False)
            if self.delete_btn is not None:
                self.delete_btn.setVisible(False)
            return
        if self.edit_btn is not None:
            self.edit_btn.setVisible(self.role == "User")
        if self.delete_btn is not None:
            self.delete_btn.setVisible(self.role == "User")

    def apply_dynamic_widths(self, message_width, user_bubble_width):
        if self.content_wrapper is not None:
            self.content_wrapper.setMaximumWidth(max(0, int(message_width)))
        if self.user_bubble_frame is not None:
            self.user_bubble_frame.setMaximumWidth(max(0, int(user_bubble_width)))
        if self.user_content_edit is not None:
            max_content_width = max(80, int(user_bubble_width) - 30)
            lines = self.user_content_edit.toPlainText().splitlines() or [""]
            natural_width = max(self.user_content_edit.fontMetrics().horizontalAdvance(line) for line in lines) + 12
            content_width = max(80, min(max_content_width, natural_width))
            self.user_content_edit.setFixedWidth(content_width)
            self.user_content_edit.scheduleAdjustHeight()
        if self.content_col is not None:
            self.content_col.setMaximumWidth(max(0, int(message_width)))

    def has_visible_stage_content(self):
        if self.role == "User":
            return True
        if bool((getattr(self, "main_content_text", "") or "").strip()):
            return True
        generated_images = getattr(self, "generated_images_container", None)
        if generated_images is not None and not generated_images.isHidden():
            return True
        if self.thinking_widget is not None and not self.thinking_widget.isHidden():
            return True
        if self.timeline_events:
            return True
        if self.inline_visualization_container is not None and not self.inline_visualization_container.isHidden():
            return True
        deliverable_cards = getattr(self, "deliverable_cards", None)
        return bool(deliverable_cards is not None and not deliverable_cards.isHidden())

    def _notify_stage_visibility_changed(self):
        parent = self.parentWidget()
        if isinstance(parent, AssistantTurnGroup):
            parent.sync_stage_visibility()

    def _refresh_conversation_geometry(self):
        if not _qt_object_alive(self):
            return
        for widget in (self.think_container, self.thinking_widget, self.content_col, self):
            if widget is None:
                continue
            layout = widget.layout()
            if layout is not None:
                layout.invalidate()
                layout.activate()
            widget.updateGeometry()
        parent = self.parentWidget()
        if isinstance(parent, AssistantTurnGroup):
            parent.sync_stage_visibility()
        self.geometryChanged.emit()

    def _has_thinking_details(self):
        for index in range(self.think_container_layout.count()):
            widget = self.think_container_layout.itemAt(index).widget()
            if widget is None:
                continue
            if isinstance(widget, AutoResizingLabel):
                if widget.text().strip():
                    return True
                continue
            return True
        return False

    def _sync_thinking_container_visibility(self):
        self.think_container.setVisible(bool(self.think_toggle_btn.isChecked() and self._has_thinking_details()))
        self._refresh_conversation_geometry()

    def _on_think_tick(self):
        if self.think_start_time is None: return
        
        elapsed = time.monotonic() - self.think_start_time
        current_total = self.think_duration + elapsed
        
        arrow = "▴" if self.think_toggle_btn.isChecked() else "▾"
        self.think_toggle_btn.setText(f" 深度思考中 · {current_total:.1f} 秒  {arrow}")

    def toggle_thinking(self, checked):
        self._sync_thinking_container_visibility()
        text = re.sub(r"\s+[▴▾]\s*$", "", self.think_toggle_btn.text())
        self.think_toggle_btn.setText(f"{text}  {'▴' if checked else '▾'}")
        log_sub_agent_runtime(
            "ui_thinking_toggled",
            session_id=self.session_id,
            group_id=str(getattr(self, "ui_turn_group_id", "")),
            stage_id=str(getattr(self, "ui_stage_id", "")),
            expanded=bool(checked),
            has_details=self._has_thinking_details(),
        )
        QTimer.singleShot(0, self._refresh_conversation_geometry)

    def set_thinking_state(self, is_thinking):
        if is_thinking:
            if not self.think_timer.isActive():
                self.think_start_time = time.monotonic()
                self.think_timer.start()
                
            arrow = "▴" if self.think_toggle_btn.isChecked() else "▾"
            self.think_toggle_btn.setText(f" 深度思考中 · {self.think_duration:.1f} 秒  {arrow}")
            self.thinking_widget.setVisible(True)
            self._notify_stage_visibility_changed()
        else:
            if self.think_timer.isActive():
                self.think_timer.stop()
                if self.think_start_time:
                    self.think_duration += time.monotonic() - self.think_start_time
                    self.think_start_time = None

    def get_active_think_widget(self, force_new=False):
        if not force_new:
            count = self.think_container_layout.count()
            if count > 0:
                widget = self.think_container_layout.itemAt(count - 1).widget()
                if isinstance(widget, AutoResizingLabel):
                    return widget
        widget = AutoResizingLabel()
        widget.setStyleSheet(
            f"color: {DesignTokens.text_secondary}; font-size: 12px; line-height: 1.5; "
            "background: transparent; border: none;"
        )
        self.think_container_layout.addWidget(widget)
        self.timeline_events.append(widget)
        widget.show()
        self._sync_thinking_container_visibility()
        return widget

    def freeze_content_fragment(self):
        # Content already rendered beneath this thought becomes the stage
        # reply for this conversational segment. Keep it visible in place.
        text = str(getattr(self, "main_content_text", "") or "").strip()
        if not text:
            return None
        self.set_main_content(text, final=True)
        return text

    def set_message_actions_enabled(self, enabled):
        self.message_actions_enabled = bool(enabled)
        final_text = bool((self.main_content_text or "").strip() and self._pending_main_content_final)
        self.copy_result_btn.setVisible(bool(self.message_actions_enabled and final_text))
        if getattr(self, "office_draft_btn", None) is not None:
            self.office_draft_btn.setVisible(bool(self.message_actions_enabled and final_text))
        if getattr(self, "skill_capture_btn", None) is not None:
            self.skill_capture_btn.setVisible(
                bool(self.message_actions_enabled and final_text and self.source_message_id)
            )

    def update_thinking(self, text=None, duration=None, is_final=False):
        if text is not None or duration is not None:
            self.thinking_widget.setVisible(True)
        if text is not None:
            widget = self.get_active_think_widget()
            widget.setText(widget.text() + str(text or ""))
            self._sync_thinking_container_visibility()
        
        if duration:
            self.think_duration = duration
        
        if is_final:
            self.set_thinking_state(False)
            self.timeline_finished_at = time.monotonic()
            total = self.think_duration
            arrow = "▴" if self.think_toggle_btn.isChecked() else "▾"
            self.think_toggle_btn.setText(f" 深度思考 · {total:.1f} 秒  {arrow}")
        self._notify_stage_visibility_changed()

    def stop_thinking_timers(self):
        if self.think_timer.isActive():
            self.think_timer.stop()
            if self.think_start_time:
                self.think_duration += time.monotonic() - self.think_start_time
                self.think_start_time = None
        timer = getattr(self, "_thinking_replay_timer", None)
        if timer and timer.isActive():
            timer.stop()
        self.timeline_finished_at = time.monotonic()
        arrow = "▴" if self.think_toggle_btn.isChecked() else "▾"
        self.think_toggle_btn.setText(f" 深度思考已停止 · {self.think_duration:.1f} 秒  {arrow}")

    def _set_main_content_view_mode(self, mode):
        target_mode = "plain" if mode == "plain" else "rich"
        if self._main_content_view_mode == target_mode and self.content_edit is not None:
            self.content_edit.setVisible(True)
            return self.content_edit
        if target_mode == "plain":
            self.content_rich_edit.setVisible(False)
            self.content_plain_edit.setVisible(True)
            self.content_edit = self.content_plain_edit
        else:
            self.content_plain_edit.setVisible(False)
            self.content_rich_edit.setVisible(True)
            self.content_edit = self.content_rich_edit
        self._main_content_view_mode = target_mode
        return self.content_edit

    def _should_render_main_content_as_plain(self, text, content_parts=None, final=False):
        if not text:
            return False
        if not final and len(text) >= STREAM_PLAIN_TEXT_THRESHOLD:
            return True
        if extract_renderable_html_response(text):
            return False
        if final and self.workspace_dir and iter_workspace_file_paths(text, self.workspace_dir):
            return False
        if final and looks_like_markdown_text(text):
            return False
        if final and len(text) < EXTREME_FINAL_PLAIN_TEXT_THRESHOLD:
            return False
        if len(text) >= LONG_TEXT_PLAIN_RENDER_THRESHOLD:
            return True
        if text.count("\n") >= LONG_TEXT_PLAIN_LINE_THRESHOLD:
            return True
        text_parts = 0
        if isinstance(content_parts, list):
            for part in content_parts:
                if isinstance(part, dict) and (part.get("type") or "").strip().lower() == "text":
                    text_parts += 1
        return text_parts > LONG_TEXT_PLAIN_LINE_THRESHOLD

    def set_main_content(self, text, content_parts=None, final=False):
        """设置对话气泡的主要内容，并合并高频流式渲染。"""
        text = text or ""
        self.main_content_text = text
        self._pending_main_content_text = text
        self._pending_main_content_parts = content_parts
        self._pending_main_content_final = bool(final)
        self._notify_stage_visibility_changed()
        actions_visible = bool(self.message_actions_enabled and final and text.strip())
        self.copy_result_btn.setVisible(actions_visible)
        if getattr(self, "office_draft_btn", None) is not None:
            self.office_draft_btn.setVisible(actions_visible)
        if getattr(self, "skill_capture_btn", None) is not None:
            self.skill_capture_btn.setVisible(bool(actions_visible and self.source_message_id))

        parts_signature = self._output_image_parts_signature(content_parts)
        already_rendered = (
            self._rendered_main_content_text == text
            and self._rendered_main_content_parts_signature == parts_signature
            and (self._rendered_main_content_final or not final)
        )
        if already_rendered:
            return

        if final:
            if self._main_content_render_timer.isActive():
                self._main_content_render_timer.stop()
            self._flush_pending_main_content_render()
            return

        now = time.time()
        elapsed = now - self._last_main_content_render_ts
        if elapsed >= self._main_content_render_interval:
            self._flush_pending_main_content_render()
            return

        if not self._main_content_render_timer.isActive():
            delay_ms = max(1, int((self._main_content_render_interval - elapsed) * 1000))
            self._main_content_render_timer.start(delay_ms)

    def _flush_pending_main_content_render(self):
        self._render_main_content(
            self._pending_main_content_text,
            content_parts=self._pending_main_content_parts,
            final=self._pending_main_content_final,
        )

    def _render_main_content(self, text, content_parts=None, final=False):
        text = text or ""
        parts_signature = self._output_image_parts_signature(content_parts)
        already_rendered = (
            self._rendered_main_content_text == text
            and self._rendered_main_content_parts_signature == parts_signature
            and (self._rendered_main_content_final or not final)
        )
        if already_rendered:
            return

        render_text = text
        if final:
            render_text = self._sync_inline_visualizations(text)

        render_mode = "plain" if self._should_render_main_content_as_plain(
            render_text,
            content_parts=content_parts,
            final=final,
        ) else "rich"
        content_widget = self._set_main_content_view_mode(render_mode)
        content_widget.setVisible(bool(render_text.strip()))

        try:
            content_widget.setUpdatesEnabled(False)
            if render_mode == "plain":
                self._render_plain_stream_content(render_text)
                render_mode = "plain"
            else:
                render_mode, html_content = render_markdown_or_html_with_cache(
                    render_text,
                    final=final,
                    workspace_dir=self.workspace_dir,
                )
                content_widget.setHtml(html_content)
        except Exception:
            plain_widget = self._set_main_content_view_mode("plain")
            plain_widget.setUpdatesEnabled(False)
            plain_widget.setPlainText(render_text)
            render_mode = "plain"
        finally:
            self.content_edit.setUpdatesEnabled(True)

        self._sync_generated_image_cards(text, content_parts, final=final)
        self._rendered_main_content_text = text
        self._rendered_main_content_parts_signature = parts_signature
        self._rendered_main_content_final = bool(final)
        self._rendered_main_content_mode = render_mode
        self._last_main_content_render_ts = time.time()
        self._sync_deliverable_cards(text)
        self.content_edit.scheduleAdjustHeight()
        QTimer.singleShot(0, self.content_edit.scheduleAdjustHeight)
        QTimer.singleShot(60, self.content_edit.scheduleAdjustHeight)
        QTimer.singleShot(0, self._refresh_conversation_geometry)
        QTimer.singleShot(60, self._refresh_conversation_geometry)
        if final:
            parent = self.parentWidget()
            if isinstance(parent, AssistantTurnGroup):
                parent.complete_pending_process_finalization(self)

    @staticmethod
    def _output_image_parts_signature(content_parts):
        return tuple(
            (
                str(part.get("source_item_id") or ""),
                str(part.get("path") or ""),
                str(part.get("mime_type") or ""),
            )
            for part in output_image_parts(content_parts)
        )

    def _sync_generated_image_cards(self, text, content_parts, *, final=False):
        container = getattr(self, "generated_images_container", None)
        layout = getattr(self, "generated_images_layout", None)
        if container is None or layout is None:
            return
        while layout.count():
            item = layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()
        images = [(image_part, False) for image_part in output_image_parts(content_parts)]
        seen_paths = {
            os.path.normcase(os.path.abspath(str(image_part.get("path") or "")))
            for image_part, _open_in_deliverables in images
            if str(image_part.get("path") or "").strip()
        }
        if final:
            for _start, _end, path in iter_workspace_file_paths(text, self.workspace_dir):
                extension = os.path.splitext(path)[1].lower()
                kind = DELIVERABLE_EXTENSIONS.get(extension, ("file", "", ""))[0]
                path_key = os.path.normcase(os.path.abspath(path))
                if kind != "image" or path_key in seen_paths:
                    continue
                images.append(({"type": "workspace_image", "path": path}, True))
                seen_paths.add(path_key)
        for image_part, open_in_deliverables in images:
            card = GeneratedImageCard(
                image_part,
                container,
                open_in_deliverables=open_in_deliverables,
            )
            if open_in_deliverables:
                card.pathActivated.connect(self._activate_workspace_image)
            layout.addWidget(card, 0, Qt.AlignLeft)
        container.setVisible(bool(images))
        self._notify_stage_visibility_changed()

    def _activate_workspace_image(self, path):
        log_ui_navigation(
            "chat_workspace_image_open_requested",
            session_id=self.session_id or "",
            extension=os.path.splitext(str(path or ""))[1].lower(),
        )
        self.deliverablePathActivated.emit(str(path or ""))

    def _sync_inline_visualizations(self, text):
        marker = "::cowork-inline-vis{file="
        if marker not in str(text or ""):
            return text
        requested = find_inline_visualization_files(text)
        if not requested:
            return text
        if self.chat_storage is None or not self.session_id:
            missing = []
            if self.chat_storage is None:
                missing.append("chat_storage")
            if not self.session_id:
                missing.append("session_id")
            log_sub_agent_runtime(
                "inline_visualization_context_missing",
                missing=missing,
                file_count=len(requested),
            )
            clean_text = strip_inline_visualization_directives(text, requested)
            message = "交互可视化未加载：消息缺少会话上下文，请重新打开会话后重试。"
            return f"{clean_text}\n\n> {message}".strip()
        artifacts = []
        for filename in requested:
            artifact = self.chat_storage.get_inline_visualization(self.session_id, filename)
            if artifact:
                artifacts.append(artifact)
        files = [artifact.get("file") for artifact in artifacts]
        if files == self._inline_visualization_files:
            return strip_inline_visualization_directives(text, files)
        if artifacts:
            self._ensure_inline_visualization_container()
        if self.inline_visualization_layout is None:
            return text
        while self.inline_visualization_layout.count():
            item = self.inline_visualization_layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()
        self.inline_visualization_cards = []
        for artifact in artifacts:
            card = InlineVisualizationCard(
                artifact,
                self.session_id,
                self.chat_storage,
                read_only=not self.visualize_enabled,
            )
            self.inline_visualization_layout.addWidget(card)
            self.inline_visualization_cards.append(card)
        self._inline_visualization_files = files
        self.inline_visualization_container.setVisible(bool(files))
        return strip_inline_visualization_directives(text, files)

    def _ensure_inline_visualization_container(self):
        if self.inline_visualization_container is not None:
            return
        container = QWidget()
        container.setVisible(False)
        layout = QVBoxLayout(container)
        layout.setContentsMargins(0, 4, 0, 0)
        layout.setSpacing(8)
        self.inline_visualization_container = container
        self.inline_visualization_layout = layout
        self.content_col_layout.addWidget(container)

    def _handle_content_link(self, href):
        value = str(href or "").strip()
        if value.startswith("cowork-file:"):
            self.deliverablePathActivated.emit(unquote(value[len("cowork-file:"):]))
            return
        url = QUrl(value)
        scheme = url.scheme().lower()
        if scheme not in {"http", "https"}:
            return
        opened = bool(QDesktopServices.openUrl(url))
        log_ui_navigation(
            "chat_external_link_opened" if opened else "chat_external_link_open_failed",
            scheme=scheme,
        )
        if not opened:
            QMessageBox.warning(
                self,
                "无法打开链接",
                "系统默认浏览器未能打开该网页，请检查默认浏览器设置后重试。",
            )

    def _sync_deliverable_cards(self, text):
        if not hasattr(self, "deliverable_cards_layout"):
            return
        paths = [path for _start, _end, path in iter_workspace_file_paths(text, self.workspace_dir)]
        if paths == self._deliverable_paths:
            return
        while self.deliverable_cards_layout.count():
            item = self.deliverable_cards_layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()
        visible_card_count = 0
        for path in paths:
            ext = os.path.splitext(path)[1].lower()
            kind, type_label, icon_name = DELIVERABLE_EXTENSIONS.get(
                ext, ("file", ext.lstrip(".").upper() or "文件", "fa5s.file")
            )
            if kind == "image":
                continue
            button = QPushButton(os.path.basename(path))
            button.setCursor(Qt.PointingHandCursor)
            button.setIcon(qta.icon(icon_name, color=DesignTokens.primary))
            button.setToolTip(path)
            button.setAccessibleName(f"预览交付物 {os.path.basename(path)}")
            button.setMinimumWidth(110)
            button.setMaximumWidth(220)
            button.setStyleSheet(f"""
                QPushButton {{
                    background: {DesignTokens.bg_main};
                    color: {DesignTokens.text_primary};
                    border: 1px solid {DesignTokens.border_subtle};
                    border-radius: 14px;
                    padding: 8px 12px;
                    font-size: 12px;
                    font-weight: 600;
                    text-align: left;
                }}
                QPushButton:hover {{
                    background: {DesignTokens.primary_soft};
                    border-color: {rgba_from_hex(DesignTokens.primary, 0.28)};
                    color: {DesignTokens.primary};
                }}
                QPushButton:pressed {{
                    background: {rgba_from_hex(DesignTokens.primary, 0.14)};
                }}
            """)
            button.setProperty("deliverableType", kind)
            button.setStatusTip(type_label)
            button.clicked.connect(lambda checked=False, value=path: self.deliverablePathActivated.emit(value))
            self.deliverable_cards_layout.addWidget(button)
            visible_card_count += 1
        self._deliverable_paths = paths
        self.deliverable_cards.setVisible(bool(visible_card_count))
        self.deliverablePathsChanged.emit(list(paths))

    def _render_plain_stream_content(self, text):
        """Avoid full Markdown conversion while a long response is still streaming."""
        previous = self._rendered_main_content_text or ""
        if self._rendered_main_content_mode == "plain" and text.startswith(previous):
            delta = text[len(previous):]
            if delta:
                cursor = self.content_edit.textCursor()
                cursor.movePosition(QTextCursor.End)
                cursor.insertText(delta)
                self.content_edit.setTextCursor(cursor)
            return
        self.content_edit.setPlainText(text)

    def copy_main_content(self):
        text = (self.main_content_text or "").strip() or self.content_edit.toPlainText().strip()
        if not text:
            return
        QApplication.clipboard().setText(text)
        self.copy_result_btn.setText("已复制")
        QTimer.singleShot(1200, self._reset_copy_result_button)

    def _reset_copy_result_button(self):
        if not _qt_object_alive(self):
            return
        button = getattr(self, "copy_result_btn", None)
        if _qt_object_alive(button):
            button.setText("复制结果")
        
    def add_tool_card(self, card_widget, session_id=None):
        self.think_container_layout.addWidget(card_widget)
        self.timeline_events.append(card_widget)
        self._start_new_think_segment = True
        self.thinking_widget.setVisible(True)
        self._sync_thinking_container_visibility()
        self._notify_stage_visibility_changed()


