def session_history_ready(state):
    if not state:
        return False
    if getattr(state, "history_loading", False):
        return False
    return bool(getattr(state, "history_loaded", False))


class DrawerResizeHandle(QWidget):
    widthRequested = Signal(int)
    resizeFinished = Signal()

    def __init__(self, parent=None):
        super().__init__(parent)
        self._press_x = None
        self._start_width = 0
        self.setCursor(Qt.SizeHorCursor)
        self.setFixedWidth(8)
        self.setToolTip("拖动调整预览宽度")
        self.setStyleSheet("background: transparent; border: none;")

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            self._press_x = event.globalPosition().x()
            self._start_width = self.parentWidget().width() if self.parentWidget() else 0
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event):
        if self._press_x is not None:
            requested = self._start_width + int(self._press_x - event.globalPosition().x())
            self.widthRequested.emit(requested)
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event):
        if self._press_x is not None:
            self._press_x = None
            self.resizeFinished.emit()
            event.accept()
            return
        super().mouseReleaseEvent(event)


class DeliverableWebPreview(QWidget):
    """Qt-owned scrolling shell for the embedded HTML deliverable preview."""

    def __init__(self, web_view, parent=None):
        super().__init__(parent)
        self.setProperty("themeSurface", "preview-shell")
        self.web_view = web_view
        self._syncing_scrollbars = False
        self._sync_pending = False
        self._pending_page_delta_x = 0.0
        self._pending_page_delta_y = 0.0
        self._page_wheel_flush_pending = False

        layout = QGridLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setHorizontalSpacing(3)
        layout.setVerticalSpacing(3)
        layout.addWidget(web_view, 0, 0)

        self.vertical_scrollbar = QScrollBar(Qt.Vertical)
        self.horizontal_scrollbar = QScrollBar(Qt.Horizontal)
        self.vertical_scrollbar.setObjectName("DeliverableVerticalScrollBar")
        self.horizontal_scrollbar.setObjectName("DeliverableHorizontalScrollBar")
        self.vertical_scrollbar.setVisible(False)
        self.horizontal_scrollbar.setVisible(False)
        layout.addWidget(self.vertical_scrollbar, 0, 1)
        layout.addWidget(self.horizontal_scrollbar, 1, 0)

        self.refresh_theme()
        self.vertical_scrollbar.valueChanged.connect(self._apply_scrollbar_values)
        self.horizontal_scrollbar.valueChanged.connect(self._apply_scrollbar_values)
        web_view.loadFinished.connect(self._handle_load_finished)
        app = QApplication.instance()
        if app is None:
            raise RuntimeError("HTML 预览滚轮控制需要已初始化的 QApplication")
        app.installEventFilter(self)
        self._application_event_filter_installed = True
        bind_theme(self, self.refresh_theme, surface="preview_shell")

    def dispose_event_filter(self):
        if not self._application_event_filter_installed:
            return
        app = QApplication.instance()
        if app is not None:
            app.removeEventFilter(self)
        self._application_event_filter_installed = False

    def refresh_theme(self, _resolved=None):
        self.setStyleSheet(
            f'QWidget[themeSurface="preview-shell"] {{ '
            f"background: {DesignTokens.preview_shell_bg}; "
            f"color: {DesignTokens.preview_shell_text}; "
            f"border: 1px solid {DesignTokens.preview_shell_border}; "
            f"border-radius: {DesignTokens.preview_shell_radius}px; }}"
        )
        scrollbar_style = f"""
            QScrollBar {{ background: transparent; border: none; margin: 0px; }}
            QScrollBar:vertical {{ width: {DesignTokens.scrollbar_width}px; }}
            QScrollBar:horizontal {{ height: {DesignTokens.scrollbar_width}px; }}
            QScrollBar::handle {{ background: {DesignTokens.scrollbar_thumb}; border-radius: {max(1, DesignTokens.scrollbar_width // 2)}px; min-width: 30px; min-height: 30px; }}
            QScrollBar::handle:hover {{ background: {DesignTokens.scrollbar_thumb_hover}; }}
            QScrollBar::add-line, QScrollBar::sub-line {{ width: 0px; height: 0px; }}
            QScrollBar::add-page, QScrollBar::sub-page {{ background: transparent; }}
        """
        self.vertical_scrollbar.setStyleSheet(scrollbar_style)
        self.horizontal_scrollbar.setStyleSheet(scrollbar_style)

    def _handle_load_finished(self, ok):
        if not ok:
            return
        self.schedule_scrollbar_sync()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.schedule_scrollbar_sync()

    def eventFilter(self, obj, event):
        if event.type() == QEvent.Wheel and not (event.modifiers() & Qt.ControlModifier):
            if not self.isVisible() or not self.web_view.isVisible():
                return super().eventFilter(obj, event)
            try:
                global_position = event.globalPosition().toPoint()
                position = self.web_view.mapFromGlobal(global_position)
            except Exception:
                return super().eventFilter(obj, event)
            if not self.web_view.rect().contains(position):
                return super().eventFilter(obj, event)
            pixel_delta = event.pixelDelta()
            angle_delta = event.angleDelta()
            delta_x = -pixel_delta.x() if not pixel_delta.isNull() else -angle_delta.x() / 2
            delta_y = -pixel_delta.y() if not pixel_delta.isNull() else -angle_delta.y() / 2
            if event.modifiers() & Qt.ShiftModifier and not delta_x:
                delta_x = delta_y
                delta_y = 0
            script = (
                "window.__coworkScrollWheelAt && "
                f"window.__coworkScrollWheelAt({position.x()},{position.y()},"
                f"{delta_x:.2f},{delta_y:.2f})"
            )
            self.web_view.page().runJavaScript(
                script,
                lambda result, x=delta_x, y=delta_y: self._handle_wheel_result(result, x, y),
            )
            event.accept()
            return True
        return False

    def _handle_wheel_result(self, result, delta_x, delta_y):
        if result == "page":
            self._pending_page_delta_x += delta_x
            self._pending_page_delta_y += delta_y
            if not self._page_wheel_flush_pending:
                self._page_wheel_flush_pending = True
                QTimer.singleShot(0, self._flush_page_wheel_delta)
            return
        if result == "nested":
            self.web_view.update()
        self.schedule_scrollbar_sync()

    def _flush_page_wheel_delta(self):
        self._page_wheel_flush_pending = False
        delta_x = self._pending_page_delta_x
        delta_y = self._pending_page_delta_y
        self._pending_page_delta_x = 0.0
        self._pending_page_delta_y = 0.0
        if delta_x:
            self.horizontal_scrollbar.setValue(
                self.horizontal_scrollbar.value() + int(round(delta_x))
            )
        if delta_y:
            self.vertical_scrollbar.setValue(
                self.vertical_scrollbar.value() + int(round(delta_y))
            )

    def schedule_scrollbar_sync(self):
        if self._sync_pending:
            return
        self._sync_pending = True
        QTimer.singleShot(0, self._sync_scrollbars)

    def _sync_scrollbars(self):
        self._sync_pending = False
        self.web_view.page().runJavaScript(
            "window.__coworkPreviewMetrics ? JSON.stringify(window.__coworkPreviewMetrics()) : ''",
            self._apply_page_metrics,
        )

    def _apply_page_metrics(self, metrics):
        if isinstance(metrics, str):
            try:
                metrics = json.loads(metrics)
            except json.JSONDecodeError:
                metrics = None
        if not isinstance(metrics, dict):
            return
        self._syncing_scrollbars = True
        try:
            width = max(0, int(metrics.get("width") or 0))
            height = max(0, int(metrics.get("height") or 0))
            client_width = max(0, int(metrics.get("clientWidth") or 0))
            client_height = max(0, int(metrics.get("clientHeight") or 0))
            max_x = max(0, width - client_width)
            max_y = max(0, height - client_height)
            self.horizontal_scrollbar.setRange(0, max_x)
            self.horizontal_scrollbar.setPageStep(client_width)
            self.horizontal_scrollbar.setValue(max(0, int(metrics.get("left") or 0)))
            self.horizontal_scrollbar.setVisible(max_x > 1)
            self.vertical_scrollbar.setRange(0, max_y)
            self.vertical_scrollbar.setPageStep(client_height)
            self.vertical_scrollbar.setValue(max(0, int(metrics.get("top") or 0)))
            self.vertical_scrollbar.setVisible(max_y > 1)
        finally:
            self._syncing_scrollbars = False

    def _apply_scrollbar_values(self, _value):
        if self._syncing_scrollbars:
            return
        x = self.horizontal_scrollbar.value()
        y = self.vertical_scrollbar.value()
        self.web_view.page().runJavaScript(
            f"window.scrollTo({x},{y})",
            lambda _result: self._handle_page_scroll_applied(),
        )

    def _handle_page_scroll_applied(self):
        self.web_view.update()
        self.schedule_scrollbar_sync()


class DeliverableEditorBridge(QObject):
    """Bounded WebChannel transport for the isolated deliverable editors."""

    readyReported = Signal(str)
    dirtyReported = Signal(bool)
    editorLoadedReported = Signal(str)
    payloadReady = Signal(str, str, str)
    errorReported = Signal(str)

    MAX_CHUNKS = 1024
    MAX_PAYLOAD_CHARS = 40 * 1024 * 1024

    def __init__(self, parent=None):
        super().__init__(parent)
        self._session_id = ""
        self._payload_kind = ""
        self._expected_chunks = 0
        self._chunks = []
        self._payload_chars = 0

    def reset(self, session_id=""):
        self._session_id = str(session_id or "")
        self._payload_kind = ""
        self._expected_chunks = 0
        self._chunks = []
        self._payload_chars = 0

    @Slot(str)
    def ready(self, mode):
        self.readyReported.emit(str(mode or ""))

    @Slot(bool)
    def setDirty(self, dirty):
        self.dirtyReported.emit(bool(dirty))

    @Slot(str)
    def editorLoaded(self, session_id):
        self.editorLoadedReported.emit(str(session_id or ""))

    @Slot(str, str, int)
    def beginPayload(self, session_id, kind, total):
        session_id = str(session_id or "")
        total = int(total or 0)
        if not self._session_id or session_id != self._session_id:
            self._fail("编辑器返回了过期会话的数据。")
            return
        if total <= 0 or total > self.MAX_CHUNKS:
            self._fail("编辑器返回的数据分块数量超出安全限制。")
            return
        self._payload_kind = str(kind or "")
        self._expected_chunks = total
        self._chunks = [None] * total
        self._payload_chars = 0

    @Slot(str, int, str)
    def appendPayload(self, session_id, index, chunk):
        if str(session_id or "") != self._session_id or not self._expected_chunks:
            self._fail("编辑器数据分块不属于当前会话。")
            return
        index = int(index)
        value = str(chunk or "")
        if index < 0 or index >= self._expected_chunks or self._chunks[index] is not None:
            self._fail("编辑器数据分块顺序无效。")
            return
        self._payload_chars += len(value)
        if self._payload_chars > self.MAX_PAYLOAD_CHARS:
            self._fail("编辑器返回的数据超过安全传输上限。")
            return
        self._chunks[index] = value

    @Slot(str)
    def finishPayload(self, session_id):
        if str(session_id or "") != self._session_id or not self._expected_chunks:
            self._fail("编辑器数据结束标记不属于当前会话。")
            return
        if any(chunk is None for chunk in self._chunks):
            self._fail("编辑器数据分块不完整。")
            return
        payload = "".join(self._chunks)
        kind = self._payload_kind
        active_session = self._session_id
        self._payload_kind = ""
        self._expected_chunks = 0
        self._chunks = []
        self._payload_chars = 0
        self.payloadReady.emit(active_session, kind, payload)

    @Slot(str)
    def reportError(self, message):
        self.errorReported.emit(str(message or "编辑器发生未知错误。"))

    def _fail(self, message):
        self._payload_kind = ""
        self._expected_chunks = 0
        self._chunks = []
        self._payload_chars = 0
        self.errorReported.emit(str(message))


class DeliverableEditLoadWorker(QThread):
    finished_signal = Signal(dict)

    def __init__(self, path, selected_encoding="", parent=None):
        super().__init__(parent)
        self.path = os.path.abspath(str(path or ""))
        self.selected_encoding = str(selected_encoding or "")

    def run(self):
        started = time.monotonic()
        try:
            log_sub_agent_runtime(
                "deliverable_edit_preflight_start",
                path=self.path,
                selected_encoding=bool(self.selected_encoding),
            )
            session, report = create_edit_session(
                self.path,
                selected_encoding=self.selected_encoding,
            )
            payload = load_editor_payload(session)
            log_sub_agent_runtime(
                "deliverable_edit_preflight_finish",
                path=self.path,
                kind=session.descriptor.kind,
                elapsed_ms=round((time.monotonic() - started) * 1000),
                size=session.initial_size,
                preserved_header_footer_count=int(
                    session.metadata.get("docx_preserved_header_footer_count") or 0
                ),
            )
            self.finished_signal.emit(
                {
                    "ok": True,
                    "session": session,
                    "report": report,
                    "payload": payload,
                }
            )
        except DeliverableEditError as exc:
            log_sub_agent_runtime(
                "deliverable_edit_preflight_error",
                path=self.path,
                code=exc.code,
                error=exc.message,
            )
            self.finished_signal.emit(
                {"ok": False, "code": exc.code, "message": exc.message}
            )
        except Exception as exc:
            log_sub_agent_runtime(
                "deliverable_edit_preflight_error",
                path=self.path,
                code="unexpected_error",
                error=str(exc),
            )
            self.finished_signal.emit(
                {
                    "ok": False,
                    "code": "unexpected_error",
                    "message": f"准备编辑器失败：{exc}",
                }
            )


class DeliverableEditSaveWorker(QThread):
    finished_signal = Signal(dict)

    def __init__(
        self,
        session,
        payload,
        target_path="",
        serialized_data=None,
        parent=None,
    ):
        super().__init__(parent)
        self.session = session
        self.payload = payload
        self.target_path = os.path.abspath(str(target_path or "")) if target_path else ""
        self.serialized_data = (
            bytes(serialized_data)
            if isinstance(serialized_data, (bytes, bytearray))
            else None
        )

    def run(self):
        data = b""
        try:
            data = (
                self.serialized_data
                if self.serialized_data is not None
                else serialize_editor_payload(self.session, self.payload)
            )
            if self.target_path:
                result = save_copy(self.session, data, self.target_path)
            else:
                result = atomic_save_session(
                    self.session,
                    data,
                    event_logger=log_sub_agent_runtime,
                )
            self.finished_signal.emit(
                {
                    "ok": True,
                    "result": result,
                    "saved_copy": bool(self.target_path),
                }
            )
        except DeliverableEditError as exc:
            self.finished_signal.emit(
                {
                    "ok": False,
                    "code": exc.code,
                    "message": exc.message,
                    "serialized": data,
                }
            )
        except Exception as exc:
            log_sub_agent_runtime(
                "deliverable_edit_save_error",
                path=getattr(self.session, "path", ""),
                error=str(exc),
            )
            self.finished_signal.emit(
                {
                    "ok": False,
                    "code": "unexpected_error",
                    "message": f"保存失败：{exc}",
                    "serialized": data,
                }
            )


class DeliverableRestoreWorker(QThread):
    finished_signal = Signal(dict)

    def __init__(self, path, parent=None):
        super().__init__(parent)
        self.path = os.path.abspath(str(path or ""))

    def run(self):
        try:
            result = restore_previous_version(self.path)
            self.finished_signal.emit({"ok": True, "result": result})
        except DeliverableEditError as exc:
            self.finished_signal.emit(
                {"ok": False, "code": exc.code, "message": exc.message}
            )
        except Exception as exc:
            self.finished_signal.emit(
                {
                    "ok": False,
                    "code": "unexpected_error",
                    "message": f"恢复上一版失败：{exc}",
                }
            )


class SmartSplitterHandle(QSplitterHandle):
    def __init__(self, orientation, parent):
        super().__init__(orientation, parent)

    def mouseDoubleClickEvent(self, event):
        # Reset to default sizes on double click
        if self.splitter():
            self.splitter().on_handle_double_clicked(self)

    def mouseReleaseEvent(self, event):
        super().mouseReleaseEvent(event)
        if self.splitter():
            self.splitter().check_auto_collapse()

class SmartSplitter(QSplitter):
    sizesChanged = Signal()

    def __init__(self, orientation, parent=None):
        super().__init__(orientation, parent)
        self.setHandleWidth(1) # Visual width is 1px via CSS, but we keep this consistent
        
        self.refresh_theme()
        bind_theme(self, self.refresh_theme, surface="global")

    def refresh_theme(self, _resolved=None):
        orientation = self.orientation()
        if orientation == Qt.Horizontal:
            self.setStyleSheet(f"""
                QSplitter::handle:horizontal {{
                    background-color: transparent; 
                    width: 1px; 
                    margin: 0; 
                }}
                QSplitter::handle:horizontal:hover {{
                    background-color: {rgba_from_hex(DesignTokens.primary, 0.16)};
                }}
                QSplitter::handle:vertical {{
                    background-color: {DesignTokens.separator};
                    height: 1px; 
                    margin: 4px 0; 
                }}
                QSplitter::handle:vertical:hover {{
                    background-color: {DesignTokens.primary};
                }}
            """)
        else:
            self.setStyleSheet(f"""
                QSplitter::handle:vertical {{
                    background-color: {DesignTokens.separator};
                    height: 1px; 
                    margin: 4px 0; 
                }}
                QSplitter::handle:vertical:hover {{
                    background-color: {DesignTokens.primary};
                }}
            """)

    def createHandle(self):
        return SmartSplitterHandle(self.orientation(), self)

    def setSizes(self, sizes):
        super().setSizes(sizes)
        self.sizesChanged.emit()

    def on_handle_double_clicked(self, handle):
        # Find which handle was clicked
        idx = -1
        for i in range(1, self.count()):
            if self.handle(i) == handle:
                idx = i
                break
        
        if idx == -1:
            return

        sizes = self.sizes()
        if self.orientation() == Qt.Horizontal:
            # Assuming 3-column layout: [Sidebar, Main, RightSidebar]
            # Handle 1: Between Sidebar (0) and Main (1)
            if idx == 1: 
                target_width = DesignTokens.sidebar_width
                if len(sizes) > 1:
                    current_w = sizes[0]
                    diff = target_width - current_w
                    sizes[0] = target_width
                    sizes[1] -= diff
            # Handle 2: Between Main (1) and RightSidebar (2)
            elif idx == 2:
                target_width = 280
                if len(sizes) > 2:
                    current_w = sizes[2]
                    diff = target_width - current_w
                    sizes[2] = target_width
                    sizes[1] -= diff
        else:
            # Vertical Splitter (Workspace)
            # Default ratio 2:1
            total = sum(sizes)
            target_h1 = int(total * 0.66)
            target_h2 = total - target_h1
            sizes = [target_h1, target_h2]
            
        self.setSizes(sizes)

    def check_auto_collapse(self):
        if self.orientation() == Qt.Horizontal:
            sizes = self.sizes()
            # Left sidebar (index 0)
            if len(sizes) > 0 and sizes[0] < 50 and sizes[0] > 0:
                sizes[1] += sizes[0]
                sizes[0] = 0
                self.setSizes(sizes)
            
            # Right sidebar (index 2)
            if len(sizes) > 2:
                if sizes[2] < 50 and sizes[2] > 0:
                    sizes[1] += sizes[2]
                    sizes[2] = 0
                    self.setSizes(sizes)


class FileNavigatorProxyModel(QSortFilterProxyModel):
    """Workspace tree filtering with an explicit full-path tooltip."""

    def data(self, index, role=Qt.DisplayRole):
        if role == Qt.ToolTipRole and index.isValid():
            source = self.sourceModel()
            source_index = self.mapToSource(index)
            if source is not None and hasattr(source, "filePath"):
                return source.filePath(source_index)
        return super().data(index, role)


class FileTabScrollArea(QScrollArea):
    """Horizontal-only scroll surface for the file tab strip."""

    def wheelEvent(self, event):
        bar = self.horizontalScrollBar()
        delta = event.angleDelta().y() or event.angleDelta().x()
        if delta:
            step = max(72, int(bar.pageStep() * 0.45))
            bar.setValue(bar.value() - step if delta > 0 else bar.value() + step)
            event.accept()
            return
        super().wheelEvent(event)


class FileTabStrip(QWidget):
    """Ordered runtime file tabs with activation, close, scroll, and overflow."""

    activateRequested = Signal(str)
    closeRequested = Signal(str)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.paths = []
        self.active_path = ""
        self._tab_frames = {}
        self._tab_bodies = {}
        self.setObjectName("FileTabStrip")
        self.setMinimumWidth(0)
        self.setFixedHeight(36)

        layout = QHBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(4)
        self.scroll = FileTabScrollArea(self)
        self.scroll.setObjectName("FileTabScrollArea")
        self.scroll.setWidgetResizable(True)
        self.scroll.setFrameShape(QFrame.NoFrame)
        self.scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.scroll.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.scroll.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
        self.scroll.setFixedHeight(36)
        self.tabs_host = QWidget()
        self.tabs_host.setObjectName("FileTabsHost")
        self.tabs_layout = QHBoxLayout(self.tabs_host)
        self.tabs_layout.setContentsMargins(0, 0, 0, 0)
        self.tabs_layout.setSpacing(4)
        self.tabs_layout.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)
        self.scroll.setWidget(self.tabs_host)
        layout.addWidget(self.scroll, 1)

        self.overflow_btn = QToolButton(self)
        self.overflow_btn.setObjectName("FileTabOverflowButton")
        self.overflow_btn.setIcon(qta.icon("fa5s.chevron-down", color=DesignTokens.text_secondary))
        self.overflow_btn.setToolTip("全部已打开文件")
        self.overflow_btn.setPopupMode(QToolButton.InstantPopup)
        self.overflow_btn.setFixedSize(30, 30)
        self.overflow_btn.setCursor(Qt.PointingHandCursor)
        self.overflow_btn.setStyleSheet(apple_tool_button_style(False))
        self.overflow_menu = create_styled_menu(self.overflow_btn)
        self.overflow_btn.setMenu(self.overflow_menu)
        self.overflow_btn.hide()
        layout.addWidget(self.overflow_btn)

        self.refresh_theme()
        bind_theme(self, self.refresh_theme, surface="preview_shell")

    @staticmethod
    def _path_key(path):
        return os.path.normcase(os.path.abspath(os.path.normpath(str(path or ""))))

    def refresh_theme(self, _resolved=None):
        self.setStyleSheet(
            f"""
            QWidget#FileTabStrip, QWidget#FileTabsHost {{
                background: transparent;
                border: none;
            }}
            QScrollArea#FileTabScrollArea {{
                background: transparent;
                border: none;
            }}
            QFrame#FileTab {{
                background: transparent;
                border: 1px solid transparent;
                border-radius: 7px;
            }}
            QFrame#FileTab[active="true"] {{
                background: {DesignTokens.bg_secondary};
                border-color: {DesignTokens.border_subtle};
            }}
            QFrame#FileTab[missing="true"] {{
                border-color: {DesignTokens.warning_border};
            }}
            QToolButton#FileTabBody {{
                background: transparent;
                color: {DesignTokens.text_primary};
                border: none;
                padding: 0px 3px;
                text-align: left;
                font-size: 12px;
                font-weight: 600;
            }}
            QToolButton#FileTabBody:hover {{ color: {DesignTokens.primary}; }}
            QToolButton#FileTabClose {{
                background: transparent;
                border: none;
                border-radius: 5px;
                padding: 0px;
            }}
            QToolButton#FileTabClose:hover {{ background: {DesignTokens.bg_hover}; }}
            """
        )
        self.overflow_btn.setIcon(
            qta.icon("fa5s.chevron-down", color=DesignTokens.text_secondary)
        )
        self.overflow_btn.setStyleSheet(apple_tool_button_style(False))
        QTimer.singleShot(0, self._sync_tab_widths)
        QTimer.singleShot(0, self._sync_overflow)

    def _clear_tabs(self):
        while self.tabs_layout.count():
            item = self.tabs_layout.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()
        self._tab_frames = {}
        self._tab_bodies = {}

    def _sync_tab_widths(self):
        if not _qt_object_alive(self):
            return
        count = len(self._tab_frames)
        if not count:
            self.tabs_host.setMinimumWidth(0)
            return
        spacing = self.tabs_layout.spacing()
        available = max(0, self.scroll.viewport().width())
        preferred = int(DesignTokens.file_tab_preferred_width)
        minimum = int(DesignTokens.file_tab_min_width)
        fitted = (available - spacing * (count - 1)) // count
        tab_width = min(preferred, max(minimum, fitted))
        total_width = tab_width * count + spacing * (count - 1)
        self.tabs_host.setMinimumWidth(total_width)
        for key, frame in self._tab_frames.items():
            frame.setFixedWidth(tab_width)
            body = self._tab_bodies.get(key)
            if body is None:
                continue
            name = str(body.property("fullName") or "")
            text_width = max(32, tab_width - 70)
            body.setText(
                QFontMetrics(body.font()).elidedText(name, Qt.ElideMiddle, text_width)
            )
        self.tabs_host.adjustSize()

    def _file_icon(self, path):
        if not os.path.isfile(path):
            return qta.icon("fa5s.exclamation-triangle", color=DesignTokens.warning_text)
        ext = os.path.splitext(path)[1].lower()
        if ext in {".py", ".js", ".ts", ".json", ".html", ".htm", ".css"}:
            name = "fa5s.file-code"
        elif ext in OFFICE_EXTENSIONS:
            name = "fa5s.file-powerpoint" if ext == ".pptx" else "fa5s.file-alt"
        elif ext in {".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg"}:
            name = "fa5s.file-image"
        elif ext == ".pdf":
            name = "fa5s.file-pdf"
        else:
            name = "fa5s.file-alt"
        return qta.icon(name, color=DesignTokens.text_secondary)

    def set_paths(self, paths, active_path=""):
        normalized = []
        seen = set()
        for path in paths or []:
            raw_value = str(path or "").strip()
            if not raw_value:
                continue
            value = os.path.normpath(raw_value)
            key = self._path_key(value)
            if key in seen:
                continue
            seen.add(key)
            normalized.append(value)
        active_key = self._path_key(active_path) if active_path else ""
        self.paths = normalized
        self.active_path = next(
            (path for path in normalized if self._path_key(path) == active_key),
            "",
        )
        self._clear_tabs()
        for path in normalized:
            active = self._path_key(path) == self._path_key(self.active_path)
            missing = not os.path.isfile(path)
            frame = QFrame(self.tabs_host)
            frame.setObjectName("FileTab")
            frame.setProperty("active", active)
            frame.setProperty("missing", missing)
            frame.setFixedHeight(32)
            frame_layout = QHBoxLayout(frame)
            frame_layout.setContentsMargins(6, 2, 3, 2)
            frame_layout.setSpacing(3)
            body = QToolButton(frame)
            body.setObjectName("FileTabBody")
            body.setToolButtonStyle(Qt.ToolButtonTextBesideIcon)
            body.setIcon(self._file_icon(path))
            name = os.path.basename(path) or path
            body.setProperty("fullName", name)
            body.setText(name)
            body.setToolTip(path if not missing else f"文件已不存在\n{path}")
            body.setCursor(Qt.PointingHandCursor)
            body.setMinimumWidth(0)
            body.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            body.clicked.connect(lambda checked=False, value=path: self.activateRequested.emit(value))
            frame_layout.addWidget(body, 1)
            close_btn = QToolButton(frame)
            close_btn.setObjectName("FileTabClose")
            close_btn.setIcon(qta.icon("fa5s.times", color=DesignTokens.text_secondary))
            close_btn.setToolTip(f"关闭 {name}")
            close_btn.setCursor(Qt.PointingHandCursor)
            close_btn.setFixedSize(22, 22)
            close_btn.clicked.connect(lambda checked=False, value=path: self.closeRequested.emit(value))
            frame_layout.addWidget(close_btn)
            self.tabs_layout.addWidget(frame)
            key = self._path_key(path)
            self._tab_frames[key] = frame
            self._tab_bodies[key] = body
        self._sync_tab_widths()
        self.tabs_host.adjustSize()
        self._rebuild_overflow_menu()
        QTimer.singleShot(0, self._sync_overflow)
        QTimer.singleShot(0, self.ensure_active_visible)

    def _rebuild_overflow_menu(self):
        self.overflow_menu.clear()
        active_key = self._path_key(self.active_path) if self.active_path else ""
        for path in self.paths:
            name = os.path.basename(path) or path
            if not os.path.isfile(path):
                name = f"{name}（已不存在）"
            action = QAction(self._file_icon(path), name, self.overflow_menu)
            action.setCheckable(True)
            action.setChecked(self._path_key(path) == active_key)
            action.setToolTip(path)
            action.triggered.connect(
                lambda checked=False, value=path: self.activateRequested.emit(value)
            )
            self.overflow_menu.addAction(action)

    def _sync_overflow(self):
        if not _qt_object_alive(self):
            return
        if not self.paths:
            self.overflow_btn.hide()
            return
        self._sync_tab_widths()
        overflow = self.tabs_host.sizeHint().width() > self.scroll.viewport().width()
        visibility_changed = self.overflow_btn.isVisible() != overflow
        self.overflow_btn.setVisible(overflow)
        if visibility_changed:
            QTimer.singleShot(0, self._sync_tab_widths)

    def ensure_active_visible(self):
        if not _qt_object_alive(self):
            return
        frame = self._tab_frames.get(self._path_key(self.active_path)) if self.active_path else None
        if frame is not None and _qt_object_alive(frame):
            self.scroll.ensureWidgetVisible(frame, 8, 0)

    def resizeEvent(self, event):
        super().resizeEvent(event)
        QTimer.singleShot(0, self._sync_tab_widths)
        QTimer.singleShot(0, self._sync_overflow)


class FileWorkbench(QWidget):
    """Single-surface file workspace with one movable navigator panel."""

    effectiveModeChanged = Signal(str)
    autoDismissRequested = Signal(str)

    def __init__(self, navigator, content, parent=None):
        super().__init__(parent)
        self.navigator = navigator
        self.content = content
        self.navigator.setParent(self)
        self.content.setParent(self)
        self.navigator_visible = True
        self.navigator_pinned = False
        self.editor_focus = False
        self.navigator_width = int(getattr(DesignTokens, "file_navigator_width", 320))
        self.navigator_min_width = int(getattr(DesignTokens, "file_navigator_min_width", 240))
        self.content_min_width = int(getattr(DesignTokens, "file_workbench_content_min_width", 280))
        self.navigator_preferred_height = None
        self._effective_mode = "overlay"
        self._auto_dismiss_anchors = []
        self.setMinimumSize(0, 0)
        self.content.show()
        self.navigator.show()
        self.navigator.installEventFilter(self)
        app = QApplication.instance()
        if app is None:
            raise RuntimeError("文件导航浮层需要已初始化的 QApplication")
        app.installEventFilter(self)
        self._application_event_filter_installed = True
        self.refresh_theme()
        bind_theme(self, self.refresh_theme, surface="preview_shell")

    def dispose_event_filter(self):
        if not self._application_event_filter_installed:
            return
        app = QApplication.instance()
        if app is not None:
            app.removeEventFilter(self)
        self._application_event_filter_installed = False

    def set_auto_dismiss_anchors(self, *widgets):
        self._auto_dismiss_anchors = [widget for widget in widgets if widget is not None]

    def _is_unpinned_overlay_visible(self):
        return bool(
            self.navigator_visible
            and not self.navigator_pinned
            and self.navigator.isVisible()
            and self.isVisible()
        )

    @staticmethod
    def _widget_belongs_to(widget, ancestor):
        current = widget
        while current is not None:
            if current is ancestor:
                return True
            current = current.parentWidget() if isinstance(current, QWidget) else None
        return False

    def _is_navigator_interaction(self, widget):
        if self._widget_belongs_to(widget, self.navigator):
            return True
        return any(
            self._widget_belongs_to(widget, anchor)
            for anchor in self._auto_dismiss_anchors
            if _qt_object_alive(anchor)
        )

    def _is_internal_pointer_event(self, watched, global_position=None):
        if global_position is not None:
            navigator_position = self.navigator.mapFromGlobal(global_position)
            if self.navigator.rect().contains(navigator_position):
                return True
        widget = watched if isinstance(watched, QWidget) else None
        if widget is None and global_position is not None:
            widget = QApplication.widgetAt(global_position)
        if self._is_navigator_interaction(widget):
            return True
        popup = QApplication.activePopupWidget()
        if popup is None or not self._is_navigator_interaction(popup):
            return False
        if global_position is None:
            return True
        popup_position = popup.mapFromGlobal(global_position)
        return popup.rect().contains(popup_position)

    def _dismiss_after_pointer_leave(self):
        if not self._is_unpinned_overlay_visible():
            return
        pointer_position = self.navigator.mapFromGlobal(QCursor.pos())
        if self.navigator.rect().contains(pointer_position):
            return
        popup = QApplication.activePopupWidget()
        if popup is not None and self._is_navigator_interaction(popup):
            return
        self.autoDismissRequested.emit("pointer_leave")

    def eventFilter(self, watched, event):
        event_type = event.type()
        if watched is self.navigator and event_type == QEvent.Leave:
            QTimer.singleShot(0, self._dismiss_after_pointer_leave)
        elif event_type == QEvent.MouseButtonPress and self._is_unpinned_overlay_visible():
            try:
                global_position = event.globalPosition().toPoint()
            except (AttributeError, TypeError):
                global_position = None
            if not self._is_internal_pointer_event(watched, global_position):
                self.autoDismissRequested.emit("outside_click")
        return False

    def refresh_theme(self, _resolved=None):
        self.navigator.setStyleSheet(
            f"QFrame#FileNavigatorPanel {{ background: {DesignTokens.bg_main}; "
            f"border: none; border-right: 1px solid {DesignTokens.separator}; border-radius: 0px; }}"
        )
        self.update_layout()

    def set_navigator_state(self, *, visible=None, pinned=None, width=None):
        if visible is not None:
            self.navigator_visible = bool(visible)
        if pinned is not None:
            self.navigator_pinned = bool(pinned)
        if width is not None:
            self.navigator_width = max(self.navigator_min_width, min(420, int(width)))
        self.update_layout()

    def set_editor_focus(self, enabled):
        enabled = bool(enabled)
        if self.editor_focus == enabled:
            self.update_layout()
            return
        self.editor_focus = enabled
        self.update_layout()

    def set_navigator_preferred_height(self, height):
        preferred = None if height is None else max(1, int(height))
        if self.navigator_preferred_height == preferred:
            return
        self.navigator_preferred_height = preferred
        self.update_layout()

    def pinned_layout_metrics(self):
        width = max(0, self.width())
        preferred = min(self.navigator_width, max(self.navigator_min_width, width - self.content_min_width - 1))
        available = width >= self.navigator_min_width + self.content_min_width + 1
        return available, max(self.navigator_min_width, preferred)

    def is_effectively_pinned(self):
        available, _nav_width = self.pinned_layout_metrics()
        return bool(self.navigator_pinned and available)

    def update_layout(self):
        width = max(0, self.width())
        height = max(0, self.height())
        if not width or not height:
            return
        available, pinned_nav_width = self.pinned_layout_metrics()
        nav_width = min(self.navigator_width, max(self.navigator_min_width, width - 1))
        pinned = self.is_effectively_pinned()
        mode = "pinned" if pinned else "overlay"
        if mode != self._effective_mode:
            self._effective_mode = mode
            self.effectiveModeChanged.emit(mode)
        show_nav = bool(self.navigator_visible or pinned)
        self.navigator.setVisible(show_nav)
        if pinned:
            nav_width = pinned_nav_width
            self.navigator.setGeometry(0, 0, nav_width, height)
            self.content.setGeometry(nav_width + 1, 0, max(0, width - nav_width - 1), height)
        else:
            self.content.setGeometry(0, 0, width, height)
            nav_height = (
                height
                if self.navigator_preferred_height is None
                else min(height, self.navigator_preferred_height)
            )
            self.navigator.setGeometry(0, 0, nav_width, nav_height)
        bottom_border = "none" if pinned else f"1px solid {DesignTokens.separator}"
        self.navigator.setStyleSheet(
            f"QFrame#FileNavigatorPanel {{ background: {DesignTokens.bg_main}; "
            f"border: none; border-right: 1px solid {DesignTokens.separator}; "
            f"border-bottom: {bottom_border}; border-radius: 0px; }}"
        )
        self.content.show()
        if show_nav:
            self.navigator.raise_()

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self.update_layout()


