    def process_ui_events(self, force=False):
        if int(getattr(self, "_history_process_events_suppressed", 0) or 0) > 0:
            return
        import time
        now = time.time()
        if force or (now - self.last_ui_update_time > 0.05):
            QApplication.processEvents()
            self.last_ui_update_time = now

    def _apply_initial_window_size(self):
        screen = QGuiApplication.primaryScreen()
        if screen is None:
            raise RuntimeError("无法获取主屏幕逻辑尺寸，不能初始化主窗口。")
        available = screen.availableGeometry()
        margin = 12
        max_width = max(1, available.width() - margin * 2)
        max_height = max(1, available.height() - margin * 2)
        target_width = min(1280, max_width)
        target_height = min(720, max_height)
        self.resize(target_width, target_height)
        log_ui_navigation(
            "main_window_initial_size",
            screen_geometry=[available.x(), available.y(), available.width(), available.height()],
            target_size=[target_width, target_height],
            device_pixel_ratio=float(getattr(screen, "devicePixelRatio", lambda: 1.0)() or 1.0),
        )

    def _queue_conversation_layout_sync(self, reason="layout"):
        self._pending_conversation_layout_sync_reasons.add(str(reason or "layout"))
        self.conversation_layout_sync_timer.start()

    def _settle_conversation_layout(self):
        reasons = sorted(self._pending_conversation_layout_sync_reasons)
        self._pending_conversation_layout_sync_reasons.clear()
        self.sync_context_drawer_layout()
        if "splitter_programmatic" in reasons:
            metrics = dict(getattr(self, "dynamic_layout_metrics", {}) or {})
            log_ui_navigation(
                "main_splitter_programmatic_resize",
                splitter_sizes=list(self.main_splitter.sizes()),
                main_width=int(self.main_container.width()),
                shell_width=int(metrics.get("shell_width", 0) or 0),
                spacer_widths=[
                    int(self.conversation_left_spacer.width()),
                    int(self.conversation_right_spacer.width()),
                ],
            )

    def showEvent(self, event):
        super().showEvent(event)
        self._queue_conversation_layout_sync("show")
        if not self._startup_hydration_scheduled:
            self._startup_hydration_scheduled = True
            QTimer.singleShot(0, self._run_startup_hydration)
        if not self._background_services_scheduled:
            self._background_services_scheduled = True
            QTimer.singleShot(0, self.start_background_services)

    def _run_startup_hydration(self):
        if self._startup_hydration_completed:
            return
        self._startup_hydration_completed = True
        log_startup_stage("startup_hydration_begin")
        self.load_default_workspace(refresh_sidebar=False)
        log_startup_stage("startup_workspace_ready", has_workspace=bool(self.workspace_dir))
        self.refresh_history_list()
        log_startup_stage("startup_history_ready")
        QTimer.singleShot(0, self._show_model_onboarding_if_needed)

    def _show_model_onboarding_if_needed(self):
        if self._model_onboarding_shown:
            return False
        try:
            if self.config_manager.has_usable_model_profile():
                return False
        except Exception as exc:
            log_model_service_event(
                "onboarding_check_error",
                error_type=type(exc).__name__,
            )
            self.add_system_toast(f"无法检查模型配置：{exc}", "error", auto_close_ms=8000)
            return False
        self._model_onboarding_shown = True
        dialog = DeepSeekQuickstartDialog(self.config_manager, self)
        self._model_onboarding_dialog = dialog
        result = dialog.exec()
        self._model_onboarding_dialog = None
        if result != QDialog.Accepted or not dialog.configured_profile:
            return False
        configured_id = str(dialog.configured_profile.get("id") or "")
        state = self.get_current_session()
        if state and configured_id:
            usable_ids = {
                str(profile.get("id") or "")
                for profile in self.config_manager.iter_model_profiles()
                if str(profile.get("api_key") or "").strip()
                and str(profile.get("model_name") or "").strip()
            }
            state_model_id = str(getattr(state, "selected_model_id", "") or "")
            if state_model_id not in usable_ids:
                self._set_session_model_id(state, configured_id)
        self.refresh_model_selector()
        recommended = get_recommended_model("openai", DEEPSEEK_OFFICIAL_BASE_URL)
        self.add_system_toast(
            f"DeepSeek 已配置，当前使用推荐模型 {recommended}",
            "success",
            auto_close_ms=5000,
        )
        return True

    def keyPressEvent(self, event):
        if (
            event.key() == Qt.Key_S
            and event.modifiers() & Qt.ControlModifier
            and getattr(self, "deliverable_edit_state", "idle") != "idle"
        ):
            self.save_deliverable_edit()
            event.accept()
            return
        if getattr(self, "current_product_route", self.PAGE_CONVERSATION) != self.PAGE_CONVERSATION:
            if event.key() == Qt.Key_Left and event.modifiers() & Qt.AltModifier:
                self.handle_product_back()
                event.accept()
                return
            if event.key() == Qt.Key_Escape:
                self.handle_product_back()
                event.accept()
                return
            page = self.product_pages.get(self.current_product_route)
            if event.key() == Qt.Key_F and event.modifiers() & Qt.ControlModifier:
                search = getattr(page, "search_input", None)
                if search is not None:
                    search.setFocus()
                    search.selectAll()
                    event.accept()
                    return
            if event.key() == Qt.Key_F5:
                if self.current_product_route == self.PAGE_CAPABILITIES and page is not None:
                    page.manual_refresh()
                    event.accept()
                    return
                if self.current_product_route == self.PAGE_FAVORITES and page is not None:
                    page.refresh()
                    event.accept()
                    return
        drawer_open = getattr(self, "right_drawer_open", False)
        files_open = drawer_open and getattr(self, "right_drawer_tab", None) == self.RIGHT_TAB_FILES
        if files_open and event.key() == Qt.Key_F and event.modifiers() & Qt.ControlModifier:
            self.set_file_navigator_visible(True, reason="shortcut_search")
            self.file_search_input.setFocus()
            self.file_search_input.selectAll()
            event.accept()
            return
        if files_open and event.key() == Qt.Key_Left and event.modifiers() & Qt.AltModifier:
            self.set_file_navigator_visible(True, reason="shortcut_back")
            event.accept()
            return
        if files_open and event.key() == Qt.Key_F5:
            if getattr(self, "current_preview_path", ""):
                self.render_selected_deliverable(force=True)
            else:
                self.refresh_deliverables()
            event.accept()
            return
        if files_open and event.key() in {Qt.Key_Return, Qt.Key_Enter} and getattr(self, "file_navigator_visible", False):
            if getattr(self, "file_navigator_scope", self.FILE_SCOPE_DELIVERABLES) == self.FILE_SCOPE_DELIVERABLES:
                self.on_deliverable_item_clicked(self.deliverables_list.currentItem())
            else:
                self.on_file_clicked(self.file_tree.currentIndex())
            event.accept()
            return
        if event.key() == Qt.Key_Escape and drawer_open:
            self.hide_context_drawer()
            event.accept()
            return
        super().keyPressEvent(event)

    def set_context_drawer_width(self, requested_width):
        parent = getattr(self, "main_container", None)
        if not parent:
            return
        maximum = max(self.context_drawer_min_width, int(parent.width() * 0.72))
        self.context_drawer_user_width = self._clamp_int(
            int(requested_width), self.context_drawer_min_width, maximum
        )
        self.context_drawer_expanded = self.context_drawer_user_width > self.context_drawer_max_width
        self._sync_deliverable_expand_button()
        self.sync_context_drawer_layout()
        self._sync_deliverable_text_editor_layout()

    def persist_context_drawer_width(self):
        if getattr(self, "deliverable_edit_focus_snapshot", None) is not None:
            return
        if getattr(self, "config_manager", None) and self.context_drawer_user_width:
            self.config_manager.set("context_drawer_width", int(self.context_drawer_user_width))

    def set_file_navigator_scope(self, scope, refresh=True, user_initiated=False):
        scope = (
            self.FILE_SCOPE_WORKSPACE
            if str(scope or "") == self.FILE_SCOPE_WORKSPACE
            else self.FILE_SCOPE_DELIVERABLES
        )
        previous = getattr(self, "file_navigator_scope", self.FILE_SCOPE_DELIVERABLES)
        self.file_navigator_scope = scope
        if getattr(self, "config_manager", None):
            self.config_manager.set("file_navigator_scope", scope)
        if user_initiated:
            self.file_navigator_user_selected_scope = True
        self._file_navigator_state()["scope"] = scope
        stack = getattr(self, "file_source_stack", None)
        if stack is not None:
            stack.setCurrentIndex(0 if scope == self.FILE_SCOPE_WORKSPACE else 1)
        labels = {
            self.FILE_SCOPE_WORKSPACE: "工作区文件",
            self.FILE_SCOPE_DELIVERABLES: "交付物",
        }
        button = getattr(self, "file_scope_btn", None)
        if button is not None:
            button.setText(labels[scope])
        for value, action in getattr(self, "file_scope_actions", {}).items():
            action.setChecked(value == scope)
        search = getattr(self, "file_search_input", None)
        if search is not None:
            search.setPlaceholderText("搜索工作区文件" if scope == self.FILE_SCOPE_WORKSPACE else "搜索交付物")
        filter_button = getattr(self, "file_filter_btn", None)
        if filter_button is not None:
            filter_button.setEnabled(scope == self.FILE_SCOPE_DELIVERABLES)
            filter_button.setToolTip("类型与排序" if scope == self.FILE_SCOPE_DELIVERABLES else "工作区文件按名称显示")
        if scope == self.FILE_SCOPE_DELIVERABLES and refresh:
            self.refresh_deliverables(render_current=True)
        self.apply_file_workspace_filters()
        if previous != scope:
            log_ui_navigation(
                "file_navigator_scope_changed",
                scope=scope,
                user_initiated=bool(user_initiated),
            )

    def _set_file_type_filter(self, value):
        self.deliverable_type_filter = str(value or "all")
        self.apply_file_workspace_filters()

    def _set_file_sort_mode(self, value):
        self.deliverable_sort_mode = str(value or "modified_desc")
        self.apply_file_workspace_filters()

    def _refresh_file_navigator_notice_theme(self, _resolved=None):
        notice = getattr(self, "file_navigator_pin_notice", None)
        if notice is None:
            return
        notice.setStyleSheet(
            f"QLabel#FileNavigatorPinNotice {{ background: {DesignTokens.warning_bg}; "
            f"color: {DesignTokens.warning_text}; border: 1px solid {DesignTokens.warning_border}; "
            "border-radius: 6px; padding: 6px 8px; font-size: 10px; }}"
        )

    def toggle_file_navigator(self):
        self.set_file_navigator_visible(
            not bool(getattr(self, "file_navigator_visible", False)),
            reason="header_button",
        )

    def _auto_dismiss_file_navigator(self, reason):
        if bool(getattr(self, "file_navigator_pinned", False)):
            return
        self.set_file_navigator_visible(False, reason=str(reason or "auto_dismiss"))

    def set_file_navigator_visible(self, visible, reason="programmatic"):
        visible = bool(visible)
        if bool(getattr(self, "file_navigator_visible", False)) == visible:
            self._sync_file_navigator_layout()
            return
        self.file_navigator_visible = visible
        if getattr(self, "config_manager", None):
            self.config_manager.set("file_navigator_visible", visible)
        self._sync_file_navigator_layout()
        log_ui_navigation(
            "file_navigator_visibility_changed",
            visible=visible,
            pinned=bool(getattr(self, "file_navigator_pinned", False)),
            reason=reason,
        )

    def toggle_file_navigator_pinned(self, checked=False):
        pinned = bool(checked)
        log_ui_navigation(
            "file_navigator_pin_request",
            pinned=pinned,
            drawer_width=int(getattr(getattr(self, "right_sidebar", None), "width", lambda: 0)()),
        )
        self.file_navigator_pinned = pinned
        self.file_navigator_visible = True
        if getattr(self, "config_manager", None):
            self.config_manager.set("file_navigator_pinned", pinned)
            self.config_manager.set("file_navigator_width", int(self.file_navigator_width))
        if pinned:
            parent = getattr(self, "main_container", None)
            if parent is not None:
                required = (
                    int(getattr(DesignTokens, "file_navigator_min_width", 240))
                    + int(getattr(DesignTokens, "file_workbench_content_min_width", 280))
                    + 30
                )
                maximum = max(self.context_drawer_min_width, int(parent.width() * 0.72))
                self.context_drawer_expanded = True
                self.context_drawer_user_width = min(
                    maximum,
                    max(required, self._expanded_file_workbench_width(parent)),
                )
                self._sync_deliverable_expand_button()
                self.sync_context_drawer_layout()
                log_ui_navigation(
                    "file_navigator_drawer_expanded",
                    requested_width=int(self.context_drawer_user_width),
                    actual_width=int(getattr(self.right_sidebar, "width", lambda: 0)()),
                    required_width=required,
                )
        self._sync_file_navigator_layout()
        QTimer.singleShot(0, lambda requested=pinned: self._finalize_file_navigator_pin_request(requested))

    def _finalize_file_navigator_pin_request(self, requested):
        self._sync_file_navigator_layout()
        workbench = getattr(self, "file_workbench", None)
        effective = bool(workbench and workbench.is_effectively_pinned())
        if requested and effective:
            log_ui_navigation(
                "file_navigator_pin_finish",
                pinned=True,
                workbench_width=int(workbench.width()),
            )
        elif requested:
            available, _width = workbench.pinned_layout_metrics() if workbench is not None else (False, 0)
            reason = "文件工作台宽度不足" if not available else "文件工作台布局尚未就绪"
            log_ui_navigation(
                "file_navigator_pin_error",
                pinned_preference=True,
                workbench_width=int(workbench.width()) if workbench is not None else 0,
                reason=reason,
            )
        else:
            log_ui_navigation("file_navigator_pin_finish", pinned=False)

    def _on_file_navigator_effective_mode_changed(self, mode):
        log_ui_navigation(
            "file_navigator_effective_mode_changed",
            mode=str(mode or "overlay"),
            pinned_preference=bool(getattr(self, "file_navigator_pinned", False)),
        )
        self._sync_file_navigator_layout()

    def _sync_file_navigator_layout(self):
        workbench = getattr(self, "file_workbench", None)
        if workbench is None:
            return
        workbench.set_navigator_state(
            visible=bool(getattr(self, "file_navigator_visible", True)),
            pinned=bool(getattr(self, "file_navigator_pinned", False)),
            width=int(getattr(self, "file_navigator_width", DesignTokens.file_navigator_width)),
        )
        effective_pinned = workbench.is_effectively_pinned()
        pinned_preference = bool(getattr(self, "file_navigator_pinned", False))
        pin_pending = bool(pinned_preference and not effective_pinned)
        pin = getattr(self, "file_navigator_pin_btn", None)
        if pin is not None:
            pin.blockSignals(True)
            pin.setChecked(pinned_preference)
            pin.blockSignals(False)
            pin.setIcon(
                qta.icon(
                    "fa5s.thumbtack",
                    color=DesignTokens.primary
                    if effective_pinned
                    else DesignTokens.text_secondary,
                )
            )
            pin.setStyleSheet(apple_tool_button_style(effective_pinned))
            if effective_pinned:
                pin.setToolTip("取消固定文件导航")
            elif pin_pending:
                pin.setToolTip("取消固定偏好；当前窗口较窄，放宽后会自动固定")
            else:
                pin.setToolTip("固定文件导航")
        notice = getattr(self, "file_navigator_pin_notice", None)
        if notice is not None:
            notice.setVisible(pin_pending)
        nav_button = getattr(self, "file_navigator_btn", None)
        if nav_button is not None:
            shown = bool(getattr(self, "file_navigator_visible", False) or effective_pinned)
            nav_button.setIcon(
                qta.icon("fa5s.bars", color=DesignTokens.primary if shown else DesignTokens.text_secondary)
            )
            nav_button.setStyleSheet(apple_tool_button_style(shown))
            if effective_pinned:
                nav_button.setToolTip("文件导航已固定；使用图钉取消固定")
            elif shown:
                nav_button.setToolTip("隐藏文件导航")
            else:
                nav_button.setToolTip("显示文件导航")
        workbench.set_navigator_preferred_height(self._file_navigator_preferred_height())

    def _visible_workspace_file_row_count(self, limit=1000):
        tree = getattr(self, "file_tree", None)
        model = getattr(self, "file_filter_model", None)
        if tree is None or model is None:
            return 0
        root = tree.rootIndex()

        def count_rows(parent, remaining):
            total = 0
            for row in range(min(model.rowCount(parent), remaining)):
                index = model.index(row, 0, parent)
                if not index.isValid():
                    continue
                total += 1
                if total >= remaining:
                    break
                if tree.isExpanded(index):
                    total += count_rows(index, remaining - total)
                    if total >= remaining:
                        break
            return total

        return count_rows(root, max(1, int(limit)))

    def _file_navigator_preferred_height(self):
        panel = getattr(self, "file_navigator_panel", None)
        if panel is None or panel.layout() is None:
            return None
        layout = panel.layout()
        margins = layout.contentsMargins()
        block_heights = [int(getattr(DesignTokens, "control_height_sm", 28)) + 2]

        notice = getattr(self, "file_navigator_pin_notice", None)
        if notice is not None and not notice.isHidden():
            available_width = max(1, int(getattr(self, "file_navigator_width", 320)) - 24)
            notice_height = notice.heightForWidth(available_width)
            block_heights.append(max(notice.sizeHint().height(), notice_height))

        block_heights.append(int(getattr(DesignTokens, "control_height", 32)))
        current = getattr(self, "file_navigator_current_frame", None)
        if current is not None and not current.isHidden():
            block_heights.append(max(1, current.sizeHint().height()))

        empty = getattr(self, "file_browser_empty_state", None)
        if empty is not None and not empty.isHidden():
            content_height = max(120, empty.sizeHint().height())
        else:
            scope = getattr(self, "file_navigator_scope", self.FILE_SCOPE_DELIVERABLES)
            if scope == self.FILE_SCOPE_DELIVERABLES:
                rows = getattr(getattr(self, "deliverables_list", None), "count", lambda: 0)()
                row_height = 48
            else:
                row_height = int(getattr(DesignTokens, "row_height", 36))
                workbench_height = int(
                    getattr(getattr(self, "file_workbench", None), "height", lambda: 0)()
                )
                visible_row_limit = max(1, workbench_height // max(1, row_height) + 1)
                rows = self._visible_workspace_file_row_count(limit=visible_row_limit)
            content_height = max(row_height, int(rows) * row_height + 8)
        block_heights.append(content_height)

        spacing = max(0, layout.spacing())
        return (
            margins.top()
            + margins.bottom()
            + sum(block_heights)
            + spacing * max(0, len(block_heights) - 1)
        )

    @staticmethod
    def _file_tab_path_key(path):
        return os.path.normcase(os.path.abspath(os.path.normpath(str(path or ""))))

    def _session_open_file_paths(self, state=None):
        state = state or (self.get_current_session() if hasattr(self, "get_current_session") else None)
        if state is None:
            return []
        normalized = []
        seen = set()
        for path in list(getattr(state, "open_file_paths", []) or []):
            raw_value = str(path or "").strip()
            if not raw_value:
                continue
            value = os.path.normpath(raw_value)
            key = self._file_tab_path_key(value)
            if key in seen:
                continue
            seen.add(key)
            normalized.append(value)
        selected_raw = str(getattr(state, "selected_deliverable_path", "") or "").strip()
        selected = os.path.normpath(selected_raw) if selected_raw else ""
        if selected and self._file_tab_path_key(selected) not in seen:
            normalized.append(selected)
        state.open_file_paths = normalized
        return normalized

    def _ensure_open_file_tab(self, path, state=None):
        raw_path = str(path or "").strip()
        path = os.path.normpath(raw_path) if raw_path else ""
        state = state or (self.get_current_session() if hasattr(self, "get_current_session") else None)
        if not path or state is None:
            return False
        key = self._file_tab_path_key(path)
        raw_open_keys = {
            self._file_tab_path_key(raw)
            for raw in list(getattr(state, "open_file_paths", []) or [])
            if str(raw or "").strip()
        }
        paths = self._session_open_file_paths(state)
        existing = next((item for item in paths if self._file_tab_path_key(item) == key), "")
        opened = key not in raw_open_keys
        if not existing:
            paths.append(path)
            state.open_file_paths = paths
        state.selected_deliverable_path = existing or path
        self._sync_file_header(state)
        if opened:
            log_ui_navigation(
                "file_tab_open",
                session_id=str(getattr(state, "session_id", "") or ""),
                path=path,
                tab_count=len(paths),
            )
        return True

    def _clear_active_file_surface(self):
        self.current_preview_path = ""
        self.current_deliverable_path = ""
        self.current_deliverable_item = None
        self._file_navigator_state()["selected_path"] = ""
        if getattr(self, "deliverable_edit_state", "idle") != "idle":
            self._release_deliverable_edit_session(show_preview=False)
        self.preview_stack.setCurrentWidget(self.preview_text)
        self.preview_text.clear()
        self.preview_meta_label.setFullText("选择文件查看内容")
        self._set_deliverable_status("")
        self._set_deliverable_controls_enabled("")

    def activate_file_tab(self, path):
        state = self.get_current_session()
        raw_path = str(path or "").strip()
        path = os.path.normpath(raw_path) if raw_path else ""
        if state is None or not path:
            return False
        if not any(
            self._file_tab_path_key(item) == self._file_tab_path_key(path)
            for item in self._session_open_file_paths(state)
        ):
            return False
        if os.path.isfile(path):
            selected = self.select_deliverable(path, render_html=True)
            if selected is False:
                self._sync_file_header(state)
                return False
        else:
            active_session = getattr(self, "deliverable_edit_session", None)
            if active_session is not None and self._file_tab_path_key(active_session.path) != self._file_tab_path_key(path):
                if not self.confirm_leave_deliverable_edit("切换文件"):
                    self._sync_file_header(state)
                    return False
            state.selected_deliverable_path = path
            self.current_deliverable_path = path
            self.current_preview_path = path
            self.preview_stack.setCurrentWidget(self.preview_text)
            self.preview_text.setPlainText(f"文件已不存在或无法访问。\n\n{path}\n\n请关闭该标签，或恢复文件后刷新。")
            self.preview_meta_label.setFullText("文件不可用")
            self.preview_meta_label.setToolTip(path)
            self._set_deliverable_status("文件已不存在或无法访问；可关闭标签后重新选择。", tone="error")
            self._set_deliverable_controls_enabled("")
            self._sync_file_header(state)
        log_ui_navigation(
            "file_tab_activate",
            session_id=str(getattr(state, "session_id", "") or ""),
            path=path,
            available=os.path.isfile(path),
        )
        return True

    def close_file_tab(self, path):
        state = self.get_current_session()
        raw_path = str(path or "").strip()
        path = os.path.normpath(raw_path) if raw_path else ""
        if state is None or not path:
            return False
        paths = self._session_open_file_paths(state)
        target_index = next(
            (index for index, item in enumerate(paths) if self._file_tab_path_key(item) == self._file_tab_path_key(path)),
            -1,
        )
        if target_index < 0:
            return False
        active = self._file_tab_path_key(getattr(state, "selected_deliverable_path", "")) == self._file_tab_path_key(path)
        if active and not self.confirm_leave_deliverable_edit("关闭当前文件"):
            return False
        paths.pop(target_index)
        state.open_file_paths = paths
        if active:
            next_path = paths[target_index] if target_index < len(paths) else (paths[-1] if paths else "")
            state.selected_deliverable_path = next_path
            self._clear_active_file_surface()
            if next_path:
                self.activate_file_tab(next_path)
            else:
                self._sync_file_header(state)
                self.set_file_navigator_visible(True, reason="last_file_tab_closed")
        else:
            self._sync_file_header(state)
        log_ui_navigation(
            "file_tab_close",
            session_id=str(getattr(state, "session_id", "") or ""),
            path=path,
            active=active,
            remaining=len(paths),
        )
        return True

    def close_current_file(self):
        state = self.get_current_session()
        path = str(
            getattr(state, "selected_deliverable_path", "") if state is not None
            else getattr(self, "current_deliverable_path", "")
        )
        if path:
            return self.close_file_tab(path)
        self._clear_active_file_surface()
        self._sync_file_header(state)
        self.set_file_navigator_visible(True, reason="close_file")
        return True

    def _sync_file_header(self, state=None):
        state = state or (self.get_current_session() if hasattr(self, "get_current_session") else None)
        identity = getattr(self, "file_header_identity_label", None)
        strip = getattr(self, "file_tab_strip", None)
        if identity is None or strip is None:
            return
        paths = self._session_open_file_paths(state) if state is not None else []
        active = str(getattr(state, "selected_deliverable_path", "") or "") if state is not None else ""
        strip.set_paths(paths, active)
        strip.setVisible(bool(paths))
        identity.setVisible(not bool(paths))

    def _set_deliverable_status(self, text="", tone="info"):
        label = getattr(self, "deliverable_status_label", None)
        if label is None:
            return
        text = str(text or "").strip()
        label.setText(text)
        label.setVisible(bool(text))
        color = {
            "error": DesignTokens.error_text,
            "warning": DesignTokens.warning_text,
            "success": DesignTokens.success_text,
        }.get(str(tone or "info"), DesignTokens.text_secondary)
        label.setStyleSheet(
            f"QLabel {{ color: {color}; font-size: {DesignTokens.font_size_meta}px; "
            "background: transparent; border: none; }}"
        )

    def _open_current_file_from_navigator(self):
        path = str(getattr(self, "current_preview_path", "") or getattr(self, "current_deliverable_path", ""))
        if path:
            if os.path.splitext(path)[1].lower() in DELIVERABLE_EXTENSIONS:
                self.select_deliverable(path, render_html=True)
            else:
                source = self.file_filter_model.mapFromSource(self.file_model.index(path))
                if source.isValid():
                    self.on_file_clicked(source)

    def _sync_deliverable_action_visibility(self):
        path = getattr(self, "current_deliverable_path", "")
        ext = os.path.splitext(path)[1].lower() if path else ""
        is_html = ext in {".html", ".htm"} and os.path.isfile(path)
        exportable_pdf = ext in PDF_EXPORT_EXTENSIONS and os.path.isfile(path)
        row = getattr(self, "deliverable_conversion_row", None)
        if row is not None:
            row.setVisible(is_html)
        export_action = getattr(self, "deliverable_more_export_pdf_action", None)
        if export_action is not None:
            export_action.setVisible(exportable_pdf)
        status = getattr(self, "deliverable_status_label", None)
        editable = bool(path and os.path.isfile(path) and editor_descriptor(path) is not None)
        mode_button = getattr(self, "deliverable_mode_btn", None)
        if mode_button is not None:
            mode_button.setVisible(editable)
        read_only = getattr(self, "deliverable_read_only_label", None)
        if read_only is not None:
            read_only.setVisible(bool(path) and not editable)

    def _snapshot_file_navigator_state(self):
        state = self._file_navigator_state()
        state["scope"] = getattr(self, "file_navigator_scope", self.FILE_SCOPE_DELIVERABLES)
        state["selected_path"] = getattr(self, "current_preview_path", "") or getattr(self, "current_deliverable_path", "")
        tree = getattr(self, "file_tree", None)
        if tree is not None:
            state["tree_scroll"] = tree.verticalScrollBar().value()
            expanded = set()
            root = tree.rootIndex()
            pending = [root]
            visited = 0
            while pending and visited < 600:
                parent_index = pending.pop()
                for row in range(self.file_filter_model.rowCount(parent_index)):
                    index = self.file_filter_model.index(row, 0, parent_index)
                    if not index.isValid():
                        continue
                    visited += 1
                    if tree.isExpanded(index):
                        source_index = self.file_filter_model.mapToSource(index)
                        path = self.file_model.filePath(source_index)
                        if path:
                            expanded.add(os.path.normcase(os.path.abspath(path)))
                        pending.append(index)
            state["expanded_paths"] = expanded
        deliverables = getattr(self, "deliverables_list", None)
        if deliverables is not None:
            state["deliverables_scroll"] = deliverables.verticalScrollBar().value()

    def _restore_file_navigator_state(self):
        state = self._file_navigator_state()
        tree = getattr(self, "file_tree", None)
        if tree is not None:
            expanded = state.get("expanded_paths") or set()
            for normalized_path in list(expanded)[:600]:
                source_index = self.file_model.index(normalized_path)
                proxy_index = self.file_filter_model.mapFromSource(source_index)
                if proxy_index.isValid():
                    tree.setExpanded(proxy_index, True)
            tree.verticalScrollBar().setValue(int(state.get("tree_scroll") or 0))
        deliverables = getattr(self, "deliverables_list", None)
        if deliverables is not None:
            deliverables.verticalScrollBar().setValue(int(state.get("deliverables_scroll") or 0))

    def apply_file_workspace_filters(self, *_args):
        search = getattr(self, "file_search_input", None)
        query = str(search.text() if search is not None else "").strip()
        self.file_browser_search_text = query
        if hasattr(self, "file_filter_model"):
            self.file_filter_model.setFilterFixedString(query)
        self.deliverable_type_filter = str(getattr(self, "deliverable_type_filter", "all") or "all")
        self.deliverable_sort_mode = str(getattr(self, "deliverable_sort_mode", "modified_desc") or "modified_desc")
        for value, action in getattr(self, "file_type_actions", {}).items():
            action.setChecked(value == self.deliverable_type_filter)
        for value, action in getattr(self, "file_sort_actions", {}).items():
            action.setChecked(value == self.deliverable_sort_mode)
        if hasattr(self, "deliverables_list"):
            self._render_deliverable_items()
        scope = getattr(self, "file_navigator_scope", self.FILE_SCOPE_DELIVERABLES)
        if scope == self.FILE_SCOPE_DELIVERABLES:
            count = len(self._filtered_deliverable_items())
        else:
            root = self.file_tree.rootIndex() if hasattr(self, "file_tree") else None
            count = self.file_filter_model.rowCount(root) if root is not None and root.isValid() else 0
        result_label = getattr(self, "file_result_count_label", None)
        if result_label is not None:
            result_label.setText(f"{count} 项")
        filter_active = self.deliverable_type_filter != "all" or self.deliverable_sort_mode != "modified_desc"
        filter_button = getattr(self, "file_filter_btn", None)
        if filter_button is not None:
            filter_button.setIcon(
                qta.icon("fa5s.filter", color=DesignTokens.primary if filter_active else DesignTokens.text_secondary)
            )
            filter_button.setToolTip("类型与排序（已筛选）" if filter_active else "类型与排序")
        self._sync_current_file_filter_notice()
        self._sync_file_browser_empty_state()
        self._sync_file_navigator_layout()

    def clear_deliverable_filters(self):
        search = getattr(self, "file_search_input", None)
        if search is not None:
            search.clear()
        self.deliverable_type_filter = "all"
        self.apply_file_workspace_filters()

    def _file_navigator_state(self):
        state = getattr(self, "file_navigator_navigation_state", None)
        if not isinstance(state, dict):
            state = {
                "scope": getattr(self, "file_navigator_scope", self.FILE_SCOPE_DELIVERABLES),
                "selected_path": "",
                "tree_scroll": 0,
                "deliverables_scroll": 0,
                "expanded_paths": set(),
            }
            self.file_navigator_navigation_state = state
        return state

    def _sync_current_file_filter_notice(self):
        frame = getattr(self, "file_navigator_current_frame", None)
        button = getattr(self, "file_navigator_current_btn", None)
        if frame is None or button is None:
            return
        path = str(getattr(self, "current_preview_path", "") or getattr(self, "current_deliverable_path", ""))
        if not path:
            frame.setVisible(False)
            return
        query = str(getattr(self, "file_browser_search_text", "") or "").casefold()
        scope = getattr(self, "file_navigator_scope", self.FILE_SCOPE_DELIVERABLES)
        excluded = False
        if scope == self.FILE_SCOPE_DELIVERABLES:
            visible_paths = {
                os.path.normcase(os.path.abspath(str(item.get("path") or "")))
                for item in self._filtered_deliverable_items()
            }
            excluded = os.path.normcase(os.path.abspath(path)) not in visible_paths
        elif query:
            try:
                relative = os.path.relpath(path, getattr(self, "workspace_dir", "") or os.path.dirname(path))
            except ValueError:
                relative = path
            excluded = query not in os.path.basename(path).casefold() and query not in relative.casefold()
        frame.setVisible(excluded)
        if excluded:
            button.setText(os.path.basename(path) or path)
            button.setToolTip(path)

    def _deliverable_matches_type(self, item, filter_key):
        kind = str(item.get("kind") or "").strip().lower()
        if not kind:
            ext = os.path.splitext(str(item.get("path") or ""))[1].lower()
            kind = str(DELIVERABLE_TYPES.get(ext, ("", "", ""))[0])
        return filter_key == "all" or DELIVERABLE_KIND_CATEGORIES.get(kind) == filter_key

    def _sync_deliverable_filter_options(self):
        actions = getattr(self, "file_type_actions", None)
        if not actions:
            return
        current = str(getattr(self, "deliverable_type_filter", "all") or "all")
        counts = {value: 0 for _label, value in DELIVERABLE_FILTER_CATEGORIES}
        items = list(getattr(self, "deliverable_items", []) or [])
        counts["all"] = len(items)
        for item in items:
            kind = str(item.get("kind") or "").strip().lower()
            category = DELIVERABLE_KIND_CATEGORIES.get(kind)
            if category:
                counts[category] += 1
        for label, value in DELIVERABLE_FILTER_CATEGORIES:
            action = actions[value]
            action.setText(f"{label} ({counts[value]})")
            action.setEnabled(value == "all" or counts[value] > 0)
        if current not in actions:
            current = "all"
        actions[current].setChecked(True)
        self.deliverable_type_filter = current

    def _filtered_deliverable_items(self):
        query = str(getattr(self, "file_browser_search_text", "") or "").casefold()
        type_filter = str(getattr(self, "deliverable_type_filter", "all") or "all")
        items = [
            item for item in (getattr(self, "deliverable_items", []) or [])
            if self._deliverable_matches_type(item, type_filter)
            and (
                not query
                or query in str(item.get("name") or "").casefold()
                or query in str(item.get("relative_path") or "").casefold()
            )
        ]
        mode = str(getattr(self, "deliverable_sort_mode", "modified_desc") or "modified_desc")
        def path_key(item):
            return os.path.normcase(os.path.normpath(str(item.get("relative_path") or item.get("path") or ""))).casefold()
        if mode in {"name", "name_asc"}:
            items.sort(key=lambda item: (str(item.get("name") or "").casefold(), path_key(item)))
        elif mode == "name_desc":
            items.sort(key=lambda item: (str(item.get("name") or "").casefold(), path_key(item)), reverse=True)
        elif mode == "modified_asc":
            items.sort(key=lambda item: (float(item.get("mtime") or 0), path_key(item)))
        elif mode == "size_asc":
            items.sort(key=lambda item: (float(item.get("size") or 0), path_key(item)))
        elif mode == "size_desc":
            items.sort(key=lambda item: (float(item.get("size") or 0), path_key(item)), reverse=True)
        else:
            items.sort(key=lambda item: (float(item.get("mtime") or 0), path_key(item)), reverse=True)
        return items

    def _sync_file_browser_empty_state(self, loading=False, error=""):
        empty = getattr(self, "file_browser_empty_state", None)
        stack = getattr(self, "file_source_stack", None)
        if empty is None or stack is None:
            return
        workspace = getattr(self, "workspace_dir", "")
        scope = getattr(self, "file_navigator_scope", self.FILE_SCOPE_DELIVERABLES)
        action = ""
        if loading:
            title, description, visible = "正在扫描交付物", "正在读取当前工作区中的可预览文件。", True
        elif error:
            title, description, visible = "无法读取文件", str(error), True
            action = "retry_scan"
        elif not workspace:
            title, description, visible = "还没有选择工作区", "从左侧选择项目后，可以在这里查找和预览文件。", True
        elif not os.path.isdir(workspace):
            title, description, visible = "当前工作区不可用", f"目录不存在或无法访问：{workspace}", True
        elif scope == self.FILE_SCOPE_DELIVERABLES and not self._filtered_deliverable_items():
            has_filters = bool(str(getattr(self, "file_browser_search_text", "") or "").strip()) or str(
                getattr(self, "deliverable_type_filter", "all") or "all"
            ) != "all"
            title = "没有匹配的交付物" if has_filters else "还没有交付物"
            description = (
                "调整搜索词或清除文件类型筛选。"
                if has_filters
                else "生成 HTML、PDF、PPTX、DOCX 或图片后，它们会自动出现在这里。"
            )
            visible = True
            action = "clear_filters" if has_filters else ""
        elif scope == self.FILE_SCOPE_WORKSPACE:
            try:
                visible = not bool(os.listdir(workspace))
            except OSError as exc:
                title, description, visible = "无法读取工作区", str(exc), True
            else:
                if visible:
                    source = self._session_workspace_source()
                    if source == "project":
                        title = "项目文件夹为空"
                        description = "添加文件，或在对话中让 Agent 创建。"
                    else:
                        title = "还没有文件"
                        description = "在对话中让 Agent 创建文件后，它们会显示在这里。"
                    action = "open_workspace"
                else:
                    title, description = "", ""
        else:
            title, description, visible = "", "", False
        if visible:
            empty.set_content(title, description)
        self.file_browser_empty_action = action
        action_button = getattr(empty, "action_button", None)
        if action_button is not None:
            action_text = {
                "open_workspace": "在资源管理器中打开",
                "clear_filters": "清除筛选",
                "retry_scan": "重试",
            }.get(action, "")
            empty.set_action(action_text, visible=visible and bool(action_text))
        empty.setVisible(visible)
        stack.setVisible(not visible)

    def _handle_file_browser_empty_action(self):
        action = str(getattr(self, "file_browser_empty_action", "") or "")
        if action == "clear_filters":
            self.clear_deliverable_filters()
            return
        if action == "open_workspace":
            workspace = getattr(self, "workspace_dir", "")
            if workspace and os.path.isdir(workspace):
                self.reveal_in_explorer(workspace)
        if action == "retry_scan":
            self.refresh_deliverables(render_current=True)

    def _sync_deliverable_expand_button(self):
        btn = getattr(self, "deliverable_expand_btn", None)
        if not btn:
            return
        expanded = bool(getattr(self, "context_drawer_expanded", False))
        btn.setIcon(qta.icon("fa5s.compress-alt" if expanded else "fa5s.expand-alt", color=DesignTokens.text_secondary))
        btn.setToolTip("退出放大" if expanded else "放大预览")

    def _expanded_file_workbench_width(self, parent):
        return max(
            DesignTokens.drawer_max_width + 1,
            min(
                int(parent.width() * 0.68),
                parent.width() - (self.context_drawer_margin * 2),
            ),
        )

    def _enter_deliverable_edit_focus(self):
        if getattr(self, "deliverable_edit_focus_snapshot", None) is not None:
            return
        parent = getattr(self, "main_container", None)
        workbench = getattr(self, "file_workbench", None)
        if parent is None or workbench is None:
            return
        self.deliverable_edit_focus_snapshot = {
            "expanded": bool(getattr(self, "context_drawer_expanded", False)),
            "user_width": int(getattr(self, "context_drawer_user_width", 0) or 0),
            "width_before_expand": int(
                getattr(self, "context_drawer_width_before_expand", 0) or 0
            ),
        }
        self.context_drawer_width_before_expand = (
            self.right_sidebar.width() if hasattr(self, "right_sidebar") else 0
        )
        self.context_drawer_expanded = True
        self.context_drawer_user_width = self._expanded_file_workbench_width(parent)
        workbench.set_editor_focus(True)
        self._sync_deliverable_expand_button()
        self.sync_context_drawer_layout()
        log_ui_navigation(
            "deliverable_edit_focus_enter",
            path=getattr(self, "current_deliverable_path", ""),
            drawer_width=int(self.context_drawer_user_width),
        )

    def _exit_deliverable_edit_focus(self):
        snapshot = getattr(self, "deliverable_edit_focus_snapshot", None)
        workbench = getattr(self, "file_workbench", None)
        if workbench is not None:
            workbench.set_editor_focus(False)
        if snapshot is None:
            return
        self.context_drawer_expanded = bool(snapshot.get("expanded", False))
        self.context_drawer_user_width = int(snapshot.get("user_width", 0) or 0)
        self.context_drawer_width_before_expand = int(
            snapshot.get("width_before_expand", 0) or 0
        )
        self.deliverable_edit_focus_snapshot = None
        self._sync_deliverable_expand_button()
        self.sync_context_drawer_layout()
        log_ui_navigation(
            "deliverable_edit_focus_exit",
            path=getattr(self, "current_deliverable_path", ""),
            drawer_width=int(self.context_drawer_user_width),
        )

    def toggle_deliverable_preview_expanded(self):
        parent = getattr(self, "main_container", None)
        if not parent:
            return
        if getattr(self, "deliverable_edit_focus_snapshot", None) is not None:
            if getattr(self, "context_drawer_expanded", False):
                self.context_drawer_expanded = False
                content_width = (
                    parent.width()
                    - self.main_layout_default_margins[0]
                    - self.main_layout_default_margins[2]
                )
                self.context_drawer_user_width = self._clamp_int(
                    int(content_width * DesignTokens.drawer_width_ratio),
                    self.context_drawer_preferred_min_width,
                    self.context_drawer_max_width,
                )
            else:
                self.context_drawer_expanded = True
                self.context_drawer_user_width = self._expanded_file_workbench_width(parent)
            self._sync_deliverable_expand_button()
            self.sync_context_drawer_layout()
            log_ui_navigation(
                "deliverable_edit_focus_width_toggled",
                expanded=bool(self.context_drawer_expanded),
                drawer_width=int(self.context_drawer_user_width),
            )
            return
        if getattr(self, "context_drawer_expanded", False):
            self.context_drawer_expanded = False
            self.context_drawer_user_width = (
                self.context_drawer_width_before_expand
                or min(DesignTokens.drawer_max_width, max(DesignTokens.drawer_preferred_min_width, int(parent.width() * DesignTokens.drawer_width_ratio)))
            )
        else:
            self.context_drawer_width_before_expand = self.right_sidebar.width() if hasattr(self, "right_sidebar") else 0
            self.context_drawer_expanded = True
            self.context_drawer_user_width = self._expanded_file_workbench_width(parent)
        self._sync_deliverable_expand_button()
        self.persist_context_drawer_width()
        self.sync_context_drawer_layout()

    def _compute_context_drawer_geometry(self):
        if not hasattr(self, "right_sidebar"):
            return None
        parent = self.right_sidebar.parentWidget()
        if not parent:
            return None
        margin = self.context_drawer_margin
        content_width = parent.width() - self.main_layout_default_margins[0] - self.main_layout_default_margins[2]
        default_width = self._clamp_int(
            int(content_width * DesignTokens.drawer_width_ratio),
            self.context_drawer_preferred_min_width,
            self.context_drawer_max_width,
        )
        width = int(getattr(self, "context_drawer_user_width", 0) or default_width)
        width_limit = content_width - self.context_drawer_gap - self.context_drawer_min_content_width
        if getattr(self, "context_drawer_expanded", False):
            width = min(width, max(self.context_drawer_min_width, int(parent.width() * 0.72)))
        elif width_limit < self.context_drawer_preferred_min_width:
            width = max(self.context_drawer_min_width, width_limit)
        else:
            width = min(width, width_limit)
        width = min(width, max(self.context_drawer_min_width, parent.width() - (margin * 2)))
        height = max(120, parent.height() - (margin * 2))
        x = parent.width() - width - margin
        return {
            "margin": margin,
            "width": width,
            "height": height,
            "x": x,
            "y": margin,
        }

    def _apply_context_drawer_content_reserve(self, drawer_width=None):
        if not hasattr(self, "main_content_layout"):
            return
        left, top, right, bottom = self.main_content_default_margins
        reserve = 0
        if getattr(self, "right_drawer_open", False) and drawer_width:
            reserve = max(0, int(drawer_width) + int(self.context_drawer_gap))
        self.content_area_layout.setContentsMargins(left, top, reserve, bottom)
        self.main_content_layout.setContentsMargins(0, 0, 0, 0)

    def _clamp_int(self, value, minimum, maximum):
        minimum = int(minimum)
        maximum = int(maximum)
        if maximum < minimum:
            return maximum
        return max(minimum, min(maximum, int(value)))

    def _drawer_is_active(self, drawer_geometry=None):
        return bool(self.right_drawer_open and isinstance(drawer_geometry, dict))

    def _main_content_shell_width(self, drawer_geometry=None):
        container = getattr(self, "main_container", None)
        if container is None:
            return DesignTokens.conversation_min_width
        available = container.width() - self.main_layout_default_margins[0] - self.main_layout_default_margins[2]
        if self._drawer_is_active(drawer_geometry):
            safe_right = int(drawer_geometry.get("x", container.width())) - self.context_drawer_gap
            available = min(
                available,
                safe_right - self.main_layout_default_margins[0],
            )
        return max(available, 0)

    def _conversation_available_width(self, drawer_geometry=None):
        return max(self._main_content_shell_width(drawer_geometry), 0)

    def _compute_conversation_shell_metrics(self, drawer_geometry=None):
        shell_width = self._main_content_shell_width(drawer_geometry)
        drawer_open = self._drawer_is_active(drawer_geometry)
        compact_min = (
            DesignTokens.conversation_open_compact_min_width
            if drawer_open else
            DesignTokens.conversation_compact_min_width
        )
        max_conversation_width = min(
            DesignTokens.conversation_max_width,
            DesignTokens.conversation_preferred_width,
            shell_width,
        )
        min_conversation_width = min(
            DesignTokens.conversation_min_width if not drawer_open else DesignTokens.conversation_open_min_width,
            max_conversation_width,
        )
        compact_conversation_width = min(compact_min, max_conversation_width)
        if drawer_open:
            conversation_width = self._clamp_int(
                int(shell_width * DesignTokens.conversation_open_target_ratio),
                compact_conversation_width,
                min(DesignTokens.conversation_open_max_width, shell_width),
            )
        else:
            conversation_width = self._clamp_int(
                int(shell_width * DesignTokens.conversation_closed_target_ratio),
                min(DesignTokens.conversation_closed_min_width, max_conversation_width),
                min(DesignTokens.conversation_closed_max_width, shell_width),
            )
        conversation_width = min(conversation_width, max_conversation_width)
        if not drawer_open and shell_width >= DesignTokens.conversation_min_width:
            conversation_width = max(conversation_width, min_conversation_width)
        else:
            conversation_width = max(conversation_width, compact_conversation_width)
        remaining = max(0, shell_width - conversation_width)
        if drawer_open:
            left_spacer_width = int(round(remaining * DesignTokens.conversation_open_left_spacer_ratio))
            right_spacer_width = remaining - left_spacer_width
        else:
            left_spacer_width = remaining // 2
            right_spacer_width = remaining - left_spacer_width
        return {
            "drawer_open": drawer_open,
            "shell_width": shell_width,
            "conversation_width": conversation_width,
            "left_spacer_width": left_spacer_width,
            "right_spacer_width": right_spacer_width,
            "drawer_width": int((drawer_geometry or {}).get("width", 0) or 0),
        }

    def _apply_conversation_shell_metrics(self, metrics):
        if not isinstance(metrics, dict):
            return
        left_spacer = getattr(self, "conversation_left_spacer", None)
        if left_spacer is not None:
            left_spacer.setFixedWidth(max(0, int(metrics.get("left_spacer_width", 0) or 0)))
        right_spacer = getattr(self, "conversation_right_spacer", None)
        if right_spacer is not None:
            right_spacer.setFixedWidth(max(0, int(metrics.get("right_spacer_width", 0) or 0)))

    def _iter_session_chat_bubbles(self):
        for state in getattr(self, "sessions", {}).values():
            chat_layout = getattr(state, "chat_layout", None)
            if chat_layout is None:
                continue
            for index in range(chat_layout.count()):
                item = chat_layout.itemAt(index)
                widget = item.widget() if item is not None else None
                if isinstance(widget, ChatBubble):
                    yield widget
                elif isinstance(widget, AssistantTurnGroup):
                    yield from widget.stage_bubbles
                elif isinstance(widget, SummonedAgentProcessBlock):
                    yield from widget.turn_group.stage_bubbles

    def sync_conversation_widths(self, drawer_geometry=None):
        metrics = self._compute_conversation_shell_metrics(drawer_geometry)
        conversation_width = int(metrics.get("conversation_width", DesignTokens.conversation_min_width) or DesignTokens.conversation_min_width)
        message_width = self._clamp_int(
            int(conversation_width * DesignTokens.message_width_ratio),
            min(DesignTokens.message_compact_min_width, conversation_width),
            min(DesignTokens.message_max_width, conversation_width),
        )
        user_bubble_width = self._clamp_int(
            int(message_width * min(0.72, DesignTokens.user_bubble_ratio)),
            min(DesignTokens.user_bubble_compact_min_width, message_width),
            min(DesignTokens.user_bubble_max_width, message_width),
        )

        self.dynamic_layout_metrics = metrics
        self.dynamic_conversation_width = conversation_width
        self.dynamic_message_width = message_width
        self.dynamic_user_bubble_width = user_bubble_width

        self._apply_conversation_shell_metrics(metrics)
        self.conversation_column.setFixedWidth(conversation_width)
        self.session_tabs.setFixedWidth(conversation_width)
        self.input_card.setFixedWidth(conversation_width)
        self._apply_composer_toolbar_layout(
            compact=conversation_width < DesignTokens.conversation_min_width
        )

        for bubble in self._iter_session_chat_bubbles():
            bubble.apply_dynamic_widths(message_width, user_bubble_width)
        self._position_active_system_toast()
        self._sync_question_navigator()

    @staticmethod
    def _question_navigator_plain_text(value, limit=180):
        text = str(value or "").replace("\r", "\n")
        text = re.sub(r"```[\s\S]*?```", " [代码] ", text)
        text = re.sub(r"`([^`]*)`", r"\1", text)
        text = re.sub(r"(?:^|\s)[#>*_~-]+\s*", " ", text)
        text = re.sub(r"\s+", " ", text).strip()
        if not text:
            return ""
        return text[:limit] + ("…" if len(text) > limit else "")

    def _question_navigator_entries_for_state(self, state):
        if state is None:
            return []
        messages = list(getattr(state, "messages", []) or [])
        entries = []
        for index, message in enumerate(messages):
            if not isinstance(message, dict) or message.get("role") != "user":
                continue
            if is_same_turn_guidance_message(message) or is_auto_query_skill_context_message(message):
                continue
            meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
            hidden_kind = str(meta.get("kind") or "") in {
                "runtime_context",
                "runtime_context_update",
                "runtime_instruction",
                "skill_context",
                "skill_context_update",
                "skill_state_update",
            }
            if bool(
                meta.get("ui_hidden")
                or meta.get("hidden_run_context")
                or meta.get("runtime_context")
                or (meta.get("hidden") and hidden_kind)
                or meta.get("embedded_agent_result")
            ):
                continue
            message_id = str(message.get("id") or "").strip()
            if not message_id:
                continue
            display = self._message_display_content(message)
            first_line = next((line.strip() for line in str(display or "").splitlines() if line.strip()), "")
            if not first_line:
                attachments = self._message_user_attachments(message)
                first_line = str((attachments[0] if attachments else {}).get("name") or "附件提问")
            answer_candidates = []
            for following in messages[index + 1:]:
                if isinstance(following, dict) and following.get("role") == "user":
                    if not is_same_turn_guidance_message(following) and not is_auto_query_skill_context_message(following):
                        break
                    continue
                if not isinstance(following, dict) or following.get("role") != "assistant":
                    continue
                content = str(following.get("content") or "").strip()
                if not content:
                    continue
                reply_meta = following.get("meta") if isinstance(following.get("meta"), dict) else {}
                priority = 1 if str(reply_meta.get("ui_reply_kind") or "") == "final" else 0
                answer_candidates.append((priority, content))
            answer = ""
            if answer_candidates:
                final_candidates = [content for priority, content in answer_candidates if priority]
                answer = final_candidates[-1] if final_candidates else answer_candidates[-1][1]
            entries.append(
                {
                    "message_id": message_id,
                    "message_index": index,
                    "title": self._question_navigator_plain_text(first_line, limit=96) or "未命名提问",
                    "answer": self._question_navigator_plain_text(answer, limit=220) or "尚无回复",
                }
            )
        return entries

    def _sync_question_navigator_geometry(self):
        rail = getattr(self, "question_navigator_rail", None)
        state = self.get_current_session() if hasattr(self, "get_current_session") else None
        if rail is None or state is None or not getattr(state, "chat_scroll", None):
            return
        if (
            getattr(self, "current_product_route", self.PAGE_CONVERSATION) != self.PAGE_CONVERSATION
            or self.main_page_stack.currentWidget() is not self.conversation_page
        ):
            self._set_question_navigator_route_visible(False)
            return
        viewport = state.chat_scroll.viewport()
        if not _qt_object_alive(viewport) or not viewport.isVisible():
            rail.set_feature_visible(False)
            self.question_navigator_theme_host.setGeometry(0, 0, 0, 0)
            return
        origin = viewport.mapTo(self.main_container, QPoint(0, 0))
        height = max(54, viewport.height() - 24)
        if len(rail.entries) < 2:
            self.question_navigator_theme_host.setGeometry(0, 0, 0, 0)
            return
        self.question_navigator_theme_host.setGeometry(
            int(getattr(DesignTokens, "question_navigator_sidebar_gap", 8)),
            origin.y() + 12,
            40,
            height,
        )
        rail.setGeometry(0, 0, 40, height)
        self.question_navigator_theme_host.raise_()
        rail.raise_()
        if self.question_navigator_preview.isVisible():
            self.question_navigator_preview.raise_()

    def _set_question_navigator_route_visible(self, visible):
        host = getattr(self, "question_navigator_theme_host", None)
        rail = getattr(self, "question_navigator_rail", None)
        preview = getattr(self, "question_navigator_preview", None)
        if preview is not None:
            preview.hide()
        if host is not None:
            host.set_route_visible(bool(visible))
            if not visible:
                host.setGeometry(0, 0, 0, 0)
        if rail is not None and not visible:
            rail.set_feature_visible(False)

    def _sync_question_navigator(self, session_id=None):
        rail = getattr(self, "question_navigator_rail", None)
        if rail is None:
            return
        state = self.get_session(session_id) if session_id else self.get_current_session()
        if state is None or state.session_id != getattr(self, "current_session_id", None):
            return
        entries = self._question_navigator_entries_for_state(state)
        rail.set_entries(entries)
        active_id = ""
        viewport = state.chat_scroll.viewport() if getattr(state, "chat_scroll", None) else None
        if viewport is not None:
            threshold = max(24, int(viewport.height() * 0.28))
            below = None
            for entry in entries:
                node = (getattr(state, "render_node_by_message_id", {}) or {}).get(entry["message_id"])
                widget = (node or {}).get("widget") if isinstance(node, dict) else None
                if widget is None or not _qt_object_alive(widget):
                    continue
                top_widget = self._top_level_chat_widget(state, widget) or widget
                try:
                    y = top_widget.mapTo(viewport, QPoint(0, 0)).y()
                except RuntimeError:
                    continue
                if y <= threshold:
                    active_id = entry["message_id"]
                elif below is None:
                    below = entry["message_id"]
            if not active_id:
                active_id = below or str((entries[-1] if entries else {}).get("message_id") or "")
        rail.set_active_message_id(active_id)
        self._sync_question_navigator_geometry()

    def _show_question_navigator_preview(self, entry, point):
        rail = getattr(self, "question_navigator_rail", None)
        card = getattr(self, "question_navigator_preview", None)
        if rail is None or card is None:
            return
        anchor = rail.mapTo(self.main_container, QPoint(rail.width() + 6, int(point.y())))
        card.show_entry(entry, anchor, self.main_container.rect())

    def _question_jump_error(self, state, message_id, reason):
        if state is not None:
            state.history_page_jump_target_id = ""
            state.history_page_jump_started_at = 0.0
        reason = str(reason or "无法定位该提问")
        log_ui_navigation(
            "question_navigator_jump_error",
            session_id=str(getattr(state, "session_id", "") or ""),
            message_id=str(message_id or ""),
            error=reason,
        )
        self._show_conversation_notice(state, reason, "error")

    def _finalize_question_navigator_jump(self, state, message_id):
        node = (getattr(state, "render_node_by_message_id", {}) or {}).get(str(message_id or ""))
        widget = (node or {}).get("widget") if isinstance(node, dict) else None
        if widget is None or not _qt_object_alive(widget):
            self._question_jump_error(state, message_id, "目标提问加载完成，但未能建立可见定位点。")
            return False
        top_widget = self._top_level_chat_widget(state, widget) or widget
        viewport = state.chat_scroll.viewport()
        try:
            y = top_widget.mapTo(viewport, QPoint(0, 0)).y()
        except RuntimeError as exc:
            self._question_jump_error(state, message_id, f"定位提问失败：{exc}")
            return False
        bar = state.chat_scroll.verticalScrollBar()
        state.auto_scroll_enabled = False
        state.pending_scroll_force = False
        bar.setValue(max(bar.minimum(), min(bar.maximum(), bar.value() + int(y) - 20)))
        started_at = float(getattr(state, "history_page_jump_started_at", 0.0) or 0.0)
        elapsed_ms = int((time.perf_counter() - started_at) * 1000) if started_at else 0
        state.history_page_jump_target_id = ""
        state.history_page_jump_started_at = 0.0
        self.question_navigator_rail.set_active_message_id(message_id)
        self.question_navigator_preview.hide()
        log_ui_navigation(
            "question_navigator_jump_finish",
            session_id=state.session_id,
            message_id=str(message_id or ""),
            elapsed_ms=elapsed_ms,
        )
        QTimer.singleShot(0, lambda sid=state.session_id: self._sync_question_navigator(sid))
        return True

    def jump_to_question(self, message_id):
        state = self.get_current_session()
        message_id = str(message_id or "").strip()
        if state is None or not message_id:
            return
        state.auto_scroll_enabled = False
        state.pending_scroll_force = False
        state.history_page_jump_target_id = message_id
        state.history_page_jump_started_at = time.perf_counter()
        log_ui_navigation(
            "question_navigator_jump_start",
            session_id=state.session_id,
            message_id=message_id,
        )
        if message_id in (getattr(state, "render_node_by_message_id", {}) or {}):
            self._finalize_question_navigator_jump(state, message_id)
            return
        if not getattr(state, "history_loaded", False) or getattr(state, "history_loading", False):
            self._question_jump_error(state, message_id, "历史会话仍在加载，请稍后重试。")
            return
        if getattr(state, "auto_loading_history", False):
            self._question_jump_error(state, message_id, "历史分页正在加载，请稍后重试。")
            return
        message_index = next(
            (
                index for index, message in enumerate(getattr(state, "messages", []) or [])
                if isinstance(message, dict) and str(message.get("id") or "") == message_id
            ),
            -1,
        )
        if message_index < 0:
            self._question_jump_error(state, message_id, "该提问已不存在，可能已被删除。")
            return
        spans = list(getattr(state, "render_items", []) or [])
        target_span_index = next(
            (
                index for index, span in enumerate(spans)
                if int(span.get("start") or 0) <= message_index < int(span.get("end") or 0)
            ),
            -1,
        )
        rendered_start = max(0, len(spans) - int(getattr(state, "displayed_render_count", 0) or 0))
        if target_span_index < 0 or target_span_index >= rendered_start:
            self._question_jump_error(state, message_id, "该提问缺少可加载的历史分页。")
            return
        viewport = state.chat_scroll.viewport()
        anchor_widget = None
        anchor_offset = 0
        for index in range(state.chat_layout.count() - 1):
            candidate = state.chat_layout.itemAt(index).widget()
            if candidate is None or not _qt_object_alive(candidate) or not candidate.isVisible():
                continue
            try:
                offset = candidate.mapTo(viewport, QPoint(0, 0)).y()
            except RuntimeError:
                continue
            if offset + max(candidate.height(), candidate.sizeHint().height(), 1) > 0:
                anchor_widget = candidate
                anchor_offset = int(offset)
                break
        spans_to_load = spans[target_span_index:rendered_start]
        state.auto_loading_history = True
        state.history_page_loading = True
        state.history_page_queue = list(spans_to_load)
        state.history_page_insert_index = 0
        state.history_page_anchor_widget = anchor_widget
        state.history_page_anchor_offset = anchor_offset
        state.displayed_render_count += len(spans_to_load)
        QTimer.singleShot(0, lambda sid=state.session_id: self._render_next_history_page_span(sid))

    def sync_context_drawer_layout(self):
        geometry = self._compute_context_drawer_geometry()
        if geometry is None:
            return
        self._apply_context_drawer_content_reserve(geometry["width"])
        self.sync_conversation_widths(geometry)
        self.right_sidebar.setGeometry(
            geometry["x"],
            geometry["y"],
            geometry["width"],
            geometry["height"],
        )
        self._sync_file_navigator_layout()
        if hasattr(self, "right_resize_handle"):
            self.right_resize_handle.setGeometry(0, 18, 8, max(40, geometry["height"] - 36))
            self.right_resize_handle.raise_()
        if self.right_sidebar.isVisible():
            self.right_sidebar.raise_()

    def _on_context_surface_changed(self, *_args):
        required = ("right_sidebar", "conversation_column", "session_tabs", "input_card")
        if any(not hasattr(self, name) for name in required):
            return
        self.sync_context_drawer_layout()

    def position_context_drawer(self):
        self.sync_context_drawer_layout()

    def _sync_file_workspace_for_current_session(self, entrypoint="files_rail"):
        state = self.get_current_session()
        target_workspace = self._workspace_dir_for_state(state) if state else ""
        target_workspace = self._normalize_project_path(target_workspace)
        window_workspace = self._normalize_project_path(getattr(self, "workspace_dir", ""))
        model = getattr(self, "file_model", None)
        model_workspace = window_workspace
        if model is not None and hasattr(model, "rootPath"):
            model_workspace = self._normalize_project_path(model.rootPath())
        target_key = self._project_key(target_workspace)
        window_key = self._project_key(window_workspace)
        model_key = self._project_key(model_workspace)
        requires_sync = target_key != window_key or target_key != model_key
        log_ui_navigation(
            "file_workspace_reconcile_begin",
            entrypoint=str(entrypoint or "files_rail"),
            session_id=str(getattr(state, "session_id", "") or ""),
            window_workspace=window_workspace,
            model_workspace=model_workspace,
            target_workspace=target_workspace,
            requires_sync=requires_sync,
        )
        if not requires_sync:
            log_ui_navigation(
                "file_workspace_reconcile_done",
                entrypoint=str(entrypoint or "files_rail"),
                session_id=str(getattr(state, "session_id", "") or ""),
                workspace_dir=target_workspace,
                changed=False,
                available=bool(target_workspace and os.path.isdir(target_workspace)),
            )
            return False
        try:
            self._apply_workspace_to_ui(
                target_workspace,
                refresh_sidebar=False,
                remember_workspace=False,
                persist_default=False,
            )
        except Exception as exc:
            log_ui_navigation(
                "file_workspace_reconcile_error",
                entrypoint=str(entrypoint or "files_rail"),
                session_id=str(getattr(state, "session_id", "") or ""),
                target_workspace=target_workspace,
                error=str(exc),
            )
            raise
        log_ui_navigation(
            "file_workspace_reconcile_done",
            entrypoint=str(entrypoint or "files_rail"),
            session_id=str(getattr(state, "session_id", "") or ""),
            workspace_dir=target_workspace,
            changed=True,
            available=bool(target_workspace and os.path.isdir(target_workspace)),
        )
        return True

    def open_file_workspace_from_rail(self, entrypoint="files_rail"):
        self._sync_file_workspace_for_current_session(entrypoint)
        self.set_file_navigator_scope(
            self._file_navigator_state().get("scope", self.FILE_SCOPE_DELIVERABLES),
            refresh=False,
        )
        self.set_file_navigator_visible(True, reason=str(entrypoint or "files_rail"))
        self.show_context_drawer(self.RIGHT_TAB_FILES)

    def show_context_drawer(self, tab_index=None):
        if tab_index is None:
            tab_index = self.right_drawer_tab
        if not hasattr(self, "right_stack"):
            return
        tab_index = max(0, min(tab_index, self.right_stack.count() - 1))
        log_sub_agent_runtime(
            "ui_context_drawer_show_begin",
            tab_index=tab_index,
            current_session_id=str(getattr(self, "current_session_id", "") or ""),
            current_tab=getattr(self, "right_drawer_tab", None),
            drawer_open=bool(getattr(self, "right_drawer_open", False)),
        )
        try:
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="set_flags", tab_index=tab_index)
            self.right_drawer_tab = tab_index
            self.right_drawer_open = True
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="set_flags", tab_index=tab_index)

            if tab_index == self.RIGHT_TAB_OBSERVABILITY:
                log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="refresh_observability", tab_index=tab_index)
                self.refresh_observability_view(self.current_session_id)
                log_sub_agent_runtime("ui_context_drawer_stage_done", stage="refresh_observability", tab_index=tab_index)
            elif tab_index == self.RIGHT_TAB_DELIVERABLES:
                log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="refresh_deliverables", tab_index=tab_index)
                self.refresh_deliverables(render_current=True)
                log_sub_agent_runtime("ui_context_drawer_stage_done", stage="refresh_deliverables", tab_index=tab_index)
            elif tab_index == self.RIGHT_TAB_SUB_AGENTS and hasattr(self, "sub_agent_monitor") and _qt_object_alive(self.sub_agent_monitor):
                log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="clear_sub_agent_monitor", tab_index=tab_index)
                self.sub_agent_monitor.reset()
                log_sub_agent_runtime("ui_context_drawer_stage_done", stage="clear_sub_agent_monitor", tab_index=tab_index)

            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="set_current_index", tab_index=tab_index)
            self.right_stack.setCurrentIndex(tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="set_current_index", tab_index=tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="update_header", tab_index=tab_index)
            self.update_context_drawer_header(tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="update_header", tab_index=tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="set_visible", tab_index=tab_index)
            self.right_sidebar.setVisible(True)
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="set_visible", tab_index=tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="sync_layout", tab_index=tab_index)
            self.sync_context_drawer_layout()
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="sync_layout", tab_index=tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="raise_sidebar", tab_index=tab_index)
            self.right_sidebar.raise_()
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="raise_sidebar", tab_index=tab_index)
            log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="update_badges", tab_index=tab_index)
            self.update_context_rail_badges()
            log_sub_agent_runtime("ui_context_drawer_stage_done", stage="update_badges", tab_index=tab_index)
            if tab_index == self.RIGHT_TAB_SUB_AGENTS:
                log_sub_agent_runtime("ui_context_drawer_stage_begin", stage="queue_sub_agent_render", tab_index=tab_index)
                self._queue_render_sub_agent_monitor_for_state(self.get_current_session(), delay_ms=250)
                log_sub_agent_runtime("ui_context_drawer_stage_done", stage="queue_sub_agent_render", tab_index=tab_index)
            log_sub_agent_runtime(
                "ui_context_drawer_show_done",
                tab_index=tab_index,
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
                drawer_open=bool(getattr(self, "right_drawer_open", False)),
                drawer_tab=getattr(self, "right_drawer_tab", None),
            )
        except Exception:
            log_sub_agent_runtime(
                "ui_context_drawer_show_failed",
                tab_index=tab_index,
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
                traceback=traceback.format_exc(),
            )

    def update_context_drawer_header(self, tab_index):
        if not hasattr(self, "right_title_label") or not hasattr(self, "right_desc_label"):
            return
        page_titles = {
            self.RIGHT_TAB_FILES: ("文件与交付物", "查看工作区文件、预览交付物并继续生成"),
            self.RIGHT_TAB_OBSERVABILITY: ("任务观测", "查看系统提示词、工具调用与返回"),
            self.RIGHT_TAB_SUB_AGENTS: ("子 Agent", "查看并行子 Agent 状态与日志"),
        }
        title, description = page_titles.get(tab_index, ("任务上下文", "查看文件与执行步骤"))
        self.right_title_label.setText(title)
        self.right_desc_label.setText(description)
        files_active = tab_index == self.RIGHT_TAB_FILES
        title_block = getattr(self, "right_title_block", None)
        if title_block is not None:
            title_block.setVisible(not files_active)
        file_controls = getattr(self, "file_header_controls", None)
        if file_controls is not None:
            file_controls.setVisible(files_active)
        if files_active:
            self._sync_file_header()

    def hide_context_drawer(self, reason="manual", source_obj=None, source_window=None, in_drawer=None, in_rail=None, is_popup=None):
        if not hasattr(self, "right_sidebar"):
            return
        if (
            getattr(self, "right_drawer_tab", None) == self.RIGHT_TAB_FILES
            and not self.confirm_leave_deliverable_edit("关闭文件与交付物")
        ):
            return False
        log_sub_agent_runtime(
            "ui_context_drawer_hide_begin",
            reason=str(reason or "manual"),
            current_session_id=str(getattr(self, "current_session_id", "") or ""),
            drawer_open=bool(getattr(self, "right_drawer_open", False)),
            drawer_tab=getattr(self, "right_drawer_tab", None),
            source_class=type(source_obj).__name__ if source_obj is not None else "",
            source_window_class=type(source_window).__name__ if source_window is not None else "",
            in_drawer=in_drawer,
            in_rail=in_rail,
            is_popup=is_popup,
        )
        self.right_drawer_open = False
        self.right_sidebar.setVisible(False)
        self.sync_context_drawer_layout()
        self.update_context_rail_badges()
        log_sub_agent_runtime(
            "ui_context_drawer_hide_done",
            reason=str(reason or "manual"),
            current_session_id=str(getattr(self, "current_session_id", "") or ""),
            drawer_open=bool(getattr(self, "right_drawer_open", False)),
            drawer_tab=getattr(self, "right_drawer_tab", None),
        )

    def set_context_tab_hint(self, tab_index, available=True):
        if not hasattr(self, "context_available_tabs"):
            return
        if available:
            self.context_available_tabs.add(tab_index)
        else:
            self.context_available_tabs.discard(tab_index)
        self.update_context_rail_badges()

    def update_context_rail_badges(self):
        if not hasattr(self, "context_rail_buttons"):
            return
        icons = {
            self.RIGHT_TAB_FILES: "fa5s.folder-open",
            self.RIGHT_TAB_OBSERVABILITY: "fa5s.chart-line",
            self.RIGHT_TAB_SUB_AGENTS: "fa5s.project-diagram",
        }
        for tab_index, btn in self.context_rail_buttons.items():
            active = self.right_drawer_open and self.right_drawer_tab == tab_index
            hinted = tab_index in self.context_available_tabs
            btn.setChecked(active)
            btn.setStyleSheet(apple_tool_button_style(active or hinted))
            color = DesignTokens.primary if active or hinted else DesignTokens.text_secondary
            btn.setIcon(qta.icon(icons.get(tab_index, "fa5s.circle"), color=color))

    def set_observability_section(self, index):
        if not hasattr(self, "observability_content_stack"):
            return
        count = self.observability_content_stack.count()
        if count <= 0:
            return
        index = max(0, min(index, count - 1))
        log_sub_agent_runtime(
            "ui_observability_section_begin",
            index=index,
            current_session_id=str(getattr(self, "current_session_id", "") or ""),
        )
        try:
            self.observability_section_index = index
            if index in {getattr(self, "OBS_SECTION_PROMPT", -1), getattr(self, "OBS_SECTION_LOG", -1)}:
                self.refresh_observability_view(self.current_session_id)
            self.observability_content_stack.setCurrentIndex(index)
            self._on_context_surface_changed()
            for btn_index, btn in enumerate(getattr(self, "observability_segment_buttons", [])):
                btn.setChecked(btn_index == index)
            log_sub_agent_runtime(
                "ui_observability_section_done",
                index=index,
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
            )
        except Exception:
            log_sub_agent_runtime(
                "ui_observability_section_failed",
                index=index,
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
                traceback=traceback.format_exc(),
            )

    def _prompt_tool_menu_entries(self):
        return [
            ("add_files", "添加文件"),
            ("add_agent", "添加智能体"),
            ("select_skills", "指定能力"),
            ("grill_mode", "拷问模式"),
        ]

    def _normalize_prompt_file_paths(self, paths):
        normalized = []
        seen = set()
        for path in paths or []:
            if not path or not os.path.isfile(path):
                continue
            norm = os.path.normpath(path)
            key = os.path.normcase(norm)
            if key in seen:
                continue
            seen.add(key)
            normalized.append(norm)
        return normalized

    def _is_supported_image_attachment(self, path):
        mime_type, _encoding = mimetypes.guess_type(path)
        return str(mime_type or "").strip().lower() in {
            "image/png",
            "image/jpeg",
            "image/webp",
            "image/gif",
        }

    def _selected_model_supports_vision(self, state=None):
        profile = self._model_profile_for_state(state or self.get_current_session())
        if not isinstance(profile, dict):
            return False
        return bool(profile.get("supports_vision", False))

    def _ensure_vision_attachment_support(self, state, file_paths, model_profile=None):
        image_paths = [path for path in self._normalize_prompt_file_paths(file_paths) if self._is_supported_image_attachment(path)]
        effective_profile = model_profile if isinstance(model_profile, dict) else self._model_profile_for_state(state)
        if not image_paths or bool(effective_profile.get("supports_vision", False)):
            return True
        log_attachment_event(
            "vision_preflight_blocked",
            session_id=getattr(state, "session_id", ""),
            image_count=len(image_paths),
            model_id=str(effective_profile.get("id") or self._model_id_for_state(state) or ""),
        )
        if state and state.session_id == self.current_session_id:
            self.add_system_toast(
                "当前模型未配置图片理解。图片已保留，请切换到支持图片的模型后再发送。",
                "warning",
                session_id=state.session_id,
                auto_close_ms=6000,
            )
            self.model_select_btn.setFocus(Qt.OtherFocusReason)
            QTimer.singleShot(0, self.model_select_btn.showMenu)
        return False

    def _resolve_text_image_references(self, user_text, existing_paths=None):
        if not getattr(self, "workspace_dir", None):
            return []
        existing_keys = {
            os.path.normcase(os.path.normpath(path))
            for path in (existing_paths or [])
        }
        candidates = []
        text = str(user_text or "")
        for match in re.finditer(r"(?P<path>[^\s\"'，。；;：:]+?\.(?:png|jpg|jpeg|webp|gif))", text, re.IGNORECASE):
            candidate = match.group("path").strip("()[]{}<>\"'`")
            if candidate:
                candidates.append(candidate)

        resolved = []
        seen = set(existing_keys)
        workspace_root = os.path.abspath(self._workspace_dir_for_state())

        def add_path(path):
            normalized = os.path.normpath(os.path.abspath(path))
            key = os.path.normcase(normalized)
            if key in seen or not os.path.isfile(normalized) or not self._is_supported_image_attachment(normalized):
                return
            try:
                if os.path.commonpath([workspace_root, normalized]) != workspace_root:
                    return
            except Exception:
                return
            seen.add(key)
            resolved.append(normalized)

        for candidate in candidates:
            if os.path.isabs(candidate):
                add_path(candidate)
            else:
                add_path(os.path.join(workspace_root, candidate))

        missing_names = {
            os.path.basename(candidate)
            for candidate in candidates
            if candidate and not os.path.isabs(candidate)
        }
        if missing_names:
            scanned = 0
            for root, _dirs, files in os.walk(workspace_root):
                scanned += 1
                if scanned > 800:
                    break
                for filename in files:
                    if filename in missing_names:
                        add_path(os.path.join(root, filename))
        return resolved

    def _prompt_file_items(self, paths):
        items = []
        seen = set()
        for raw_path in paths or []:
            path = os.path.normpath(str(raw_path or "").strip())
            if not path:
                continue
            key = os.path.normcase(path)
            if key in seen:
                continue
            seen.add(key)
            items.append({"path": path, "name": os.path.basename(path) or path})
        return items

    def _current_prompt_files(self, session_id=None):
        state = self.get_session(session_id)
        return list(getattr(state, "prompt_files", []) or []) if state else []

    def _managed_attachment_root(self):
        return os.path.join(self.chat_history_dir, "attachments")

    def _session_attachment_dir(self, session_id):
        safe_session_id = re.sub(r"[^A-Za-z0-9_.-]", "_", str(session_id or "").strip())
        if not safe_session_id:
            raise ValueError("当前会话不可用，无法保存图片附件。")
        return os.path.join(self._managed_attachment_root(), safe_session_id)

    def _is_managed_attachment(self, path):
        try:
            root = os.path.normcase(os.path.abspath(self._managed_attachment_root()))
            target = os.path.normcase(os.path.abspath(path))
            return os.path.commonpath([root, target]) == root
        except (OSError, ValueError, TypeError):
            return False

    def _attachment_is_referenced(self, path, state=None):
        target = os.path.normcase(os.path.normpath(str(path or "")))
        state = state or self.get_current_session()
        for message in list(getattr(state, "messages", []) or []):
            for attachment in self._message_user_attachments(message):
                if os.path.normcase(os.path.normpath(attachment.get("path") or "")) == target:
                    return True
        return False

    def _add_clipboard_image(self, image):
        state = self.get_current_session()
        if not state:
            self.add_system_toast("当前没有可接收图片的会话。", "error")
            return ""
        if hasattr(image, "toImage"):
            image = image.toImage()
        if image is None or not hasattr(image, "isNull") or image.isNull():
            log_attachment_event("clipboard_decode_failed", session_id=state.session_id)
            self.add_system_toast("剪贴板中的图片无法读取。", "error")
            return ""
        target_dir = self._session_attachment_dir(state.session_id)
        os.makedirs(target_dir, exist_ok=True)
        filename = f"clipboard-{datetime.now().strftime('%Y%m%d-%H%M%S')}-{uuid.uuid4().hex[:8]}.png"
        target_path = os.path.join(target_dir, filename)
        temp_path = target_path + ".tmp"
        log_attachment_event(
            "clipboard_capture_begin",
            session_id=state.session_id,
            width=image.width(),
            height=image.height(),
        )
        try:
            if not image.save(temp_path, "PNG"):
                raise OSError("Qt image encoder rejected clipboard image")
            os.replace(temp_path, target_path)
        except Exception as exc:
            if os.path.exists(temp_path):
                os.remove(temp_path)
            log_attachment_event("clipboard_save_failed", session_id=state.session_id, error=str(exc))
            self.add_system_toast(f"图片附件保存失败：{exc}", "error", auto_close_ms=6000)
            return ""
        self._add_prompt_files([target_path])
        log_attachment_event("clipboard_capture_completed", session_id=state.session_id, path=target_path)
        return target_path

    def _add_clipboard_files(self, paths):
        requested_paths = [
            os.path.normpath(str(path or "").strip())
            for path in (paths or [])
            if str(path or "").strip()
        ]
        log_attachment_event(
            "clipboard_files_paste_begin",
            requested_count=len(requested_paths),
        )
        file_paths = []
        directory_paths = []
        missing_paths = []
        for path in requested_paths:
            if os.path.isfile(path):
                file_paths.append(path)
            elif os.path.isdir(path):
                directory_paths.append(path)
            else:
                missing_paths.append(path)

        before_keys = {
            os.path.normcase(os.path.normpath(path))
            for path in self._current_prompt_files()
        }
        try:
            accepted_paths = self._add_prompt_files(file_paths)
        except Exception as exc:
            log_attachment_event(
                "clipboard_files_paste_failed",
                requested_count=len(requested_paths),
                error=str(exc),
            )
            self.add_system_toast(
                f"粘贴文件失败：{exc}",
                "error",
                auto_close_ms=6000,
            )
            return []

        added_paths = [
            path
            for path in self._current_prompt_files()
            if os.path.normcase(os.path.normpath(path)) not in before_keys
        ]
        rejected_count = len(directory_paths) + len(missing_paths)
        if rejected_count:
            reasons = []
            if directory_paths:
                reasons.append(f"{len(directory_paths)} 个文件夹")
            if missing_paths:
                reasons.append(f"{len(missing_paths)} 个失效路径")
            prefix = f"已添加 {len(added_paths)} 个文件；" if added_paths else "未添加附件："
            self.add_system_toast(
                prefix + "聊天附件不支持 " + "、".join(reasons) + "。",
                "warning",
                auto_close_ms=6000,
            )
            log_attachment_event(
                "clipboard_files_paste_rejected",
                directory_count=len(directory_paths),
                missing_count=len(missing_paths),
                accepted_count=len(accepted_paths),
                added_count=len(added_paths),
            )
        log_attachment_event(
            "clipboard_files_paste_completed",
            requested_count=len(requested_paths),
            accepted_count=len(accepted_paths),
            added_count=len(added_paths),
            duplicate_count=max(0, len(accepted_paths) - len(added_paths)),
            rejected_count=rejected_count,
        )
        return accepted_paths

    def _start_deepseek_billing_run(self, state, run_id):
        if not state:
            return
        state.current_deepseek_billing = {}
        state.last_deepseek_billing = {}
        self.refresh_token_usage_label(state.session_id)
        profile = self._model_profile_snapshot_for_state(state)
        base_url = str(profile.get("base_url") or "").strip()
        if not is_deepseek_official_base_url(base_url):
            return
        profile_id = str(
            profile.get("profile_id")
            or profile.get("id")
            or profile.get("name")
            or ""
        ).strip()
        state.current_deepseek_billing = {
            "run_id": str(run_id or "").strip(),
            "profile_id": profile_id,
            "model": str(profile.get("model_name") or "").strip(),
            "base_url": base_url,
            "request_started_at": {},
            "counted_request_ids": set(),
            "usage": {
                "input_tokens": 0,
                "output_tokens": 0,
                "cached_input_tokens": 0,
                "uncached_input_tokens": 0,
                "request_count": 0,
            },
            "cost_status": "available",
            "cost_reason_code": "",
            "costs": {"CNY": "0", "USD": "0"},
            "pricing_version": DEEPSEEK_PRICING_VERSION,
            "pricing_periods": [],
            "finalized": False,
        }
        log_chat_runtime_debug(
            "billing_started",
            session_id=state.session_id,
            run_id=str(run_id or ""),
            profile_id=profile_id,
            model=str(profile.get("model_name") or ""),
        )

    def _safe_start_deepseek_billing_run(self, state, run_id):
        try:
            self._start_deepseek_billing_run(state, run_id)
        except Exception as exc:
            if state:
                state.current_deepseek_billing = {}
                state.last_deepseek_billing = {}
            log_chat_runtime_debug(
                "billing_start_failed",
                session_id=str(getattr(state, "session_id", "") or ""),
                run_id=str(run_id or ""),
                error_type=type(exc).__name__,
            )

    def _record_deepseek_billing_request_start(self, state, event):
        billing = getattr(state, "current_deepseek_billing", {}) if state else {}
        if not isinstance(billing, dict) or billing.get("finalized"):
            return
        request_id = str((event or {}).get("request_id") or "").strip()
        if not request_id:
            return
        if not is_deepseek_official_base_url((event or {}).get("base_url")):
            return
        if str((event or {}).get("model") or "").strip().lower() != str(
            billing.get("model") or ""
        ).strip().lower():
            return
        try:
            started_at = float((event or {}).get("timestamp") or time.time())
        except (TypeError, ValueError):
            return
        billing.setdefault("request_started_at", {})[request_id] = started_at

    def _record_deepseek_billing_usage(self, state, usage):
        billing = getattr(state, "current_deepseek_billing", {}) if state else {}
        if not isinstance(billing, dict) or billing.get("finalized"):
            return
        source = dict(usage) if isinstance(usage, dict) else {}
        request_id = str(source.get("request_id") or "").strip()
        if not request_id:
            return
        counted_ids = billing.setdefault("counted_request_ids", set())
        if request_id in counted_ids:
            return
        if not is_deepseek_official_base_url(source.get("base_url")):
            return
        if str(source.get("model") or "").strip().lower() != str(
            billing.get("model") or ""
        ).strip().lower():
            return
        source_profile_id = str(source.get("profile_id") or "").strip()
        if source_profile_id and source_profile_id != str(billing.get("profile_id") or ""):
            return
        counted_ids.add(request_id)
        run_usage = billing.setdefault("usage", {})
        for key in (
            "input_tokens",
            "output_tokens",
            "cached_input_tokens",
            "uncached_input_tokens",
        ):
            try:
                run_usage[key] = int(run_usage.get(key) or 0) + max(0, int(source.get(key) or 0))
            except (TypeError, ValueError):
                billing["cost_status"] = "unavailable"
                billing["cost_reason_code"] = "missing_usage"
        run_usage["request_count"] = int(run_usage.get("request_count") or 0) + 1
        started_at = billing.get("request_started_at", {}).get(request_id)
        if started_at is None:
            billing["cost_status"] = "unavailable"
            billing["cost_reason_code"] = "missing_request_start"
            billing["costs"] = {}
        elif billing.get("cost_status") == "available":
            estimate = estimate_deepseek_request_cost(source, started_at)
            if not estimate.get("ok"):
                billing["cost_status"] = "unavailable"
                billing["cost_reason_code"] = str(estimate.get("reason_code") or "unknown")
                billing["costs"] = {}
            else:
                totals = billing.setdefault("costs", {})
                for currency, amount in (estimate.get("amounts") or {}).items():
                    totals[currency] = str(
                        Decimal(str(totals.get(currency) or "0")) + Decimal(str(amount or "0"))
                    )
                period = str(estimate.get("period") or "")
                if period and period not in billing.setdefault("pricing_periods", []):
                    billing["pricing_periods"].append(period)
        log_chat_runtime_debug(
            "usage_recorded",
            session_id=state.session_id,
            run_id=str(billing.get("run_id") or ""),
            request_id=request_id,
            request_count=int(run_usage.get("request_count") or 0),
            cost_status=str(billing.get("cost_status") or ""),
        )

    def _persist_deepseek_billing_state(self, state):
        if not state:
            return
        snapshot = billing_snapshot_for_persistence(
            getattr(state, "last_deepseek_billing", {})
        )
        meta = copy.deepcopy(getattr(state, "persisted_conversation_meta", {}) or {})
        if snapshot:
            meta["last_deepseek_billing"] = snapshot
        else:
            meta.pop("last_deepseek_billing", None)
        state.persisted_conversation_meta = meta
        if not self.chat_storage.has_conversation(state.session_id):
            return
        if self._history_writer_owner_for_session(state.session_id) == "daemon":
            self.chat_storage.update_conversation_meta(
                state.session_id,
                {"last_deepseek_billing": snapshot},
            )
        else:
            self.save_chat_history(session_id=state.session_id)

    def _release_deepseek_balance_worker(self, worker_key, worker):
        workers = getattr(self, "_deepseek_balance_workers", None)
        if isinstance(workers, dict) and workers.get(worker_key) is worker:
            workers.pop(worker_key, None)
        worker.deleteLater()

    def _handle_deepseek_balance_result(self, result):
        if not isinstance(result, dict):
            return
        state = self.get_session(result.get("session_id"))
        if not state:
            return
        billing = normalize_deepseek_billing_snapshot(
            getattr(state, "last_deepseek_billing", {})
        )
        if (
            str(billing.get("run_id") or "") != str(result.get("run_id") or "")
            or str(billing.get("profile_id") or "") != str(result.get("profile_id") or "")
        ):
            log_chat_runtime_debug(
                "billing_balance_stale_rejected",
                session_id=state.session_id,
                run_id=str(result.get("run_id") or ""),
                profile_id=str(result.get("profile_id") or ""),
            )
            return
        if result.get("ok") and isinstance(result.get("balance"), dict):
            billing["balance_status"] = "succeeded"
            billing["balance"] = result.get("balance")
            billing.pop("balance_error_category", None)
            state.last_deepseek_billing = normalize_deepseek_billing_snapshot(billing)
            self._persist_deepseek_billing_state(state)
            log_chat_runtime_debug(
                "balance_succeeded",
                session_id=state.session_id,
                run_id=str(result.get("run_id") or ""),
                profile_id=str(result.get("profile_id") or ""),
                currency_count=len((result.get("balance") or {}).get("balance_infos") or []),
            )
        else:
            billing["balance_status"] = "failed"
            billing["balance_error_category"] = str(result.get("error_category") or "unknown")
            billing.pop("balance", None)
            state.last_deepseek_billing = normalize_deepseek_billing_snapshot(billing)
            log_chat_runtime_debug(
                "balance_failed",
                session_id=state.session_id,
                run_id=str(result.get("run_id") or ""),
                profile_id=str(result.get("profile_id") or ""),
                error_category=str(result.get("error_category") or "unknown"),
            )
        self.refresh_token_usage_label(state.session_id)

    def _safe_handle_deepseek_balance_result(self, result):
        try:
            self._handle_deepseek_balance_result(result)
        except Exception as exc:
            state = self.get_session((result or {}).get("session_id")) if isinstance(result, dict) else None
            log_chat_runtime_debug(
                "billing_balance_handler_failed",
                session_id=str(getattr(state, "session_id", "") or ""),
                run_id=str((result or {}).get("run_id") or "") if isinstance(result, dict) else "",
                error_type=type(exc).__name__,
            )
            if state:
                self.refresh_token_usage_label(state.session_id)

    def _finalize_deepseek_billing(self, state, run_id):
        billing = getattr(state, "current_deepseek_billing", {}) if state else {}
        if not isinstance(billing, dict) or not billing or billing.get("finalized"):
            return False
        if str(billing.get("run_id") or "") != str(run_id or ""):
            return False
        billing["finalized"] = True
        request_count = int((billing.get("usage") or {}).get("request_count") or 0)
        if request_count <= 0:
            log_chat_runtime_debug(
                "finalized",
                session_id=state.session_id,
                run_id=str(run_id or ""),
                outcome="no_usage",
            )
            return False
        snapshot = normalize_deepseek_billing_snapshot(
            {
                "run_id": billing.get("run_id"),
                "profile_id": billing.get("profile_id"),
                "model": billing.get("model"),
                "cost_status": billing.get("cost_status"),
                "cost_reason_code": billing.get("cost_reason_code"),
                "costs": billing.get("costs"),
                "usage": billing.get("usage"),
                "pricing_version": billing.get("pricing_version"),
                "pricing_periods": billing.get("pricing_periods"),
                "completed_at": time.time(),
                "balance_status": "querying",
            }
        )
        state.last_deepseek_billing = snapshot
        self._persist_deepseek_billing_state(state)
        self.refresh_token_usage_label(state.session_id)
        profile = self._model_profile_for_state(
            state,
            model_id=str(billing.get("profile_id") or ""),
        )
        resolved_profile_id = str(
            (profile or {}).get("profile_id")
            or (profile or {}).get("id")
            or (profile or {}).get("name")
            or ""
        ).strip()
        profile_matches_run = bool(
            isinstance(profile, dict)
            and resolved_profile_id == str(billing.get("profile_id") or "")
            and str(profile.get("model_name") or "").strip().lower()
            == str(billing.get("model") or "").strip().lower()
            and str(profile.get("base_url") or "").strip()
            == str(billing.get("base_url") or "").strip()
            and is_deepseek_official_base_url(profile.get("base_url"))
        )
        api_key = str(profile.get("api_key") or "").strip() if profile_matches_run else ""
        worker = DeepSeekBalanceWorker(
            state.session_id,
            billing.get("run_id"),
            billing.get("profile_id"),
            api_key,
            self,
        )
        worker_key = (
            state.session_id,
            str(billing.get("run_id") or ""),
            str(billing.get("profile_id") or ""),
        )
        workers = getattr(self, "_deepseek_balance_workers", None)
        if not isinstance(workers, dict):
            self._deepseek_balance_workers = {}
            workers = self._deepseek_balance_workers
        workers[worker_key] = worker
        worker.result_signal.connect(self._safe_handle_deepseek_balance_result)
        worker.finished.connect(
            lambda key=worker_key, current=worker: self._release_deepseek_balance_worker(key, current)
        )
        log_chat_runtime_debug(
            "billing_balance_query_started",
            session_id=state.session_id,
            run_id=str(billing.get("run_id") or ""),
            profile_id=str(billing.get("profile_id") or ""),
        )
        worker.start()
        log_chat_runtime_debug(
            "finalized",
            session_id=state.session_id,
            run_id=str(run_id or ""),
            outcome="balance_query_started",
            request_count=request_count,
            cost_status=str(snapshot.get("cost_status") or ""),
        )
        return True

    def _safe_finalize_deepseek_billing(self, state, run_id):
        try:
            return self._finalize_deepseek_billing(state, run_id)
        except Exception as exc:
            billing = getattr(state, "current_deepseek_billing", {}) if state else {}
            if isinstance(billing, dict):
                billing["finalized"] = True
            log_chat_runtime_debug(
                "billing_finalize_failed",
                session_id=str(getattr(state, "session_id", "") or ""),
                run_id=str(run_id or ""),
                error_type=type(exc).__name__,
            )
            return False

    def _cleanup_orphan_attachment_dirs(self):
        root = self._managed_attachment_root()
        if not os.path.isdir(root):
            return
        known_ids = {str(item.get("id") or "") for item in self.chat_storage.list_conversations()}
        for name in os.listdir(root):
            path = os.path.join(root, name)
            if not os.path.isdir(path) or name in known_ids:
                continue
            shutil.rmtree(path)

    def _set_prompt_files(self, paths, session_id=None, refresh=True):
        state = self.get_session(session_id)
        normalized = self._normalize_prompt_file_paths(paths)
        if state:
            state.prompt_files = normalized
        if refresh and (session_id is None or session_id == self.current_session_id):
            self.refresh_prompt_file_chips(session_id)
        return normalized

    def refresh_prompt_file_chips(self, session_id=None):
        if not hasattr(self, "prompt_files_section") or not hasattr(self, "prompt_files_row"):
            return
        files = self._current_prompt_files(session_id)
        while self.prompt_files_row.count():
            item = self.prompt_files_row.takeAt(0)
            widget = item.widget()
            if widget is not None:
                widget.deleteLater()
        if not files:
            self.prompt_files_section.setVisible(False)
            return
        self.prompt_files_hint.setText(f"用户添加的文件 ({len(files)})")
        for path in files:
            chip = FileChip(path, removable=True)
            chip.removeRequested.connect(self._remove_prompt_file)
            self.prompt_files_row.addWidget(chip)
        self.prompt_files_row.addStretch()
        self.prompt_files_section.setVisible(True)

    def _token_speed_snapshot(self, state):
        tracker = getattr(state, "token_speed_tracker", None) if state else None
        if tracker is None:
            return None
        return tracker.snapshot(time.monotonic())

    def _fail_token_speed_monitor(self, state, error, event_type):
        if not state:
            return
        tracker = getattr(state, "token_speed_tracker", None)
        if tracker is None:
            return
        reason = str(error or "Token speed monitoring failed.")
        tracker.fail(reason, time.monotonic())
        timer = getattr(state, "token_speed_timer", None)
        if timer is not None and timer.isActive():
            timer.stop()
        log_chat_runtime_debug(
            "token_speed_monitor_error",
            session_id=state.session_id,
            event_type=str(event_type or ""),
            error=reason,
        )
        self.refresh_token_usage_label(state.session_id)

    def _start_token_speed_monitor(self, state, event):
        if not state:
            return
        try:
            self._record_deepseek_billing_request_start(state, event)
        except Exception as exc:
            log_chat_runtime_debug(
                "billing_request_start_failed",
                session_id=state.session_id,
                request_id=str((event or {}).get("request_id") or ""),
                error_type=type(exc).__name__,
            )
        request_id = str((event or {}).get("request_id") or "").strip()
        try:
            state.token_speed_tracker.begin(request_id, time.monotonic())
        except Exception as exc:
            self._fail_token_speed_monitor(state, exc, "provider_request_start")
            return
        timer = getattr(state, "token_speed_timer", None)
        if timer is not None and not timer.isActive():
            timer.start()
        log_chat_runtime_debug(
            "token_speed_monitor_started",
            session_id=state.session_id,
            request_id=request_id,
            provider=str((event or {}).get("provider") or ""),
            model=str((event or {}).get("model") or ""),
        )
        self.refresh_token_usage_label(state.session_id)

    def _retry_token_speed_monitor(self, state, event):
        if not state:
            return
        request_id = str((event or {}).get("request_id") or "").strip()
        try:
            state.token_speed_tracker.retry(request_id, time.monotonic())
        except Exception as exc:
            self._fail_token_speed_monitor(state, exc, "provider_retry")
            return
        log_chat_runtime_debug(
            "token_speed_monitor_retry_reset",
            session_id=state.session_id,
            request_id=request_id,
            retry_attempt=max(1, int((event or {}).get("attempt") or 1)),
        )
        self.refresh_token_usage_label(state.session_id)

    def _finish_token_speed_monitor(self, state, event, status=None):
        if not state:
            return
        request_id = str((event or {}).get("request_id") or "").strip()
        finish_status = str(status or (event or {}).get("status") or "completed")
        try:
            snapshot = state.token_speed_tracker.finish(
                request_id,
                time.monotonic(),
                status=finish_status,
            )
        except Exception as exc:
            self._fail_token_speed_monitor(state, exc, str((event or {}).get("type") or "finish"))
            return
        timer = getattr(state, "token_speed_timer", None)
        if timer is not None and timer.isActive():
            timer.stop()
        log_chat_runtime_debug(
            "token_speed_monitor_finished",
            session_id=state.session_id,
            request_id=request_id,
            status=finish_status,
            last_rate=snapshot.get("last_rate"),
            last_tokens=snapshot.get("last_tokens"),
            last_duration=snapshot.get("last_duration"),
        )
        self.refresh_token_usage_label(state.session_id)

    def _cancel_token_speed_monitor(self, state, reason):
        if not state:
            return
        tracker = getattr(state, "token_speed_tracker", None)
        if tracker is None or not tracker.active:
            return
        request_id = tracker.request_id
        tracker.cancel(time.monotonic())
        timer = getattr(state, "token_speed_timer", None)
        if timer is not None and timer.isActive():
            timer.stop()
        log_chat_runtime_debug(
            "token_speed_monitor_cancelled",
            session_id=state.session_id,
            request_id=request_id,
            reason=str(reason or "cancelled"),
        )
        self.refresh_token_usage_label(state.session_id)

    def _record_token_speed_delta(self, state, text, kind):
        if not state or not str(text or ""):
            return
        try:
            first_sample = state.token_speed_tracker.record_text(
                text,
                time.monotonic(),
            )
        except Exception as exc:
            self._fail_token_speed_monitor(state, exc, f"{kind}_delta")
            return
        if first_sample:
            log_chat_runtime_debug(
                "token_speed_monitor_first_sample",
                session_id=state.session_id,
                request_id=state.token_speed_tracker.request_id,
                content_kind=str(kind or ""),
                estimated_tokens=state.token_speed_tracker.estimated_tokens,
            )
            self.refresh_token_usage_label(state.session_id)

    def refresh_token_usage_label(self, session_id=None):
        state = self.get_session(session_id)
        if not state:
            return
        label = getattr(state, "token_usage_label", None)
        if not label or not _qt_object_alive(label):
            return
        summary = normalize_token_usage_summary(getattr(state, "token_usage_summary", {}))
        state.token_usage_summary = summary
        speed_snapshot = self._token_speed_snapshot(state)
        billing_snapshot = getattr(state, "last_deepseek_billing", {})
        label.setText(format_token_usage_chip_text(summary, speed_snapshot, billing_snapshot))
        label.setDetailText(
            format_token_usage_tooltip(
                summary,
                getattr(state, "last_token_usage", {}),
                speed_snapshot,
                billing_snapshot,
            )
        )
        has_speed = bool(
            isinstance(speed_snapshot, dict)
            and (
                speed_snapshot.get("active")
                or speed_snapshot.get("last_rate") is not None
                or str(speed_snapshot.get("unavailable_reason") or "").strip()
            )
        )
        label.setVisible(int(summary.get("total_tokens") or 0) > 0 or has_speed)

    def apply_token_usage_event(self, state, usage):
        if not state:
            return
        if not isinstance(usage, dict) or not usage:
            summary = normalize_token_usage_summary(getattr(state, "token_usage_summary", {}))
            summary["missing_usage_count"] += 1
            state.token_usage_summary = summary
            self.refresh_token_usage_label(state.session_id)
            return
        usage_request_id = str(usage.get("request_id") or "").strip()
        counted_request_ids = getattr(state, "counted_usage_request_ids", set())
        if usage_request_id and usage_request_id in counted_request_ids:
            log_chat_runtime_debug(
                "token_usage_duplicate_request_ignored",
                session_id=state.session_id,
                request_id=usage_request_id,
            )
            return
        bucket_key = token_usage_bucket_key(usage)
        buckets = normalize_token_usage_buckets(getattr(state, "token_usage_buckets", {}))
        current = normalize_token_usage_summary(buckets.get(bucket_key, {}))
        last = normalize_last_token_usage(usage)
        counted = False
        for key in ("input_tokens", "output_tokens", "total_tokens", "cached_input_tokens", "uncached_input_tokens"):
            value = last.get(key, 0)
            if value:
                current[key] += value
                counted = True
        if counted:
            current["request_count"] += 1
            if usage_request_id:
                counted_request_ids.add(usage_request_id)
                state.counted_usage_request_ids = counted_request_ids
            state.last_token_usage = dict(last)
            state.last_token_usage["cache_bucket"] = bucket_key
            try:
                self._record_deepseek_billing_usage(state, usage)
            except Exception as exc:
                log_chat_runtime_debug(
                    "billing_usage_record_failed",
                    session_id=state.session_id,
                    request_id=usage_request_id,
                    error_type=type(exc).__name__,
                )
        else:
            current["missing_usage_count"] += 1
            state.last_token_usage = {}
        buckets[bucket_key] = current
        state.token_usage_buckets = buckets
        state.token_usage_summary = current
        meta = copy.deepcopy(getattr(state, "persisted_conversation_meta", {}) or {})
        meta["token_usage_summary"] = copy.deepcopy(current)
        meta["token_usage_buckets"] = copy.deepcopy(buckets)
        state.persisted_conversation_meta = meta
        self.refresh_token_usage_label(state.session_id)

    def _remove_prompt_file(self, path):
        remaining = [
            item
            for item in self._current_prompt_files()
            if os.path.normcase(item) != os.path.normcase(os.path.normpath(path))
        ]
        self._set_prompt_files(remaining)
        if self._is_managed_attachment(path) and not self._attachment_is_referenced(path):
            try:
                os.remove(path)
                log_attachment_event("pending_attachment_removed", path=path)
            except FileNotFoundError:
                pass
            except OSError as exc:
                log_attachment_event("pending_attachment_remove_failed", path=path, error=str(exc))

    def _clear_prompt_files(self, session_id=None):
        self._set_prompt_files([], session_id=session_id, refresh=True)

    def _add_prompt_files(self, paths):
        file_paths = self._normalize_prompt_file_paths(paths)
        if not file_paths or not hasattr(self, "input_field"):
            return []

        if not self._workspace_dir_for_state():
            state = self.get_current_session()
            if state:
                self._ensure_session_workspace(state)
                if state.session_id == self.current_session_id:
                    self._sync_workspace_ui_for_session(state.session_id, refresh_sidebar=False)
                    self.normalize_session_ui(state)

        existing = self._current_prompt_files()
        self._set_prompt_files(existing + file_paths)
        self.input_field.moveCursor(QTextCursor.End)
        self.input_field.ensureCursorVisible()
        self.input_field.setFocus()
        if hasattr(self.input_field, "adjustHeight"):
            self.input_field.adjustHeight()
        self.set_context_tab_hint(self.RIGHT_TAB_FILES, True)
        return file_paths

    def _append_files_to_input(self, paths):
        return self._add_prompt_files(paths)

    def select_files_for_prompt(self):
        start_dir = self._workspace_dir_for_state() or self.config_manager.get("default_workspace", "") or ""
        file_paths, _selected_filter = QFileDialog.getOpenFileNames(
            self,
            "选择文件",
            start_dir,
            "所有文件 (*.*)",
        )
        self._add_prompt_files(file_paths)

    def _build_user_added_files_prompt(self, file_paths):
        normalized = self._normalize_prompt_file_paths(file_paths)
        if not normalized:
            return ""
        lines = [
            "[用户添加的文件]",
            "以下文件由用户通过“添加文件”手动附加，请优先视为本轮任务的重要输入：",
        ]
        for path in normalized:
            lines.append(f"- 文件名: {os.path.basename(path) or path}")
            lines.append(f"  路径: {path}")
        return "\n".join(lines)

    def _build_user_message_payload(
        self,
        user_text,
        file_paths,
        supports_vision=False,
        *,
        resolve_text_references=True,
        keep_audio_local=False,
        audio_transcription_backend=ASR_BACKEND_LOCAL,
    ):
        display_text = str(user_text or "").strip()
        normalized_files = self._normalize_prompt_file_paths(file_paths)
        referenced_images = (
            self._resolve_text_image_references(display_text, normalized_files)
            if resolve_text_references
            else []
        )
        if referenced_images:
            normalized_files = self._normalize_prompt_file_paths(normalized_files + referenced_images)
        model_visible_files, local_audio_files = partition_model_visible_attachments(
            normalized_files,
            keep_audio_local=bool(keep_audio_local),
        )
        image_paths = [path for path in normalized_files if self._is_supported_image_attachment(path)]
        model_image_paths = [path for path in model_visible_files if path in image_paths]
        regular_files = [path for path in model_visible_files if path not in image_paths]
        content_blocks = []
        if model_visible_files:
            content_blocks.append(self._build_user_added_files_prompt(model_visible_files))
        if local_audio_files:
            if audio_transcription_backend == ASR_BACKEND_OPENAI_COMPATIBLE:
                content_blocks.append(
                    "[语音转文字专用附件]\n"
                    "本轮音频附件仅授权给用户已配置的语音转文字服务；"
                    "未向当前对话模型提供文件名、路径、大小或音频内容。"
                )
            else:
                content_blocks.append(
                    "[本地音频附件]\n"
                    "本轮音频附件仅授权给本地语音转文字工具；"
                    "未向当前模型提供文件名、路径、大小或音频内容。"
                )
        if display_text:
            content_blocks.append(display_text)
        content = "\n\n".join([block for block in content_blocks if block]).strip()
        content_parts = []
        if display_text:
            content_parts.append({"type": "text", "text": display_text})
        for path in model_image_paths:
            content_parts.append(
                {
                    "type": "input_image",
                    "path": path,
                    "name": os.path.basename(path) or path,
                    "source": "user_added",
                }
            )
        for path in regular_files:
            content_parts.append(
                {
                    "type": "input_file",
                    "path": path,
                    "name": os.path.basename(path) or path,
                    "source": "user_added",
                }
            )
        meta = {}
        if display_text:
            meta["display_content"] = display_text
        if normalized_files:
            meta["user_added_files"] = normalized_files
        if local_audio_files:
            if audio_transcription_backend == ASR_BACKEND_OPENAI_COMPATIBLE:
                meta["transcription_only_audio_files"] = local_audio_files
                meta["transcription_only_audio_count"] = len(local_audio_files)
                meta["audio_transcription_backend"] = ASR_BACKEND_OPENAI_COMPATIBLE
            else:
                meta["local_only_audio_files"] = local_audio_files
                meta["local_only_audio_count"] = len(local_audio_files)
        if image_paths:
            meta["user_added_images"] = image_paths
            meta["vision_requested"] = bool(supports_vision)
        if referenced_images:
            meta["workspace_referenced_images"] = referenced_images
        if image_paths:
            log_attachment_event(
                "vision_payload_built",
                image_count=len(image_paths),
                supports_vision=bool(supports_vision),
            )
        return {
            "content": content,
            "display_content": display_text,
            "attachments": self._prompt_file_items(normalized_files),
            "content_parts": content_parts or None,
            "meta": meta or None,
        }

    def _speech_to_text_runtime_config(self):
        values = (
            self.config_manager.get_skill_config(SPEECH_TO_TEXT_SKILL_ID)
            if getattr(self, "config_manager", None)
            and hasattr(self.config_manager, "get_skill_config")
            else {}
        )
        return speech_to_text_config(values)

    def _open_speech_to_text_settings(self):
        if not self.show_product_page(self.PAGE_CAPABILITIES):
            return False
        skill = next(
            (
                item
                for item in self.skill_manager.get_all_skills()
                if str(item.get("name") or "") == SPEECH_TO_TEXT_SKILL_ID
            ),
            None,
        )
        return bool(skill and self.show_capability_detail(skill))

    def _ensure_speech_component_before_submit(
        self,
        state,
        file_paths,
        *,
        keep_audio_local,
        transcription_config=None,
    ):
        if not keep_audio_local or not any(is_audio_attachment(path) for path in file_paths or []):
            return True
        config = transcription_config or self._speech_to_text_runtime_config()
        try:
            validated_config = validate_speech_to_text_config({
                "ASR_BACKEND": config.get("backend"),
                "ASR_API_URL": config.get("api_url"),
                "ASR_MODEL_NAME": config.get("model_name"),
                "ASR_API_KEY": config.get("api_key"),
            })
        except ValueError as exc:
            log_chat_runtime_debug(
                "speech_config_preflight_blocked",
                session_id=str(getattr(state, "session_id", "") or ""),
                error=str(exc),
            )
            self._show_conversation_notice(
                state,
                f"{exc} 本次录音尚未提交给 AI。",
                "warning",
                action_text="打开语音转文字设置",
                action_callback=self._open_speech_to_text_settings,
            )
            return False
        if validated_config.get("backend") == ASR_BACKEND_OPENAI_COMPATIBLE:
            try:
                for path in file_paths or []:
                    if is_audio_attachment(path):
                        validate_remote_transcription_input(validated_config, path)
            except RemoteTranscriptionInputError as exc:
                log_chat_runtime_debug(
                    "speech_remote_input_preflight_blocked",
                    session_id=str(getattr(state, "session_id", "") or ""),
                    error_code=exc.code,
                    **exc.details,
                )
                self._show_conversation_notice(
                    state,
                    f"{exc} {exc.recovery} 本次录音尚未提交给 AI。",
                    "warning",
                    action_text="打开语音转文字设置",
                    action_callback=self._open_speech_to_text_settings,
                )
                return False
            return True
        status = speech_to_text_component_status(include_size=False)
        if status.get("ready"):
            return True
        detail = str(status.get("health_error") or "语音转文字组件尚未安装。")
        log_chat_runtime_debug(
            "speech_component_preflight_blocked",
            session_id=str(getattr(state, "session_id", "") or ""),
            needs_update=bool(status.get("needs_update")),
            needs_repair=bool(status.get("needs_repair")),
            error=detail,
        )
        self._show_conversation_notice(
            state,
            f"{detail} 请先安装或修复“语音转文字组件”，本次录音尚未提交给 AI。",
            "warning",
            action_text="打开组件与依赖",
            action_callback=lambda: self.open_settings("组件与依赖"),
        )
        return False

    def _message_user_attachments(self, message):
        if not isinstance(message, dict):
            return []
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        meta_paths = meta.get("user_added_files")
        if isinstance(meta_paths, list):
            return self._prompt_file_items(meta_paths)
        attachments = []
        for part in message.get("content_parts") or []:
            if not isinstance(part, dict):
                continue
            part_type = str(part.get("type") or "").strip().lower()
            if part_type not in {"input_file", "input_image"}:
                continue
            path = str(part.get("path") or "").strip()
            if not path:
                continue
            attachments.append(path)
        return self._prompt_file_items(attachments)

    def _message_display_content(self, message):
        if not isinstance(message, dict):
            return ""
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        display = meta.get("display_content")
        if display is not None:
            return str(display)
        return str(message.get("content") or "")

    def _new_message_id(self):
        return uuid.uuid4().hex

    def _session_is_busy(self, state):
        return bool(
            state
            and (
                str(getattr(state, "session_status", "") or "") in {
                    "running",
                    "finalizing",
                }
                or
                bool(getattr(state, "live_activity", False))
                or
                (getattr(state, "llm_worker", None) and state.llm_worker.isRunning())
                or (getattr(state, "code_worker", None) and state.code_worker.isRunning())
                or getattr(state, "daemon_running", False)
                or getattr(state, "stop_pending", False)
            )
        )

    def _can_rewrite_session_from_message(self, state):
        if not state:
            return (False, "找不到当前会话。")
        if getattr(state, "history_loading", False) or not getattr(state, "history_loaded", True):
            return (False, "历史消息仍在加载，请稍后再试。")
        if self._session_is_busy(state):
            return (False, "当前会话正在运行，请先停止任务后再编辑或删除消息。")
        return (True, "")

    def _message_attachment_paths(self, message):
        attachments = self._message_user_attachments(message)
        return self._normalize_prompt_file_paths(
            [item.get("path") for item in attachments if isinstance(item, dict) and item.get("path")]
        )

    def _find_message_by_id(self, messages, message_id):
        target_id = str(message_id or "").strip()
        if not target_id:
            return None
        for msg in messages or []:
            if not isinstance(msg, dict):
                continue
            if str(msg.get("id") or "").strip() == target_id:
                return msg
        return None

    def _assistant_source_message_id_from_messages(self, messages):
        for msg in reversed(messages or []):
            if not isinstance(msg, dict):
                continue
            if (msg.get("role") or "") != "assistant":
                continue
            message_id = str(msg.get("id") or "").strip()
            if message_id:
                return message_id
        return ""

    def _render_rewritten_session(self, state, messages):
        raise RuntimeError("全量历史重写已禁用；请使用渲染节点局部重写事务。")

    def _capture_history_rewrite(self, state, message_id):
        node = (getattr(state, "render_node_by_message_id", {}) or {}).get(str(message_id or ""))
        widget = (node or {}).get("widget") if isinstance(node, dict) else None
        if widget is None or not _qt_object_alive(widget):
            raise RuntimeError("无法定位消息界面，请重新打开会话后重试。")
        top_level = self._top_level_chat_widget(state, widget)
        layout_index = state.chat_layout.indexOf(top_level) if top_level is not None else -1
        if layout_index < 0:
            raise RuntimeError("无法定位消息界面，请重新打开会话后重试。")
        viewport_offset = 0
        try:
            viewport_offset = top_level.mapTo(state.chat_scroll.viewport(), QPoint(0, 0)).y()
        except RuntimeError:
            viewport_offset = 0
        snapshot = {
            "messages": copy.deepcopy(state.messages),
            "render_items": copy.deepcopy(state.render_items),
            "render_nodes": dict(state.render_nodes),
            "render_node_by_message_id": dict(state.render_node_by_message_id),
            "tool_cards": dict(state.tool_cards),
            "pending_tool_results": copy.deepcopy(state.pending_tool_results),
            "ui_timeline_events": copy.deepcopy(state.ui_timeline_events),
            "pending_guidance_messages": copy.deepcopy(state.pending_guidance_messages),
            "persisted_agents": copy.deepcopy(state.persisted_agents),
            "history_detail_summaries": list(state.history_detail_summaries),
            "history_office_cards": list(state.history_office_cards),
            "displayed_render_count": int(state.displayed_render_count or 0),
            "layout_index": layout_index,
            "viewport_offset": viewport_offset,
            "widgets": [],
        }
        while state.chat_layout.count() - 1 > layout_index:
            item = state.chat_layout.takeAt(layout_index)
            detached = item.widget() if item is not None else None
            if detached is None:
                continue
            detached.hide()
            snapshot["widgets"].append(detached)
            for summary in detached.findChildren(HistoricalAssistantSummary):
                summary.detail_button.setChecked(False)
            if isinstance(detached, HistoricalAssistantSummary):
                detached.detail_button.setChecked(False)
        return snapshot

    def _truncate_rewrite_state(self, state, target_index):
        retained_messages = self.chat_storage.normalize_messages(
            copy.deepcopy((state.messages or [])[:target_index]),
            conversation_id=state.session_id,
        )
        retained_ids = {
            str(message.get("id") or "")
            for message in retained_messages
            if isinstance(message, dict) and str(message.get("id") or "")
        }
        retained_tool_ids = {
            str(tool_call.get("id") or "")
            for message in retained_messages
            if isinstance(message, dict)
            for tool_call in (message.get("tool_calls") or [])
            if isinstance(tool_call, dict) and str(tool_call.get("id") or "")
        }
        retained_group_ids = {
            str((message.get("meta") or {}).get("ui_turn_group_id") or "")
            for message in retained_messages
            if isinstance(message, dict) and isinstance(message.get("meta"), dict)
            and str((message.get("meta") or {}).get("ui_turn_group_id") or "")
        }
        state.messages = retained_messages
        state.tool_cards = {
            tool_id: card for tool_id, card in state.tool_cards.items()
            if str(tool_id) in retained_tool_ids
        }
        state.pending_tool_results = {
            tool_id: result for tool_id, result in state.pending_tool_results.items()
            if str(tool_id) in retained_tool_ids
        }
        state.ui_timeline_events = [
            event for event in state.ui_timeline_events
            if (str(event.get("message_id") or "") and str(event.get("message_id") or "") in retained_ids)
            or (str(event.get("tool_call_id") or "") and str(event.get("tool_call_id") or "") in retained_tool_ids)
            or (str(event.get("group_id") or "") and str(event.get("group_id") or "") in retained_group_ids)
        ]
        state.pending_guidance_messages = [
            message for message in state.pending_guidance_messages
            if str(message.get("id") or "") in retained_ids
        ]
        state.persisted_agents = [
            agent for agent in state.persisted_agents
            if not str(agent.get("parent_message_id") or "")
            or str(agent.get("parent_message_id") or "") in retained_ids
        ]
        state.render_nodes = {
            key: node for key, node in state.render_nodes.items()
            if int(node.get("end") or 0) <= int(target_index)
        }
        state.render_node_by_message_id = {
            message_id: node for message_id, node in state.render_node_by_message_id.items()
            if message_id in retained_ids and node.get("key") in state.render_nodes
        }
        state.history_detail_summaries = [
            summary for summary in state.history_detail_summaries
            if _qt_object_alive(summary) and int(getattr(summary, "span_end", 0) or 0) <= int(target_index)
        ]
        state.history_office_cards = [
            card for card in state.history_office_cards
            if _qt_object_alive(card) and int(getattr(card, "_history_span_end", 0) or 0) <= int(target_index)
        ]
        self._rebuild_session_render_spans(state)
        state.displayed_render_count = min(state.displayed_render_count, len(state.render_items))
        state.last_agent_bubble = None
        state.temp_thinking_bubble = None
        state.active_agent_turn_group = None
        state.pending_guidance_messages = []
        return retained_ids

    def _session_has_current_execution(self, state):
        if not state:
            return False
        llm_worker = getattr(state, "llm_worker", None)
        code_worker = getattr(state, "code_worker", None)
        daemon_worker = getattr(state, "daemon_worker", None)
        return bool(
            getattr(state, "submit_in_progress", False)
            or getattr(state, "live_activity", False)
            or getattr(state, "daemon_running", False)
            or (llm_worker is not None and llm_worker.isRunning())
            or (code_worker is not None and code_worker.isRunning())
            or (daemon_worker is not None and daemon_worker.isRunning())
        )

    def _restore_history_rewrite(self, state, snapshot):
        start = int(snapshot.get("layout_index") or 0)
        while state.chat_layout.count() - 1 > start:
            item = state.chat_layout.takeAt(start)
            widget = item.widget() if item is not None else None
            if widget is not None:
                self._retire_chat_widget(widget)
        for offset, widget in enumerate(snapshot.get("widgets") or []):
            state.chat_layout.insertWidget(start + offset, widget)
            widget.show()
        for field in (
            "messages",
            "render_items",
            "render_nodes",
            "render_node_by_message_id",
            "tool_cards",
            "pending_tool_results",
            "ui_timeline_events",
            "pending_guidance_messages",
            "persisted_agents",
            "history_detail_summaries",
            "history_office_cards",
            "displayed_render_count",
        ):
            setattr(state, field, snapshot[field])
        QTimer.singleShot(0, lambda s=state, snap=snapshot: self._restore_rewrite_viewport(s, snap))

    def _restore_rewrite_viewport(self, state, snapshot, message_id=""):
        target = None
        if message_id:
            node = state.render_node_by_message_id.get(str(message_id))
            target = (node or {}).get("widget") if isinstance(node, dict) else None
        if target is None:
            widgets = snapshot.get("widgets") or []
            target = widgets[0] if widgets else None
        if target is None or not _qt_object_alive(target):
            return
        try:
            current_offset = target.mapTo(state.chat_scroll.viewport(), QPoint(0, 0)).y()
            bar = state.chat_scroll.verticalScrollBar()
            bar.setValue(bar.value() + current_offset - int(snapshot.get("viewport_offset") or 0))
        except RuntimeError:
            return

    def _commit_history_rewrite(self, snapshot):
        for widget in snapshot.get("widgets") or []:
            self._retire_chat_widget(widget)

    def _history_rewrite_guard(self, state):
        committed_messages = self.chat_storage.get_messages(state.session_id)
        committed_meta = self.chat_storage.get_conversation_meta(state.session_id)
        return {
            "messages_hash": RuntimeJournal.messages_hash(committed_messages),
            "revision": max(0, int(committed_meta.get("history_save_revision") or 0)),
        }

    def _persist_history_rewrite(self, state, guard, *, operation):
        if not state or not isinstance(guard, dict):
            raise ValueError("历史改写缺少 revision/hash 校验信息")
        next_meta = self._compose_session_meta(state)
        result = self.chat_storage.rewrite_conversation_safely(
            state.session_id,
            filter_persistable_messages(state.messages),
            expected_messages_hash=guard.get("messages_hash"),
            expected_revision=guard.get("revision"),
            title=self._resolved_session_title(state, state.messages),
            status=getattr(state, "session_status", "draft"),
            meta=next_meta,
        )
        state.chat_save_revision = int(result.get("revision") or 0)
        state.persisted_conversation_meta = copy.deepcopy(result.get("meta") or next_meta)
        try:
            pending_path = self.chat_recovery_journal._path_for_session(state.session_id)
            if os.path.exists(pending_path):
                envelope = self.chat_recovery_journal._read_envelope(pending_path)
                payload = envelope.get("payload") or {}
                self.chat_recovery_journal.acknowledge(
                    state.session_id,
                    int(payload.get("revision") or 0),
                )
        except Exception as exc:
            self.append_log(
                f"历史改写旧保存快照清理失败({state.session_id}, operation={operation}): {exc}"
            )
        try:
            manifest = self.runtime_journal.load_manifest(state.session_id)
            pending_run_id = str(manifest.get("pending_commit_run_id") or "")
            if pending_run_id:
                self.runtime_journal.quarantine_pending_commit(
                    state.session_id,
                    pending_run_id,
                    reason=f"history rewrite committed: {operation}",
                    committed_messages=self.chat_storage.get_messages(state.session_id),
                )
            self.runtime_journal.update_manifest(
                state.session_id,
                {
                    "sqlite_messages_hash": result.get("messages_hash") or "",
                    "history_rewrite_revision": state.chat_save_revision,
                    "history_rewrite_operation": str(operation or "rewrite"),
                    "history_rewrite_at": time.time(),
                },
            )
        except Exception as exc:
            result["post_commit_error"] = str(exc)
            self.append_log(
                f"历史已写入 SQLite，但运行状态更新失败"
                f"({state.session_id}, operation={operation}): {exc}"
            )
            self._show_conversation_notice(
                state,
                f"消息已保存，但运行状态更新失败：{exc}",
                "error",
            )
        log_ui_navigation(
            "history_rewrite_persisted",
            session_id=state.session_id,
            operation=str(operation or "rewrite"),
            revision=state.chat_save_revision,
            previous_messages_hash=str(result.get("previous_messages_hash") or ""),
            messages_hash=str(result.get("messages_hash") or ""),
            message_count=int(result.get("message_count") or 0),
        )
        return result

    def edit_user_message_inline(self, session_id, message_id, edited_text):
        session_id = str(session_id or "").strip()
        message_id = str(message_id or "").strip()
        if not session_id or not message_id:
            return False
        state = self.get_session(session_id)
        allowed, message = self._can_rewrite_session_from_message(state)
        if not allowed:
            self._show_conversation_notice(state, message, "warning")
            return False
        source_message = self._find_message_by_id(getattr(state, "messages", []), message_id)
        if not isinstance(source_message, dict) or (source_message.get("role") or "") != "user":
            self._show_conversation_notice(state, "只能编辑用户消息。", "warning")
            return False

        edited_text = str(edited_text or "").strip()
        prompt_files = self._message_attachment_paths(source_message)
        if not edited_text and not prompt_files:
            self._show_conversation_notice(state, "消息内容不能为空。", "warning")
            return False

        self.save_chat_history(session_id=session_id, flush=True)
        rewrite_guard = self._history_rewrite_guard(state)
        messages = list(getattr(state, "messages", []) or [])
        target_index = next(
            (index for index, item in enumerate(messages) if str(item.get("id") or "").strip() == message_id),
            -1,
        )
        if target_index < 0:
            self._show_conversation_notice(state, "找不到要编辑的消息。", "warning")
            return False
        downstream_count = max(0, len(messages) - target_index - 1)
        log_ui_navigation(
            "history_edit_begin",
            session_id=session_id,
            downstream_count=downstream_count,
            attachment_count=len(prompt_files),
        )
        log_ui_navigation(
            "history_rewrite_start",
            session_id=session_id,
            message_id=message_id,
            target_index=target_index,
            downstream_count=downstream_count,
        )
        if downstream_count:
            dialog = ProductMessageDialog(
                "从这里重新生成？",
                f"这会替换此消息之后的 {downstream_count} 条消息；已经生成的工作区文件不会删除。",
                tone="destructive",
                buttons=[
                    ("取消", QMessageBox.No, "secondary", False),
                    ("替换并重新生成", QMessageBox.Yes, "danger", True),
                ],
                parent=self,
            )
            if dialog.exec_result(QMessageBox.No) != QMessageBox.Yes:
                return False
        try:
            rewrite_snapshot = self._capture_history_rewrite(state, message_id)
        except Exception as exc:
            self._show_conversation_notice(state, str(exc), "error")
            log_ui_navigation(
                "history_rewrite_index_error",
                session_id=session_id,
                message_id=message_id,
                error=str(exc),
            )
            return False
        log_ui_navigation(
            "history_rewrite_snapshot_ready",
            session_id=session_id,
            detached_widget_count=len(rewrite_snapshot.get("widgets") or []),
            target_index=target_index,
        )
        self._truncate_rewrite_state(state, target_index)
        log_ui_navigation(
            "history_rewrite_downstream_detached",
            session_id=session_id,
            retained_message_count=len(state.messages),
            downstream_count=downstream_count,
        )
        log_ui_navigation("history_rewrite_submit_started", session_id=session_id, target_index=target_index)
        state.last_history_rewrite_committed = False
        try:
            submitted = self._submit_session_request(
                state,
                edited_text,
                prompt_files,
                check_duplicates=False,
                clear_current_input=False,
                user_message_meta={"edited": True},
                history_rewrite_guard=rewrite_guard,
            )
        except Exception as exc:
            submitted = False
            self._show_conversation_notice(
                state,
                f"消息修改失败：{exc}",
                "error",
            )
        if not submitted:
            if getattr(state, "last_history_rewrite_committed", False):
                self._commit_history_rewrite(rewrite_snapshot)
                self.refresh_history_list()
                log_ui_navigation(
                    "history_edit_committed_run_not_started",
                    session_id=session_id,
                    downstream_count=downstream_count,
                )
                return False
            self._restore_history_rewrite(state, rewrite_snapshot)
            self._show_conversation_notice(state, "消息未修改，请重试。", "warning")
            log_ui_navigation("history_edit_failed", session_id=session_id, downstream_count=downstream_count)
            log_ui_navigation("history_rewrite_rolled_back", session_id=session_id, target_index=target_index)
            return False
        removed_agent_ids = {
            str(agent.get("id") or "")
            for agent in (rewrite_snapshot.get("persisted_agents") or [])
            if str(agent.get("id") or "")
        } - {
            str(agent.get("id") or "")
            for agent in state.persisted_agents
            if str(agent.get("id") or "")
        }
        for agent_id in removed_agent_ids:
            self.chat_storage.delete_agent(agent_id, hard=True)
        self._commit_history_rewrite(rewrite_snapshot)
        edited_message_id = str((state.messages[-1] if state.messages else {}).get("id") or "")
        edited_node = state.render_node_by_message_id.get(edited_message_id)
        edited_widget = (edited_node or {}).get("widget") if isinstance(edited_node, dict) else None
        if isinstance(edited_widget, ChatBubble):
            edited_widget.mark_edited()
        elif edited_widget is not None:
            for bubble in edited_widget.findChildren(ChatBubble):
                if bubble.role == "User" and bubble.source_message_id == edited_message_id:
                    bubble.mark_edited()
                    break
        QTimer.singleShot(
            0,
            lambda s=state, snap=rewrite_snapshot, mid=edited_message_id: self._restore_rewrite_viewport(s, snap, mid),
        )
        self.refresh_history_list()
        log_ui_navigation("history_edit_done", session_id=session_id, downstream_count=downstream_count)
        log_ui_navigation(
            "history_rewrite_committed",
            session_id=session_id,
            target_index=target_index,
            retained_message_count=len(state.messages),
        )
        return True

    def delete_user_message_in_place(self, session_id, message_id):
        session_id = str(session_id or "").strip()
        message_id = str(message_id or "").strip()
        if not session_id or not message_id:
            return False
        state = self.get_session(session_id)
        allowed, message = self._can_rewrite_session_from_message(state)
        if not allowed:
            self.add_system_toast(message, "warning", session_id=session_id, auto_close_ms=3200)
            return False
        source_message = self._find_message_by_id(getattr(state, "messages", []), message_id)
        if not isinstance(source_message, dict) or (source_message.get("role") or "") != "user":
            self.add_system_toast("只能删除用户消息。", "warning", session_id=session_id, auto_close_ms=3200)
            return False

        confirm = QMessageBox.question(
            self,
            "确认删除消息",
            "仅删除这条用户消息，后续内容会保留。是否继续？",
        )
        if confirm != QMessageBox.Yes:
            return False

        self.save_chat_history(session_id=session_id, flush=True)
        rewrite_guard = self._history_rewrite_guard(state)
        messages = list(getattr(state, "messages", []) or [])
        target_index = next(
            (
                index for index, item in enumerate(messages)
                if str(item.get("id") or "").strip() == message_id
            ),
            -1,
        )
        remaining_messages = [
            item for item in messages
            if str(item.get("id") or "").strip() != message_id
        ]
        if len(remaining_messages) == len(messages):
            self.add_system_toast("找不到要删除的消息。", "warning", session_id=session_id, auto_close_ms=3200)
            return False
        node = (state.render_node_by_message_id or {}).get(message_id)
        widget = (node or {}).get("widget") if isinstance(node, dict) else None
        top_level = self._top_level_chat_widget(state, widget) if widget is not None else None
        layout_index = state.chat_layout.indexOf(top_level) if top_level is not None else -1
        if layout_index < 0:
            message = "无法定位消息界面，请重新打开会话后重试。"
            self.add_system_toast(message, "error", session_id=session_id, auto_close_ms=5000)
            log_ui_navigation(
                "history_rewrite_index_error",
                session_id=session_id,
                message_id=message_id,
                operation="delete",
            )
            return False
        log_ui_navigation(
            "history_rewrite_start",
            session_id=session_id,
            message_id=message_id,
            target_index=target_index,
            operation="delete",
        )
        state.chat_layout.removeWidget(top_level)
        top_level.hide()
        original_render_items = copy.deepcopy(state.render_items)
        original_displayed_render_count = int(state.displayed_render_count or 0)
        original_render_nodes = {
            key: dict(value) for key, value in state.render_nodes.items()
        }
        original_render_node_by_message_id = {
            key: original_render_nodes.get(str(value.get("key") or ""), value)
            for key, value in state.render_node_by_message_id.items()
        }
        original_history_office_cards = list(state.history_office_cards)
        state.history_office_cards = [
            card for card in state.history_office_cards if card is not top_level
        ]
        state.messages = self.chat_storage.normalize_messages(
            copy.deepcopy(remaining_messages),
            conversation_id=state.session_id,
        )
        affected_message_ids = list((node or {}).get("message_ids") or [message_id])
        for affected_id in affected_message_ids:
            state.render_node_by_message_id.pop(str(affected_id), None)
        state.render_nodes.pop(str((node or {}).get("key") or ""), None)
        message_positions = {
            str(message.get("id") or ""): index
            for index, message in enumerate(state.messages)
            if str(message.get("id") or "")
        }
        for existing in state.render_nodes.values():
            positions = [
                message_positions[mid]
                for mid in existing.get("message_ids") or []
                if mid in message_positions
            ]
            if positions:
                existing["start"] = min(positions)
                existing["end"] = max(positions) + 1
        self._rebuild_session_render_spans(state)
        state.displayed_render_count = min(state.displayed_render_count, len(state.render_items))
        replacement_widget_count = 0
        if len(affected_message_ids) > 1:
            replacement_span = next(
                (
                    span for span in state.render_items
                    if int(span.get("start") or 0) <= target_index < int(span.get("end") or 0)
                ),
                None,
            )
            if replacement_span is not None:
                replacement_widget_count = int(
                    self._render_session_history_spans(
                        state,
                        [replacement_span],
                        insert_index=layout_index,
                    ) or 0
                )
        try:
            self._persist_history_rewrite(
                state,
                rewrite_guard,
                operation="delete_message",
            )
        except Exception as exc:
            state.messages = messages
            for _ in range(replacement_widget_count):
                item = state.chat_layout.takeAt(layout_index)
                replacement = item.widget() if item is not None else None
                if replacement is not None:
                    replacement.deleteLater()
            state.chat_layout.insertWidget(layout_index, top_level)
            top_level.show()
            state.render_items = original_render_items
            state.displayed_render_count = original_displayed_render_count
            state.render_nodes = original_render_nodes
            state.render_node_by_message_id = original_render_node_by_message_id
            state.history_office_cards = original_history_office_cards
            self.add_system_toast(
                f"删除消息失败：{exc}",
                "error",
                session_id=session_id,
                auto_close_ms=5000,
            )
            log_ui_navigation(
                "history_rewrite_rolled_back",
                session_id=session_id,
                message_id=message_id,
                operation="delete",
                error=str(exc),
            )
            return False
        top_level.deleteLater()
        log_ui_navigation(
            "history_rewrite_committed",
            session_id=session_id,
            message_id=message_id,
            target_index=target_index,
            operation="delete",
        )
        self.refresh_history_list()
        self.add_system_toast("已删除消息，后续内容保持不变。", "success", session_id=session_id, auto_close_ms=3200)
        if hasattr(self, "input_field") and self.input_field:
            self.input_field.setFocus()
        return True

    def show_prompt_tool_menu(self):
        existing = getattr(self, "composer_action_popover", None)
        if existing and _qt_object_alive(existing) and existing.isVisible():
            existing.close()
            return
        if existing and _qt_object_alive(existing):
            existing.close()
        popover = ComposerActionPopover(self, self)
        self.composer_action_popover = popover
        self.tool_menu_btn.setChecked(True)

        def restore():
            self.tool_menu_btn.setChecked(False)
            if self.input_field.isEnabled():
                QTimer.singleShot(0, self.input_field.setFocus)

        popover.closed.connect(restore)
        popover.destroyed.connect(
            lambda _obj=None, current=popover: setattr(
                self,
                "composer_action_popover",
                None,
            ) if getattr(self, "composer_action_popover", None) is current else None
        )
        popover.show_for(self.tool_menu_btn, prefer_above=True)

    def show_app_variable_insert_menu(self):
        state = self.get_current_session()
        if not state or not self.input_field.isEnabled():
            return
        try:
            variables = self.config_manager.list_app_variables(kind=VARIABLE_KIND_TEXT)
        except Exception as exc:
            self.add_system_toast(f"变量读取失败：{exc}", "error", session_id=state.session_id)
            return
        if not variables:
            self.add_system_toast("暂无可插入的普通变量", "info", session_id=state.session_id)
            return
        menu = QMenu(self)
        for variable in variables:
            action = menu.addAction(str(variable.get("name") or "变量"))
            description = str(variable.get("description") or "").strip()
            if description:
                action.setToolTip(description)
            action.setData(str(variable.get("id") or ""))
            action.triggered.connect(
                lambda _checked=False, variable_id=str(variable.get("id") or ""): self.insert_app_variable(variable_id)
            )
        menu.popup(self.tool_menu_btn.mapToGlobal(QPoint(0, -menu.sizeHint().height())))

    def insert_app_variable(self, variable_id):
        state = self.get_current_session()
        if not state:
            return False
        try:
            value = self.config_manager.get_variable_store().get_text_by_id(variable_id)
        except Exception as exc:
            self.add_system_toast(f"插入失败：{exc}", "error", session_id=state.session_id)
            return False
        cursor = self.input_field.textCursor()
        cursor.insertText(value)
        self.input_field.setTextCursor(cursor)
        self.input_field.setFocus()
        return True

    def save_composer_as_favorite(self):
        state = self.get_current_session()
        if not state:
            return False
        prompt = self.input_field.toPlainText().strip()
        skills = normalize_selected_skill_names(getattr(state, "selected_skill_names", []))
        if not prompt and not skills:
            self.add_system_toast("请先输入提示词或指定能力", "info", session_id=state.session_id)
            return False
        source = self._session_workspace_source(state)
        workspace_dir = self._workspace_dir_for_state(state) if source == "project" else ""
        first_line = re.sub(r"\s+", " ", prompt.splitlines()[0] if prompt else "").strip()
        name = first_line[:36] if first_line else f"{len(skills)} 个能力组合"
        prefill = {
            "name": name,
            "prompt": prompt,
            "skill_names": skills,
            "execution_mode": FAVORITE_EXECUTION_WORKSPACE if workspace_dir else FAVORITE_EXECUTION_CHAT,
            "workspace_dir": workspace_dir,
        }
        if not self.show_product_page(self.PAGE_FAVORITES):
            return False
        return self.show_favorite_editor(prefill=prefill)

    def _model_id_for_state(self, state=None):
        state = state or self.get_current_session()
        model_id = str(getattr(state, "selected_model_id", "") or "").strip() if state else ""
        if model_id:
            return model_id
        meta = getattr(state, "persisted_conversation_meta", {}) if state else {}
        if isinstance(meta, dict):
            model_id = str(meta.get("selected_model_id") or "").strip()
            if model_id:
                return model_id
        try:
            return self.config_manager.get_selected_model_id()
        except Exception:
            return ""

    def _model_profile_for_state(self, state=None, model_id=None):
        selected_model_id = str(model_id or self._model_id_for_state(state) or "").strip()
        try:
            profiles = list(self.config_manager.iter_model_profiles() or [])
        except Exception:
            profiles = []
        if selected_model_id:
            profile = next((item for item in profiles if item.get("id") == selected_model_id), None)
            if isinstance(profile, dict):
                return profile
            if not profiles:
                try:
                    profile = self.config_manager.get_model_profile(selected_model_id)
                except Exception:
                    profile = None
                return profile if isinstance(profile, dict) else {}
            return {}
        try:
            profile = self.config_manager.get_model_profile()
        except Exception:
            profile = None
        return profile if isinstance(profile, dict) else {}

    def _model_profile_snapshot_for_state(self, state=None, model_id=None):
        profile = copy.deepcopy(self._model_profile_for_state(state, model_id=model_id))
        if not isinstance(profile, dict):
            profile = {}
        effort = self._selected_reasoning_effort(state, model_id=model_id)
        if effort:
            profile["reasoning_effort"] = effort
            profile["deepseek_reasoning_effort"] = effort
        return profile

    def _set_session_model_id(self, state, model_id):
        model_id = str(model_id or "").strip()
        if not state or not model_id:
            return False
        profile = self._model_profile_for_state(state, model_id=model_id)
        if not profile:
            return False
        state.selected_model_id = str(profile.get("id") or model_id)
        meta = copy.deepcopy(getattr(state, "persisted_conversation_meta", {}) or {})
        meta["selected_model_id"] = state.selected_model_id
        state.persisted_conversation_meta = meta
        return True

    def _default_model_id_for_new_session(self):
        return self.config_manager.get_selected_model_id()

    def refresh_model_selector(self):
        if not hasattr(self, "model_select_btn"):
            return
        state = self.get_current_session()
        selected_id = self._model_id_for_state(state)
        profiles = list(self.config_manager.iter_model_profiles() or [])
        selected = next((item for item in profiles if item.get("id") == selected_id), None)
        effort_labels = {
            "low": "low",
            "medium": "medium",
            "high": "high",
            "xhigh": "xhigh",
            "max": "max",
        }
        efforts = normalize_reasoning_efforts((selected or {}).get("reasoning_efforts"))
        current_effort = normalize_reasoning_effort((selected or {}).get("reasoning_effort"), efforts)
        self.model_select_btn.setMenu(None)
        if selected:
            display_name = selected.get("display_name") or selected.get("model_name") or "模型"
            channel_name = selected.get("channel_display_name") or selected.get("provider_display_name") or selected.get("provider") or ""
            label = f"{channel_name} / {display_name}" if channel_name else display_name
            if is_recommended_model(
                selected.get("model_name"),
                selected.get("provider_type") or selected.get("provider"),
                selected.get("base_url"),
            ):
                label += " · 推荐"
            label += f" · {effort_labels.get(current_effort, current_effort) if current_effort else '标准'}"
            self.model_select_btn.setText(label)
            self.model_select_btn.setToolTip(label)
        elif selected_id:
            self.model_select_btn.setText("模型不可用")
            self.model_select_btn.setToolTip("当前对话选择的模型已不存在，请重新选择。")
        else:
            self.model_select_btn.setText("未配置模型")

    def show_model_selector_popover(self):
        profiles = list(self.config_manager.iter_model_profiles() or [])
        if not profiles:
            self.add_system_toast("还没有可用模型，请先在设置中添加。", "warning", auto_close_ms=4000)
            return
        existing = getattr(self, "model_selector_popover", None)
        if existing and _qt_object_alive(existing) and existing.isVisible():
            existing.close()
            return
        popover = ModelSelectorPopover(profiles, self._model_id_for_state(self.get_current_session()), self)
        self.model_selector_popover = popover

        def select_model(model_id):
            self.on_model_selection_changed(model_id)
            popover.profiles = list(self.config_manager.iter_model_profiles() or [])
            popover.set_selected_model(self._model_id_for_state(self.get_current_session()))

        def select_effort(effort):
            self.on_reasoning_effort_selected(effort)
            popover.profiles = list(self.config_manager.iter_model_profiles() or [])
            popover.set_selected_model(self._model_id_for_state(self.get_current_session()))

        popover.modelSelected.connect(select_model)
        popover.effortSelected.connect(select_effort)
        popover.closed.connect(lambda: QTimer.singleShot(0, self.input_field.setFocus))
        popover.show_for(self.model_select_btn, align_right=True, prefer_above=True)
        QTimer.singleShot(0, popover.search_input.setFocus)

    def on_model_selection_changed(self, model_id):
        state = self.get_current_session()
        previous_model_id = self._model_id_for_state(state)
        requested_model_id = str(model_id or "").strip()
        if requested_model_id and requested_model_id == previous_model_id:
            log_ui_navigation(
                "model_switch",
                session_id=str(getattr(state, "session_id", "") or ""),
                previous_model_id=previous_model_id,
                selected_model_id=requested_model_id,
                outcome="unchanged",
                notice_shown=False,
            )
            self.refresh_model_selector()
            return True
        if requested_model_id and self._set_session_model_id(state, requested_model_id):
            self.save_chat_history(session_id=state.session_id)
            self.refresh_model_selector()
            self.refresh_context_badges()
            notice_shown = self._session_has_visible_conversation(state)
            if notice_shown:
                self._append_model_switch_notice(state)
            log_ui_navigation(
                "model_switch",
                session_id=str(getattr(state, "session_id", "") or ""),
                previous_model_id=previous_model_id,
                selected_model_id=requested_model_id,
                outcome="changed",
                notice_shown=notice_shown,
            )
            return True
        log_ui_navigation(
            "model_switch",
            session_id=str(getattr(state, "session_id", "") or ""),
            previous_model_id=previous_model_id,
            selected_model_id=requested_model_id,
            outcome="failed",
            notice_shown=False,
        )
        self.add_system_toast("模型切换失败，已保留原选择。", "error", auto_close_ms=5000)
        self.refresh_model_selector()
        return False

    @staticmethod
    def _session_has_visible_conversation(state):
        for message in getattr(state, "messages", []) or []:
            if not isinstance(message, dict) or message.get("role") not in {"user", "assistant"}:
                continue
            meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
            if not meta.get("hidden") and not meta.get("ui_only"):
                return True
        return False

    def _append_model_switch_notice(self, state):
        if state is None or getattr(state, "chat_layout", None) is None:
            raise RuntimeError("模型切换提示缺少会话布局，无法显示。")
        notice = ModelSwitchInlineNotice()
        state.chat_layout.insertWidget(max(0, state.chat_layout.count() - 1), notice)
        self.request_session_scroll_to_bottom(state.session_id, force=False)
        return notice

    def on_reasoning_effort_selected(self, effort):
        model_id = self._model_id_for_state(self.get_current_session())
        if self.config_manager.set_model_reasoning_effort(model_id, effort):
            self.refresh_model_selector()
            return True
        self.add_system_toast("思考强度更新失败，已保留原选择。", "error", auto_close_ms=5000)
        self.refresh_model_selector()
        return False

    def _selected_reasoning_effort(self, state=None, model_id=None):
        profile = self._model_profile_for_state(state, model_id=model_id)
        if not isinstance(profile, dict):
            return ""
        efforts = normalize_reasoning_efforts(profile.get("reasoning_efforts"))
        return normalize_reasoning_effort(profile.get("reasoning_effort"), efforts)

    def update_ui_state_for_workspace(self):
        if self.workspace_dir:
            self.input_field.setEnabled(True)
            self.input_field.setPlaceholderText("例如：把这个文件夹里的图片按日期分类")
            self.action_btn.setEnabled(True)
            self.ws_label.setStyleSheet(f"color: {DesignTokens.success_text}; font-weight: 600;")
        else:
            # Keep input enabled but change placeholder to guide user
            self.input_field.setPlaceholderText("📁 先选择或拖拽一个文件夹到这里...")
            # Disable send button
            self.action_btn.setEnabled(False)
            self.ws_label.setStyleSheet(f"color: {DesignTokens.text_secondary}; font-weight: 500;")

        self.refresh_context_badges()

    def update_ui_state_for_workspace(self):
        if self.workspace_dir:
            self.input_field.setEnabled(True)
            self.input_field.setPlaceholderText("描述你要完成的任务，例如：整理本周截图并生成周报摘要")
            self.action_btn.setEnabled(True)
            self.ws_label.setStyleSheet(apple_inline_project_chip_style(True))
        else:
            self.input_field.setEnabled(True)
            self.input_field.setPlaceholderText("直接开始聊天；需要处理文件时再连接项目")
            self.action_btn.setEnabled(True)
            self.ws_label.setStyleSheet(apple_inline_project_chip_style(False))
            self.ws_label.setText("未连接项目 · 聊天")
        self.refresh_project_selector()
        self.refresh_context_badges()

    def refresh_context_badges(self, session_id=None):
        state = self.get_session(session_id)
        if hasattr(self, "knowledge_refs_button"):
            references = getattr(state, "knowledge_refs", []) if state else []
            self.knowledge_refs_button.setVisible(bool(references))
            self.knowledge_refs_button.setText(f"资料 · {len(references)}")
            self.knowledge_refs_button.setIcon(qta.icon("fa5s.book-open", color=DesignTokens.icon_secondary))
            self.knowledge_refs_button.setToolTip("\n".join(ref.get("title", "") for ref in references))
            self.knowledge_refs_button.setStyleSheet(apple_button_style("ghost", radius=DesignTokens.radius_sm))
        profile = self._model_profile_for_state(state)
        provider_text = profile.get("provider_display_name") if profile else self.config_manager.get("llm_provider", "openai")
        model_name = profile.get("display_name") or profile.get("model_name") if profile else self.config_manager.get("model_name", DEFAULT_DEEPSEEK_MODEL)
        if getattr(self, "daemon_available", False):
            connection_text = "Daemon Ready"
        elif getattr(self, "daemon_bootstrapping", False):
            connection_text = "Connecting"
        else:
            connection_text = "Local Agent"
        self.model_badge.setText(f"{provider_text} | {model_name} | {connection_text}")

        if self.config_manager.get_god_mode():
            self.security_badge.setText("Extended Access")
            self.security_badge.setStyleSheet(
                f"background: {DesignTokens.warning_bg}; color: {DesignTokens.warning_text}; "
                f"border-radius: 12px; padding: 4px 10px; font-size: 11px; font-weight: 600;"
            )
        else:
            self.security_badge.setText("Workspace Only")
            self.security_badge.setStyleSheet(
                f"background: {DesignTokens.success_bg}; color: {DesignTokens.success_text}; "
                f"border-radius: 12px; padding: 4px 10px; font-size: 11px; font-weight: 600;"
            )

        phase = "Idle"
        if state:
            phase = getattr(state, "run_phase", "Idle") or "Idle"
            if int(getattr(state, "provider_retry_attempt", 0) or 0) > 0:
                phase = (
                    f"正在重试 {int(state.provider_retry_attempt)}/"
                    f"{int(state.provider_retry_max or state.provider_retry_attempt)}"
                )
        self.phase_badge.setText(f"状态：{display_run_phase(phase)}")

        has_workspace = bool(self._workspace_dir_for_state(state))
        has_clarify_context = bool(
            state
            and bool(getattr(state, "pending_clarify_questions", []))
        )
        has_observability_context = bool(
            state
            and (
                getattr(state, "observability_events", [])
                or getattr(state, "system_prompt_text", "")
                or getattr(state, "system_prompt_appends", [])
            )
        )
        has_context = bool(state and (state.step_records or state.has_file_changes or has_clarify_context or has_observability_context))
        self.context_available_tabs = set()
        if has_workspace:
            self.context_available_tabs.add(self.RIGHT_TAB_FILES)
            self.context_available_tabs.add(self.RIGHT_TAB_DELIVERABLES)
        if has_observability_context or has_context:
            self.context_available_tabs.add(self.RIGHT_TAB_OBSERVABILITY)
        if state and (getattr(state, "sub_agent_events", []) or getattr(state, "persisted_agents", [])):
            self.context_available_tabs.add(self.RIGHT_TAB_SUB_AGENTS)
        self.update_context_rail_badges()
        if state and state.session_id == self.current_session_id:
            self.refresh_clarify_controls(state.session_id)

    def _extract_pending_clarify_questions_from_args(self, args_obj):
        if not isinstance(args_obj, dict):
            return []
        return normalize_pending_clarify_questions(args_obj.get("questions"))

    def _session_clarify_meta(self, state):
        if not state:
            return {}
        return {
            "clarify_mode_enabled": False,
            "clarify_phase": normalize_clarify_phase(
                getattr(state, "clarify_phase", ""),
                default=derive_clarify_phase(
                    bool(getattr(state, "pending_clarify_questions", [])),
                    getattr(state, "clarify_mode_state", CLARIFY_MODE_EXPLORING),
                ),
            ),
            "clarify_mode_state": normalize_clarify_phase(
                getattr(state, "clarify_mode_state", CLARIFY_MODE_EXPLORING),
                default=CLARIFY_MODE_EXPLORING,
            ),
            "pending_clarify_questions": normalize_pending_clarify_questions(
                getattr(state, "pending_clarify_questions", [])
            ),
            "grill_mode_state": normalize_grill_mode_state(
                getattr(state, "grill_mode_state", GRILL_MODE_DISABLED)
            ),
            "grill_round_count": min(
                GRILL_MAX_ROUNDS,
                max(0, int(getattr(state, "grill_round_count", 0) or 0)),
            ),
            "grill_cycle_count": max(0, int(getattr(state, "grill_cycle_count", 0) or 0)),
            "grill_execution_confirmed": bool(
                getattr(state, "grill_execution_confirmed", False)
            ),
        }

    def _session_selected_skills_meta(self, state):
        if not state:
            return {}
        return {
            "selected_skill_names": normalize_selected_skill_names(
                getattr(state, "selected_skill_names", [])
            )
        }

    def _ppt_tasks_for_state(self, state):
        if not state:
            return {}
        meta = copy.deepcopy(getattr(state, "persisted_conversation_meta", {}) or {})
        tasks = meta.get("ppt_tasks_v1")
        if not isinstance(tasks, dict):
            tasks = {}
        meta["ppt_tasks_v1"] = tasks
        state.persisted_conversation_meta = meta
        return tasks

    def _ppt_task_for_state(self, state, task_id=None):
        task_id = str(task_id or getattr(state, "ppt_agent_task_id", "") or "").strip()
        if not task_id:
            return {}
        task = self._ppt_tasks_for_state(state).get(task_id)
        return copy.deepcopy(task) if isinstance(task, dict) else {}

    def _update_ppt_task_checkpoint(self, state, task_id, *, persist=False, **patch):
        task_id = str(task_id or "").strip()
        if not state or not task_id:
            raise ValueError("PPT 任务检查点缺少 task_id。")
        tasks = self._ppt_tasks_for_state(state)
        record = copy.deepcopy(tasks.get(task_id) or {})
        record.update(copy.deepcopy(patch))
        record.update({"task_id": task_id, "updated_at": time.time()})
        tasks[task_id] = record
        meta = copy.deepcopy(getattr(state, "persisted_conversation_meta", {}) or {})
        meta["ppt_tasks_v1"] = tasks
        state.persisted_conversation_meta = meta
        state.ppt_agent_task_id = task_id
        log_chat_runtime_debug(
            "ppt_task_checkpoint",
            session_id=state.session_id,
            task_id=task_id,
            task_stage=str(record.get("stage") or ""),
            status=str(record.get("status") or ""),
            validation_round=int(record.get("validation_round") or 0),
            next_action=str(record.get("next_action") or ""),
            persist=bool(persist),
        )
        if persist and not self.save_chat_history(session_id=state.session_id, flush=True):
            raise RuntimeError("PPT 任务检查点无法安全写入会话记录。")
        return record

    def _ppt_task_file_snapshot(self, path):
        value = str(path or "").strip()
        normalized = os.path.normpath(value) if value else ""
        if not normalized or not os.path.isfile(normalized):
            return {"path": normalized, "sha256": ""}
        return {"path": normalized, "sha256": sha256_file(normalized)}

    def _restore_ppt_task_state(self, state, task):
        if not state or not isinstance(task, dict):
            return
        state.ppt_agent_mode = True
        state.ppt_agent_output_format = PPT_AGENT_OUTPUT_PPTX
        state.ppt_agent_task_id = str(task.get("task_id") or "")
        state.ppt_agent_run_id = str(task.get("ppt_agent_run_id") or "")
        state.ppt_agent_template_file = str(task.get("template_file") or "")
        state.ppt_agent_template_hash = str(task.get("template_hash") or "")
        state.ppt_agent_template_screenshots = list(task.get("template_screenshots") or [])
        state.ppt_agent_renderer = str(task.get("renderer") or RENDERER_NONE)
        state.ppt_agent_renderer_prog_id = str(task.get("renderer_prog_id") or "")
        state.ppt_agent_task_model_id = str(task.get("task_model_id") or "")
        state.ppt_agent_validation_round = int(task.get("validation_round") or 0)
        state.ppt_agent_visual_status = str(task.get("visual_status") or "")
        state.ppt_agent_verification_level = str(task.get("verification_level") or "")
        pptx_file = task.get("pptx") if isinstance(task.get("pptx"), dict) else {}
        state.ppt_agent_result_file = str(pptx_file.get("path") or "")
        if state.ppt_agent_result_file:
            self._sync_office_task_card_paths(state, [state.ppt_agent_result_file])

    def _is_office_workflow_enabled(self, state):
        return bool(getattr(state, "office_draft_preview_pending", False))

    def _is_office_workflow_context(self, workflow_mode):
        return normalize_workflow_mode(workflow_mode) in {
            WORKFLOW_MODE_OFFICE_HTML_FIRST,
            WORKFLOW_MODE_OFFICE_FILE_CONVERSION,
        }

    def _message_is_office_draft_request(self, message):
        if not isinstance(message, dict):
            return False
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        return self._is_office_workflow_context(meta.get("workflow_mode"))

    def _office_profile_label_from_message(self, message):
        if not isinstance(message, dict):
            return self._office_profile_label(OFFICE_OUTPUT_PROFILE_FREE)
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        if normalize_workflow_mode(meta.get("workflow_mode")) == WORKFLOW_MODE_OFFICE_FILE_CONVERSION:
            target = str(meta.get("office_conversion_target") or "").strip().upper()
            return target or "办公文件"
        return self._office_profile_label(meta.get("office_output_profile"))

    def _office_target_format_from_message(self, message):
        if not isinstance(message, dict):
            return "html"
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        if normalize_workflow_mode(meta.get("workflow_mode")) == WORKFLOW_MODE_OFFICE_FILE_CONVERSION:
            target = str(meta.get("office_conversion_target") or "").strip().lower()
            return target if target in {"pptx", "docx", "pdf"} else "file"
        if bool(meta.get("ppt_agent_mode")):
            target = normalize_ppt_agent_output_format(meta.get("ppt_agent_output_format"))
            return target
        return "html"

    def _current_model_process_label(self, state=None, run_context=None):
        profile = {}
        selected_model_id = ""
        if isinstance(run_context, dict):
            snapshot = run_context.get("selected_model_profile")
            if isinstance(snapshot, dict):
                profile = snapshot
            selected_model_id = str(run_context.get("selected_model_id") or profile.get("id") or "").strip()
        if not profile:
            selected_model_id = self._model_id_for_state(state)
            profile = self._model_profile_for_state(state, selected_model_id)
        if not isinstance(profile, dict):
            profile = {}
        model_name = profile.get("display_name") or profile.get("model_name") or selected_model_id or "当前模型"
        channel_name = profile.get("channel_display_name") or profile.get("provider_display_name") or profile.get("provider") or ""
        label = f"{channel_name} / {model_name}" if channel_name else model_name
        return label, selected_model_id

    def _office_message_attachment_count(self, message):
        if not isinstance(message, dict):
            return 0
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        attachments = meta.get("attachments") if isinstance(meta.get("attachments"), list) else []
        if attachments:
            return len(attachments)
        content_parts = message.get("content_parts") if isinstance(message.get("content_parts"), list) else []
        file_count = 0
        for part in content_parts:
            if isinstance(part, dict) and str(part.get("type") or "").lower() in {"file", "input_file", "document"}:
                file_count += 1
        return file_count

    def _initialize_office_task_process(self, card, state, message=None, prompt_files=None, run_context=None, runtime_note=""):
        if card is None or getattr(card, "_process_initialized", False):
            log_chat_runtime_debug(
                "office_process_init_skipped",
                session_id=getattr(state, "session_id", ""),
                has_card=card is not None,
                already_initialized=bool(getattr(card, "_process_initialized", False)) if card is not None else False,
            )
            return
        setattr(card, "_process_initialized", True)
        meta = message.get("meta") if isinstance(message, dict) and isinstance(message.get("meta"), dict) else {}
        workflow_mode = normalize_workflow_mode(meta.get("workflow_mode") or (run_context or {}).get("workflow_mode"))
        ppt_agent_mode = bool(meta.get("ppt_agent_mode") or (run_context or {}).get("ppt_agent_mode"))
        log_chat_runtime_debug(
            "office_process_init_begin",
            session_id=getattr(state, "session_id", ""),
            workflow_mode=workflow_mode,
            ppt_agent_mode=ppt_agent_mode,
            prompt_file_count=len(prompt_files or []),
            runtime_note=runtime_note,
            message_role=message.get("role") if isinstance(message, dict) else "",
        )
        if ppt_agent_mode:
            selected_strategy = normalize_ppt_agent_strategy(
                meta.get("ppt_agent_selected_strategy")
                or (run_context or {}).get("ppt_agent_selected_strategy")
                or PPT_AGENT_STRATEGY_DEFAULT
            )
            ok, skill_name, status_message = self._ppt_agent_skill_status(selected_strategy)
            if not ok:
                card.add_process_note(status_message, tone="error")
        card._sync_process_placeholder()
        log_chat_runtime_debug(
            "office_process_init_done",
            session_id=getattr(state, "session_id", ""),
            process_widget_count=card.process_widget_count(),
            placeholder_visible=not card.process_placeholder.isHidden(),
        )
        self._schedule_office_task_process_bootstrap_check(state)

    def _schedule_office_task_process_bootstrap_check(self, state):
        if not state or getattr(state, "_office_process_bootstrap_check_pending", False):
            log_chat_runtime_debug(
                "office_process_bootstrap_check_skipped",
                session_id=getattr(state, "session_id", "") if state else "",
                pending=bool(getattr(state, "_office_process_bootstrap_check_pending", False)) if state else False,
            )
            return
        state._office_process_bootstrap_check_pending = True
        log_chat_runtime_debug(
            "office_process_bootstrap_check_scheduled",
            session_id=getattr(state, "session_id", ""),
            delay_ms=OFFICE_TASK_PROCESS_BOOTSTRAP_CHECK_MS,
        )
        QTimer.singleShot(
            OFFICE_TASK_PROCESS_BOOTSTRAP_CHECK_MS,
            lambda sid=getattr(state, "session_id", ""): self._ensure_office_task_process_visible(sid),
        )

    def _ensure_office_task_process_visible(self, session_id):
        state = self.get_session(session_id)
        if not state:
            log_chat_runtime_debug("office_process_bootstrap_missing_session", session_id=session_id)
            return
        state._office_process_bootstrap_check_pending = False
        if not getattr(state, "office_draft_preview_pending", False):
            log_chat_runtime_debug(
                "office_process_bootstrap_not_pending",
                session_id=session_id,
                office_draft_preview_pending=False,
            )
            return
        card = self._office_draft_card_for_state(state)
        if card is None or card.process_widget_count() > 0:
            log_chat_runtime_debug(
                "office_process_bootstrap_noop",
                session_id=session_id,
                has_card=card is not None,
                process_widget_count=card.process_widget_count() if card is not None else -1,
            )
            return
        log_chat_runtime_debug(
            "office_process_bootstrap_left_empty",
            session_id=session_id,
            process_widget_count=card.process_widget_count(),
        )

    def _create_office_draft_task_card(
        self,
        state,
        profile_label=None,
        insert_index=None,
        running=True,
        target_format=None,
        task_id="",
    ):
        if not state:
            return None
        card = OfficeDraftTaskCard(
            profile_label or self._office_profile_label(OFFICE_OUTPUT_PROFILE_FREE),
            target_format=target_format or getattr(state, "office_task_target_format", "html") or "html",
        )
        card.deliverablePathActivated.connect(
            lambda path, sid=state.session_id: self.open_deliverable_from_chat(path, sid)
        )
        card.ppt_task_id = str(task_id or "").strip()
        if running:
            card.set_running()
        if insert_index is not None:
            state.chat_layout.insertWidget(insert_index, card)
        else:
            state.chat_layout.insertWidget(state.chat_layout.count() - 1, card)
        state.office_draft_task_card = card
        if card.ppt_task_id:
            cards = getattr(state, "ppt_task_cards", None)
            if not isinstance(cards, dict):
                cards = {}
                state.ppt_task_cards = cards
            cards[card.ppt_task_id] = card
        log_chat_runtime_debug(
            "office_task_card_created",
            session_id=getattr(state, "session_id", ""),
            profile_label=profile_label or self._office_profile_label(OFFICE_OUTPUT_PROFILE_FREE),
            target_format=target_format or getattr(state, "office_task_target_format", "html") or "html",
            running=running,
            insert_index=insert_index,
            task_id=card.ppt_task_id,
        )
        if running:
            self._schedule_office_task_process_bootstrap_check(state)
        return card

    def _office_draft_card_for_state(self, state, task_id=""):
        task_id = str(task_id or "").strip()
        if task_id:
            card = (getattr(state, "ppt_task_cards", {}) or {}).get(task_id)
            if card is not None and _qt_object_alive(card):
                return card
        card = getattr(state, "office_draft_task_card", None)
        if card is not None and _qt_object_alive(card):
            return card
        return None

    def _ppt_task_id_from_message(self, message):
        if not isinstance(message, dict):
            return ""
        meta = message.get("meta") if isinstance(message.get("meta"), dict) else {}
        return str(meta.get("ppt_task_id") or "").strip()

    def _apply_ppt_task_card_state(self, state, card, task_id, *, restored=False):
        task = self._ppt_task_for_state(state, task_id)
        if card is None or not task:
            return False
        status = str(task.get("status") or "").strip().lower()
        pptx = task.get("pptx") if isinstance(task.get("pptx"), dict) else {}
        pptx_value = str(pptx.get("path") or "").strip()
        pptx_path = os.path.normpath(pptx_value) if pptx_value else ""
        if status == "completed" and pptx_path and os.path.isfile(pptx_path):
            card.set_completed([pptx_path])
            return True
        callback = lambda sid=state.session_id, tid=task_id: self.resume_ppt_task(sid, tid)
        if status == "failed":
            card.set_failed(self._office_task_failed_title(state))
            card.set_retry_failure(
                str(task.get("error") or "PPTX 生成失败，可从最后检查点重试。"),
                callback,
                action_text="重试",
            )
            return True
        if restored or status in {"running", "paused", "interrupted"}:
            card.set_interrupted("生成中断")
            card.set_retry_failure(
                "任务已中断，可从最后完成的阶段继续。",
                callback,
                action_text="继续生成",
            )
            return True
        return False

    def _append_office_process_note(self, state, text, tone="info"):
        card = self._office_draft_card_for_state(state)
        if card is None:
            return None
        return card.add_process_note(text, tone=tone)

    def _ppt_agent_skill_status(self, strategy):
        skill_name = ppt_agent_strategy_skill_name(strategy)
        if not skill_name:
            return True, "", ""
        manager = getattr(self, "skill_manager", None)
        if manager is None:
            return False, skill_name, f"PPT 助手内置 Skill `{skill_name}` 未找到: 技能管理器尚未初始化。"
        finder = getattr(manager, "_find_skill_path", None)
        skill_path = finder(skill_name) if callable(finder) else ""
        if not skill_path:
            return False, skill_name, f"PPT 助手内置 Skill `{skill_name}` 未找到，请检查 ai_skills 目录。"
        enabled_checker = getattr(manager, "_is_skill_enabled_for_path", None)
        if callable(enabled_checker) and not enabled_checker(skill_name, skill_path):
            return False, skill_name, f"PPT 助手内置 Skill `{skill_name}` 已被关闭，请先在能力商城开启。"
        return True, skill_name, ""

    def _fail_office_request_before_worker(self, state, message, title=None):
        text = str(message or "").strip() or "办公任务启动失败。"
        self._append_office_process_note(state, text, tone="error")
        card = self._office_draft_card_for_state(state)
        if card is not None:
            card.set_failed(title or self._office_task_failed_title(state))
        self.set_session_phase("Failed", state.session_id)
        self.set_session_status("failed", state.session_id, save=True)
        self.refresh_step_list(state.session_id)
        self.refresh_change_list(state.session_id)
        self.save_chat_history(session_id=state.session_id)
        retry_run_id = str(
            (getattr(state, "active_run_retry_context", {}) or {}).get("source_run_id")
            or getattr(state, "active_turn_request_id", "")
            or ""
        )
        self._show_retryable_run_failure(state, text, retry_run_id)
        if state.session_id == self.current_session_id:
            self.normalize_session_ui(state)

    def _finish_office_draft_task_card(self, state, content="", failed_message="", bubble=None):
        card = self._office_draft_card_for_state(state)
        if state and getattr(state, "session_id", None) == getattr(self, "current_session_id", None):
            self._set_deliverable_conversion_running("")
        if failed_message:
            if card is not None:
                card.set_failed(failed_message)
            return
        result_paths = self._collect_office_task_result_paths(state, content=content, bubble=bubble)
        if (
            getattr(state, "ppt_agent_mode", False)
            and normalize_ppt_agent_output_format(getattr(state, "ppt_agent_output_format", "")) == PPT_AGENT_OUTPUT_PPTX
        ):
            self._handle_ppt_agent_validation_completion(state, content, result_paths)
            return
        if card is not None:
            card.set_completed(result_paths)

    def _ppt_agent_generated_pptx(self, state, result_paths):
        template_key = os.path.normcase(os.path.abspath(str(getattr(state, "ppt_agent_template_file", "") or "")))
        candidates = []
        for path in result_paths or []:
            normalized = os.path.normpath(str(path or ""))
            if os.path.splitext(normalized)[1].lower() != ".pptx" or not os.path.isfile(normalized):
                continue
            if template_key and os.path.normcase(os.path.abspath(normalized)) == template_key:
                continue
            candidates.append(normalized)
        return max(candidates, key=os.path.getmtime) if candidates else ""

    def _fail_ppt_task(self, state, message, *, stage="failed", next_action=""):
        task_id = str(getattr(state, "ppt_agent_task_id", "") or "").strip()
        text = str(message or "PPTX 生成失败。")
        if task_id:
            try:
                checkpoint_patch = {
                    "status": "failed",
                    "stage": stage,
                    "next_action": next_action,
                    "error": text,
                    "visual_status": "validation_failed",
                    "failed_run_id": str(getattr(state, "active_turn_request_id", "") or ""),
                }
                result_file = str(getattr(state, "ppt_agent_result_file", "") or "")
                if result_file and os.path.isfile(result_file):
                    checkpoint_patch["pptx"] = self._ppt_task_file_snapshot(result_file)
                self._update_ppt_task_checkpoint(
                    state,
                    task_id,
                    persist=True,
                    **checkpoint_patch,
                )
            except Exception as exc:
                text = f"{text}；检查点写入失败：{exc}"
        card = self._office_draft_card_for_state(state, task_id)
        if card is not None:
            card.add_process_note(text, tone="error")
            card.set_failed(self._office_task_failed_title(state))
            if task_id:
                card.set_retry_failure(
                    text,
                    lambda sid=state.session_id, tid=task_id: self.resume_ppt_task(sid, tid),
                    action_text="重试",
                )
        log_chat_runtime_debug(
            "ppt_task_error",
            session_id=state.session_id,
            task_id=task_id,
            task_stage=stage,
            next_action=next_action,
            error=text,
        )
        return False

    def _complete_ppt_task(self, state, pptx_path, *, verification_level, visual_status):
        task_id = str(getattr(state, "ppt_agent_task_id", "") or "").strip()
        snapshot = self._ppt_task_file_snapshot(pptx_path)
        try:
            self._update_ppt_task_checkpoint(
                state,
                task_id,
                persist=True,
                status="completed",
                stage="completed",
                last_completed_stage="completed",
                next_action="",
                pptx=snapshot,
                verification_level=verification_level,
                visual_status=visual_status,
                error="",
                current_run_id="",
                failed_run_id="",
            )
        except Exception as exc:
            return self._fail_ppt_task(
                state,
                f"PPTX 已生成，但完成检查点写入失败：{exc}",
                stage="checkpoint_failed",
                next_action="complete",
            )
        state.ppt_agent_verification_level = verification_level
        state.ppt_agent_visual_status = visual_status
        state.ppt_agent_result_file = snapshot.get("path") or pptx_path
        self._sync_office_task_card_paths(state, [state.ppt_agent_result_file])
        card = self._office_draft_card_for_state(state, task_id)
        if card is not None:
            card.set_completed([state.ppt_agent_result_file])
        log_chat_runtime_debug(
            "ppt_task_finish",
            session_id=state.session_id,
            task_id=task_id,
            verification_level=verification_level,
            visual_status=visual_status,
            pptx_path=state.ppt_agent_result_file,
        )
        return True

    def _validate_generated_pptx_structure(self, state, pptx_path):
        task_id = str(getattr(state, "ppt_agent_task_id", "") or "").strip()
        try:
            result = validate_pptx_structure(pptx_path)
            snapshot = self._ppt_task_file_snapshot(pptx_path)
            self._update_ppt_task_checkpoint(
                state,
                task_id,
                persist=True,
                status="running",
                stage="structure_validated",
                last_completed_stage="structure_validated",
                next_action=(
                    "complete"
                    if str(getattr(state, "ppt_agent_renderer", RENDERER_NONE) or RENDERER_NONE) == RENDERER_NONE
                    else "render"
                ),
                pptx=snapshot,
                structure_validation=result,
                verification_level="structure_only",
                visual_status="unverified",
                error="",
            )
            log_chat_runtime_debug(
                "ppt_task_structure_validated",
                session_id=state.session_id,
                task_id=task_id,
                page_count=int(result.get("page_count") or 0),
                shape_count=int(result.get("shape_count") or 0),
            )
            return result
        except Exception as exc:
            self._fail_ppt_task(
                state,
                f"PPTX 结构校验失败：{exc}",
                stage="structure_failed",
                next_action="structure_validate",
            )
            return None

    def _handle_ppt_agent_validation_completion(self, state, content, result_paths):
        if not state or not getattr(state, "ppt_agent_mode", False):
            return
        if normalize_ppt_agent_output_format(getattr(state, "ppt_agent_output_format", "")) != PPT_AGENT_OUTPUT_PPTX:
            return
        card = self._office_draft_card_for_state(state)
        visual_status = str(getattr(state, "ppt_agent_visual_status", "") or "").strip().lower()
        if visual_status == "validating":
            if "[PPT_VALIDATION_PASS]" in str(content or ""):
                state.ppt_agent_visual_status = "verified"
                log_chat_runtime_debug(
                    "ppt_agent_validation_finish",
                    session_id=state.session_id,
                    status="verified",
                    validation_round=getattr(state, "ppt_agent_validation_round", 0),
                )
                self._complete_ppt_task(
                    state,
                    getattr(state, "ppt_agent_result_file", ""),
                    verification_level="visual",
                    visual_status="verified",
                )
                return
            if "[PPT_VALIDATION_REPAIRED]" in str(content or ""):
                final_only = int(getattr(state, "ppt_agent_validation_round", 0) or 0) >= 2
                state.ppt_agent_visual_status = "repair_render_pending"
                try:
                    self._update_ppt_task_checkpoint(
                        state,
                        getattr(state, "ppt_agent_task_id", ""),
                        persist=True,
                        status="running",
                        stage="repaired",
                        last_completed_stage="repaired",
                        next_action="final_render" if final_only else "render",
                        validation_round=int(getattr(state, "ppt_agent_validation_round", 0) or 0),
                        visual_status="repair_render_pending",
                        pptx=self._ppt_task_file_snapshot(getattr(state, "ppt_agent_result_file", "")),
                    )
                except Exception as exc:
                    self._fail_ppt_task(state, f"修复结果检查点写入失败：{exc}", stage="checkpoint_failed", next_action="render")
                    return
                self._schedule_ppt_agent_result_render(state, result_paths, final_only=final_only)
                return
            state.ppt_agent_visual_status = "validation_failed"
            log_chat_runtime_debug(
                "ppt_agent_validation_finish",
                session_id=state.session_id,
                status="marker_missing",
                validation_round=getattr(state, "ppt_agent_validation_round", 0),
            )
            self._fail_ppt_task(
                state,
                "视觉复核未返回可识别结论。",
                stage="validation_failed",
                next_action="validate",
            )
            return
        if visual_status in {"verified", "validation_failed", "repair_limit_reached"}:
            return
        pptx_path = self._ppt_agent_generated_pptx(state, result_paths)
        if not pptx_path:
            remembered = os.path.normpath(str(getattr(state, "ppt_agent_result_file", "") or ""))
            if os.path.isfile(remembered) and os.path.splitext(remembered)[1].lower() == ".pptx":
                pptx_path = remembered
        if not pptx_path:
            self._fail_ppt_task(state, "未找到独立生成的 PPTX 文件。", stage="generation_failed", next_action="generate")
            return
        state.ppt_agent_result_file = pptx_path
        if self._validate_generated_pptx_structure(state, pptx_path) is None:
            return
        if str(getattr(state, "ppt_agent_renderer", RENDERER_NONE) or RENDERER_NONE) == RENDERER_NONE:
            if card is not None:
                card.add_process_note(
                    "已完成 python-pptx 结构校验，未执行 PowerPoint/WPS 截图验收。",
                    tone="muted",
                )
            self._complete_ppt_task(
                state,
                pptx_path,
                verification_level="structure_only",
                visual_status="unverified",
            )
            return
        self._schedule_ppt_agent_result_render(state, result_paths, final_only=False)

    def _schedule_ppt_agent_result_render(self, state, result_paths, final_only=False):
        if str(getattr(state, "ppt_agent_renderer", RENDERER_NONE) or RENDERER_NONE) == RENDERER_NONE:
            self._fail_ppt_task(
                state,
                "当前任务没有可用于截图验收的 PowerPoint/WPS 渲染器。",
                stage="render_unavailable",
                next_action="structure_validate",
            )
            return
        if getattr(state, "ppt_agent_validation_worker", None) is not None:
            return
        pptx_path = self._ppt_agent_generated_pptx(state, result_paths)
        if not pptx_path:
            remembered = os.path.normpath(str(getattr(state, "ppt_agent_result_file", "") or ""))
            if os.path.isfile(remembered) and os.path.splitext(remembered)[1].lower() == ".pptx":
                pptx_path = remembered
        card = self._office_draft_card_for_state(state)
        if not pptx_path:
            state.ppt_agent_visual_status = "validation_failed"
            self._fail_ppt_task(
                state,
                "未找到独立生成的 PPTX 文件，无法开始视觉校验。",
                stage="render_failed",
                next_action="render",
            )
            return
        state.ppt_agent_result_file = pptx_path
        next_round = max(1, int(getattr(state, "ppt_agent_validation_round", 0) or 0) + (0 if final_only else 1))
        if final_only:
            next_round = max(2, int(getattr(state, "ppt_agent_validation_round", 0) or 0))
        worker = PptResultRenderWorker(
            pptx_path,
            getattr(state, "ppt_agent_renderer", RENDERER_NONE),
            getattr(state, "ppt_agent_renderer_prog_id", ""),
            getattr(state, "ppt_agent_run_id", ""),
            next_round,
            final_only=final_only,
            parent=self,
        )
        state.ppt_agent_validation_worker = worker
        worker.completed.connect(lambda result, sid=state.session_id: self._handle_ppt_agent_result_rendered(sid, result))
        worker.failed.connect(lambda error, sid=state.session_id: self._handle_ppt_agent_result_render_failed(sid, error))
        worker.finished.connect(lambda sid=state.session_id, item=worker: self._finish_ppt_agent_validation_worker(sid, item))
        try:
            self._update_ppt_task_checkpoint(
                state,
                getattr(state, "ppt_agent_task_id", ""),
                persist=True,
                status="running",
                stage="final_rendering" if final_only else "rendering",
                next_action="final_render" if final_only else "render",
                validation_round=next_round,
                visual_status=str(getattr(state, "ppt_agent_visual_status", "") or ""),
                pptx=self._ppt_task_file_snapshot(pptx_path),
            )
        except Exception as exc:
            state.ppt_agent_validation_worker = None
            worker.deleteLater()
            self._fail_ppt_task(
                state,
                f"渲染检查点写入失败：{exc}",
                stage="checkpoint_failed",
                next_action="final_render" if final_only else "render",
            )
            return
        log_chat_runtime_debug(
            "ppt_agent_validation_render_start",
            session_id=state.session_id,
            pptx_path=pptx_path,
            validation_round=next_round,
            final_only=bool(final_only),
        )
        worker.start()

    def _finish_ppt_agent_validation_worker(self, session_id, worker):
        state = self.get_session(session_id)
        if state and getattr(state, "ppt_agent_validation_worker", None) is worker:
            state.ppt_agent_validation_worker = None
        worker.deleteLater()

    def _handle_ppt_agent_result_render_failed(self, session_id, error):
        state = self.get_session(session_id)
        if not state:
            return
        state.ppt_agent_visual_status = "validation_failed"
        log_chat_runtime_debug(
            "ppt_agent_validation_render_error",
            session_id=session_id,
            error=str(error),
        )
        self._fail_ppt_task(
            state,
            f"PPTX 逐页渲染失败：{error}",
            stage="render_failed",
            next_action="render",
        )

    def _handle_ppt_agent_result_rendered(self, session_id, result):
        state = self.get_session(session_id)
        if not state:
            return
        result = dict(result or {})
        screenshots = self._normalize_prompt_file_paths(result.get("screenshots") or [])
        validation_round = max(1, int(result.get("validation_round") or 1))
        card = self._office_draft_card_for_state(state)
        if not screenshots:
            self._handle_ppt_agent_result_render_failed(session_id, "渲染器未输出任何页面截图")
            return
        if result.get("final_only"):
            state.ppt_agent_visual_status = "verified"
            screenshot_manifest = [self._ppt_task_file_snapshot(path) for path in screenshots]
            try:
                self._update_ppt_task_checkpoint(
                    state,
                    getattr(state, "ppt_agent_task_id", ""),
                    persist=True,
                    status="running",
                    stage="final_rendered",
                    last_completed_stage="final_rendered",
                    next_action="complete",
                    validation_round=validation_round,
                    screenshots=screenshot_manifest,
                    screenshot_page_count=len(screenshot_manifest),
                )
            except Exception as exc:
                self._fail_ppt_task(state, f"最终渲染检查点写入失败：{exc}", stage="checkpoint_failed", next_action="final_render")
                return
            log_chat_runtime_debug(
                "ppt_agent_validation_finish",
                session_id=session_id,
                status="verified_after_repair",
                screenshot_count=len(screenshots),
                validation_round=validation_round,
            )
            self._complete_ppt_task(
                state,
                getattr(state, "ppt_agent_result_file", ""),
                verification_level="visual",
                visual_status="verified",
            )
            return
        state.ppt_agent_validation_round = validation_round
        state.ppt_agent_visual_status = "validating"
        pptx_path = str(result.get("pptx_path") or getattr(state, "ppt_agent_result_file", "") or "")
        template_screenshots = self._normalize_prompt_file_paths(
            getattr(state, "ppt_agent_template_screenshots", []) or []
        )
        screenshot_manifest = [self._ppt_task_file_snapshot(path) for path in screenshots]
        try:
            self._update_ppt_task_checkpoint(
                state,
                getattr(state, "ppt_agent_task_id", ""),
                persist=True,
                status="running",
                stage="rendered",
                last_completed_stage="rendered",
                next_action="validate",
                validation_round=validation_round,
                screenshots=screenshot_manifest,
                screenshot_page_count=len(screenshot_manifest),
                visual_status="validating",
            )
        except Exception as exc:
            self._fail_ppt_task(state, f"截图检查点写入失败：{exc}", stage="checkpoint_failed", next_action="render")
            return
        validation_prompt = (
            "这是 PPT Agent 自动视觉校验，请使用本任务原先选择的多模态模型完成。\n\n"
            f"当前是第 {validation_round} 轮（最多 2 轮自动修复）。请逐页查看生成 PPTX 的截图，并参考模板截图，"
            "检查图片缺失、错位、字体替换、文字溢出、遮挡、异常空白以及品牌元素破坏。模板只提供品牌规范、背景、色彩、页眉页脚和版式语言；"
            "示例文案、示例图形、参考流程、金字塔、图标和占位符不需要作为默认保留内容。逐页确认固定品牌元素、可复用容器和示例内容已经正确区分，"
            "不得在旧示例元素上叠加新内容；标题必须避开 Logo 和公司名称安全区，不适配的页面应以品牌框架空白页重建。\n"
            f"生成文件：{pptx_path}\n"
            "若所有页面渲染正常，不要改文件，并在回复第一行写 [PPT_VALIDATION_PASS]。\n"
            "若发现模板文字残留、旧图形与新内容重叠、标题侵入品牌区、文本截断或元素遮挡，请直接修复同一个 PPTX，"
            "使用本机 PowerPoint/WPS 重新导出全部页面截图并检查修复结果；只有修复后截图已通过时，才在回复第一行写 "
            "[PPT_VALIDATION_REPAIRED]。无法确认通过时请明确报告失败，不要输出通过标记。不要生成 HTML，不要调用默认 PPT/HTML Skill。"
        )
        prompt_files = list(OrderedDict.fromkeys([pptx_path] + screenshots + template_screenshots))
        submitted = self._submit_session_request(
            state,
            validation_prompt,
            prompt_files,
            check_duplicates=False,
            clear_current_input=False,
            workflow_mode=WORKFLOW_MODE_OFFICE_HTML_FIRST,
            office_output_profile=OFFICE_OUTPUT_PROFILE_PPT,
            ppt_agent_mode=True,
            ppt_agent_strategy=getattr(state, "ppt_agent_strategy", PPT_AGENT_STRATEGY_AUTO),
            ppt_agent_selected_strategy=PPT_AGENT_STRATEGY_DEFAULT,
            ppt_agent_preference=getattr(state, "ppt_agent_preference", PPT_AGENT_PREFERENCE_AUTO),
            ppt_agent_template_file=getattr(state, "ppt_agent_template_file", ""),
            ppt_agent_output_format=PPT_AGENT_OUTPUT_PPTX,
            ppt_agent_template_screenshots=template_screenshots,
            ppt_agent_template_hash=getattr(state, "ppt_agent_template_hash", ""),
            ppt_agent_renderer=getattr(state, "ppt_agent_renderer", RENDERER_NONE),
            ppt_agent_renderer_prog_id=getattr(state, "ppt_agent_renderer_prog_id", ""),
            ppt_agent_visual_status="validating",
            ppt_agent_run_id=getattr(state, "ppt_agent_run_id", ""),
            ppt_agent_task_id=getattr(state, "ppt_agent_task_id", ""),
            ppt_agent_internal_stage="visual_validation",
            ppt_agent_verification_level="visual",
            task_model_id=getattr(state, "ppt_agent_task_model_id", ""),
            user_message_meta={
                "ppt_agent_visual_validation": True,
                "ppt_agent_validation_round": validation_round,
                "ppt_task_id": getattr(state, "ppt_agent_task_id", ""),
                "ppt_agent_internal_stage": "visual_validation",
            },
        )
        if not submitted:
            state.ppt_agent_visual_status = "validation_failed"
            self._fail_ppt_task(
                state,
                "页面截图已生成，但视觉复核任务启动失败。",
                stage="validation_failed",
                next_action="validate",
            )
            return

    def _office_task_failed_title(self, state):
        target = str(getattr(state, "office_task_target_format", "") or "").strip().upper()
        if target in {"PPTX", "DOCX", "PDF"}:
            return f"{target} 生成失败"
        return "办公稿生成失败"

    def _sync_office_task_card_paths(self, state, paths):
        workspace_dir = self._workspace_dir_for_state(state)
        valid_paths = [
            normalized
            for path in (paths or [])
            if (normalized := normalize_workspace_file(path, workspace_dir))
        ]
        if not valid_paths:
            return
        existing = list(getattr(state, "office_task_result_paths", []) or [])
        merged = []
        seen = set()
        for path in existing + valid_paths:
            key = os.path.normcase(os.path.abspath(path))
            if key in seen:
                continue
            seen.add(key)
            merged.append(path)
        state.office_task_result_paths = merged
        card = self._office_draft_card_for_state(state)
        if card is not None:
            card.add_result_paths(valid_paths)

    def _collect_office_task_result_paths(self, state, content="", bubble=None):
        workspace_dir = self._workspace_dir_for_state(state)
        candidates = []
        candidates.extend(getattr(state, "office_task_result_paths", []) or [])
        candidates.extend(path for _start, _end, path in iter_workspace_file_paths(content or "", workspace_dir))
        if bubble is not None:
            candidates.extend(getattr(bubble, "_deliverable_paths", []) or [])
        for item in getattr(state, "changed_files", []) or []:
            if isinstance(item, dict):
                candidates.append(item.get("path") or "")
        valid_paths = [
            normalized
            for path in candidates
            if (normalized := normalize_workspace_file(path, workspace_dir))
        ]
        self._sync_office_task_card_paths(state, valid_paths)
        return list(getattr(state, "office_task_result_paths", []) or [])

    def refresh_clarify_controls(self, session_id=None):
        state = self.get_session(session_id)
        if not state or state.session_id != self.current_session_id:
            return
        self.refresh_grill_mode_controls(state.session_id)

    def refresh_grill_mode_controls(self, session_id=None):
        state = self.get_session(session_id) if session_id else self.get_current_session()
        if not state or state.session_id != self.current_session_id or not hasattr(self, "grill_mode_badge"):
            return
        grill_state = normalize_grill_mode_state(
            getattr(state, "grill_mode_state", GRILL_MODE_DISABLED)
        )
        visible = grill_state in {GRILL_MODE_ARMED, GRILL_MODE_ACTIVE}
        active = grill_state == GRILL_MODE_ACTIVE
        round_count = min(
            GRILL_MAX_ROUNDS,
            max(0, int(getattr(state, "grill_round_count", 0) or 0)),
        )
        cycle_number = max(0, int(getattr(state, "grill_cycle_count", 0) or 0)) + 1
        self.grill_mode_badge.setText(
            f"拷问中 {cycle_number} · {round_count}/{GRILL_MAX_ROUNDS}"
            if active
            else "拷问模式"
        )
        self.grill_mode_badge.setRemovable(grill_state == GRILL_MODE_ARMED)
        self.grill_mode_badge.setEnabled(grill_state == GRILL_MODE_ARMED)
        self.grill_mode_badge.setToolTip(
            "正在先澄清关键决策；可使用停止按钮结束，绝不会自动执行"
            if active
            else "先澄清关键决策，再执行下一项任务"
        )
        self.grill_mode_badge.setVisible(visible)

    def toggle_grill_mode(self):
        state = self.get_current_session()
        if not state:
            return
        if self._session_has_current_execution(state):
            self.add_system_toast(
                "当前任务结束后可调整拷问模式",
                "info",
                session_id=state.session_id,
                auto_close_ms=3200,
            )
            return
        current = normalize_grill_mode_state(
            getattr(state, "grill_mode_state", GRILL_MODE_DISABLED)
        )
        enabled = current != GRILL_MODE_ARMED
        state.grill_mode_state = GRILL_MODE_ARMED if enabled else GRILL_MODE_DISABLED
        state.grill_round_count = 0
        state.grill_cycle_count = 0
        state.grill_execution_confirmed = False
        log_ui_navigation(
            "grill_mode_toggled",
            session_id=state.session_id,
            enabled=enabled,
        )
        self.refresh_grill_mode_controls(state.session_id)
        self.refresh_composer_action_state()
        self.save_chat_history(session_id=state.session_id)
        self.add_system_toast(
            "已开启拷问模式，仅作用于下一项任务" if enabled else "已取消拷问模式",
            "success" if enabled else "info",
            session_id=state.session_id,
            auto_close_ms=3000,
        )

    def _finish_grill_mode(self, state, outcome):
        if not state:
            return False
        active = normalize_grill_mode_state(
            getattr(state, "grill_mode_state", GRILL_MODE_DISABLED)
        ) == GRILL_MODE_ACTIVE
        confirmed = bool(getattr(state, "grill_execution_confirmed", False))
        if not active and not confirmed:
            return False
        log_ui_navigation(
            "grill_finished",
            session_id=state.session_id,
            outcome=str(outcome or "finished"),
            cycle=max(0, int(getattr(state, "grill_cycle_count", 0) or 0)) + 1,
            round=min(
                GRILL_MAX_ROUNDS,
                max(0, int(getattr(state, "grill_round_count", 0) or 0)),
            ),
            execution_confirmed=confirmed,
        )
        if str(outcome or "").strip().lower() == "error":
            log_ui_navigation(
                "grill_error",
                session_id=state.session_id,
                phase="run",
            )
        state.grill_mode_state = GRILL_MODE_DISABLED
        state.grill_round_count = 0
        state.grill_cycle_count = 0
        state.grill_execution_confirmed = False
        self.refresh_grill_mode_controls(state.session_id)
        return True

    def set_session_phase(self, phase, session_id=None):
        state = self.get_session(session_id)
        if not state:
            return
        state.run_phase = phase
        if state.session_id == self.current_session_id:
            if hasattr(self, "loop_hint"):
                self.loop_hint.setText(display_run_phase(phase or "运行中"))
            self.refresh_context_badges(state.session_id)

    def _session_has_live_activity(self, session_id):
        state = self.get_session(session_id)
        if not state:
            return False
        return str(getattr(state, "session_status", "") or "") in {
            "running",
            "finalizing",
        }

    def refresh_session_activity_indicator(self, session_id):
        indicators = getattr(self, "history_activity_indicators", {})
        indicator = indicators.get(session_id)
        status_widget = getattr(self, "history_activity_statuses", {}).get(session_id)
        if indicator or status_widget:
            state = self.get_session(session_id)
            waiting = bool(state and getattr(state, "pending_interactions", {}))
            failed = bool(
                state
                and getattr(state, "session_status", "") in {"error", "failed"}
            )
            running = self._session_has_live_activity(session_id)
            finalizing = bool(
                state and getattr(state, "session_status", "") == "finalizing"
            )
            status = (
                "waiting"
                if waiting
                else (
                    "error"
                    if failed
                    else ("finalizing" if finalizing else ("running" if running else "idle"))
                )
            )
            if status_widget:
                status_widget.setState(status)
            elif indicator:
                indicator.setState(status)
            age_label = getattr(self, "history_age_labels", {}).get(session_id)
            if age_label:
                age_label.setVisible(not (running or waiting or failed) and bool(age_label.text()))
            workspace_dir = self._workspace_dir_for_state(state) if state else ""
            if workspace_dir and self._session_workspace_source(state) == "project":
                self.refresh_project_activity_indicator(workspace_dir)
        self.refresh_skill_capture_sidebar_indicator(session_id)

    def _project_activity_summary(self, path):
        project_key = self._project_key(path)
        running = 0
        finalizing = 0
        waiting = 0
        for state in (getattr(self, "sessions", {}) or {}).values():
            if self._session_workspace_source(state) != "project":
                continue
            if self._project_key(self._workspace_dir_for_state(state)) != project_key:
                continue
            if getattr(state, "pending_interactions", {}):
                waiting += 1
            elif getattr(state, "session_status", "") == "finalizing":
                finalizing += 1
            elif self._session_has_live_activity(state.session_id):
                running += 1
        if waiting:
            return "waiting", waiting
        if finalizing:
            return "finalizing", finalizing
        if running:
            return "running", running
        return "idle", 0

    def refresh_project_activity_indicator(self, path):
        normalized = self._normalize_project_path(path)
        indicator = getattr(self, "project_activity_statuses", {}).get(normalized)
        if indicator is None or not _qt_object_alive(indicator):
            return
        state, count = self._project_activity_summary(normalized)
        indicator.setState(state, count=count)

    def _conversation_skill_capture_phase(self, session_id):
        state = self.get_session(session_id)
        pending = getattr(state, "pending_conversation_skill_result", None) if state else None
        if isinstance(pending, dict) and pending.get("phase"):
            return str(pending.get("phase") or "")
        repository = getattr(self, "conversation_skill_capture_repository", None)
        if repository is None:
            return ""
        captures = repository.list_for_session(session_id)
        return str((captures[0] if captures else {}).get("phase") or "")

    def refresh_skill_capture_sidebar_indicator(self, session_id):
        indicator = getattr(self, "history_skill_capture_indicators", {}).get(session_id)
        if indicator is None or not _qt_object_alive(indicator):
            return
        phase = self._conversation_skill_capture_phase(session_id)
        labels = {
            "analyzing": "正在分析复用价值",
            "analysis_ready": "复用分析待确认",
            "compiling": "正在编译 Skill 草稿",
            "draft_ready": "Skill 草稿待确认",
            "failed": "Skill 沉淀失败，返回会话查看",
        }
        indicator.set_phase(phase if phase in labels else "")
        indicator.setToolTip(labels.get(phase, ""))
        indicator.setAccessibleName(labels.get(phase, ""))

    def set_session_status(self, status, session_id=None, save=False, error=""):
        state = self.get_session(session_id)
        if not state:
            return
        status = str(status or "draft")
        allowed = {"draft", "running", "finalizing", "completed", "error", "failed", "interrupted"}
        if status not in allowed:
            raise ValueError(f"不支持的会话运行状态：{status}")
        state.session_status = status
        if status in {"running", "finalizing"}:
            state.live_activity = True
        else:
            state.live_activity = False
            state.turn_steerable = False
            state.daemon_running = False
        if status in {"completed", "error", "failed", "interrupted", "draft"}:
            self._cancel_token_speed_monitor(state, f"session_{status}")
        if status != "running":
            state.provider_retry_attempt = 0
            state.provider_retry_max = 0
        log_sub_agent_runtime(
            "ui_session_lifecycle_transition",
            session_id=state.session_id,
            lifecycle_status=status,
            save_requested=bool(save),
            error=str(error or ""),
        )
        self._sync_history_age_for_session(state)
        # The authoritative lifecycle state must reach both sidebar surfaces
        # before any presentation finalizer or asynchronous persistence work.
        self.refresh_session_activity_indicator(state.session_id)
        log_sub_agent_runtime(
            "ui_sidebar_lifecycle_refreshed",
            session_id=state.session_id,
            lifecycle_status=status,
            sidebar_running=self._session_has_live_activity(state.session_id),
        )
        if state.session_id == self.current_session_id:
            self.refresh_context_badges(state.session_id)
        if status in {"completed", "error", "failed", "interrupted", "draft"}:
            try:
                self._finalize_live_turn_process_groups(state)
            except Exception as exc:
                self.append_log(
                    f"运行终态过程视图收尾失败({state.session_id}, status={status}): {exc}"
                )
                log_sub_agent_runtime(
                    "ui_terminal_process_finalize_failed",
                    session_id=state.session_id,
                    terminal_status=status,
                    error=str(exc),
                    traceback=traceback.format_exc(),
                )
                self._show_conversation_notice(
                    state,
                    f"任务已结束，但过程视图收尾失败：{exc}",
                    "warning",
                )
        terminal_status = status in {"completed", "error", "failed", "interrupted"}
        favorite_terminal = terminal_status and bool(getattr(state, "favorite_run_id", ""))
        persistence_succeeded = True
        if (save and state.messages) or favorite_terminal:
            saved = self.save_chat_history(
                session_id=state.session_id,
                flush=bool(favorite_terminal),
            )
            persistence_succeeded = bool(saved)
            if not saved:
                log_sub_agent_runtime(
                    "ui_terminal_save_not_queued",
                    session_id=state.session_id,
                    lifecycle_status=status,
                )
        if terminal_status:
            self._mark_session_favorite_run_completed(
                state,
                status,
                error=error,
                delivery_persistence_succeeded=persistence_succeeded,
            )

    def _finalize_live_turn_process_groups(self, state):
        groups = list(getattr(state, "live_agent_turn_groups", []) or [])
        result_group = getattr(state, "active_agent_turn_group", None)
        result_bubble = (
            result_group.active_stage()
            if isinstance(result_group, AssistantTurnGroup)
            else None
        )
        if groups and result_group not in groups:
            log_sub_agent_runtime(
                "ui_assistant_terminal_group_invariant_failed",
                session_id=state.session_id,
                group_count=len(groups),
                result_group_id=str(getattr(result_group, "group_id", "") or ""),
            )
            raise RuntimeError("实时执行过程终态缺少当前结果组，无法安全折叠。")
        state.live_agent_turn_groups = []
        for group in groups:
            if group is None or not _qt_object_alive(group):
                continue
            if group is result_group:
                group.finalize_non_result_stages(result_bubble)
                group.request_process_finalization(result_bubble)
                log_sub_agent_runtime(
                    "ui_assistant_terminal_result_group",
                    session_id=state.session_id,
                    group_id=group.group_id,
                    stage_count=len(group.stage_bubbles),
                    pending=bool(group.process_finalization_pending),
                    result_ready=bool(
                        result_bubble is not None
                        and getattr(result_bubble, "_rendered_main_content_final", False)
                    ),
                )
                continue
            group.finalize_process_only()
        log_sub_agent_runtime(
            "ui_assistant_terminal_groups_finalized",
            session_id=state.session_id,
            terminal_status=str(getattr(state, "session_status", "") or ""),
            group_count=len(groups),
            result_group_id=str(getattr(result_group, "group_id", "") or ""),
        )

    def refresh_change_list(self, session_id=None):
        state = self.get_session(session_id)
        if not state:
            return
        if session_id is None or state.session_id == self.current_session_id:
            self.refresh_context_badges(state.session_id)

    def refresh_step_list(self, session_id=None):
        state = self.get_session(session_id)
        if not state:
            return
        if session_id is None or state.session_id == self.current_session_id:
            self.step_list.clear()
            if not state.step_records:
                item = QListWidgetItem(qta.icon('fa5s.stream', color=DesignTokens.text_tertiary), "本轮还没有工具调用")
                item.setFlags(Qt.NoItemFlags)
                self.step_list.addItem(item)
            else:
                for record in state.step_records:
                    status = record.get("status") or "running"
                    title = record.get("display_title") or record.get("tool_name") or "Step"
                    summary = record.get("summary") or "Waiting for more output"
                    step_title = record.get("plan_step_title") or ""
                    duration = record.get("duration")
                    duration_text = f" · {duration:.1f}s" if isinstance(duration, (int, float)) else ""
                    line2 = summary
                    if step_title:
                        line2 = f"[步骤] {step_title} | {summary}"
                    failed = status in {"failed", "error", "killed"}
                    icon_name = "fa5s.exclamation-circle" if failed else ("fa5s.check-circle" if status == "done" else "fa5s.play-circle")
                    icon_color = DesignTokens.status_error if failed else (DesignTokens.status_success if status == "done" else DesignTokens.status_running)
                    item = QListWidgetItem(
                        qta.icon(icon_name, color=icon_color),
                        f"{title} · {status_label_text(status)}{duration_text}\n{line2}",
                    )
                    item.setData(Qt.UserRole, record.get("tool_id"))
                    item.setToolTip("选择后按 Enter 或点击查看技术详情")
                    self.step_list.addItem(item)
            self.refresh_context_badges(state.session_id)

    def _observability_pretty_json(self, value):
        try:
            if isinstance(value, str):
                text = value.strip()
                if text.startswith("{") or text.startswith("["):
                    return _safe_text_preview(json.dumps(json.loads(text), indent=2, ensure_ascii=False), 2500)
                return _safe_text_preview(value, 2500)
            text = json.dumps(value, indent=2, ensure_ascii=False)
            return _safe_text_preview(text, 2500)
        except Exception:
            return _safe_text_preview(str(value), 2500)

    def _set_observability_text(self, edit, text, field_name, limit=6000):
        if not _qt_object_alive(edit):
            log_sub_agent_runtime(
                "ui_observability_text_widget_invalid",
                field=field_name,
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
            )
            return
        safe_text = str(text or "") if limit is None else _safe_text_preview(text, limit)
        try:
            current_text = edit.toPlainText()
            if current_text == safe_text:
                log_sub_agent_runtime(
                    "ui_observability_text_unchanged",
                    field=field_name,
                    raw_len=len(str(text or "")),
                    safe_len=len(safe_text),
                    current_session_id=str(getattr(self, "current_session_id", "") or ""),
                )
                return
            edit.setPlainText(safe_text)
            log_sub_agent_runtime(
                "ui_observability_text_set",
                field=field_name,
                raw_len=len(str(text or "")),
                safe_len=len(safe_text),
                current_session_id=str(getattr(self, "current_session_id", "") or ""),
            )
        except Exception:
            log_sub_agent_runtime(
                "ui_observability_text_set_failed",
                field=field_name,
                raw_len=len(str(text or "")),
                traceback=traceback.format_exc(),
            )

    def _format_observability_prompt_append(self, item, index):
        if not isinstance(item, dict):
            return ""
        source = item.get("source") or "system"
        content = item.get("content") or ""
        if not content:
            return ""
        return f"\n\n# 追加系统消息 {index}: {source}\n{content}"

    def _build_observability_prompt_texts(self, state, preview_limit=6000):
        prompt_text = getattr(state, "system_prompt_text", "") or ""
        runtime_context = getattr(state, "runtime_context_text", "") or ""
        prompt_meta = getattr(state, "prompt_cache_meta", {}) or {}
        meta_lines = []
        if isinstance(prompt_meta, dict) and prompt_meta:
            meta_lines = [
                "# Prompt Cache Observability",
                f"prompt_cache_key: {prompt_meta.get('prompt_cache_key') or ''}",
                "",
            ]
        prompt_parts = []
        if meta_lines:
            prompt_parts.append("\n".join(meta_lines))
        if prompt_text:
            prompt_parts.append("# Stable System Prompt\n" + prompt_text)
        if runtime_context:
            prompt_parts.append("# Runtime Context Prompt\n" + runtime_context)
        append_parts = []
        for index, item in enumerate(getattr(state, "system_prompt_appends", []) or [], start=1):
            formatted = self._format_observability_prompt_append(item, index)
            if formatted:
                append_parts.append(formatted)
        full_text = "\n\n".join(prompt_parts) + "".join(append_parts)
        preview_source = "".join(append_parts) if append_parts else full_text
        preview_text = _safe_text_tail_preview(preview_source, preview_limit)
        return full_text, preview_text

    def _observability_time_text(self, ts):
        try:
            if ts is None or ts == "":
                return datetime.now().strftime("%H:%M:%S")
            return datetime.fromtimestamp(float(ts)).strftime("%H:%M:%S")
        except Exception:
            return datetime.now().strftime("%H:%M:%S")

    def _format_observability_event(self, event):
        if not isinstance(event, dict):
            return ""
        event_type = event.get("type") or ""
        stamp = self._observability_time_text(event.get("timestamp"))
        if event_type == "tool_call":
            return (
                f"[{stamp}] CALL {event.get('name') or 'unknown_tool'} ({event.get('id') or ''})\n"
                f"args:\n{self._observability_pretty_json(event.get('args') or {})}"
            )
        if event_type == "tool_result":
            meta = event.get("meta") if isinstance(event.get("meta"), dict) else {}
            duration = meta.get("duration")
            duration_text = f" duration={float(duration):.2f}s" if isinstance(duration, (int, float)) else ""
            result_value = event.get("result_obj") if event.get("result_obj") is not None else event.get("result", "")
            return (
                f"[{stamp}] RESULT {event.get('name') or 'unknown_tool'} ({event.get('id') or ''}){duration_text}\n"
                f"result:\n{self._observability_pretty_json(result_value)}"
            )
        if event_type == "system_prompt_append":
            source = event.get("source") or "system"
            return f"[{stamp}] SYSTEM APPEND {source}\n{event.get('content') or ''}"
        if event_type == "system_prompt":
            cache_key = event.get("prompt_cache_key") or ""
            return f"[{stamp}] SYSTEM PROMPT loaded\nprompt_cache_key={cache_key}"
        if event_type == "run_error":
            return (
                f"[{stamp}] RUN ERROR {event.get('summary') or ''}\n"
                f"category={event.get('category') or ''} "
                f"retry={event.get('retry_attempt', 0)}/{event.get('max_retries', 0)}\n"
                f"session_id={event.get('session_id') or ''} "
                f"turn_id={event.get('turn_id') or ''} "
                f"run_id={event.get('run_id') or ''}\n"
                f"error={event.get('error') or ''}"
            )
        if event_type == "llm_usage":
            usage = event.get("usage") if isinstance(event.get("usage"), dict) else {}
            rate = usage.get("cache_hit_rate")
            try:
                rate_text = f"{float(rate) * 100:.1f}%"
            except Exception:
                rate_text = "unknown"
            return (
                f"[{stamp}] LLM USAGE cache_hit={rate_text}\n"
                f"input={usage.get('input_tokens', 'unknown')} "
                f"cached={usage.get('cached_input_tokens', 'unknown')} "
                f"uncached={usage.get('uncached_input_tokens', 'unknown')} "
                f"output={usage.get('output_tokens', 'unknown')} "
                f"total={usage.get('total_tokens', 'unknown')}\n"
                f"prompt_cache_key={usage.get('prompt_cache_key') or ''}"
            )
        return f"[{stamp}] {event_type or 'event'}\n{self._observability_pretty_json(event)}"

    def refresh_observability_view(self, session_id=None):
        try:
            on_ui_thread = QThread.currentThread() is self.thread()
        except RuntimeError:
            on_ui_thread = True
        if not on_ui_thread:
            QTimer.singleShot(0, lambda sid=session_id: self.refresh_observability_view(sid))
            return
        state = self.get_session(session_id)
        if not state or state.session_id != self.current_session_id:
            return
        if not (
            hasattr(self, "observability_prompt_edit")
            and hasattr(self, "observability_log_edit")
            and _qt_object_alive(self.observability_prompt_edit)
            and _qt_object_alive(self.observability_log_edit)
        ):
            log_sub_agent_runtime(
                "ui_observability_widgets_unavailable",
                session_id=getattr(state, "session_id", ""),
            )
            return
        try:
            prompt_joined, _ = self._build_observability_prompt_texts(state, preview_limit=6000)
            self._set_observability_text(
                self.observability_prompt_edit,
                prompt_joined,
                "system_prompt",
                limit=None,
            )
            if hasattr(self, "observability_copy_prompt_btn") and _qt_object_alive(self.observability_copy_prompt_btn):
                self.observability_copy_prompt_btn.setEnabled(bool(prompt_joined.strip()))

            log_parts = []
            for event in getattr(state, "observability_events", []) or []:
                if not isinstance(event, dict):
                    continue
                if event.get("type") == "system_prompt":
                    continue
                formatted = self._format_observability_event(event)
                if formatted:
                    log_parts.append(formatted)
            log_joined = "\n\n---\n\n".join(log_parts)
            self._set_observability_text(
                self.observability_log_edit,
                log_joined,
                "event_log",
                limit=10000,
            )
            for edit in (self.observability_prompt_edit, self.observability_log_edit):
                cursor = edit.textCursor()
                cursor.movePosition(QTextCursor.End)
                edit.setTextCursor(cursor)
            log_sub_agent_runtime(
                "ui_observability_refresh_done",
                session_id=state.session_id,
                event_count=len(getattr(state, "observability_events", []) or []),
                prompt_len=len(prompt_joined),
                log_len=len(log_joined),
            )
        except Exception:
            log_sub_agent_runtime(
                "ui_observability_refresh_failed",
                session_id=state.session_id,
                traceback=traceback.format_exc(),
            )

    def _event_matches_active_run(self, state, turn_id=None, request_id=None):
        if not state:
            return False
        if turn_id is not None and str(turn_id) != str(getattr(state, "active_turn_id", "")):
            return False
        if request_id is not None and str(request_id) != str(
            getattr(state, "active_turn_request_id", "")
        ):
            return False
        return True

    def _bind_run_worker_finished(self, state, worker, kind, turn_id, request_id, result_handler):
        if not state or worker is None:
            raise ValueError("运行 worker 收尾缺少会话或 worker。")
        worker._ui_result_received = False
        worker._ui_terminal_handled = False

        def mark_result_received(*_args):
            worker._ui_result_received = True

        def on_result(*args):
            result = args[0] if args else {}
            if worker._ui_terminal_handled:
                return
            worker._ui_terminal_handled = True
            result_handler(result)

        worker.finished_signal.connect(mark_result_received, Qt.DirectConnection)
        worker.finished_signal.connect(on_result, Qt.QueuedConnection)
        worker.finished.connect(
            lambda sid=state.session_id, tid=turn_id, rid=request_id, current=worker, worker_kind=kind:
            self._handle_native_run_worker_finished(sid, tid, rid, worker_kind, current),
            Qt.QueuedConnection,
        )

    def _handle_native_run_worker_finished(self, session_id, turn_id, request_id, kind, worker):
        state = self.get_session(session_id)
        if not state or not self._event_matches_active_run(state, turn_id, request_id):
            return
        current_worker = {
            "llm": getattr(state, "llm_worker", None),
            "daemon": getattr(state, "daemon_worker", None),
            "code": getattr(state, "code_worker", None),
        }.get(str(kind or ""))
        if current_worker is not worker or getattr(worker, "_ui_result_received", False) or getattr(worker, "_ui_terminal_handled", False):
            return
        worker._ui_terminal_handled = True
        message = "运行线程提前结束"
        log_sub_agent_runtime(
            "ui_run_worker_native_finished_without_result",
            session_id=state.session_id,
            turn_id=str(turn_id or ""),
            request_id=str(request_id or ""),
            worker_kind=str(kind or ""),
        )
        if kind == "code":
            state.code_worker = None
            self._show_conversation_notice(state, message, "error")
            self.set_session_phase("Failed", state.session_id)
            self.set_session_status("failed", state.session_id, save=True, error=message)
            self.refresh_step_list(state.session_id)
            self.refresh_change_list(state.session_id)
            if state.session_id == self.current_session_id:
                self.normalize_session_ui(state)
            return
        result = {"error": message, "_runtime_terminal": "failed", "request_id": request_id}
        if kind == "daemon":
            self.handle_daemon_response(result, state.session_id, turn_id, request_id)
            return
        state.llm_worker = None
        self.handle_llm_response(result, state.session_id, turn_id, request_id)

    def handle_observability_event(self, data, session_id=None, turn_id=None, request_id=None):
        try:
            on_ui_thread = QThread.currentThread() is self.thread()
        except RuntimeError:
            on_ui_thread = True
        if not on_ui_thread:
            payload = dict(data) if isinstance(data, dict) else {}
            QTimer.singleShot(
                0,
                lambda p=payload, sid=session_id, tid=turn_id, rid=request_id:
                    self.handle_observability_event(p, sid, tid, rid),
            )
            return
        if not isinstance(data, dict):
            log_sub_agent_runtime(
                "ui_observability_event_invalid",
                session_id=str(session_id or ""),
                data_type=type(data).__name__,
            )
            return
        state = self.get_session(session_id)
        if not state:
            log_sub_agent_runtime(
                "ui_observability_missing_session",
                session_id=str(session_id or ""),
                event_type=data.get("type") or "",
            )
            return
        if not self._event_matches_active_run(state, turn_id, request_id):
            log_sub_agent_runtime(
                "ui_observability_stale_run_rejected",
                session_id=state.session_id,
                turn_id=str(turn_id or ""),
                request_id=str(request_id or ""),
            )
            return
        try:
            event = dict(data)
            event.setdefault("timestamp", time.time())
            event.setdefault("session_id", state.session_id)
            event.setdefault("turn_id", str(turn_id or ""))
            event.setdefault("run_id", str(request_id or ""))
            event_type = event.get("type") or ""
            if event_type == "provider_request_start":
                self._start_token_speed_monitor(state, event)
            elif event_type == "provider_request_finish":
                self._finish_token_speed_monitor(state, event)
            elif event_type == "provider_request_error":
                self._finish_token_speed_monitor(state, event, status="error")
            elif event_type == "system_prompt":
                state.system_prompt_text = event.get("content") or ""
                state.runtime_context_text = event.get("runtime_context") or ""
                state.prompt_cache_meta = {
                    "prompt_cache_key": event.get("prompt_cache_key") or "",
                }
                state.system_prompt_appends = [
                    item for item in (event.get("skill_contexts") or [])
                    if isinstance(item, dict)
                ]
            elif event_type == "system_prompt_append":
                state.system_prompt_appends.append(event)
            elif event_type == "llm_usage":
                self.apply_token_usage_event(
                    state,
                    event.get("usage") if isinstance(event.get("usage"), dict) else {},
                )
            elif event_type == "provider_retry":
                self._retry_token_speed_monitor(state, event)
                retry_attempt = max(1, int(event.get("attempt") or 1))
                retry_max = max(retry_attempt, int(event.get("max_retries") or retry_attempt))
                state.provider_retry_attempt = retry_attempt
                state.provider_retry_max = retry_max
                log_sub_agent_runtime(
                    "ui_provider_retry",
                    session_id=state.session_id,
                    turn_id=str(event.get("turn_id") or ""),
                    run_id=str(request_id or event.get("request_id") or ""),
                    request_id=str(event.get("request_id") or ""),
                    attempt=retry_attempt,
                    max_retries=retry_max,
                    delay_seconds=float(event.get("delay_seconds") or 0.0),
                    reason=str(event.get("reason") or ""),
                )
            elif event_type == "guidance":
                message_id = str(event.get("message_id") or "")
                if message_id:
                    self._timeline_set_guidance_status(state, message_id, "applied")
                    self.save_chat_history(session_id=state.session_id)
                    log_sub_agent_runtime(
                        "ui_guidance_timeline_applied",
                        session_id=state.session_id,
                        message_id=message_id,
                    )
            state.observability_events.append(event)
            if len(state.observability_events) > 500:
                state.observability_events = state.observability_events[-500:]
            log_sub_agent_runtime(
                "ui_observability_event_recorded",
                session_id=state.session_id,
                event_type=event_type,
                content_len=_sub_agent_payload_content_len(event),
                event_count=len(state.observability_events),
            )
            if state.session_id == self.current_session_id:
                self.set_context_tab_hint(self.RIGHT_TAB_OBSERVABILITY, True)
                self.refresh_observability_view(state.session_id)
                self.refresh_context_badges(state.session_id)
                if event_type == "provider_retry":
                    self.normalize_session_ui(state)
        except Exception:
            log_sub_agent_runtime(
                "ui_observability_event_failed",
                session_id=state.session_id,
                event_type=(data or {}).get("type") or "",
                traceback=traceback.format_exc(),
            )

    def on_step_item_clicked(self, item):
        tool_id = item.data(Qt.UserRole)
        if not tool_id:
            return
        state = self.get_current_session()
        if not state or tool_id not in state.tool_cards:
            return
        card = state.tool_cards[tool_id]
        self.show_tool_details(tool_id, card.args, card.result, meta=card.meta, switch_tab=True)

    def select_step_item(self, item):
        tool_id = item.data(Qt.UserRole)
        if not tool_id:
            return
        state = self.get_current_session()
        if not state or tool_id not in state.tool_cards:
            return
        card = state.tool_cards[tool_id]
        self.show_tool_details(tool_id, card.args, card.result, meta=card.meta, switch_tab=False)

    def start_background_services(self):
        if self._background_services_started:
            return
        self._background_services_started = True
        self._schedule_background_service_start(40, self.start_background_skill_load)
        if not self._external_background_services_allowed():
            log_startup_stage(
                "external_background_services_skipped",
                platform=QApplication.platformName(),
            )
            return
        self._schedule_background_service_start(BACKGROUND_TRAY_START_DELAY_MS, self.setup_tray)
        self._schedule_background_service_start(BACKGROUND_DAEMON_PREWARM_DELAY_MS, self._start_background_daemon_prewarm)
        self._schedule_background_service_start(BACKGROUND_DAEMON_MONITOR_DELAY_MS, self.start_daemon_monitor)
        self._schedule_background_service_start(BACKGROUND_FAVORITES_START_DELAY_MS, self.start_favorites_scheduler)

    @staticmethod
    def _external_background_services_allowed():
        explicit = str(os.environ.get("COWORK_EXTERNAL_BACKGROUND_SERVICES") or "").strip().lower()
        if explicit in {"1", "true", "yes", "on"}:
            return True
        if explicit in {"0", "false", "no", "off"}:
            return False
        return str(QApplication.platformName() or "").strip().lower() != "offscreen"

    def _schedule_background_service_start(self, delay_ms, callback):
        QTimer.singleShot(max(int(delay_ms or 0), 0), callback)

    def start_background_skill_load(self, force=False):
        if self.skill_manager_loading:
            return
        if self.skill_manager_ready and not force:
            return
        self.skill_manager_loading = True
        self.skill_load_error = ""
        log_startup_stage("skill_load_begin")
        log_startup_stage("mcp_probe_deferred")
        worker = SkillManagerLoadWorker(
            self.config_manager,
            None,
            load_mcp_tools=False,
            catalog_service=self.skill_catalog_service,
            parent=self,
        )
        self.skill_load_worker = worker
        worker.completed.connect(self.handle_background_skill_load_completed, Qt.QueuedConnection)
        worker.finished.connect(worker.deleteLater)
        worker.start()
        self.refresh_selected_skill_controls()

    def handle_background_skill_load_completed(self, payload):
        payload = payload if isinstance(payload, dict) else {}
        self.skill_manager_loading = False
        if payload.get("ok"):
            manager = payload.get("skill_manager")
            if manager is not None:
                self.skill_manager = manager
                self.skill_manager_ready = True
                self.skill_catalog_service.start_watching()
            log_startup_stage(
                "skill_load_done",
                ok=True,
                skill_count=len(getattr(self.skill_manager, "skill_records", {}) or {}),
            )
            self.add_system_toast("能力已加载完成", "success", auto_close_ms=2600)
        else:
            self.skill_manager_ready = False
            self.skill_load_error = payload.get("error") or "未知错误"
            log_startup_stage("skill_load_done", ok=False, error=self.skill_load_error)
            log_sub_agent_runtime(
                "skill_manager_background_load_failed",
                error=self.skill_load_error,
                traceback=payload.get("traceback") or "",
            )
            self.add_system_toast(f"能力加载失败：{self.skill_load_error}", "error", auto_close_ms=8000)
        self.skill_load_worker = None
        self.refresh_selected_skill_controls()
        self.update_skill_capture_button_state()
        self.refresh_context_badges()

    def _start_background_daemon_prewarm(self):
        self.setup_daemon_client(retries=6)

    def setup_daemon_client(self, retries=6):
        self.daemon_client = DaemonClient(
            self.daemon_host,
            self.daemon_port,
            timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
        )
        self.queue_daemon_connection(allow_start=True, retries=retries)

    def queue_daemon_connection(self, allow_start=False, retries=0):
        self._pending_daemon_connect_allow_start = bool(
            getattr(self, "_pending_daemon_connect_allow_start", False) or allow_start
        )
        self._pending_daemon_connect_retries = max(
            int(getattr(self, "_pending_daemon_connect_retries", 0) or 0),
            max(0, int(retries or 0)),
        )
        self._drain_daemon_connection_queue()

    def _drain_daemon_connection_queue(self):
        worker = getattr(self, "daemon_connect_worker", None)
        if worker and worker.isRunning():
            self.daemon_bootstrapping = bool(
                getattr(self, "_pending_daemon_connect_allow_start", False) or getattr(worker, "allow_start", False)
            )
            self.refresh_context_badges()
            return
        allow_start = bool(getattr(self, "_pending_daemon_connect_allow_start", False))
        retries = max(0, int(getattr(self, "_pending_daemon_connect_retries", 0) or 0))
        if not allow_start and retries <= 0:
            self.daemon_bootstrapping = False
            self.refresh_context_badges()
            return
        self._pending_daemon_connect_allow_start = False
        self._pending_daemon_connect_retries = 0
        if not self.daemon_client:
            self.daemon_client = DaemonClient(
                self.daemon_host,
                self.daemon_port,
                timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
            )
        can_start = allow_start
        if self.daemon_process and self.daemon_process.poll() is None:
            can_start = False
        self.daemon_bootstrapping = bool(allow_start)
        self.refresh_context_badges()
        worker = DaemonConnectWorker(
            self.daemon_host,
            self.daemon_port,
            self.daemon_runtime_signature,
            allow_start=can_start,
            retries=retries,
            timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
            parent=self,
        )
        self.daemon_connect_worker = worker
        worker.finished_signal.connect(self.handle_daemon_connect_finished, Qt.QueuedConnection)
        worker.finished.connect(worker.deleteLater)
        worker.start()

    def handle_daemon_connect_finished(self, payload):
        payload = payload if isinstance(payload, dict) else {}
        process = payload.get("process")
        if process is not None:
            self.daemon_process = process
        self.daemon_available = bool(payload.get("connected"))
        self.daemon_connect_worker = None
        log_ui_navigation(
            "daemon_connect_finished",
            connected=self.daemon_available,
            signature_mismatch=bool(payload.get("signature_mismatch")),
            replaced_mismatched_daemon=bool(payload.get("replaced_mismatched_daemon")),
            remote_pid=int(payload.get("remote_pid") or 0),
            remote_signature=str(payload.get("remote_signature") or ""),
            local_signature=str(self.daemon_runtime_signature or ""),
            remote_active_runs=payload.get("remote_active_runs"),
            error=str(payload.get("error") or ""),
        )
        if payload.get("signature_mismatch"):
            if not getattr(self, "_daemon_signature_mismatch_notified", False):
                self._daemon_signature_mismatch_notified = True
                active_runs = payload.get("remote_active_runs")
                remote_pid = int(payload.get("remote_pid") or 0)
                if isinstance(active_runs, int) and active_runs > 0:
                    message = (
                        f"后台进程 PID {remote_pid} 仍在执行 {active_runs} 个任务；"
                        "任务结束后将自动切换到当前版本。"
                    )
                else:
                    message = (
                        f"后台进程 PID {remote_pid} 与当前版本不匹配，"
                        "但无法确认它已空闲；请查看 ui_navigation.log。"
                    )
                self.add_system_toast(
                    message,
                    "warning",
                    auto_close_ms=8000,
                )
        else:
            self._daemon_signature_mismatch_notified = False
            if self.daemon_available:
                for state in list(self.sessions.values()):
                    self.attach_active_daemon_run_if_needed(state)
        self._drain_daemon_connection_queue()

    def start_daemon_monitor(self):
        if self.daemon_timer:
            return
        self.daemon_timer = QTimer(self)
        self.daemon_timer.setInterval(5000)
        self.daemon_timer.timeout.connect(self.ensure_daemon_connection)
        self.daemon_timer.start()

    def ensure_daemon_connection(self):
        self.recover_runtime_pending_commits()
        self.queue_daemon_connection(allow_start=True, retries=0)

    def recover_runtime_pending_commits(self):
        journal = getattr(self, "chat_recovery_journal", None)
        storage = getattr(self, "chat_storage", None)
        if journal is None or storage is None:
            return []
        busy_session_ids = {
            str(session_id)
            for session_id, state in list(getattr(self, "sessions", {}).items())
            if (
                getattr(state, "live_activity", False)
                or getattr(state, "daemon_running", False)
                or (
                    getattr(state, "llm_worker", None) is not None
                    and state.llm_worker.isRunning()
                )
                or (
                    getattr(state, "code_worker", None) is not None
                    and state.code_worker.isRunning()
                )
            )
        }
        recovered, errors = journal.recover_into(
            storage,
            skip_session_ids=busy_session_ids,
        )
        for item in errors:
            log_chat_recovery(
                "runtime_record_failed",
                path=str(item.get("path") or ""),
                source=str(item.get("source") or "unknown"),
                error=str(item.get("error") or "unknown error"),
            )
            self.append_log(
                f"运行提交恢复失败: {item.get('path')} | {item.get('error')}"
            )
        if not recovered:
            return []
        self.refresh_history_list()
        log_ui_navigation(
            "runtime_pending_commits_recovered",
            recovered_count=len(recovered),
            error_count=len(errors),
        )
        return recovered

    def start_favorites_scheduler(self):
        if self.favorites_timer:
            return
        self.favorites_timer = QTimer(self)
        self.favorites_timer.setInterval(DEFAULT_FAVORITES_TIMER_INTERVAL_MS)
        self.favorites_timer.timeout.connect(self.check_favorite_schedules)
        self.favorites_timer.start()
        log_favorites_runtime(
            "favorite_scheduler_start",
            interval_ms=DEFAULT_FAVORITES_TIMER_INTERVAL_MS,
        )
        QTimer.singleShot(0, self.check_favorite_schedules)

    def _favorite_validation_error(self, favorite):
        available = {
            str(item.get("name") or "").strip()
            for item in self._available_session_skills()
            if str(item.get("name") or "").strip()
        }
        missing = [name for name in normalize_selected_skill_names(favorite.get("skill_names")) if name not in available]
        if missing:
            return "以下能力不可用：" + "、".join(missing)
        if favorite.get("execution_mode") == FAVORITE_EXECUTION_WORKSPACE:
            workspace_dir = str(favorite.get("workspace_dir") or "").strip()
            if not workspace_dir or not os.path.isdir(workspace_dir):
                return "指定工作区不存在，请编辑常用项后重新选择。"
        return ""

    def _update_favorite_record(self, updated):
        if updated:
            self.config_manager.upsert_favorite(updated)

    def _append_favorite_history(self, record):
        saved = self.config_manager.append_favorite_run_history(record)
        if saved and saved.get("status") == FAVORITE_RUN_STATUS_RUNNING:
            self._running_favorite_history_ids.add(saved.get("id"))
        self._refresh_favorites_runtime_view()
        return saved

    def _refresh_favorites_runtime_view(self):
        page = (getattr(self, "product_pages", {}) or {}).get(self.PAGE_FAVORITES)
        if page is not None and _qt_object_alive(page):
            page.favorites = list(self.config_manager.get_favorites())
            if self.main_page_stack.currentWidget() is page:
                page.refresh_cards()

    def _finalize_favorite_history_record(self, history_id, status, summary="", error=""):
        history = self.config_manager.get_favorite_run_history()
        target_id = str(history_id or "").strip()
        for record in history:
            if str(record.get("id") or "").strip() != target_id:
                continue
            record["status"] = status
            record["finished_at"] = int(time.time())
            if summary:
                record["summary"] = summary
            if error:
                record["error"] = error
            self.config_manager.set_favorite_run_history(history)
            break
        self._running_favorite_history_ids.discard(target_id)
        self._refresh_favorites_runtime_view()

    def _update_favorite_delivery_history_record(self, history_id, delivery_id, status, error=""):
        history = self.config_manager.get_favorite_run_history()
        target_id = str(history_id or "").strip()
        changed = False
        for record in history:
            if str(record.get("id") or "").strip() != target_id:
                continue
            values = {
                "delivery_id": str(delivery_id or "").strip(),
                "delivery_status": str(status or "").strip(),
                "delivery_error": str(error or "").strip(),
            }
            for key, value in values.items():
                if str(record.get(key) or "") != value:
                    record[key] = value
                    changed = True
            break
        if changed:
            self.config_manager.set_favorite_run_history(history)
            self._refresh_favorites_runtime_view()

    def _sync_favorite_delivery_history(self):
        history = self.config_manager.get_favorite_run_history()
        delivery_ids = [record.get("delivery_id") for record in history if record.get("delivery_id")]
        if not delivery_ids:
            return False
        jobs = {
            job.get("id"): job
            for job in self.favorite_delivery_service.get_jobs(delivery_ids)
            if job and job.get("id")
        }
        changed = False
        for record in history:
            job = jobs.get(record.get("delivery_id"))
            if not job:
                continue
            status = str(job.get("status") or "")
            error = str(job.get("error") or "")
            if record.get("delivery_status") != status or record.get("delivery_error") != error:
                record["delivery_status"] = status
                record["delivery_error"] = error
                changed = True
        if changed:
            self.config_manager.set_favorite_run_history(history)
        return changed

    def _favorite_terminal_output(self, state):
        if not state:
            return "", []
        content = ""
        content_parts = []
        for message in reversed(getattr(state, "messages", []) or []):
            if not isinstance(message, dict) or message.get("role") != "assistant":
                continue
            candidate = str(self._message_display_content(message) or "").strip()
            parts = message.get("content_parts") if isinstance(message.get("content_parts"), list) else []
            if candidate or parts:
                content = candidate
                content_parts = parts
                break
        workspace_dir = self._workspace_dir_for_state(state)
        candidate_paths = []
        for part in content_parts:
            if not isinstance(part, dict) or str(part.get("type") or "").lower() not in {"file", "image"}:
                continue
            path = str(part.get("path") or "").strip()
            if path:
                candidate_paths.append(path)
        candidate_paths.extend(path for _start, _end, path in iter_workspace_file_paths(content, workspace_dir))
        return content, collect_feishu_artifacts(candidate_paths, workspace_dir)

    def _enqueue_favorite_delivery(self, state, favorite, run_id, terminal_status, error=""):
        schedule = dict((favorite or {}).get("schedule") or {})
        delivery = dict(schedule.get("delivery") or {})
        if not delivery.get("enabled"):
            return None
        content, artifacts = self._favorite_terminal_output(state)
        try:
            job = self.favorite_delivery_service.enqueue_delivery(
                run_history_id=run_id,
                favorite_id=favorite.get("id") or "",
                session_id=state.session_id,
                binding_id=delivery.get("binding_id") or "",
                favorite_name=favorite.get("name") or "常用任务",
                terminal_status=terminal_status,
                content=content,
                error=error,
                artifacts=artifacts,
            )
            active_provider = str(
                ((normalize_im_gateway_config(self.config_manager.get("im_gateway", {})).get("enabled_providers") or [""])[0])
                or ""
            )
            if active_provider != job.get("provider"):
                blocked_error = "绑定渠道当前未启用；请切换到该渠道后在运行历史中重新发送。"
                job = self.favorite_delivery_service.save_job_state(
                    job["id"],
                    job.get("payload") or {},
                    FAVORITE_DELIVERY_STATUS_BLOCKED,
                    error=blocked_error,
                )
            self._update_favorite_delivery_history_record(
                run_id,
                job.get("id") or "",
                job.get("status") or FAVORITE_DELIVERY_STATUS_PENDING,
                job.get("error") or "",
            )
            log_favorites_runtime(
                "favorite_delivery_enqueued",
                favorite_id=favorite.get("id"),
                run_id=run_id,
                delivery_id=job.get("id"),
                provider=job.get("provider"),
                status=job.get("status"),
                artifact_count=len(artifacts) if job.get("provider") == "feishu" else 0,
            )
            return job
        except Exception as exc:
            self._update_favorite_delivery_history_record(
                run_id,
                "",
                FAVORITE_DELIVERY_STATUS_FAILED,
                str(exc),
            )
            log_favorites_runtime(
                "favorite_delivery_error",
                favorite_id=favorite.get("id"),
                run_id=run_id,
                error=str(exc),
            )
            return None

    def _favorite_summary_from_state(self, state):
        if not state:
            return ""
        for message in reversed(getattr(state, "messages", [])):
            if isinstance(message, dict) and message.get("role") == "assistant":
                content = str(self._message_display_content(message) or "").strip()
                if content:
                    return re.sub(r"\s+", " ", content)[:240]
        return ""

    def _mark_session_favorite_run_completed(
        self,
        state,
        status,
        error="",
        delivery_persistence_succeeded=True,
    ):
        if not state or not getattr(state, "favorite_run_id", ""):
            return
        mapped_status = {
            "completed": FAVORITE_RUN_STATUS_COMPLETED,
            "error": FAVORITE_RUN_STATUS_ERROR,
            "failed": FAVORITE_RUN_STATUS_ERROR,
            "interrupted": FAVORITE_RUN_STATUS_INTERRUPTED,
        }.get(status)
        if not mapped_status:
            return
        run_id = str(state.favorite_run_id or "")
        favorite_id = str(state.favorite_id or "")
        self._finalize_favorite_history_record(
            run_id,
            mapped_status,
            summary=self._favorite_summary_from_state(state),
            error=error,
        )
        log_favorites_runtime(
            "favorite_finish" if mapped_status == FAVORITE_RUN_STATUS_COMPLETED else "favorite_error",
            favorite_id=favorite_id,
            run_id=run_id,
            session_id=state.session_id,
            trigger_source=str(getattr(state, "favorite_trigger_source", "") or ""),
            status=mapped_status,
            error=error,
        )
        favorite = self.config_manager.get_favorite(favorite_id)
        if favorite and favorite.get("schedule"):
            favorite["schedule"]["last_run_at"] = int(time.time())
            favorite["schedule"]["last_history_id"] = run_id
            self._update_favorite_record(favorite)
            delivery = dict((favorite.get("schedule") or {}).get("delivery") or {})
            if delivery.get("enabled") and not delivery_persistence_succeeded:
                delivery_error = "最终消息未可靠持久化，未创建企业消息投递任务。"
                self._update_favorite_delivery_history_record(
                    run_id,
                    "",
                    FAVORITE_DELIVERY_STATUS_FAILED,
                    delivery_error,
                )
                log_favorites_runtime(
                    "favorite_delivery_error",
                    favorite_id=favorite_id,
                    run_id=run_id,
                    error="terminal_persistence_failed",
                )
            else:
                self._enqueue_favorite_delivery(
                    state,
                    favorite,
                    run_id,
                    "completed" if mapped_status == FAVORITE_RUN_STATUS_COMPLETED else (
                        "interrupted" if mapped_status == FAVORITE_RUN_STATUS_INTERRUPTED else "error"
                    ),
                    error=error,
                )
        state.favorite_run_id = ""
        state.favorite_id = ""
        state.favorite_trigger_source = ""

    def _create_favorite_session(self, favorite):
        workspace_dir = ""
        if favorite.get("execution_mode") == FAVORITE_EXECUTION_WORKSPACE:
            workspace_dir = str(favorite.get("workspace_dir") or "")
        session_id = self.create_new_session(
            title=favorite.get("name") or "常用任务",
            make_current=False,
            workspace_dir=workspace_dir,
        )
        state = self.get_session(session_id)
        if state:
            state.selected_skill_names = normalize_selected_skill_names(favorite.get("skill_names"))
        return session_id, state

    def _set_favorite_task_origin(self, state, favorite, trigger_source, scheduled_at=0):
        if not state:
            raise ValueError("无法记录定时任务来源：目标会话不存在。")
        origin = {
            "type": "favorite_schedule",
            "favorite_id": str(favorite.get("id") or ""),
            "favorite_name": str(favorite.get("name") or "常用任务"),
            "trigger_source": str(trigger_source or "scheduler"),
            "scheduled_at": int(scheduled_at or 0),
        }
        meta = copy.deepcopy(getattr(state, "persisted_conversation_meta", {}) or {})
        meta["task_origin"] = origin
        state.persisted_conversation_meta = meta
        return origin

    def launch_favorite(self, favorite_id, source="ui"):
        favorite = self.config_manager.get_favorite(favorite_id)
        if not favorite:
            self.add_system_toast("未找到这个常用项", "error")
            log_favorites_runtime("favorite_error", favorite_id=favorite_id, source=source, error="favorite_not_found")
            return False
        validation_error = self._favorite_validation_error(favorite)
        if validation_error:
            self.add_system_toast(validation_error, "error", auto_close_ms=7000)
            log_favorites_runtime("favorite_error", favorite_id=favorite_id, source=source, error=validation_error)
            return False
        if not self.show_conversation_page():
            log_favorites_runtime("favorite_navigation_cancelled", favorite_id=favorite_id, source=source)
            return False
        session_id, state = self._create_favorite_session(favorite)
        if not state:
            self.add_system_toast("无法创建常用会话", "error")
            log_favorites_runtime("favorite_error", favorite_id=favorite_id, source=source, error="session_creation_failed")
            return False
        self.activate_session(session_id)
        prompt = str(favorite.get("prompt") or "").strip()
        log_favorites_runtime(
            "favorite_submit",
            favorite_id=favorite_id,
            source=source,
            session_id=session_id,
            has_prompt=bool(prompt),
            skill_count=len(state.selected_skill_names),
        )
        if not prompt:
            self.refresh_selected_skill_controls(session_id)
            self.refresh_context_badges(session_id)
            self.input_field.setFocus()
            self.add_system_toast("已加载常用能力，可以开始输入", "success", session_id=session_id)
            log_favorites_runtime("favorite_start", favorite_id=favorite_id, source=source, session_id=session_id)
            return True
        submitted = self._submit_session_request(
            state,
            prompt,
            [],
            check_duplicates=False,
            clear_current_input=False,
        )
        if not submitted:
            self.input_field.setPlainText(prompt)
            self.add_system_toast("常用提示词未能提交，已保留在输入框中", "error", session_id=session_id, auto_close_ms=7000)
            log_favorites_runtime("favorite_error", favorite_id=favorite_id, source=source, error="submission_failed")
            return False
        log_favorites_runtime("favorite_start", favorite_id=favorite_id, source=source, session_id=session_id)
        return True

    def run_favorite_schedule_now(self, favorite_id):
        return self._trigger_favorite_schedule(favorite_id, trigger_source="manual", scheduled_at=0)

    def retry_favorite_delivery(self, delivery_id):
        job = self.favorite_delivery_service.get_job(delivery_id)
        if not job:
            self.add_system_toast("未找到这条企业消息投递记录", "error", auto_close_ms=5000)
            return False
        active_provider = str(
            ((normalize_im_gateway_config(self.config_manager.get("im_gateway", {})).get("enabled_providers") or [""])[0])
            or ""
        )
        if active_provider != job.get("provider"):
            self.add_system_toast("请先在企业消息设置中启用绑定渠道", "error", auto_close_ms=6000)
            return False
        retried = self.favorite_delivery_service.retry_job(delivery_id)
        if not retried:
            self.add_system_toast("当前投递状态不能重新发送", "error", auto_close_ms=5000)
            return False
        self._update_favorite_delivery_history_record(
            retried.get("run_history_id"),
            retried.get("id"),
            retried.get("status"),
            retried.get("error"),
        )
        log_favorites_runtime(
            "favorite_delivery_retry_requested",
            favorite_id=retried.get("favorite_id"),
            run_id=retried.get("run_history_id"),
            delivery_id=retried.get("id"),
            provider=retried.get("provider"),
        )
        self.add_system_toast("已重新提交企业消息投递", "success", auto_close_ms=4000)
        return True

    def _trigger_favorite_schedule(self, favorite_id, trigger_source="scheduler", scheduled_at=0):
        favorite = self.config_manager.get_favorite(favorite_id)
        if not favorite or not favorite.get("schedule"):
            log_favorites_runtime("favorite_error", favorite_id=favorite_id, error="schedule_not_found")
            return False
        error = self._favorite_validation_error(favorite)
        prompt = favorite_effective_prompt(favorite)
        if not prompt:
            error = "定时计划没有可执行的提示词。"
        if error:
            self._append_favorite_history(make_favorite_run_record(
                favorite,
                status=FAVORITE_RUN_STATUS_ERROR,
                trigger_source=trigger_source,
                scheduled_at=scheduled_at,
                error=error,
            ))
            log_favorites_runtime("favorite_error", favorite_id=favorite_id, trigger_source=trigger_source, error=error)
            return False
        if trigger_source == "manual" and not self.show_conversation_page():
            log_favorites_runtime("favorite_navigation_cancelled", favorite_id=favorite_id, source=trigger_source)
            return False
        session_id, state = self._create_favorite_session(favorite)
        if not state:
            error = "无法创建定时运行会话。"
            self._append_favorite_history(make_favorite_run_record(
                favorite,
                status=FAVORITE_RUN_STATUS_ERROR,
                trigger_source=trigger_source,
                scheduled_at=scheduled_at,
                error=error,
            ))
            return False
        saved = self._append_favorite_history(make_favorite_run_record(
            favorite,
            status=FAVORITE_RUN_STATUS_RUNNING,
            trigger_source=trigger_source,
            session_id=session_id,
            scheduled_at=scheduled_at,
        ))
        state.favorite_run_id = str((saved or {}).get("id") or "")
        state.favorite_id = str(favorite.get("id") or "")
        state.favorite_trigger_source = trigger_source
        self._set_favorite_task_origin(state, favorite, trigger_source, scheduled_at)
        if trigger_source == "manual":
            self.activate_session(session_id)
        log_favorites_runtime(
            "favorite_submit",
            favorite_id=favorite_id,
            run_id=state.favorite_run_id,
            trigger_source=trigger_source,
            scheduled_at=scheduled_at,
            session_id=session_id,
        )
        submitted = self._submit_session_request(
            state,
            prompt,
            [],
            check_duplicates=False,
            clear_current_input=False,
        )
        if not submitted:
            self._finalize_favorite_history_record(
                state.favorite_run_id,
                FAVORITE_RUN_STATUS_ERROR,
                error="定时计划未能成功提交。",
            )
            state.favorite_run_id = ""
            state.favorite_id = ""
            state.favorite_trigger_source = ""
            log_favorites_runtime(
                "favorite_error",
                favorite_id=favorite_id,
                run_id=str((saved or {}).get("id") or ""),
                session_id=session_id,
                trigger_source=trigger_source,
                error="submission_failed",
            )
            return False
        log_favorites_runtime(
            "favorite_start",
            favorite_id=favorite_id,
            run_id=state.favorite_run_id,
            session_id=session_id,
            trigger_source=trigger_source,
        )
        if trigger_source == "manual":
            self.add_system_toast("定时计划已立即启动", "success", session_id=session_id)
        return True

    def check_favorite_schedules(self):
        self._sync_favorite_delivery_history()
        favorites = self.config_manager.get_favorites()
        if not favorites:
            return
        now_ts = int(time.time())
        updated = []
        changed = False
        for favorite in favorites:
            current = dict(favorite)
            current["schedule"] = dict(favorite.get("schedule") or {}) if favorite.get("schedule") else None
            schedule = current.get("schedule")
            if not schedule or not schedule.get("enabled"):
                updated.append(current)
                continue
            next_run_at = int(schedule.get("next_run_at") or 0)
            if not next_run_at:
                schedule["next_run_at"] = compute_next_favorite_run_at(schedule, now_ts=now_ts)
                schedule["schedule_summary"] = describe_favorite_schedule(schedule)
                changed = True
                updated.append(current)
                continue
            if next_run_at + FAVORITE_RUN_GRACE_SECONDS < now_ts:
                skipped = 0
                while int((current.get("schedule") or {}).get("next_run_at") or 0) + FAVORITE_RUN_GRACE_SECONDS < now_ts:
                    skipped += 1
                    current["schedule"]["last_missed_at"] = int(current["schedule"].get("next_run_at") or 0)
                    if current["schedule"].get("schedule_type") == FAVORITE_SCHEDULE_ONCE:
                        current["schedule"]["enabled"] = False
                        break
                    current = advance_favorite_schedule(
                        current,
                        now_ts=now_ts,
                        after_ts=int(current["schedule"].get("next_run_at") or now_ts),
                    )
                self._append_favorite_history(make_favorite_run_record(
                    current,
                    status=FAVORITE_RUN_STATUS_MISSED,
                    trigger_source="scheduler",
                    scheduled_at=next_run_at,
                    summary=f"应用未运行，已跳过 {skipped} 次计划触发。",
                ))
                log_favorites_runtime(
                    "favorite_missed",
                    favorite_id=current.get("id"),
                    scheduled_at=next_run_at,
                    skipped=skipped,
                )
                changed = True
                updated.append(current)
                continue
            if next_run_at <= now_ts:
                triggered = self._trigger_favorite_schedule(current.get("id"), "scheduler", next_run_at)
                current["schedule"]["last_run_at"] = now_ts if triggered else int(current["schedule"].get("last_run_at") or 0)
                if current["schedule"].get("schedule_type") == FAVORITE_SCHEDULE_ONCE:
                    current["schedule"]["enabled"] = False
                else:
                    current = advance_favorite_schedule(current, now_ts=now_ts, after_ts=max(now_ts, next_run_at))
                changed = True
            updated.append(current)
        if changed:
            self.config_manager.set_favorites(updated)

    def _daemon_signature_matches(self, payload):
        if not isinstance(payload, dict):
            return False
        remote = str(payload.get("signature") or "").strip()
        local = str(getattr(self, "daemon_runtime_signature", "") or "").strip()
        return bool(remote and local and remote == local)

    def try_connect_daemon(self, allow_start=False, retries=0):
        if not self.daemon_client:
            self.daemon_client = DaemonClient(
                self.daemon_host,
                self.daemon_port,
                timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
            )
        ping_payload = self.daemon_client.ping()
        connected = bool(ping_payload)
        signature_mismatch = bool(
            connected and not self._daemon_signature_matches(ping_payload)
        )
        if signature_mismatch:
            connected = False
            reconciliation = None
            if allow_start:
                reconciliation = request_idle_daemon_shutdown(
                    self.daemon_client,
                    ping_payload,
                )
                if reconciliation.get("stopped"):
                    signature_mismatch = False
                    log_ui_navigation(
                        "daemon_mismatch_replaced",
                        remote_pid=int(reconciliation.get("remote_pid") or 0),
                        remote_signature=str(reconciliation.get("remote_signature") or ""),
                        local_signature=str(self.daemon_runtime_signature or ""),
                    )
            if not getattr(self, "_daemon_signature_mismatch_notified", False):
                if signature_mismatch:
                    self._daemon_signature_mismatch_notified = True
                    active_runs = (
                        reconciliation.get("active_runs")
                        if isinstance(reconciliation, dict)
                        else None
                    )
                    remote_pid = int((ping_payload or {}).get("pid") or 0)
                    if isinstance(active_runs, int) and active_runs > 0:
                        message = (
                            f"后台进程 PID {remote_pid} 仍在执行 {active_runs} 个任务；"
                            "任务结束后将自动切换到当前版本。"
                        )
                    else:
                        message = (
                            f"后台进程 PID {remote_pid} 与当前版本不匹配，"
                            "但无法确认它已空闲；请查看 ui_navigation.log。"
                        )
                    self.add_system_toast(message, "warning", auto_close_ms=8000)
        if not connected and allow_start and not signature_mismatch:
            self.start_daemon_process()
            for _ in range(max(retries, 0)):
                time.sleep(0.2)
                retry_ping = self.daemon_client.ping()
                if retry_ping and self._daemon_signature_matches(retry_ping):
                    connected = True
                    break
        if connected:
            self._daemon_signature_mismatch_notified = False
        self.daemon_available = connected
        self.refresh_context_badges()

    def start_daemon_process(self):
        try:
            if self.daemon_process and self.daemon_process.poll() is None:
                return
            self.daemon_process = launch_daemon_subprocess(self.daemon_port)
        except Exception:
            self.daemon_process = None

    def start_gateway_process(self):
        try:
            if getattr(self, "gateway_starting", False):
                return True
            if self.gateway_process and self.gateway_process.poll() is None:
                return True
            cmd, cwd = build_gateway_launch_command()
            env = os.environ.copy()
            self.gateway_starting = True
            self.gateway_last_error = ""
            if self.gateway_log_file:
                try:
                    self.gateway_log_file.close()
                except Exception:
                    pass
                self.gateway_log_file = None
            log_path = os.path.join(get_app_data_dir(), "im_gateway.log")
            self.gateway_log_file = open(log_path, "a", encoding="utf-8")
            self.gateway_process = subprocess.Popen(
                cmd,
                cwd=cwd,
                stdout=subprocess.DEVNULL,
                stderr=self.gateway_log_file,
                env=env,
                **subprocess_kwargs_no_window(),
            )
            QTimer.singleShot(GATEWAY_START_SETTLE_DELAY_MS, self._finalize_gateway_startup_state)
            return True
        except Exception as exc:
            self.gateway_starting = False
            self.gateway_process = None
            self.gateway_last_error = str(exc)
            append_background_process_log(
                "im_gateway.log",
                f"gateway process launch failed error={exc}",
            )
            if self.gateway_log_file:
                try:
                    self.gateway_log_file.close()
                except Exception:
                    pass
                self.gateway_log_file = None
            return False

    def _finalize_gateway_startup_state(self):
        process = getattr(self, "gateway_process", None)
        if process and process.poll() is not None:
            self.gateway_last_error = f"网关进程退出，返回码 {process.returncode}。"
            append_background_process_log(
                "im_gateway.log",
                f"gateway process exited returncode={process.returncode}",
            )
            self.gateway_process = None
            if self.gateway_log_file:
                try:
                    self.gateway_log_file.close()
                except Exception:
                    pass
                self.gateway_log_file = None
        self.gateway_starting = False

    def stop_gateway_process(self):
        self.gateway_starting = False
        if not self.gateway_process:
            return
        self._terminate_process(self.gateway_process)
        self.gateway_process = None
        if self.gateway_log_file:
            try:
                self.gateway_log_file.close()
            except Exception:
                pass
            self.gateway_log_file = None

    def setup_tray(self):
        if not QSystemTrayIcon.isSystemTrayAvailable():
            return
        icon = self.windowIcon()
        if icon.isNull():
            icon = QIcon()
        self.tray_icon = QSystemTrayIcon(icon, self)
        menu = QMenu()
        toggle_action = QAction("显示/隐藏", self)
        toggle_action.triggered.connect(self.toggle_window_visibility)
        status_action = QAction("查看状态", self)
        status_action.triggered.connect(self.show_tray_status)
        quit_action = QAction("退出", self)
        quit_action.triggered.connect(self.quit_app)
        menu.addAction(toggle_action)
        menu.addAction(status_action)
        menu.addSeparator()
        menu.addAction(quit_action)
        self.tray_icon.setContextMenu(menu)
        self.tray_icon.activated.connect(self.on_tray_activated)
        self.tray_icon.show()

    def on_tray_activated(self, reason):
        if reason == QSystemTrayIcon.Trigger:
            self.toggle_window_visibility()

    def toggle_window_visibility(self):
        if self.isVisible():
            self.hide()
        else:
            self.activate_existing_window()

    def activate_existing_window(self):
        if self.isMinimized():
            self.showNormal()
        elif not self.isVisible():
            self.show()
        else:
            self.show()
        self.activateWindow()
        self.raise_()

    def get_daemon_status_text(self):
        if getattr(self, "daemon_bootstrapping", False):
            return "守护进程连接中"
        if getattr(self, "daemon_available", False):
            return "守护进程在线"
        return "守护进程未连接"

    def show_tray_status(self):
        connect_worker = getattr(self, "daemon_connect_worker", None)
        if connect_worker and connect_worker.isRunning():
            status = "守护进程连接中"
            if self.tray_icon:
                self.tray_icon.showMessage("状态", status, QSystemTrayIcon.Information, 3000)
            else:
                QMessageBox.information(self, "状态", status)
            return
        if not getattr(self, "daemon_available", False):
            self.queue_daemon_connection(allow_start=True, retries=2)
            status = "正在启动守护进程"
            if self.tray_icon:
                self.tray_icon.showMessage("状态", status, QSystemTrayIcon.Information, 3000)
            else:
                QMessageBox.information(self, "状态", status)
            return
        worker = getattr(self, "daemon_status_worker", None)
        if worker and worker.isRunning():
            status = "守护进程状态查询中"
            if self.tray_icon:
                self.tray_icon.showMessage("状态", status, QSystemTrayIcon.Information, 3000)
            else:
                QMessageBox.information(self, "状态", status)
            return
        worker = DaemonStatusWorker(
            self.daemon_host,
            self.daemon_port,
            self.daemon_runtime_signature,
            timeout=UI_DAEMON_CONNECT_TIMEOUT_SEC,
            parent=self,
        )
        self.daemon_status_worker = worker
        worker.finished_signal.connect(self.handle_daemon_status_finished, Qt.QueuedConnection)
        worker.finished.connect(worker.deleteLater)
        worker.start()
        status = "正在刷新守护进程状态"
        if self.tray_icon:
            self.tray_icon.showMessage("状态", status, QSystemTrayIcon.Information, 2000)
        else:
            QMessageBox.information(self, "状态", status)

    def handle_daemon_status_finished(self, payload):
        payload = payload if isinstance(payload, dict) else {}
        self.daemon_available = bool(payload.get("connected"))
        self.daemon_status_worker = None
        self.refresh_context_badges()
        status = str(payload.get("status_text") or self.get_daemon_status_text()).strip() or "守护进程状态未知"
        if self.tray_icon:
            self.tray_icon.showMessage("状态", status, QSystemTrayIcon.Information, 3000)
        else:
            QMessageBox.information(self, "状态", status)

    def quit_app(self):
        if any(worker.isRunning() for worker in getattr(self, "skillhub_workers", [])):
            self.add_system_toast("SkillHub 操作仍在进行，请完成后再退出。", "info")
            return
        if not self.confirm_leave_deliverable_edit("退出应用"):
            return
        self._dispose_application_event_filters()
        preserved_daemon_runs = self.shutdown_workers(preserve_daemon_runs=True)
        if not preserved_daemon_runs:
            if self.daemon_client and self.daemon_available:
                self.daemon_client.shutdown()
            self.stop_daemon_process()
        self.stop_gateway_process()
        if self.tray_icon:
            self.tray_icon.hide()
        QApplication.quit()

    def _dispose_application_event_filters(self):
        for attribute in ("deliverable_web_preview", "file_workbench"):
            target = getattr(self, attribute, None)
            if target is not None and _qt_object_alive(target):
                target.dispose_event_filter()
        app = QApplication.instance()
        controller = getattr(app, "product_tooltip_controller", None) if app is not None else None
        if controller is not None and _qt_object_alive(controller):
            controller.dispose()

    def stop_daemon_process(self):
        if not self.daemon_process:
            return
        self._terminate_process(self.daemon_process)
        self.daemon_process = None

    def shutdown_workers(self, preserve_daemon_runs=False):
        for worker in list(getattr(self, "skillhub_workers", [])):
            worker.wait()
        preserved_daemon_runs = False
        if not self.flush_pending_chat_saves(timeout_ms=3000):
            self.append_log("会话保存队列在关闭前未能完全 flush，应用将继续退出。")
        deliverable_scan_worker = getattr(self, "deliverable_scan_worker", None)
        if deliverable_scan_worker is not None and deliverable_scan_worker.isRunning():
            deliverable_scan_worker.wait(3000)
        self.deliverable_scan_worker = None
        if self.daemon_connect_worker and self.daemon_connect_worker.isRunning():
            self.daemon_connect_worker.wait(1000)
        self.daemon_connect_worker = None
        if self.daemon_status_worker and self.daemon_status_worker.isRunning():
            self.daemon_status_worker.wait(1000)
        self.daemon_status_worker = None
        for stop_worker in list(getattr(self, "_daemon_stop_workers", set())):
            if stop_worker.isRunning():
                stop_worker.wait(3500)
        for session_id, state in list(self.sessions.items()):
            for guidance_worker in list(getattr(state, "guidance_workers", []) or []):
                try:
                    guidance_worker.wait(500)
                except Exception:
                    pass
            state.guidance_workers = []
            preserve_session_run = bool(preserve_daemon_runs and state.daemon_running)
            if preserve_session_run:
                preserved_daemon_runs = True
            if not preserve_session_run:
                self._stop_live_subagents(state, force=True)
            if self.daemon_client and state.daemon_running and state.session_id and not preserve_session_run:
                try:
                    self.daemon_client.stop_session(state.session_id)
                except Exception:
                    pass
            if state.daemon_worker and state.daemon_worker.isRunning():
                self._disconnect_worker_signals(state.daemon_worker)
                if preserve_session_run:
                    state.daemon_worker.detach()
                else:
                    state.daemon_worker.abort()
                state.daemon_worker.wait(1000)
            if state.llm_worker and state.llm_worker.isRunning():
                self._disconnect_worker_signals(state.llm_worker)
                state.llm_worker.stop()
                state.llm_worker.wait(1000)
            if state.code_worker and state.code_worker.isRunning():
                self._disconnect_worker_signals(state.code_worker)
                state.code_worker.stop()
                state.code_worker.wait(1000)
            state.daemon_running = False
            state.daemon_worker = None
            state.llm_worker = None
            state.code_worker = None
        if self.daemon_timer:
            self.daemon_timer.stop()
        if getattr(self, "chat_save_worker", None):
            if not self.chat_save_worker.stop_worker(timeout_ms=3000):
                self.append_log("会话保存线程未在超时内退出。")
            self.chat_save_worker = None
        return preserved_daemon_runs

    def _terminate_process(self, proc):
        if not proc:
            return
        try:
            if proc.poll() is None:
                proc.terminate()
                proc.wait(timeout=2)
        except Exception:
            pass
        if proc.poll() is None and platform.system() == "Windows":
            try:
                subprocess.run(
                    ["taskkill", "/PID", str(proc.pid), "/T", "/F"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    **subprocess_kwargs_no_window(),
                )
            except Exception:
                pass
        try:
            if proc.poll() is None:
                proc.kill()
        except Exception:
            pass

    def closeEvent(self, event):
        if any(worker.isRunning() for worker in getattr(self, "skillhub_workers", [])):
            self.add_system_toast("SkillHub 操作仍在进行，请完成后再退出。", "info")
            event.ignore()
            return
        if self.tray_icon:
            event.ignore()
            self.hide()
            self.tray_icon.showMessage("DeepSeek Cowork", "已最小化到托盘", QSystemTrayIcon.Information, 2000)
        else:
            if not self.confirm_leave_deliverable_edit("退出应用"):
                event.ignore()
                return
            self._dispose_application_event_filters()
            self.skill_catalog_service.stop_watching()
            preserved_daemon_runs = self.shutdown_workers(preserve_daemon_runs=True)
            if not preserved_daemon_runs:
                self.stop_daemon_process()
            self.stop_gateway_process()
            event.accept()

    def attach_single_instance_server(self, server):
        self.single_instance_server = server
            
    def resizeEvent(self, event):
        super().resizeEvent(event)
        if hasattr(self, 'drag_overlay'):
            self.drag_overlay.resize(self.size())
        if hasattr(self, "right_sidebar"):
            self.position_context_drawer()
        self._sync_deliverable_text_editor_layout()
        self._position_active_system_toast()

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.acceptProposedAction()
            if hasattr(self, 'drag_overlay'):
                self.drag_overlay.show()
                self.drag_overlay.raise_()
        else:
            event.ignore()

    def dragLeaveEvent(self, event):
        if hasattr(self, 'drag_overlay'):
            self.drag_overlay.hide()

    def dropEvent(self, event):
        if hasattr(self, 'drag_overlay'):
            self.drag_overlay.hide()
            
        if event.mimeData().hasUrls():
            urls = event.mimeData().urls()
            if not urls: return
            
            path = urls[0].toLocalFile()
            if os.path.isdir(path):
                # Switch workspace
                self.load_workspace(path)
            else:
                self._add_prompt_files([path])
            
            event.acceptProposedAction()

    # --- Session & Logic Methods (No changes to logic, only UI wrappers) ---
    def get_current_session(self):
        if not self.current_session_id: return None
        return self.sessions.get(self.current_session_id)

    def get_session(self, session_id=None):
        if session_id is None: return self.get_current_session()
        return self.sessions.get(session_id)

    def sync_current_session_state(self):
        state = self.get_current_session()
        if not state: return
        if hasattr(self, "input_field"):
            state.composer_draft = self.input_field.toPlainText()
        if getattr(state, "chat_scroll", None):
            state.saved_scroll_position = state.chat_scroll.verticalScrollBar().value()
        state.drawer_open = bool(getattr(self, "right_drawer_open", False))
        state.drawer_tab = getattr(self, "right_drawer_tab", None)

    def set_current_session(self, session_id):
        state = self.sessions.get(session_id)
        if not state: return
        self.current_session_id = session_id
        self.active_skills_label = state.active_skills_label
        open_paths = self._session_open_file_paths(state)
        if not getattr(state, "selected_deliverable_path", "") and open_paths:
            state.selected_deliverable_path = open_paths[-1]
        self.current_deliverable_path = getattr(state, "selected_deliverable_path", "") or ""
        self.current_preview_path = self.current_deliverable_path
        self.refresh_change_list(session_id)
        self.refresh_step_list(session_id)
        self.refresh_observability_view(session_id)
        self.refresh_context_badges(session_id)
        self.refresh_selected_skill_controls(session_id)
        self.refresh_grill_mode_controls(session_id)
        self.refresh_model_selector()
        self.refresh_prompt_file_chips(session_id)
        self.refresh_token_usage_label(session_id)
        if hasattr(self, "input_field") and self.input_field.toPlainText() != state.composer_draft:
            self.input_field.setPlainText(state.composer_draft or "")
        if getattr(state, "chat_scroll", None) and state.saved_scroll_position is not None:
            QTimer.singleShot(
                0,
                lambda bar=state.chat_scroll.verticalScrollBar(), value=state.saved_scroll_position: bar.setValue(int(value)),
            )
        if (
            getattr(state, "history_loaded", True)
            and getattr(self, "right_drawer_open", False)
            and getattr(self, "right_drawer_tab", None) == self.RIGHT_TAB_SUB_AGENTS
        ):
            self._queue_render_sub_agent_monitor_for_state(state)
        self._sync_workspace_ui_for_session(session_id, refresh_sidebar=False)
        if (
            getattr(self, "right_drawer_open", False)
            and getattr(self, "right_drawer_tab", None) == self.RIGHT_TAB_DELIVERABLES
        ):
            self.refresh_deliverables(render_current=True)
        self._sync_file_header()
        QTimer.singleShot(0, lambda sid=session_id: self._sync_question_navigator(sid))

    def normalize_session_ui(self, state):
        if not state: return
        running = state.llm_worker and state.llm_worker.isRunning()
        running_code = state.code_worker and state.code_worker.isRunning()
        running_daemon = getattr(state, "daemon_running", False)
        
        if running or running_code or running_daemon:
            self.action_btn.setText("停止")
            self.action_btn.setIcon(qta.icon('fa5s.stop', color='white'))
            self.action_btn.setStyleSheet(
                f"background: {DesignTokens.error_text}; color: {DesignTokens.text_inverse}; "
                f"border-radius: {DesignTokens.radius_xl}px; font-weight: bold; border: none;"
            )
            self.action_btn.setEnabled(True)
            self.input_field.setEnabled(False)
            
            # Hide extra buttons/prompts when running
            self.loop_hint.setVisible(False)
        else:
            self.action_btn.setText("发送")
            self.action_btn.setText("开始")
            self.action_btn.setIcon(qta.icon('fa5s.paper-plane', color='white'))
            self.action_btn.setStyleSheet(
                f"background: {DesignTokens.primary}; color: {DesignTokens.text_inverse}; "
                f"border-radius: {DesignTokens.radius_xl}px; font-weight: bold; border: none;"
            )
            self.action_btn.setEnabled(True)
            self.input_field.setEnabled(True)
            
            self.loop_hint.setVisible(False)

    def normalize_session_ui(self, state):
        if not state:
            return
        history_ready = session_history_ready(state)
        lifecycle_running = str(
            getattr(state, "session_status", "") or ""
        ) in {"running", "finalizing"}
        worker_running = bool(
            lifecycle_running
            and state.llm_worker
            and state.llm_worker.isRunning()
        )
        running = lifecycle_running
        running_code = bool(
            lifecycle_running
            and state.code_worker
            and state.code_worker.isRunning()
        )
        running_daemon = bool(
            lifecycle_running and getattr(state, "daemon_running", False)
        )

        if running or running_code or running_daemon:
            steerable = bool(getattr(state, "turn_steerable", False) and not running_code)
            self.action_btn.setText("调整方向" if steerable else "运行中")
            self.action_btn.setIcon(qta.icon('fa5s.paper-plane', color='white'))
            self.action_btn.setStyleSheet(apple_button_style("primary", radius=8))
            self.action_btn.setEnabled(steerable)
            self.input_field.setEnabled(steerable)
            self.tool_menu_btn.setEnabled(steerable)
            self.stop_btn.setVisible(True)
            if steerable:
                self.input_field.setPlaceholderText("输入补充说明，将在当前任务的下一个安全节点生效")
            if int(getattr(state, "provider_retry_attempt", 0) or 0) > 0:
                loop_text = (
                    f"正在重试 {int(state.provider_retry_attempt)}/"
                    f"{int(state.provider_retry_max or state.provider_retry_attempt)}"
                )
            else:
                loop_text = display_run_phase(
                    getattr(state, "run_phase", "")
                    or ("Running" if (running_daemon or running_code) else "")
                )
            self.loop_hint.setText(loop_text or "处理中")
            self.loop_hint.setToolTip(loop_text or "处理中")
            self.loop_hint.setVisible(bool(running_daemon or running_code or loop_text))
        else:
            grill_armed = normalize_grill_mode_state(
                getattr(state, "grill_mode_state", GRILL_MODE_DISABLED)
            ) == GRILL_MODE_ARMED
            self.action_btn.setText("开始拷问" if grill_armed else "开始")
            self.action_btn.setIcon(qta.icon('fa5s.paper-plane', color='white'))
            self.action_btn.setStyleSheet(apple_button_style("primary", radius=8))
            self.action_btn.setEnabled(history_ready)
            self.input_field.setEnabled(history_ready)
            self.tool_menu_btn.setEnabled(history_ready)
            self.tool_menu_btn.setToolTip("添加上下文" if history_ready else "历史会话仍在加载")
            self.stop_btn.setVisible(False)
            if not history_ready:
                self.input_field.setPlaceholderText("正在加载历史会话，请稍候…")
                self.action_btn.setText("加载中")
                self.input_field.setPlaceholderText("描述你要完成的任务，例如：整理本周截图并生成周报摘要")
            else:
                self.input_field.setPlaceholderText("直接开始聊天；需要处理文件时再连接项目")
            self.loop_hint.setVisible(False)
        self.refresh_selected_skill_controls(state.session_id)
        self.refresh_grill_mode_controls(state.session_id)
        self.refresh_project_selector(state.session_id)
        self.refresh_context_badges(state.session_id)
        self.refresh_observability_view(state.session_id)
        self.update_skill_capture_button_state()

    def get_session_id_for_tab(self, index):
        widget = self.session_tabs.widget(index)
        if not widget: return None
        for session_id, state in self.sessions.items():
            if state.session_widget == widget: return session_id
        return None

    def close_session_tab(self, index):
        session_id = self.get_session_id_for_tab(index)
        if not session_id: return
        if (
            session_id == getattr(self, "current_session_id", None)
            and not self.confirm_leave_deliverable_edit("关闭会话")
        ):
            return
        state = self.sessions.get(session_id)
        if state:
            self._stop_live_subagents(state, force=True)
            self._cancel_token_speed_monitor(state, "session_closed")
            if state.daemon_worker:
                self._disconnect_worker_signals(state.daemon_worker)
                try:
                    state.daemon_worker.abort()
                except Exception:
                    pass
            if state.llm_worker:
                self._disconnect_worker_signals(state.llm_worker)
                try:
                    state.llm_worker.stop()
                except Exception:
                    pass
            if state.code_worker:
                self._disconnect_worker_signals(state.code_worker)
                try:
                    state.code_worker.stop()
                except Exception:
                    pass
            del self.sessions[session_id]
        self.session_tabs.removeTab(index)
        if self.session_tabs.count() == 0: self.create_new_session()

    def on_session_tab_changed(self, index):
        target_session_id = self.get_session_id_for_tab(index)
        if (
            target_session_id
            and target_session_id != getattr(self, "current_session_id", None)
            and not self.confirm_leave_deliverable_edit("切换会话")
        ):
            current_state = self.get_current_session()
            current_index = (
                self.session_tabs.indexOf(current_state.session_widget)
                if current_state is not None
                else -1
            )
            if current_index >= 0:
                self.session_tabs.blockSignals(True)
                try:
                    self.session_tabs.setCurrentIndex(current_index)
                finally:
                    self.session_tabs.blockSignals(False)
            return
        self.sync_current_session_state()
        session_id = target_session_id
        if session_id:
            self.activate_session(session_id, switch_tab=False, ensure_loaded=True)

    def clear_chat_layout(self, chat_layout):
        while chat_layout.count():
            item = chat_layout.takeAt(0)
            widget = item.widget()
            self._retire_chat_widget(widget)
        chat_layout.addStretch()

    def _retire_chat_widget(self, widget):
        if widget is None or not _qt_object_alive(widget):
            return
        bubbles = [widget] if isinstance(widget, ChatBubble) else []
        bubbles.extend(widget.findChildren(ChatBubble))
        for bubble in bubbles:
            if hasattr(bubble, "think_timer"):
                bubble.stop_thinking_timers()
            render_timer = getattr(bubble, "_main_content_render_timer", None)
            if render_timer is not None:
                render_timer.stop()
        widget.hide()
        widget.deleteLater()

    def _compute_session_title(self, messages):
        fallback = ""
        generic = re.compile(r"^(你好|您好|hi|hello|测试(?:下|一下)?|试试|在吗|向我提问|问我问题)[!！。,.，\s]*$", re.I)
        for msg in messages:
            if msg.get("role") == "user":
                content = self._message_display_content(msg).strip()
                if not content:
                    attachments = self._message_user_attachments(msg)
                    if attachments:
                        content = attachments[0].get("name") or attachments[0].get("path") or ""
                content = re.sub(r"\s+", " ", content).strip()
                if not content:
                    continue
                fallback = fallback or content
                if generic.match(content):
                    continue
                return content[:18] + "…" if len(content) > 18 else content
        if fallback:
            return fallback[:18] + "…" if len(fallback) > 18 else fallback
        return "新对话"

    def _resolved_session_title(self, state, messages=None):
        """Return the persisted manual title or the normal generated title."""
        messages = list(messages if messages is not None else getattr(state, "messages", []) or [])
        meta = self._session_base_meta(state) if state else {}
        if meta.get("manual_title") and state:
            record = self.chat_storage.get_conversation_record(state.session_id) or {}
            manual = str(record.get("title") or "").strip()
            if manual:
                return manual
        return self._compute_session_title(messages)

    def update_session_tab_title(self, session_id):
        state = self.sessions.get(session_id)
        if not state: return
        title = self._resolved_session_title(state)
        index = self.session_tabs.indexOf(state.session_widget)
        if index >= 0: self.session_tabs.setTabText(index, title)
        if session_id == self.current_session_id:
            self.update_conversation_header()

    def create_new_session(self, session_id=None, title=None, make_current=True, workspace_dir=None):
        is_fresh_session = session_id is None
        if session_id is None: session_id = uuid.uuid4().hex
        session_widget = QWidget()
        session_widget.setStyleSheet("background: transparent;")
        session_layout = QVBoxLayout(session_widget)
        session_layout.setContentsMargins(0, 0, 0, 0)
        session_layout.setSpacing(10)

        session_header = QWidget()
        session_header.setStyleSheet("background: transparent; border: none;")
        session_header_layout = QHBoxLayout(session_header)
        session_header_layout.setContentsMargins(22, 10, 26, 0)
        session_header_layout.setSpacing(8)

        active_skills_label = QLabel("本次会话使用的功能: ")
        active_skills_label.setStyleSheet(f"color: {DesignTokens.text_tertiary}; font-size: 11px;")
        active_skills_label.setVisible(False)
        session_header_layout.addWidget(active_skills_label)
        session_header_layout.addStretch(1)

        token_usage_label = TokenUsageChip()
        session_header_layout.addWidget(token_usage_label, 0, Qt.AlignRight)
        session_layout.addWidget(session_header)

        chat_scroll = QScrollArea()
        chat_scroll.setObjectName("ChatScrollArea")
        chat_scroll.setWidgetResizable(True)
        chat_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        chat_scroll.setVerticalScrollBar(ProductGrabScrollBar(Qt.Vertical, chat_scroll))
        chat_scroll.setStyleSheet(
            f"QScrollArea#ChatScrollArea {{ border: none; background: transparent; }}"
        )
        chat_container = QWidget()
        chat_container.setStyleSheet("background: transparent;")
        chat_layout = QVBoxLayout(chat_container)
        chat_layout.setContentsMargins(52, 18, 26, 22)
        chat_layout.setSpacing(10)
        
        # Add Empty State
        empty_state = EmptyStateWidget(self)
        chat_layout.addWidget(empty_state)
        
        chat_layout.addStretch()
        chat_scroll.setWidget(chat_container)
        session_layout.addWidget(chat_scroll, 1)

        tab_title = title or "新对话"
        tab_index = self.session_tabs.addTab(session_widget, tab_title)
        self.session_tabs.tabBar().hide()

        state = SessionState(session_id, chat_layout, active_skills_label, session_widget, chat_scroll, token_usage_label)
        state.token_speed_timer = QTimer(self)
        state.token_speed_timer.setInterval(500)
        state.token_speed_timer.timeout.connect(
            lambda sid=session_id: self.refresh_token_usage_label(sid)
        )
        state.content_flush_timer = QTimer(self)
        state.content_flush_timer.setSingleShot(True)
        state.content_flush_timer.setInterval(CONTENT_FLUSH_INTERVAL_MS)
        state.content_flush_timer.timeout.connect(lambda sid=session_id: self.flush_session_content(sid))
        state.thinking_flush_timer = QTimer(self)
        state.thinking_flush_timer.setSingleShot(True)
        state.thinking_flush_timer.setInterval(THINKING_FLUSH_INTERVAL_MS)
        state.thinking_flush_timer.timeout.connect(lambda sid=session_id: self.flush_session_thinking(sid))
        state.scroll_flush_timer = QTimer(self)
        state.scroll_flush_timer.setSingleShot(True)
        state.scroll_flush_timer.setInterval(SCROLL_FLUSH_INTERVAL_MS)
        state.scroll_flush_timer.timeout.connect(lambda sid=session_id: self.flush_session_scroll(sid))
        state.virtualization_timer = QTimer(self)
        state.virtualization_timer.setSingleShot(True)
        state.virtualization_timer.setInterval(90)
        state.virtualization_timer.timeout.connect(lambda sid=session_id: self.virtualize_session_bubbles(sid))
        chat_scroll.verticalScrollBar().valueChanged.connect(lambda value, sid=session_id: self.on_chat_scroll_value_changed(value, sid))
        chat_scroll.verticalScrollBar().sliderPressed.connect(lambda sid=session_id: self.on_chat_scroll_drag_started(sid))
        chat_scroll.verticalScrollBar().sliderReleased.connect(lambda sid=session_id: self.on_chat_scroll_drag_finished(sid))
        state.empty_state = empty_state
        state.history_loaded = is_fresh_session
        state.selected_model_id = self._default_model_id_for_new_session()
        log_model_service_event(
            "session_model_initialized", session_id=session_id,
            model_id=state.selected_model_id, fresh_session=is_fresh_session,
        )
        self.sessions[session_id] = state
        requested_workspace = workspace_dir if workspace_dir is not None else ""
        state.knowledge_refs = []
        if is_fresh_session and requested_workspace:
            state.knowledge_refs = self._knowledge_service().store.references("project:" + self._project_key(requested_workspace))
        if self._normalize_project_path(requested_workspace):
            self._set_session_workspace(state, requested_workspace, source="project")
        elif is_fresh_session or workspace_dir is not None:
            self._ensure_session_workspace(state)
        self.refresh_token_usage_label(state.session_id)
        if make_current:
            self.session_tabs.setCurrentIndex(tab_index)
            self.set_current_session(session_id)
            self.refresh_change_list(session_id)
            self.refresh_step_list(session_id)
            self.refresh_context_badges(session_id)
        return session_id

